# Generated from tools/data/rulebooks/billiards.json; run tools/compile-rulebooks.rb.
module GameRoomGames
  class Billiards
    module GeneratedRulebook
      private

      def generated_rule_sections
        [
          rule_section(:competition, GameRoomRules.translate("Social billiards: your first game"),
            GameRoomRules.translate("New billiards tables select Social billiards for two to eight players, including computer players. The default layout is a diamond of balls 1\u20139 plus the white cue ball. Clear balls 1\u20138, then pot the 9-ball legally to win the round. The match is decided by round wins."),
            GameRoomRules.translate("Select an object ball with L or Shift+L and hear its position with I. Press A to aim at it, adjust direction and power with the arrows, then strike with Enter or Space on the Cue control. You do not call a ball or pocket in Social billiards. After the shot, listen to the outcome and whose turn comes next. The next chapter explains rounds, fouls and scoring; aiming controls follow.")),
          rule_section(:friendly, GameRoomRules.translate("Social rounds and fouls"),
            GameRoomRules.translate("Social billiards is for two to eight players, including computer players. Choose a total of 1 to 30 rounds. The match ends after that many rounds have been settled; the player with the most round wins wins the match. If several players share the most round wins, the match is a draw."),
            GameRoomRules.translate("The default diamond contains nine object balls, numbered 1\u20139, and the white cue ball. The 9-ball is the final ball. While other object balls remain, the cue ball must hit one of those first. A legal ordinary pot keeps your turn; without a pot, play passes to the next player. After contact, a ball must reach a cushion or an object ball must be potted."),
            GameRoomRules.translate("A scratch, wrong first ball or missing cushion gives the next player cue ball in hand anywhere: use M to place it. Other balls stay where they finish. If the final ball falls early or on a foul, the round ends and the next player in table order receives the round win. A legal final pot wins the round for the shooter. P starts the next round when offered. Arbitrary placement, undo and resetting an exercise are not part of this game."),
            GameRoomRules.translate("Alongside round wins, each legal object-ball pot earns 1 point, including a legal final ball. The cue ball earns no points. A foul shot or an early final-ball pot earns no pot points. These points accumulate across every round of the match; they do not decide round wins or break a tied match. S reads round wins and pot points aloud without opening a window; Shift+P includes both in the current match status.")),
          rule_section(:table, GameRoomRules.translate("Reading the table"),
            GameRoomRules.translate("X is measured from the left end and Y from the bottom cushion. Zero degrees points right, 90 up, 180 left and 270 down. C switches spoken directions to clock positions: three, twelve, nine and six. Pocket numbers run from 1 to 6: lower left, lower middle, lower right, upper left, upper middle, upper right. Carom tables have no pockets."),
            GameRoomRules.translate("O opens all ball positions, ordered by distance from the active cue ball, with pocketed balls last. L and Shift+L select an object ball; I describes its number or colour, sector, coordinates, distance and any obstruction. You can also reach the ball list with Tab and explore it with the arrows. The active cue is white in pool, your assigned white or yellow in English billiards and carom, or your chosen ball in Free Pyramid."),
            GameRoomRules.translate("In pool, the head string crosses the left quarter of the table; the foot spot is on the centre line at the right quarter. In snooker and English billiards, Baulk is the area to the left of the line 73.7 cm from the left end. The D is the semicircle of radius 29.2 cm on that side of the line. Carom\u2019s corner triangles extend 71 cm along the long cushion and 35.5 cm along the short cushion. The head spot is the centre of the head string; the area to its left is called the kitchen."),
            GameRoomRules.translate("- Pool: 254 by 127 cm."),
            GameRoomRules.translate("- Snooker and English billiards: 356.9 by 177.8 cm."),
            GameRoomRules.translate("- Carom: 284 by 142 cm, with no pockets."),
            GameRoomRules.translate("- Free Pyramid: 355 by 177.5 cm.")),
          rule_section(:aim, GameRoomRules.translate("Aiming and striking"),
            GameRoomRules.translate("Return to the Cue control with Tab. Left and Right turn anticlockwise and clockwise by one degree. Hold Shift for 0.1-degree steps or Ctrl for 0.01 degree. Up and Down change power by one percent, or 0.1 percent with Shift. Releasing an aiming arrow reads a short ball, cushion or pocket description. K reads the exact angle and F the power."),
            GameRoomRules.translate("While you turn the cue, short beeps guide your aim: 5000 Hz at the centre of the first ball on the shot line, falling to 500 Hz at either edge. Outside balls there is silence, except when aiming into a pocket. The tone follows side spin and your game sound settings, and stops when you leave the Cue control or open a dialog. These cues are local to your computer."),
            GameRoomRules.translate("Select an object ball and press A to aim at its centre. To aim for a pocket, choose that pocket with J, then press Shift+A. This geometric aid sets an angle; cushions, other balls, power and spin can still prevent the pot. G reports the first obstacle on the current line, including the side of a ball that will be contacted. H lists nearby balls within five degrees, including blocked ones."),
            GameRoomRules.translate("Press E to enter exact numbers. Both a decimal point and a decimal comma are accepted. Angle ranges from 0 to 359.99 degrees and power from 0.1 to 100 percent. Choose Apply to keep the settings or Cancel to retain the earlier ones. Enter or Space on the Cue control commits the shot.")),
          rule_section(:spin, GameRoomRules.translate("Spin"),
            GameRoomRules.translate("W adds follow spin; Shift+B adds draw spin. N adds left spin and D adds right spin. Each press changes the value by five. R returns to a centre-ball strike. Positive top spin helps the cue ball follow an object ball after contact; backspin can draw it back. Side spin changes cushion rebounds and slightly deflects the initial shot. These effects depend on power and distance: cloth friction can remove draw before the cue ball reaches its target."),
            GameRoomRules.translate("The two spin values range from -100 to 100. Together they must describe a point within the cue ball: maximum top spin cannot be combined with maximum side spin. The form rejects such a setting.")),
          rule_section(:feedback, GameRoomRules.translate("Listening to a shot"),
            GameRoomRules.translate("During play you hear the cue, ball collisions, cushions and pocket drops. The spoken outcome tells you what was hit and pocketed and gives the referee\u2019s decision. U opens the chronological contacts of the last shot, with angle, power and spin. Y calculates the current whole shot and shows its outcome and final positions without moving the real balls. Escape closes a report."),
            GameRoomRules.translate("With 3D sound (HRTF), cue strikes, ball collisions, cushions and pocket drops come from their positions on the table. The layout stays fixed: the table\u2019s left and right remain on your left and right, and the far side is in front of you. Aiming beeps always sound in the centre, including when HRTF is enabled. In Power Games Settings \u2192 Sounds, enable HRTF and select Billiards in the list of games using 3D sound. With HRTF off or unavailable, sounds remain in stereo."),
            GameRoomRules.translate("When the aiming line enters a pocket opening, a short 3000 Hz tone accompanies its number. The number is not repeated while you stay over that opening. Ball descriptions begin with the number or colour; pool balls 9 to 15 are striped."),
            GameRoomRules.translate("Point at a cushion and press V to calculate the active cue ball\u2019s rebound at your current power and spin. You hear the first cushion, the number of cushion contacts and any later ball contact or pocket entry. A shot too weak to reach the cushion is reported as such. This is a preview, not a played shot."),
            GameRoomRules.translate("B reads the objects farther along the aiming line, behind the first ball: other balls in order, then a cushion or pocket. Off-axis and rearward balls are omitted. B names a cushion or pocket directly if no ball is before it. This is the straight geometric line; use Y or Comma to calculate physical motion.")),
          rule_section(:object_prediction, GameRoomRules.translate("Predicting the ball you are aiming at"),
            GameRoomRules.translate("Point at an object ball and press Comma. This calculates the whole shot with the current angle, power and spin, then reports what happens to the first ball on your aiming line: its contacts and whether it enters a pocket or stops on the table. It does not replace that ball\u2019s motion with a straight aiming ray and does not play the shot. If no ball is on the line, you are told so. Y reports the whole shot with final positions, and V describes the active cue ball\u2019s cushion rebound.")),
          rule_section(:match, GameRoomRules.translate("Choosing a discipline and making decisions"),
            GameRoomRules.translate("The table settings select the discipline. Competitive pool, snooker, English billiards and carom require two players; Cutthroat requires three. The first listed player starts, and later racks or frames alternate the start. Competitive matches normally end at the chosen number of game wins. Points within a game are separate from those wins."),
            GameRoomRules.translate("P opens declarations and pending decisions. Choose the ball, pocket or other required details, confirm the choice, then use Enter or Space on the Cue control to strike. Enter asks for missing declarations. Shift+P reads the current rules situation, T whose turn it is, and S the scores without a separate window. M places the active cue only when the rules grant ball in hand. Q offers to concede the current game. A stalemate rerack proposed with P needs every other player\u2019s agreement; any refusal returns play to the proposer.")),
          rule_section(:pool_eight, GameRoomRules.translate("Pool: 8-ball"),
            GameRoomRules.translate("The table starts open. The break does not assign groups. On a later legal called pot you receive solids 1 to 7 or stripes 9 to 15, and your opponent receives the other group. Continue after pocketing your called ball in the called pocket. Hit your group first; after clearing it, play the 8-ball. On an open table, the 8-ball may be played only if an entire group is already absent and you declare the 8-ball."),
            GameRoomRules.translate("Except on the break, declare the ball and pocket before striking. P changes the declaration; Enter asks for any missing declaration. Safety ends your turn even if an object ball drops. Pocketing the 8-ball too early, with a foul or in the wrong pocket loses the rack. A scratch without potting the 8-ball is an ordinary foul. A wrong first ball or no pot and no cushion after contact is also a foul; the opponent receives cue ball in hand anywhere."),
            GameRoomRules.translate("If the break pots nothing, at least four different object balls must reach cushions. Otherwise the incoming player may accept the position or choose who reracks and breaks. An 8-ball potted on a legal break is spotted or the breaker may rerack. An 8-ball potted with a break foul gives those choices to the opponent, with cue ball in hand behind the head string if the position is retained. Other break fouls offer the current position or cue ball in hand behind that string. From there you cannot directly hit a ball in the head area without first crossing the string. P can request spotting the nearest legal ball if every legal ball is in that area.")),
          rule_section(:pool_nine, GameRoomRules.translate("Pool: 9-ball"),
            GameRoomRules.translate("Always hit the lowest numbered ball remaining first. Any legal object-ball pot continues your turn; a legal 9-ball pot wins, including a combination. Calls are not required. A foul gives the opponent cue ball in hand anywhere. The 9-ball returns to the foot spot if pocketed on a foul or push-out; other object balls stay down. Three consecutive fouls by the same player lose the rack; two are announced as a warning. A legal shot resets that player's foul count."),
            GameRoomRules.translate("The rack has the 9-ball on the foot spot and the 1-ball at the front. A break that pots nothing must send four object balls to cushions. The three-ball break rule also requires at least three different balls to be pocketed or cross the head string. If it fails without a foul, the opponent accepts the position or returns the shot; a potted 9-ball is spotted. Only a returned breaker may then push out. After an otherwise legal break, the second shot may be a push-out, declared with P: hitting the lowest ball and reaching a cushion are suspended. After a legal push-out the opponent chooses who plays next.")),
          rule_section(:pool_ten, GameRoomRules.translate("Pool: 10-ball"),
            GameRoomRules.translate("Hit the lowest remaining number first, but call a ball and pocket with P before each ordinary shot. There is no safety declaration. Making the call legally keeps your turn. The 10-ball wins only when it was the sole object ball remaining before the shot and enters the called pocket without a foul; earlier 10-balls are spotted."),
            GameRoomRules.translate("The break needs a pot or four different object balls at cushions. After a legal break, P can declare a push-out on the second shot; a legal push-out lets the opponent accept or return the shot. In ordinary play, pocketing a ball without making the call also gives the opponent that choice. A foul gives cue ball in hand anywhere; three consecutive fouls lose the rack.")),
          rule_section(:straight_pool, GameRoomRules.translate("Straight pool 14.1"),
            GameRoomRules.translate("Call a ball and pocket with P. When you make the call legally, every object ball potted on the shot scores 1 point and your turn continues. Reach the point target to win. A missed call or declared safety ends your turn and returns pocketed balls."),
            GameRoomRules.translate("The opening break starts behind the head string. Make your called pot or send the cue and at least two object balls to cushions after contact. Failure costs 2 points; the opponent accepts the position or requires another break. Ordinary fouls cost 1 point and may make your score negative. A scratch gives the opponent cue ball in hand behind the head string. The third consecutive ordinary foul costs 16 on that stroke and forces a fresh full-rack break; breaking fouls do not count in that sequence."),
            GameRoomRules.translate("After fourteen balls have scored, they are reracked with the apex empty, leaving the cue and last object ball where they are. Play continues without the opening spread requirement. If the last ball also fell, or both remaining balls obstruct the rack, all fifteen return. An obstructing object ball alone goes to the head spot, or centre if occupied. When only the cue obstructs, a last ball on or beyond the head string gives kitchen ball in hand; one behind the string sends the cue to the head spot, or centre if blocked."),
            GameRoomRules.translate("After an agreed stalemate rerack, scores and debts are retained and P offers the choice of new breaker. A new match game starts from zero.")),
          rule_section(:one_pocket, GameRoomRules.translate("One Pocket"),
            GameRoomRules.translate("Each player owns one of the two corner pockets at the right end. The breaker chooses theirs with P before the break. Each legal ball into your pocket gives you 1 point, even if the opponent pots it; the first to 8 wins. Your own legal pot keeps your turn. Other pockets\u2019 balls return after the turn, or immediately if the table empties before a win. A break needs contact followed by a rail or a pot, not four balls at cushions."),
            GameRoomRules.translate("A foul costs you 1 point and returns one of your scored balls. If none is available, you owe a ball: a future scoring pot repays the debt and is returned. Opponent-pocket balls still score on a foul unless the only foul was pocketing the cue ball. A cue ball off the table or a scratch with another foul does not cancel those opponent points. A scratch gives kitchen ball in hand. Three consecutive fouls lose the game. If both players reach 8 on the same shot, the shooter wins. An agreed stalemate keeps scores and debts and asks for a new breaker and pockets.")),
          rule_section(:bank, GameRoomRules.translate("Bank Pool: short and full rack"),
            GameRoomRules.translate("A scoring bank needs a declared ball, pocket and ordered cushion route. Under P choose the ball and pocket, then add each next cushion: left, right, top or bottom. Finish the route when complete; one to twelve contacts may be declared. Cancelling leaves the previous declaration intact. The cue must hit the called ball before any cushion or other ball. The called ball may not then hit another ball or the cue again. Its cushions must follow the call; incidental jaw contacts while entering the destination pocket are omitted."),
            GameRoomRules.translate("A valid bank gives 1 point and keeps your turn. Short-rack Bank Pool uses 9 balls and a target of 5; full-rack Bank Pool uses 15 and a target of 8. Extra pocketed balls wait until your turn ends before returning, or return immediately if the table empties before a win. Do not declare a bank on the break: any pot continues but earns no point. With no pot, four different object balls must reach cushions; an inadequate break lets the opponent accept or require another break."),
            GameRoomRules.translate("A foul costs 1 point and returns a scored ball. Without one, your debt is repaid by returning a later scoring ball; scores may be negative. A scratch gives kitchen ball in hand. Three consecutive fouls lose the game. Scores and debts survive an agreed stalemate rerack, followed by a P choice of new breaker.")),
          rule_section(:cutthroat, GameRoomRules.translate("Cutthroat for three players"),
            GameRoomRules.translate("This club variant assigns fixed groups in seat order: 1\u20135, 6\u201310 and 11\u201315. Protect your own group and remove the others. Any object ball may be hit first, and you may sacrifice one of your own balls. A legal pot continues your turn unless it removed your last ball. Players with no balls are temporarily skipped; the last group remaining wins."),
            GameRoomRules.translate("A foul gives the next player cue ball in hand anywhere and returns one pocketed ball for each opponent, choosing the lowest absent number in that group. This can bring a skipped player back into play. Three-foul rack loss is not used. If one legal shot removes every group, the round is a draw. This fixed-group version does not use a negotiation to claim groups. Conceding with Q removes all balls in your group and prevents their revival for the rest of this rack; the remaining players continue.")),
          rule_section(:blackball, GameRoomRules.translate("Blackball"),
            GameRoomRules.translate("Play your group of solids or stripes, then black. Calls are not required. The table stays open after the break and free shots; groups are assigned by a later legal ordinary pot. A legal pot keeps your turn. Potting the last of your group and black together is a legal win; potting black with a foul or before clearing your group loses the rack. Black on the break instead reracks for the same breaker."),
            GameRoomRules.translate("A legal break pots a ball or sends at least two different object balls across the centre line. A foul grants one free shot followed by one normal shot. For the free shot, play from the current position or use M to move the cue into baulk, the leftmost fifth of the table. The free shot suspends wrong-first-ball only: potting only the opponent\u2019s balls is still a foul. After the normal shot, continuation again needs a legal pot. When fully snookered with no path to any part of a ball on, the usual cushion requirement is suspended. A touching ball on must be played away from without pushing it.")),
          rule_section(:snooker, GameRoomRules.translate("Snooker"),
            GameRoomRules.translate("There are fifteen reds, worth one point each, and yellow 2, green 3, brown 4, blue 5, pink 6 and black 7. Red balls have IDs 1 to 15; colours have IDs 16 to 21 in that order. Pot a red, nominate a colour with P or when Enter asks, then alternate red and colour. Multiple reds may score in one stroke. Colours return to their spots during this phase, including after a foul. Reds normally remain pocketed. After the last red you may still play one colour, then clear yellow through black in order without replacing legally potted colours."),
            GameRoomRules.translate("A foul gives the opponent 4 to 7 points: use the highest applicable value among the ball on and illegally contacted or pocketed balls. No points are scored by the offender on that stroke. The opponent chooses to play or asks the offender to play again. Cue-ball scratches give placement inside the D only; M moves only the cue ball and leaves all other final positions alone. Occupied colour spots use the highest free spot, then the nearest legal position toward the black end, with the pink/black exception toward the other end when necessary."),
            GameRoomRules.translate("After a foul, a snooker on every ball on permits nomination of a free ball with P. Both extreme edges of a ball on must be available to avoid a snooker; a cushion does not count as a blocking ball. If the cue ball is in hand, the whole D is checked at the recorded placement precision. A nominated free ball takes the value of the ball on and returns to its spot if potted. It may not itself leave a non-scoring snooker except in the final two-ball exception."),
            GameRoomRules.translate("If a direct path was available but the first required contact was missed, the referee may call Foul and a Miss. The opponent can restore the previous balls and ask the offender to retry; penalty points remain. Two restored full-ball misses cause a warning, and another failure loses the frame. Ordinary Miss is not called when penalty points are already needed or become needed after the stroke. When only black remains, the first pot or foul settles the frame. A tied score respots black, draws a choice of player and gives cue ball in hand in the D; the next pot or foul decides it.")),
          rule_section(:english, GameRoomRules.translate("English billiards"),
            GameRoomRules.translate("Each player keeps their own white or yellow cue ball; red is shared. On the opening turn red is on its spot and the starting cue ball is played from the D. The other player\u2019s ball is initially off the table and enters when that player first needs it. Score up to the chosen point target, or lead when the selected time ends. A scoring stroke keeps your turn."),
            GameRoomRules.translate("One stroke can combine several scores:"),
            GameRoomRules.translate("- A cannon means your cue ball contacts both other balls. It scores 2 points, once per stroke."),
            GameRoomRules.translate("- Potting red scores 3; potting the other player\u2019s ball scores 2."),
            GameRoomRules.translate("- Your cue ball entering a pocket after contacting red scores 3; after the opponent\u2019s ball it scores 2. When both were hit, the first contact decides; an unresolved simultaneous first contact gives 2."),
            GameRoomRules.translate("After an in-off, use M to place your cue in the D. You must play out of Baulk before directly playing a ball whose centre is in Baulk, including on the line; when returning into Baulk, a cushion or ball outside it must have been contacted first. A legal English Miss when all targets are in Baulk gives the opponent 2 points and play from the resulting position. A foul instead gives 2 points, cancels that stroke\u2019s scores and offers P decisions: accept the position or reset red and the opponent\u2019s ball, then play from the D."),
            GameRoomRules.translate("Red is respotted after a pot. Repeated red-only pots from its spot follow two pots on the normal spot, then one from the centre, with substitute spots when occupied. The opponent\u2019s potted ball usually stays off the table until needed. A cue ball touching another ball triggers red\u2019s spot, the opponent\u2019s centre spot if that ball is present, and cue ball in hand in the D."),
            GameRoomRules.translate("A run may contain at most 75 cannon-only strokes or 15 hazard strokes without a cannon; a hazard is a pot or in-off. Warnings come at 70 and 10. Combining a cannon and hazard breaks both sequences. A special fifteenth-hazard respot applies when the opponent\u2019s ball was left off the table by that opponent\u2019s last turn. If Baulk crossing is enabled in settings, you must make the required inward crossing during each break\u2019s 80\u2013100 point interval; failure is a foul.")),
          rule_section(:carom, GameRoomRules.translate("Carom: straight rail, one cushion and three cushions"),
            GameRoomRules.translate("There are three balls on a pocketless table. Keep your assigned white or yellow cue throughout the game. A cannon means your cue contacts both other balls in one stroke. A legal cannon gives 1 point and keeps your inning; a miss or foul passes play without a point penalty. Reach the selected point target to win, subject to the equalizing-inning setting. With equalizing enabled, if the opening player reaches the target after one more inning, the other player gets one final inning from the starting position. Reaching the target then draws the game; ending that inning short of it gives the opening player the win. With equalizing disabled, reaching the target wins immediately."),
            GameRoomRules.translate("At the start, P lets you choose the lower or upper starting spot. Your first attack must be directly on red. The disciplines then differ as follows:"),
            GameRoomRules.translate("- Straight rail needs no cushion contact. Its four marked corner triangles restrict repeated cannons."),
            GameRoomRules.translate("- One cushion needs at least one contact by your cue with a cushion before it touches the second different object ball."),
            GameRoomRules.translate("- Three cushions needs at least three such contacts. Separate impacts on the same cushion count, and impacts before the first object ball also count. Impacts after the second object ball do not repair a missed cannon."),
            GameRoomRules.translate("In a straight-rail corner, after both object balls enter, you may make one cannon without either leaving. On the following cannon at least one must leave that triangle; it may return during the same stroke. A ball on the boundary is treated against the player. The programme follows the whole movement, not only where the balls stop."),
            GameRoomRules.translate("If your cue touches an object ball, straight rail restores all three to the opening position. In the cushion games P offers playing away without pushing the touching ball or respotting. One cushion resets all three; three cushions replaces only the touching balls on their assigned spots. Driving a frozen cue directly into its cushion is a foul. An off-table ball resets all three in straight rail and one cushion, but only the escaped balls in three cushions.")),
          rule_section(:pyramid, GameRoomRules.translate("Free Pyramid"),
            GameRoomRules.translate("Score 8 points before your opponent. All sixteen balls have the same value: 1 point for every legal pot, including your cue ball after it contacts another ball. No ball or pocket call is needed. Before each shot after the break, use P and Choose the cue ball to select any ball still on the table. A legal pot keeps your turn and gives you a fresh choice of cue."),
            GameRoomRules.translate("The opening shot uses the coloured ball from behind the home line at the left quarter. After hitting an object ball, either pot a ball, send three different object balls to cushions, or send two to cushions and an object ball across the centre line."),
            GameRoomRules.translate("In later shots, after the required ball contact, one of the following must happen:"),
            GameRoomRules.translate("- A ball is potted."),
            GameRoomRules.translate("- A ball rebounds from a cushion and then reaches another cushion, directly or by driving another ball there. Contact with a ball frozen to that other cushion can also satisfy the condition."),
            GameRoomRules.translate("- A ball crosses the centre and then reaches a cushion, directly or by transmitting movement to another ball; a frozen ball at that cushion also counts."),
            GameRoomRules.translate("- After a cushion rebound, a ball crosses the centre, drives another across, or contacts a ball on the opposite half or centre line; the corresponding transmitted contacts also count."),
            GameRoomRules.translate("If you foul, all illegally potted and escaped balls are spotted first. Under P your opponent selects any table ball as the penalty ball, removes it and gains 1 point. They then choose to play or return the shot. After an illegal break they can also rerack and choose who breaks; the penalty point stays and the new pyramid is incomplete. An ordinary cue-ball pot is not automatically a foul here: it scores when made legally after contact. Multiple fouls in one shot incur one penalty."),
            GameRoomRules.translate("Spotted balls go from the foot spot toward the right end along the centre line, then backward if space runs out. They may become the next cue ball. The larger balls and narrow jaws need more precise aim than pool; a line toward a pocket is not a promise that the ball will pass its jaws.")),
          rule_section(:settings, GameRoomRules.translate("Match settings"),
            GameRoomRules.translate("Before play, choose the discipline and its winning target. Social billiards uses a total of 1 to 30 rounds and one of three layouts. Where the discipline permits it, choose its point target; its match target counts game wins. English billiards can instead run for the selected time: a shot already started when time expires is allowed to finish, and equal final scores are a draw. Carom\u2019s equalizing-inning option gives the second player a final inning from the starting position when needed to equal the number of innings. In timed English billiards, an accepted shot must reach the table before the time limit; pressing a key before it expires is not enough."),
            GameRoomRules.translate("Social billiards starts with the nine-ball diamond. In table settings you can instead select one object ball or the fifteen-ball triangle; their final balls are 1 and 15 respectively. An explicit layout choice and an older saved game keep their selected layout."),
            GameRoomRules.translate("The match target is 1 to 25 game wins. Adjustable point targets range from 1 to 1000; English time limits range from 1 to 180 minutes."),
            GameRoomRules.translate("More accurate physics uses smaller calculation steps and may change the result of a close contact. Computer strength controls how many candidate shots a bot compares. Spin and power remain part of every shot, including previews."),
            GameRoomRules.translate("Only older saved practice games use the limit of 1 to 500 shots; it does not apply to new games.")),
          rule_section(:referee, GameRoomRules.translate("Rules and digital adaptations"),
            GameRoomRules.translate("Pool follows WPA Rules and Regulations effective 21 October 2026; snooker and English billiards use WPBSA 2024\u201325, carom uses UMB rules, and Free Pyramid uses IPC\u2019s 2025 revision. Cutthroat and Social billiards use the club rules described here. Table order replaces a physical lag. Agreement to rerack does not itself award a game win. The snooker referee calls automatic Miss only with a direct path; entirely obstructed attempts remain ordinary fouls without restoration."),
            GameRoomRules.translate("The simulation is two-dimensional: no jumps, cue elevation or mass\u00E9 controls. Frozen-ball pushes and pocket jaws are approximations. First contacts unresolved within the same physics step are treated as simultaneous. Pyramid uses a documented training geometry with large balls and tight pockets; this is not certification of current federation equipment. Directional aids and previews use the active cue and the same physics as play.")),
          rule_section(:controls, GameRoomRules.translate("Keyboard shortcuts"),
            GameRoomRules.translate("K: Read cue direction."),
            GameRoomRules.translate("F: Read shot power."),
            GameRoomRules.translate("G: Read the first contact on the shot line."),
            GameRoomRules.translate("H: List balls near the shot line."),
            GameRoomRules.translate("I: Describe the selected ball."),
            GameRoomRules.translate("O: List all balls and their positions."),
            GameRoomRules.translate("L: Select the next object ball."),
            GameRoomRules.translate("Shift+L: Select the previous object ball."),
            GameRoomRules.translate("J: Choose a target pocket."),
            GameRoomRules.translate("A: Aim at the centre of the selected ball."),
            GameRoomRules.translate("Shift+A: Aim the selected ball towards the chosen pocket."),
            GameRoomRules.translate("E: Enter exact angle, power and spin."),
            GameRoomRules.translate("W: Increase follow spin."),
            GameRoomRules.translate("Shift+B: Increase draw spin."),
            GameRoomRules.translate("N: Increase left spin."),
            GameRoomRules.translate("D: Increase right spin."),
            GameRoomRules.translate("R: Remove spin."),
            GameRoomRules.translate("C: Switch between degrees and clock directions."),
            GameRoomRules.translate("Y: Predict this shot without moving the balls."),
            GameRoomRules.translate("U: Read contacts from the last shot."),
            GameRoomRules.translate("Left: turn anticlockwise by 1 degree."),
            GameRoomRules.translate("Right: turn clockwise by 1 degree."),
            GameRoomRules.translate("Shift+Left: turn anticlockwise by 0.1 degree."),
            GameRoomRules.translate("Shift+Right: turn clockwise by 0.1 degree."),
            GameRoomRules.translate("Ctrl+Left: turn anticlockwise by 0.01 degree."),
            GameRoomRules.translate("Ctrl+Right: turn clockwise by 0.01 degree."),
            GameRoomRules.translate("Up: increase power by 1 percent."),
            GameRoomRules.translate("Down: decrease power by 1 percent."),
            GameRoomRules.translate("Shift+Up: increase power by 0.1 percent."),
            GameRoomRules.translate("Shift+Down: decrease power by 0.1 percent."),
            GameRoomRules.translate("Enter or Space: play the current shot."),
            GameRoomRules.translate("T: read whose turn it is."),
            GameRoomRules.translate("V: Predict the cushion rebound and next ball contact."),
            GameRoomRules.translate("B: Describe objects behind the aimed ball."),
            GameRoomRules.translate("S: Read scores aloud, including Social round wins and pot points."),
            GameRoomRules.translate("M: Place the active cue ball when in hand."),
            GameRoomRules.translate("P: Open declarations, cue choice or a pending match decision."),
            GameRoomRules.translate("Shift+P: Read the current match situation."),
            GameRoomRules.translate("Q: Concede the current round, rack or frame after confirmation."),
            GameRoomRules.translate("Comma: Predict the first aimed ball with the current power and spin."))
        ]
      end

      def localized_rule_sections
        case GameRoomLocalization.primary_language
        when "cs"
          [
            rule_section(:competition, "Spole\u010Densk\u00FD kule\u010Dn\u00EDk: prvn\u00ED hra",
              "Nov\u00E9 kule\u010Dn\u00EDkov\u00E9 stoly maj\u00ED p\u0159edvolen\u00FD spole\u010Densk\u00FD kule\u010Dn\u00EDk pro dva a\u017E osm hr\u00E1\u010D\u016F v\u010Detn\u011B po\u010D\u00EDta\u010Dov\u00FDch. V\u00FDchoz\u00ED rozestaven\u00ED je koso\u010Dtverec koul\u00ED 1\u20139 a b\u00EDl\u00E1 hrac\u00ED koule. Odstra\u0148te koule 1\u20138 a potom spr\u00E1vn\u011B potopte dev\u00EDtku, abyste vyhr\u00E1li kolo. O v\u00EDt\u011Bzi z\u00E1pasu rozhoduj\u00ED vyhran\u00E1 kola.",
              "Vyberte hranou kouli kl\u00E1vesou L nebo Shift+L a p\u0159e\u010Dt\u011Bte jej\u00ED polohu pomoc\u00ED I. Stiskn\u011Bte A pro zam\u00ED\u0159en\u00ED, upravte sm\u011Br a s\u00EDlu \u0161ipkami a prove\u010Fte strk Enterem nebo mezern\u00EDkem na prvku t\u00E1ga. Ve spole\u010Densk\u00E9m kule\u010Dn\u00EDku se koule ani kapsa nehl\u00E1s\u00ED. Po strku usly\u0161\u00EDte v\u00FDsledek i dal\u0161\u00EDho hr\u00E1\u010De. N\u00E1sleduj\u00EDc\u00ED kapitola vysv\u011Btluje kola, fauly a bodov\u00E1n\u00ED, dal\u0161\u00ED pak m\u00ED\u0159en\u00ED."),
            rule_section(:friendly, "Spole\u010Densk\u00E1 kola a fauly",
              "Spole\u010Densk\u00FD kule\u010Dn\u00EDk je pro dva a\u017E osm hr\u00E1\u010D\u016F v\u010Detn\u011B po\u010D\u00EDta\u010Dov\u00FDch. Vyberte celkem 1 a\u017E 30 kol. Z\u00E1pas kon\u010D\u00ED po rozhodnut\u00ED tohoto po\u010Dtu kol; vyhraje hr\u00E1\u010D s nejv\u011Bt\u0161\u00EDm po\u010Dtem v\u00EDt\u011Bzn\u00FDch kol. P\u0159i stejn\u00E9m nejvy\u0161\u0161\u00EDm po\u010Dtu vyhran\u00FDch kol skon\u010D\u00ED z\u00E1pas rem\u00EDzou.",
              "V\u00FDchoz\u00ED koso\u010Dtverec obsahuje dev\u011Bt hran\u00FDch koul\u00ED s \u010D\u00EDsly 1\u20139 a b\u00EDlou hrac\u00ED kouli. Z\u00E1v\u011Bre\u010Dnou koul\u00ED je dev\u00EDtka. Dokud zb\u00FDvaj\u00ED jin\u00E9 hran\u00E9 koule, mus\u00ED b\u00EDl\u00E1 nejprve zas\u00E1hnout n\u011Bkterou z nich. Spr\u00E1vn\u00E9 potopen\u00ED b\u011B\u017En\u00E9 koule v\u00E1m zachov\u00E1 tah; bez potopen\u00ED hraje dal\u0161\u00ED hr\u00E1\u010D. Po kontaktu mus\u00ED n\u011Bkter\u00E1 koule zas\u00E1hnout mantinel nebo mus\u00ED b\u00FDt potopena hran\u00E1 koule.",
              "Potopen\u00ED b\u00EDl\u00E9, z\u00E1sah nespr\u00E1vn\u00E9 koule jako prvn\u00ED nebo chyb\u011Bj\u00EDc\u00ED mantinel d\u00E1vaj\u00ED dal\u0161\u00EDmu hr\u00E1\u010Di b\u00EDlou do ruky kdekoli na stole; um\u00EDst\u00ED ji pomoc\u00ED M. Ostatn\u00ED koule z\u016Fst\u00E1vaj\u00ED na sv\u00FDch m\u00EDstech. P\u0159ed\u010Dasn\u00E9 potopen\u00ED z\u00E1v\u011Bre\u010Dn\u00E9 koule nebo jej\u00ED potopen\u00ED s faulem ukon\u010D\u00ED kolo a v\u00EDt\u011Bzstv\u00ED p\u0159ipadne n\u00E1sleduj\u00EDc\u00EDmu hr\u00E1\u010Di v po\u0159ad\u00ED u stolu. Spr\u00E1vn\u00E9 potopen\u00ED z\u00E1v\u011Bre\u010Dn\u00E9 koule vyhraje kolo st\u0159elci. P nab\u00EDz\u00ED zah\u00E1jen\u00ED dal\u0161\u00EDho kola. Libovoln\u00E9 p\u0159esouv\u00E1n\u00ED koul\u00ED, vracen\u00ED strk\u016F a obnoven\u00ED cvi\u010Dn\u00E9ho rozestaven\u00ED zde nejsou dostupn\u00E9.",
              "Vedle vyhran\u00FDch kol z\u00EDsk\u00E1v\u00E1te 1 bod za ka\u017Edou spr\u00E1vn\u011B potopenou hranou kouli, v\u010Detn\u011B spr\u00E1vn\u011B potopen\u00E9 z\u00E1v\u011Bre\u010Dn\u00E9. B\u00EDl\u00E1 body ned\u00E1v\u00E1. Strk s faulem nebo p\u0159ed\u010Dasn\u00FDm potopen\u00EDm z\u00E1v\u011Bre\u010Dn\u00E9 koule nep\u0159in\u00E1\u0161\u00ED body za potopen\u00ED. Body se s\u010D\u00EDtaj\u00ED p\u0159es v\u0161echna kola z\u00E1pasu; nerozhoduj\u00ED o v\u00EDt\u011Bzstv\u00ED v kole. P\u0159i shodn\u00E9m nejvy\u0161\u0161\u00EDm po\u010Dtu vyhran\u00FDch kol z\u016Fst\u00E1v\u00E1 z\u00E1pas rem\u00EDzou i p\u0159i rozd\u00EDln\u00E9m po\u010Dtu bod\u016F. S p\u0159e\u010Dte vyhran\u00E1 kola i body za potopen\u00ED bez otev\u0159en\u00ED okna; Shift+P uvede ob\u011B hodnoty v aktu\u00E1ln\u00EDm stavu z\u00E1pasu."),
            rule_section(:table, "Orientace na stole",
              "X ud\u00E1v\u00E1 vzd\u00E1lenost od lev\u00E9ho konce, Y od doln\u00EDho mantinelu. Nula stup\u0148\u016F m\u00ED\u0159\u00ED doprava, 90 nahoru, 180 doleva a 270 dol\u016F. C p\u0159ep\u00EDn\u00E1 sm\u011Bry na hodiny: t\u0159i, dvan\u00E1ct, dev\u011Bt a \u0161est. Kapsy 1 a\u017E 6 jsou dole vlevo, dole uprost\u0159ed, dole vpravo, naho\u0159e vlevo, naho\u0159e uprost\u0159ed a naho\u0159e vpravo. Karambolov\u00FD st\u016Fl kapsy nem\u00E1.",
              "O otev\u0159e p\u0159ehled poloh v\u0161ech koul\u00ED, se\u0159azen\u00FD podle vzd\u00E1lenosti od aktivn\u00ED hrac\u00ED koule; potopen\u00E9 koule jsou na konci. L a Shift+L vyb\u00EDraj\u00ED hranou kouli; I pop\u00ED\u0161e jej\u00ED \u010D\u00EDslo \u010Di barvu, sektor, sou\u0159adnice, vzd\u00E1lenost a p\u0159ek\u00E1\u017Eky. Na seznam koul\u00ED m\u016F\u017Eete p\u0159ej\u00EDt i Tabem a proch\u00E1zet jej \u0161ipkami. V poolu hrajete b\u00EDlou, v anglick\u00E9m kule\u010Dn\u00EDku a karambolu p\u0159id\u011Blenou b\u00EDlou nebo \u017Elutou; ve voln\u00E9 pyramid\u011B si hrac\u00ED kouli vyb\u00EDr\u00E1te.",
              "V poolu vede p\u0159edn\u00ED \u010D\u00E1ra p\u0159es levou \u010Dtvrtinu stolu a zadn\u00ED bod le\u017E\u00ED na pod\u00E9ln\u00E9 ose v prav\u00E9 \u010Dtvrtin\u011B. Ve snookeru a anglick\u00E9m kule\u010Dn\u00EDku je baulk oblast vlevo od \u010D\u00E1ry vzd\u00E1len\u00E9 73,7 cm od lev\u00E9ho konce. D je p\u016Flkruh s polom\u011Brem 29,2 cm na t\u00E9to stran\u011B \u010D\u00E1ry. Rohov\u00E9 troj\u00FAheln\u00EDky karambolu sahaj\u00ED 71 cm pod\u00E9l dlouh\u00E9ho mantinelu a 35,5 cm pod\u00E9l kr\u00E1tk\u00E9ho. P\u0159edn\u00ED bod je st\u0159ed p\u0159edn\u00ED \u010D\u00E1ry, naz\u00FDvan\u00E9 tak\u00E9 \u010D\u00E1rou rozbit\u00ED.",
              "- Pool: 254 kr\u00E1t 127 cm.",
              "- Snooker a anglick\u00FD kule\u010Dn\u00EDk: 356,9 kr\u00E1t 177,8 cm.",
              "- Karambol: 284 kr\u00E1t 142 cm, bez kapes.",
              "- Voln\u00E1 pyramida: 355 kr\u00E1t 177,5 cm."),
            rule_section(:aim, "M\u00ED\u0159en\u00ED a strk",
              "Vra\u0165te se Tabem na prvek t\u00E1ga. Vlevo a Vpravo ot\u00E1\u010Dej\u00ED proti sm\u011Bru a po sm\u011Bru hodinov\u00FDch ru\u010Di\u010Dek o jeden stupe\u0148. Shift zmen\u0161\u00ED krok na 0,1 stupn\u011B, Ctrl na 0,01. Nahoru a Dol\u016F m\u011Bn\u00ED s\u00EDlu o jedno procento, se Shiftem o 0,1 procenta. Po uvoln\u011Bn\u00ED m\u00ED\u0159ic\u00ED \u0161ipky zazn\u00ED kr\u00E1tk\u00FD popis koule, mantinelu \u010Di kapsy. K p\u0159e\u010Dte p\u0159esn\u00FD \u00FAhel, F s\u00EDlu.",
              "P\u0159i ot\u00E1\u010Den\u00ED t\u00E1ga pom\u00E1haj\u00ED kr\u00E1tk\u00E1 p\u00EDpnut\u00ED naj\u00EDt kouli: st\u0159ed prvn\u00ED koule v dr\u00E1ze strku m\u00E1 t\u00F3n 5000 Hz, kter\u00FD sm\u011Brem k ob\u011Bma okraj\u016Fm kles\u00E1 a\u017E na 500 Hz. Mimo koule je ticho, krom\u011B m\u00ED\u0159en\u00ED do kapsy. T\u00F3n zohled\u0148uje bo\u010Dn\u00ED rotaci a nastaven\u00ED zvuk\u016F hry. Ztichne po opu\u0161t\u011Bn\u00ED prvku T\u00E1go nebo otev\u0159en\u00ED dialogu. Sly\u0161\u00EDte jej pouze na sv\u00E9m po\u010D\u00EDta\u010Di.",
              "Vyberte kouli a stiskn\u011Bte A pro zam\u00ED\u0159en\u00ED na jej\u00ED st\u0159ed. Pro pokus o potopen\u00ED vyberte kapsu kl\u00E1vesou J a stiskn\u011Bte Shift+A. Tato geometrick\u00E1 pom\u016Fcka nastav\u00ED \u00FAhel; mantinel, jin\u00E9 koule, s\u00EDla a rotace mohou potopen\u00ED st\u00E1le zabr\u00E1nit. G popisuje prvn\u00ED p\u0159ek\u00E1\u017Eku na z\u00E1m\u011Brn\u00E9 p\u0159\u00EDmce v\u010Detn\u011B strany kontaktu s koul\u00ED. H p\u0159e\u010Dte koule do p\u011Bti stup\u0148\u016F od t\u00E9to p\u0159\u00EDmky, i ty zakryt\u00E9.",
              "Kl\u00E1vesa E otev\u0159e formul\u00E1\u0159 p\u0159esn\u00FDch hodnot. Lze pou\u017E\u00EDt desetinnou te\u010Dku i \u010D\u00E1rku. \u00DAhel je od 0 do 359,99 stupn\u011B, s\u00EDla od 0,1 do 100 procent. Tla\u010D\u00EDtkem Pou\u017E\u00EDt nastaven\u00ED zachov\u00E1te, tla\u010D\u00EDtkem Zru\u0161it ponech\u00E1te p\u016Fvodn\u00ED. Enter nebo mezern\u00EDk na ovl\u00E1dac\u00EDm prvku T\u00E1go provede strk."),
            rule_section(:spin, "Rotace",
              "W p\u0159id\u00E1v\u00E1 horn\u00ED rotaci, Shift+B spodn\u00ED. N p\u0159id\u00E1v\u00E1 levou bo\u010Dn\u00ED rotaci, D pravou. Ka\u017Ed\u00FD stisk m\u011Bn\u00ED hodnotu o p\u011Bt. R obnov\u00ED \u00FAder do st\u0159edu bez rotace. Horn\u00ED rotace pom\u00E1h\u00E1 hrac\u00ED kouli pokra\u010Dovat za zasa\u017Eenou koul\u00ED, spodn\u00ED ji m\u016F\u017Ee vr\u00E1tit zp\u011Bt. Bo\u010Dn\u00ED rotace m\u011Bn\u00ED odrazy od mantinel\u016F a m\u00EDrn\u011B vychyluje po\u010D\u00E1te\u010Dn\u00ED sm\u011Br. \u00DA\u010Dinek z\u00E1vis\u00ED na s\u00EDle a vzd\u00E1lenosti: t\u0159en\u00ED o pl\u00E1tno m\u016F\u017Ee spodn\u00ED rotaci vy\u010Derpat je\u0161t\u011B p\u0159ed kontaktem.",
              "Ob\u011B hodnoty rotace jsou od -100 do 100. Spole\u010Dn\u011B mus\u00ED odpov\u00EDdat bodu uvnit\u0159 hrac\u00ED koule: maxim\u00E1ln\u00ED horn\u00ED rotaci nelze spojit s maxim\u00E1ln\u00ED bo\u010Dn\u00ED. Formul\u00E1\u0159 takov\u00E9 nastaven\u00ED odm\u00EDtne."),
            rule_section(:feedback, "Poslech strku",
              "P\u0159i h\u0159e sly\u0161\u00EDte t\u00E1go, sr\u00E1\u017Eky koul\u00ED, mantinely a p\u00E1dy do kapes. Slovn\u00ED v\u00FDsledek ozn\u00E1m\u00ED z\u00E1sahy, potopen\u00ED a rozhodnut\u00ED rozhod\u010D\u00EDho. U otev\u0159e \u010Dasov\u00FD seznam kontakt\u016F posledn\u00EDho strku v\u010Detn\u011B \u00FAhlu, s\u00EDly a rotace. Y vypo\u010Dte cel\u00FD aktu\u00E1ln\u00ED strk a uk\u00E1\u017Ee v\u00FDsledek i kone\u010Dn\u00E9 polohy bez pohybu skute\u010Dn\u00FDch koul\u00ED. Escape zpr\u00E1vu zav\u0159e.",
              "P\u0159i 3D zvuku (HRTF) sly\u0161\u00EDte \u00FAder t\u00E1ga, sr\u00E1\u017Eky koul\u00ED, mantinely a p\u00E1dy do kapes z jejich m\u00EDst na stole. Rozlo\u017Een\u00ED je st\u00E1l\u00E9: lev\u00E1 a prav\u00E1 strana stolu z\u016Fst\u00E1vaj\u00ED po va\u0161\u00ED levici a pravici, vzd\u00E1len\u00E1 \u010D\u00E1st je p\u0159ed v\u00E1mi. P\u00EDp\u00E1n\u00ED p\u0159i m\u00ED\u0159en\u00ED zn\u00ED v\u017Edy uprost\u0159ed, i p\u0159i zapnut\u00E9m HRTF. V Power Games otev\u0159ete Nastaven\u00ED \u2192 Zvuky, zapn\u011Bte HRTF a v seznamu her s 3D zvukem ozna\u010Dte Kule\u010Dn\u00EDk. P\u0159i vypnut\u00E9m nebo nedostupn\u00E9m HRTF z\u016Fst\u00E1v\u00E1 zvuk stereofonn\u00ED.",
              "Kdy\u017E p\u0159\u00EDmka m\u00ED\u0159en\u00ED vstoup\u00ED do otvoru kapsy, zazn\u00ED jej\u00ED \u010D\u00EDslo s kr\u00E1tk\u00FDm t\u00F3nem 3000 Hz. \u010C\u00EDslo se neopakuje, dokud z\u016Fst\u00E1v\u00E1te u stejn\u00E9ho otvoru. Popisy koul\u00ED za\u010D\u00EDnaj\u00ED \u010D\u00EDslem \u010Di barvou; poolov\u00E9 koule 9\u201315 jsou p\u016Flen\u00E9.",
              "Zami\u0159te na mantinel a stiskn\u011Bte V pro v\u00FDpo\u010Det odrazu aktivn\u00ED hrac\u00ED koule p\u0159i aktu\u00E1ln\u00ED s\u00EDle a rotaci. Usly\u0161\u00EDte prvn\u00ED mantinel, po\u010Det kontakt\u016F a pozd\u011Bj\u0161\u00ED z\u00E1sah koule nebo vstup do kapsy. P\u0159\u00EDli\u0161 slab\u00FD strk, kter\u00FD k mantinelu nedojde, je ozn\u00E1men. Jde o p\u0159edpov\u011B\u010F, nikoli proveden\u00FD strk.",
              "B p\u0159e\u010Dte objekty d\u00E1le po p\u0159\u00EDmce m\u00ED\u0159en\u00ED za prvn\u00ED koul\u00ED: dal\u0161\u00ED koule v po\u0159ad\u00ED, potom mantinel \u010Di kapsu. Koule mimo sm\u011Br a za hrac\u00ED koul\u00ED vynech\u00E1. Nen\u00ED-li p\u0159ed mantinelem \u010Di kapsou koule, B je p\u0159\u00EDmo pojmenuje. Jde o geometrickou p\u0159\u00EDmku; fyzik\u00E1ln\u00ED pohyb vypo\u010Dtete pomoc\u00ED Y nebo \u010D\u00E1rky."),
            rule_section(:object_prediction, "P\u0159edpov\u011B\u010F zam\u011B\u0159en\u00E9 koule",
              "Zami\u0159te na hranou kouli a stiskn\u011Bte \u010D\u00E1rku. Vypo\u010D\u00EDt\u00E1 se cel\u00FD strk p\u0159i aktu\u00E1ln\u00EDm \u00FAhlu, s\u00EDle a rotaci; potom usly\u0161\u00EDte pohyb prvn\u00ED koule ve sm\u011Bru m\u00ED\u0159en\u00ED: jej\u00ED kontakty a to, zda spadne do kapsy, nebo se zastav\u00ED na stole. Jde o v\u00FDsledek fyziky strku, nikoli o pouh\u00E9 prodlou\u017Een\u00ED p\u0159\u00EDmky. P\u0159edpov\u011B\u010F strk neprovede. Pokud ve sm\u011Bru m\u00ED\u0159en\u00ED koule nen\u00ED, dostanete tuto informaci. Y popisuje cel\u00FD strk i kone\u010Dn\u00E9 polohy, V odraz aktivn\u00ED hrac\u00ED koule od mantinelu."),
            rule_section(:match, "Volba discipl\u00EDny a rozhodov\u00E1n\u00ED",
              "Discipl\u00EDnu zvol\u00EDte v nastaven\u00ED stolu. Sout\u011B\u017En\u00ED pool, snooker, anglick\u00FD kule\u010Dn\u00EDk a karambol vy\u017Eaduj\u00ED dva hr\u00E1\u010De, Cutthroat t\u0159i. Za\u010D\u00EDn\u00E1 prvn\u00ED hr\u00E1\u010D v seznamu, v dal\u0161\u00EDch parti\u00EDch \u010Di framech se za\u010D\u00E1tek st\u0159\u00EDd\u00E1. Z\u00E1pas obvykle kon\u010D\u00ED dosa\u017Een\u00EDm zvolen\u00E9ho po\u010Dtu v\u00EDt\u011Bzn\u00FDch parti\u00ED. Body uvnit\u0159 partie se po\u010D\u00EDtaj\u00ED zvl\u00E1\u0161\u0165.",
              "P otev\u00EDr\u00E1 hl\u00E1\u0161en\u00ED strk\u016F a \u010Dekaj\u00EDc\u00ED rozhodnut\u00ED. Vyberte kouli, kapsu \u010Di dal\u0161\u00ED po\u017Eadovan\u00E9 \u00FAdaje a potvr\u010Fte volbu; samotn\u00FD strk potom zahrajte Enterem nebo mezern\u00EDkem na prvku t\u00E1ga. Enter si vy\u017E\u00E1d\u00E1 chyb\u011Bj\u00EDc\u00ED hl\u00E1\u0161en\u00ED. Shift+P p\u0159e\u010Dte stav podle pravidel, T hr\u00E1\u010De na tahu a S sk\u00F3re bez dal\u0161\u00EDho okna. M um\u00EDs\u0165uje aktivn\u00ED hrac\u00ED kouli pouze p\u0159i h\u0159e z ruky. Q nab\u00EDz\u00ED vzd\u00E1n\u00ED aktu\u00E1ln\u00ED partie. Nov\u00E9 rozestaven\u00ED p\u0159i patu navr\u017Een\u00E9 p\u0159es P mus\u00ED schv\u00E1lit v\u0161ichni ostatn\u00ED hr\u00E1\u010Di; p\u0159i jedin\u00E9m odm\u00EDtnut\u00ED se hra vrac\u00ED navrhovateli."),
            rule_section(:pool_eight, "Pool: 8-ball",
              "St\u016Fl je zpo\u010D\u00E1tku otev\u0159en\u00FD. Rozbit\u00ED neur\u010Duje skupiny. Pozd\u011Bj\u0161\u00ED platn\u00E9 ohl\u00E1\u0161en\u00E9 potopen\u00ED p\u0159i\u0159ad\u00ED pln\u00E9 koule 1\u20137 nebo p\u016Flen\u00E9 9\u201315; soupe\u0159 z\u00EDsk\u00E1 druhou skupinu. Po potopen\u00ED ohl\u00E1\u0161en\u00E9 koule do ohl\u00E1\u0161en\u00E9 kapsy pokra\u010Dujete. Nejprve zasahujte vlastn\u00ED skupinu, po jej\u00EDm odstran\u011Bn\u00ED osmi\u010Dku. Na otev\u0159en\u00E9m stole lze hl\u00E1sit osmi\u010Dku pouze tehdy, kdy\u017E ji\u017E cel\u00E1 jedna skupina chyb\u00ED.",
              "Krom\u011B rozbit\u00ED p\u0159edem ohlaste kouli a kapsu. P hl\u00E1\u0161en\u00ED m\u011Bn\u00ED, Enter se zept\u00E1 na chyb\u011Bj\u00EDc\u00ED \u00FAdaje. Jistota ukon\u010D\u00ED tah i p\u0159i potopen\u00ED koule. P\u0159ed\u010Dasn\u00E9 potopen\u00ED osmi\u010Dky, s faulem nebo do nespr\u00E1vn\u00E9 kapsy znamen\u00E1 prohru. Samotn\u00E1 b\u00EDl\u00E1 bez osmi\u010Dky je b\u011B\u017En\u00FD faul. Faulem je i prvn\u00ED z\u00E1sah nespr\u00E1vn\u00E9 koule nebo \u017E\u00E1dn\u00E9 potopen\u00ED a \u017E\u00E1dn\u00FD mantinel po kontaktu. Soupe\u0159 m\u00E1 b\u00EDlou v ruce na cel\u00E9m stole.",
              "Nepotop\u00ED-li rozbit\u00ED nic, mus\u00ED nejm\u00E9n\u011B \u010Dty\u0159i r\u016Fzn\u00E9 barevn\u00E9 koule zas\u00E1hnout mantinel. Jinak m\u016F\u017Ee soupe\u0159 p\u0159ijmout pozici nebo ur\u010Dit, kdo znovu rozestav\u00ED a rozbije. Osmi\u010Dka potopen\u00E1 p\u0159i platn\u00E9m rozbit\u00ED se vr\u00E1t\u00ED na bod, nebo rozb\u00EDjej\u00EDc\u00ED zvol\u00ED nov\u00E9 rozbit\u00ED. P\u0159i faulu s osmi\u010Dkou vol\u00ED soupe\u0159; p\u0159i ponech\u00E1n\u00ED pozice dostane b\u00EDlou v ruce za \u010Darou rozbit\u00ED. Jin\u00E9 fauly p\u0159i rozbit\u00ED nab\u00EDzej\u00ED sou\u010Dasnou pozici nebo b\u00EDlou za \u010Darou. Z tohoto prostoru nelze p\u0159\u00EDmo zas\u00E1hnout kouli ve stejn\u00E9m prostoru bez p\u0159edchoz\u00EDho p\u0159ekro\u010Den\u00ED \u010D\u00E1ry. Jsou-li tam v\u0161echny povolen\u00E9 koule, P umo\u017En\u00ED po\u017E\u00E1dat o p\u0159esun nejbli\u017E\u0161\u00ED na bod."),
            rule_section(:pool_nine, "Pool: 9-ball",
              "V\u017Edy nejprve zas\u00E1hn\u011Bte nejni\u017E\u0161\u00ED \u010D\u00EDslo na stole. Ka\u017Ed\u00E9 platn\u00E9 potopen\u00ED barevn\u00E9 koule prodlu\u017Euje tah; platn\u00E1 dev\u00EDtka vyhr\u00E1v\u00E1 i v kombinaci. Kapsa se nehl\u00E1s\u00ED. Faul d\u00E1v\u00E1 soupe\u0159i b\u00EDlou v ruce kdekoliv. Dev\u00EDtka se po faulu \u010Di push-outu vrac\u00ED na bod, ostatn\u00ED koule z\u016Fst\u00E1vaj\u00ED v kaps\u00E1ch. T\u0159i po sob\u011B jdouc\u00ED fauly t\u00E9ho\u017E hr\u00E1\u010De znamenaj\u00ED prohru, dva vyvolaj\u00ED varov\u00E1n\u00ED. Platn\u00FD strk jeho po\u010Det faul\u016F vynuluje.",
              "V koso\u010Dtverci stoj\u00ED dev\u00EDtka na bodu a jedni\u010Dka vp\u0159edu. Rozbit\u00ED bez potopen\u00ED mus\u00ED poslat \u010Dty\u0159i koule k mantinel\u016Fm. Pravidlo t\u0159\u00ED koul\u00ED nav\u00EDc vy\u017Eaduje alespo\u0148 t\u0159i r\u016Fzn\u00E9 koule potopen\u00E9 nebo za \u010Darou rozbit\u00ED. Nespln\u00ED-li se bez dal\u0161\u00EDho faulu, soupe\u0159 p\u0159ijme pozici nebo vr\u00E1t\u00ED strk; potopen\u00E1 dev\u00EDtka se vr\u00E1t\u00ED na bod. Push-out pak sm\u00ED hr\u00E1t jen rozb\u00EDjej\u00EDc\u00ED, jemu\u017E byl strk vr\u00E1cen. Po platn\u00E9m rozbit\u00ED m\u016F\u017Ee b\u00FDt druh\u00FD strk push-outem, ohl\u00E1\u0161en\u00FDm p\u0159es P: nejni\u017E\u0161\u00ED \u010D\u00EDslo ani mantinel nejsou povinn\u00E9. Po platn\u00E9m push-outu soupe\u0159 zvol\u00ED, kdo pokra\u010Duje."),
            rule_section(:pool_ten, "Pool: 10-ball",
              "Nejprve zas\u00E1hn\u011Bte nejni\u017E\u0161\u00ED zb\u00FDvaj\u00EDc\u00ED \u010D\u00EDslo, ale p\u0159ed b\u011B\u017En\u00FDm strkem pod P nahlaste kouli a kapsu. Hl\u00E1\u0161en\u00ED safety zde nen\u00ED. Spr\u00E1vn\u00E9 spln\u011Bn\u00ED hl\u00E1\u0161en\u00ED zachov\u00E1 v\u00E1\u0161 tah. Des\u00EDtka vyhr\u00E1v\u00E1 jen tehdy, byla-li p\u0159ed strkem jedinou zb\u00FDvaj\u00EDc\u00ED hranou koul\u00ED a spadla bez faulu do nahl\u00E1\u0161en\u00E9 kapsy; d\u0159\u00EDv\u011Bj\u0161\u00ED des\u00EDtky se vracej\u00ED na bod.",
              "Rozbit\u00ED vy\u017Eaduje potopen\u00ED nebo dotyk \u010Dty\u0159 r\u016Fzn\u00FDch hran\u00FDch koul\u00ED s mantinely. Po spr\u00E1vn\u00E9m rozbit\u00ED m\u016F\u017Ee b\u00FDt druh\u00FD strk push-out nahl\u00E1\u0161en\u00FD pod P; po spr\u00E1vn\u00E9m push-outu soupe\u0159 p\u0159ijme pozici nebo vr\u00E1t\u00ED strk. V b\u011B\u017En\u00E9 h\u0159e d\u00E1v\u00E1 potopen\u00ED bez spln\u011Bn\u00ED hl\u00E1\u0161en\u00ED soupe\u0159i stejnou volbu. Faul p\u0159id\u011Bl\u00ED b\u00EDlou do ruky kdekoli, t\u0159i po sob\u011B jdouc\u00ED fauly prohr\u00E1vaj\u00ED partii."),
            rule_section(:straight_pool, "Pr\u016Fb\u011B\u017En\u00FD pool 14.1",
              "Pod P nahlaste kouli a kapsu. Pokud hl\u00E1\u0161en\u00ED spr\u00E1vn\u011B spln\u00EDte, ka\u017Ed\u00E1 hran\u00E1 koule potopen\u00E1 t\u00EDmto strkem d\u00E1v\u00E1 1 bod a pokra\u010Dujete. Partii vyhrajete dosa\u017Een\u00EDm bodov\u00E9ho c\u00EDle. Nespln\u011Bn\u00E9 hl\u00E1\u0161en\u00ED nebo nahl\u00E1\u0161en\u00E1 safety ukon\u010D\u00ED tah a vr\u00E1t\u00ED potopen\u00E9 koule.",
              "Prvn\u00ED rozbit\u00ED hrajete zpoza p\u0159edn\u00ED \u010D\u00E1ry. Spl\u0148te hl\u00E1\u0161en\u00E9 potopen\u00ED nebo po kontaktu po\u0161lete b\u00EDlou a alespo\u0148 dv\u011B hran\u00E9 koule k mantinel\u016Fm. Chyba stoj\u00ED 2 body; soupe\u0159 p\u0159ijme pozici nebo po\u017Eaduje nov\u00E9 rozbit\u00ED. B\u011B\u017En\u00FD faul stoj\u00ED 1 bod, sk\u00F3re tedy m\u016F\u017Ee b\u00FDt z\u00E1porn\u00E9. Po potopen\u00ED b\u00EDl\u00E9 ji soupe\u0159 dostane do ruky za p\u0159edn\u00ED \u010D\u00E1rou. T\u0159et\u00ED po sob\u011B jdouc\u00ED b\u011B\u017En\u00FD faul stoj\u00ED v tomto strku 16 bod\u016F a vy\u017E\u00E1d\u00E1 nov\u00E9 rozbit\u00ED pln\u00E9ho troj\u00FAheln\u00EDku; chyby rozbit\u00ED do t\u00E9to s\u00E9rie nepat\u0159\u00ED.",
              "Po zapo\u010Dten\u00ED \u010Dtrn\u00E1cti koul\u00ED se vr\u00E1t\u00ED do troj\u00FAheln\u00EDku s pr\u00E1zdn\u00FDm vrcholem; b\u00EDl\u00E1 a posledn\u00ED hran\u00E1 koule z\u016Fst\u00E1vaj\u00ED. Pokra\u010Dujete bez po\u017Eadavk\u016F prvn\u00EDho rozbit\u00ED. Spadla-li i posledn\u00ED koule nebo ob\u011B zb\u00FDvaj\u00EDc\u00ED p\u0159ek\u00E1\u017Eej\u00ED troj\u00FAheln\u00EDku, vr\u00E1t\u00ED se v\u0161ech patn\u00E1ct. Samotn\u00E1 p\u0159ek\u00E1\u017Eej\u00EDc\u00ED hran\u00E1 koule jde na p\u0159edn\u00ED bod, p\u0159\u00EDpadn\u011B na st\u0159ed. P\u0159ek\u00E1\u017E\u00ED-li jen b\u00EDl\u00E1, posledn\u00ED koule na p\u0159edn\u00ED \u010D\u00E1\u0159e \u010Di za n\u00ED sm\u011Brem k troj\u00FAheln\u00EDku d\u00E1 b\u00EDlou do ruky za \u010D\u00E1rou; koule p\u0159ed \u010D\u00E1rou po\u0161le b\u00EDlou na p\u0159edn\u00ED bod, p\u0159\u00EDpadn\u011B na st\u0159ed.",
              "P\u0159i dohodnut\u00E9m nov\u00E9m rozestaven\u00ED kv\u016Fli patu z\u016Fst\u00E1vaj\u00ED body a dluhy zachov\u00E1ny; P nab\u00EDdne v\u00FDb\u011Br nov\u00E9ho rozb\u00EDjej\u00EDc\u00EDho. Nov\u00E1 partie z\u00E1pasu za\u010D\u00EDn\u00E1 od nuly."),
            rule_section(:one_pocket, "One Pocket",
              "Ka\u017Ed\u00FD hr\u00E1\u010D m\u00E1 jednu ze dvou rohov\u00FDch kapes na prav\u00E9m konci. Rozb\u00EDjej\u00EDc\u00ED si svou vybere pod P p\u0159ed rozbit\u00EDm. Ka\u017Ed\u00E1 spr\u00E1vn\u011B potopen\u00E1 koule do va\u0161\u00ED kapsy v\u00E1m d\u00E1v\u00E1 1 bod, i kdy\u017E ji potop\u00ED soupe\u0159; prvn\u00ED s 8 body vyhraje. Vlastn\u00ED spr\u00E1vn\u00E9 potopen\u00ED prodlu\u017Euje tah. Koule z jin\u00FDch kapes se vracej\u00ED po n\u00E1b\u011Bhu, nebo ihned p\u0159i vypr\u00E1zdn\u011Bn\u00ED stolu p\u0159ed v\u00EDt\u011Bzstv\u00EDm. Rozbit\u00ED vy\u017Eaduje kontakt a n\u00E1sledn\u00FD mantinel nebo potopen\u00ED, nikoli \u010Dty\u0159i koule u mantinel\u016F.",
              "Faul v\u00E1s stoj\u00ED 1 bod a vr\u00E1t\u00ED jednu z\u00EDskanou kouli. Nem\u00E1te-li ji, vznikne dluh: budouc\u00ED bodovan\u00E1 koule jej splat\u00ED a vr\u00E1t\u00ED se na st\u016Fl. Koule v soupe\u0159ov\u011B kapse boduj\u00ED i p\u0159i faulu, leda\u017Ee jedin\u00FDm faulem bylo potopen\u00ED b\u00EDl\u00E9. Vylet\u011Bn\u00ED b\u00EDl\u00E9 ze stolu ani potopen\u00ED b\u00EDl\u00E9 s dal\u0161\u00EDm faulem tyto soupe\u0159ovy body neru\u0161\u00ED. Po potopen\u00ED b\u00EDl\u00E9 dostane soupe\u0159 hru z ruky za p\u0159edn\u00ED \u010D\u00E1rou. T\u0159i po sob\u011B jdouc\u00ED fauly prohr\u00E1vaj\u00ED partii. Dos\u00E1hnou-li oba 8 ve stejn\u00E9m strku, vyhraje st\u0159elec. Dohodnut\u00E9 nov\u00E9 rozestaven\u00ED zachov\u00E1 body i dluhy a vy\u017E\u00E1d\u00E1 nov\u00E9ho rozb\u00EDjej\u00EDc\u00EDho a kapsy."),
            rule_section(:bank, "Bank Pool: kr\u00E1tk\u00FD a pln\u00FD",
              "Bodovan\u00E9 potopen\u00ED od mantinelu vy\u017Eaduje nahl\u00E1\u0161en\u00ED koule, kapsy a po\u0159ad\u00ED mantinel\u016F. Pod P vyberte kouli a kapsu, potom postupn\u011B p\u0159id\u00E1vejte lev\u00FD, prav\u00FD, horn\u00ED \u010Di doln\u00ED mantinel a hotovou trasu ukon\u010Dete. Lze nahl\u00E1sit jeden a\u017E dvan\u00E1ct kontakt\u016F. Zru\u0161en\u00ED zachov\u00E1 p\u0159edchoz\u00ED hl\u00E1\u0161en\u00ED. B\u00EDl\u00E1 mus\u00ED zas\u00E1hnout hl\u00E1\u0161enou kouli p\u0159ed jak\u00FDmkoli mantinelem \u010Di jinou koul\u00ED. Hl\u00E1\u0161en\u00E1 koule pak nesm\u00ED zas\u00E1hnout jinou kouli ani znovu b\u00EDlou. Odrazy mus\u00ED odpov\u00EDdat hl\u00E1\u0161en\u00ED; n\u00E1hodn\u00E9 kontakty s \u010Delistmi c\u00EDlov\u00E9 kapsy p\u0159i vstupu se nezapo\u010D\u00EDt\u00E1vaj\u00ED.",
              "Spr\u00E1vn\u00FD bank d\u00E1v\u00E1 1 bod a zachov\u00E1 tah. Kr\u00E1tk\u00E1 varianta m\u00E1 9 koul\u00ED a c\u00EDl 5 bod\u016F, pln\u00E1 15 koul\u00ED a c\u00EDl 8. Dal\u0161\u00ED potopen\u00E9 koule \u010Dekaj\u00ED do konce n\u00E1b\u011Bhu, nebo se vracej\u00ED ihned p\u0159i vypr\u00E1zdn\u011Bn\u00ED stolu p\u0159ed v\u00EDt\u011Bzstv\u00EDm. P\u0159i rozbit\u00ED bank nehla\u0161te: potopen\u00ED prodlou\u017E\u00ED tah, ale neboduje. Bez potopen\u00ED mus\u00ED \u010Dty\u0159i r\u016Fzn\u00E9 hran\u00E9 koule zas\u00E1hnout mantinely; po chybn\u00E9m rozbit\u00ED soupe\u0159 p\u0159ijme pozici nebo vy\u017E\u00E1d\u00E1 opakov\u00E1n\u00ED.",
              "Faul stoj\u00ED 1 bod a vr\u00E1cen\u00ED z\u00EDskan\u00E9 koule. Nem\u00E1te-li ji, dluh splat\u00EDte vr\u00E1cen\u00EDm pozd\u011Bj\u0161\u00ED bodovan\u00E9 koule; sk\u00F3re m\u016F\u017Ee b\u00FDt z\u00E1porn\u00E9. Potopen\u00ED b\u00EDl\u00E9 d\u00E1v\u00E1 hru z ruky za p\u0159edn\u00ED \u010D\u00E1rou. T\u0159i po sob\u011B jdouc\u00ED fauly prohr\u00E1vaj\u00ED partii. Dohodnut\u00E9 nov\u00E9 rozestaven\u00ED p\u0159i patu zachov\u00E1 body i dluhy a pod P se potom vybere nov\u00FD rozb\u00EDjej\u00EDc\u00ED."),
            rule_section(:cutthroat, "Cutthroat pro t\u0159i hr\u00E1\u010De",
              "Tato klubov\u00E1 varianta p\u0159id\u011Bluje pevn\u00E9 skupiny podle m\u00EDst u stolu: 1\u20135, 6\u201310 a 11\u201315. Chra\u0148te svou skupinu a odstra\u0148ujte ostatn\u00ED. Jako prvn\u00ED sm\u00EDte zas\u00E1hnout kteroukoli hranou kouli a m\u016F\u017Eete ob\u011Btovat i vlastn\u00ED. Spr\u00E1vn\u00E9 potopen\u00ED zachov\u00E1 tah, pokud neodstranilo va\u0161i posledn\u00ED kouli. Hr\u00E1\u010Di bez koul\u00ED se do\u010Dasn\u011B p\u0159eskakuj\u00ED; vyhraje posledn\u00ED zb\u00FDvaj\u00EDc\u00ED skupina.",
              "Faul d\u00E1v\u00E1 dal\u0161\u00EDmu hr\u00E1\u010Di b\u00EDlou do ruky kdekoli a vrac\u00ED jednu potopenou kouli ka\u017Ed\u00E9ho soupe\u0159e: nejni\u017E\u0161\u00ED chyb\u011Bj\u00EDc\u00ED \u010D\u00EDslo dan\u00E9 skupiny. T\u00EDm se m\u016F\u017Ee p\u0159esko\u010Den\u00FD hr\u00E1\u010D vr\u00E1tit. Ztr\u00E1ta partie za t\u0159i fauly zde nen\u00ED. Odstran\u00ED-li jedin\u00FD spr\u00E1vn\u00FD strk v\u0161echny skupiny, kolo skon\u010D\u00ED rem\u00EDzou. Skupiny jsou v t\u00E9to variant\u011B pevn\u00E9, bez dohody o jejich p\u0159id\u011Blen\u00ED. Vzd\u00E1n\u00ED p\u0159es Q odstran\u00ED v\u0161echny koule va\u0161\u00ED skupiny a do konce partie zabr\u00E1n\u00ED jejich n\u00E1vratu; zb\u00FDvaj\u00EDc\u00ED hr\u00E1\u010Di pokra\u010Duj\u00ED."),
            rule_section(:blackball, "Blackball",
              "Hrajte svou skupinu pln\u00FDch nebo p\u016Flen\u00FDch koul\u00ED a potom \u010Dernou. Kapsy se nehl\u00E1s\u00ED. St\u016Fl z\u016Fst\u00E1v\u00E1 otev\u0159en\u00FD po rozbit\u00ED a voln\u00FDch strc\u00EDch; skupiny ur\u010D\u00ED pozd\u011Bj\u0161\u00ED spr\u00E1vn\u00E9 b\u011B\u017En\u00E9 potopen\u00ED. Spr\u00E1vn\u00E9 potopen\u00ED prodlu\u017Euje tah. Sou\u010Dasn\u00E9 potopen\u00ED posledn\u00ED vlastn\u00ED koule a \u010Dern\u00E9 je spr\u00E1vn\u00E9 v\u00EDt\u011Bzstv\u00ED; potopen\u00ED \u010Dern\u00E9 s faulem nebo p\u0159ed odstran\u011Bn\u00EDm vlastn\u00ED skupiny znamen\u00E1 prohru. \u010Cern\u00E1 na rozbit\u00ED m\u00EDsto toho obnov\u00ED rozestaven\u00ED pro stejn\u00E9ho rozb\u00EDjej\u00EDc\u00EDho.",
              "Spr\u00E1vn\u00E9 rozbit\u00ED potop\u00ED kouli nebo po\u0161le alespo\u0148 dv\u011B r\u016Fzn\u00E9 hran\u00E9 koule p\u0159es st\u0159edovou \u010D\u00E1ru. Faul poskytne jeden voln\u00FD strk a po n\u011Bm jeden b\u011B\u017En\u00FD. Voln\u00FD strk zahrajte z aktu\u00E1ln\u00ED pozice nebo p\u0159es M p\u0159esu\u0148te hrac\u00ED kouli do baulku, lev\u00E9 p\u011Btiny stolu. Voln\u00FD strk ru\u0161\u00ED jen po\u017Eadavek spr\u00E1vn\u00E9 prvn\u00ED koule: potopen\u00ED pouze soupe\u0159ov\u00FDch koul\u00ED je st\u00E1le faul. Po b\u011B\u017En\u00E9m strku dal\u0161\u00ED pokra\u010Dov\u00E1n\u00ED op\u011Bt vy\u017Eaduje spr\u00E1vn\u00E9 potopen\u00ED. P\u0159i \u00FApln\u00E9m snookeru bez cesty k jak\u00E9koli \u010D\u00E1sti povolen\u00E9 koule se nevy\u017Eaduje b\u011B\u017En\u00FD kontakt s mantinelem. Od dot\u00FDkan\u00E9 povolen\u00E9 koule mus\u00EDte hr\u00E1t pry\u010D bez jej\u00EDho postr\u010Den\u00ED."),
            rule_section(:snooker, "Snooker",
              "Hraje se s patn\u00E1cti \u010Derven\u00FDmi po bodu a se \u017Elutou za 2, zelenou za 3, hn\u011Bdou za 4, modrou za 5, r\u016F\u017Eovou za 6 a \u010Dernou za 7. \u010Cerven\u00E9 maj\u00ED \u010D\u00EDsla 1\u201315, barvy 16\u201321 v uveden\u00E9m po\u0159ad\u00ED. Potopte \u010Dervenou, p\u0159es P nebo p\u0159i dotazu Enteru ur\u010Dete barvu, pak st\u0159\u00EDdejte \u010Dervenou a barvu. Jedn\u00EDm strkem lze bodovat v\u00EDce \u010Derven\u00FDch. Barvy se v t\u00E9to f\u00E1zi vracej\u00ED na body i po faulu; \u010Derven\u00E9 obvykle z\u016Fst\u00E1vaj\u00ED dole. Po posledn\u00ED \u010Derven\u00E9 lze hr\u00E1t je\u0161t\u011B jednu barvu, potom se hraje od \u017Elut\u00E9 po \u010Dernou; spr\u00E1vn\u011B potopen\u00E9 barevn\u00E9 koule se u\u017E nevracej\u00ED.",
              "Faul p\u0159id\u00E1 soupe\u0159i 4 a\u017E 7 bod\u016F podle nejvy\u0161\u0161\u00ED p\u0159\u00EDslu\u0161n\u00E9 hodnoty hran\u00E9 a nespr\u00E1vn\u011B zasa\u017Een\u00E9 \u010Di potopen\u00E9 koule. H\u0159\u00ED\u0161n\u00EDk za dan\u00FD strk neboduje. Soupe\u0159 bu\u010F hraje, nebo vyzve h\u0159\u00ED\u0161n\u00EDka znovu. Po potopen\u00ED b\u00EDl\u00E9 se umis\u0165uje pouze do D; M p\u0159esouv\u00E1 jen b\u00EDlou a ostatn\u00ED kone\u010Dn\u00E9 pozice zachov\u00E1. Obsazen\u00FD bod barvy nahrad\u00ED nejvy\u0161\u0161\u00ED voln\u00FD bod, jinak nejbli\u017E\u0161\u00ED povolen\u00E1 pozice sm\u011Brem k \u010Dern\u00E9; r\u016F\u017Eov\u00E1 a \u010Dern\u00E1 maj\u00ED p\u0159i nutnosti v\u00FDjimku opa\u010Dn\u00FDm sm\u011Brem.",
              "Po faulu lze p\u0159i snookeru na v\u0161ech hran\u00FDch koul\u00EDch p\u0159es P ur\u010Dit volnou kouli. Aby ne\u0161lo o snooker, mus\u00ED b\u00FDt p\u0159\u00EDstupn\u00E9 oba krajn\u00ED okraje alespo\u0148 jedn\u00E9 hran\u00E9 koule; mantinel se jako blokuj\u00EDc\u00ED koule nepo\u010D\u00EDt\u00E1. P\u0159i b\u00EDl\u00E9 v ruce se prov\u011B\u0159uje cel\u00E9 D s p\u0159esnost\u00ED ukl\u00E1dan\u00FDch pozic. Voln\u00E1 koule m\u00E1 hodnotu hran\u00E9 koule a po potopen\u00ED se vrac\u00ED na bod. Po neboduj\u00EDc\u00EDm strku nesm\u00ED sama zanechat snooker krom\u011B v\u00FDjimky posledn\u00EDch dvou koul\u00ED.",
              "Byla-li voln\u00E1 p\u0159\u00EDm\u00E1 cesta, ale prvn\u00ED povinn\u00FD kontakt se nezda\u0159il, rozhod\u010D\u00ED m\u016F\u017Ee hl\u00E1sit Foul and a Miss. Soupe\u0159 m\u016F\u017Ee obnovit p\u0159edchoz\u00ED pozici a po\u017Eadovat opakov\u00E1n\u00ED; trestn\u00E9 body z\u016Fst\u00E1vaj\u00ED. Po dvou obnoven\u00FDch ne\u00FAsp\u011B\u0161\u00EDch s pln\u00FDm p\u0159\u00EDstupem ke kouli p\u0159ijde varov\u00E1n\u00ED, dal\u0161\u00ED ne\u00FAsp\u011Bch ztrat\u00ED frame. B\u011B\u017En\u00FD Miss se nehl\u00E1s\u00ED, pokud byly nebo po strku jsou pot\u0159eba body z faul\u016F. Zb\u00FDv\u00E1-li jen \u010Dern\u00E1, rozhodne prvn\u00ED potopen\u00ED \u010Di faul. Rem\u00EDza vr\u00E1t\u00ED \u010Dernou, vylosuje pr\u00E1vo zvolit hr\u00E1\u010De a d\u00E1 b\u00EDlou v ruce v D; dal\u0161\u00ED potopen\u00ED \u010Di faul rozhodne."),
            rule_section(:english, "Anglick\u00FD kule\u010Dn\u00EDk",
              "Ka\u017Ed\u00FD hr\u00E1\u010D pou\u017E\u00EDv\u00E1 svou b\u00EDlou nebo \u017Elutou hrac\u00ED kouli, \u010Derven\u00E1 je spole\u010Dn\u00E1. Na za\u010D\u00E1tku stoj\u00ED \u010Derven\u00E1 na bod\u011B a prvn\u00ED hr\u00E1\u010D hraje svou koul\u00ED z D. Koule druh\u00E9ho hr\u00E1\u010De je zpo\u010D\u00E1tku mimo st\u016Fl a vr\u00E1t\u00ED se, a\u017E ji bude pot\u0159ebovat. Vyhraje dosa\u017Een\u00ED bodov\u00E9ho c\u00EDle nebo veden\u00ED po uplynut\u00ED zvolen\u00E9ho \u010Dasu. Bodovan\u00FD strk v\u00E1m zachov\u00E1 n\u00E1b\u011Bh.",
              "Jeden strk m\u016F\u017Ee spojit n\u011Bkolik bodovan\u00FDch akc\u00ED:",
              "- Karambol neboli cannon znamen\u00E1, \u017Ee vlastn\u00ED hrac\u00ED koule zas\u00E1hne ob\u011B ostatn\u00ED. D\u00E1v\u00E1 2 body, nejv\u00FD\u0161e jednou za strk.",
              "- Potopen\u00ED \u010Derven\u00E9 d\u00E1v\u00E1 3 body, soupe\u0159ovy koule 2.",
              "- Potopen\u00ED vlastn\u00ED koule po kontaktu s \u010Dervenou d\u00E1v\u00E1 3 body, po soupe\u0159ov\u011B kouli 2. P\u0159i z\u00E1sahu obou rozhoduje prvn\u00ED kontakt; nerozli\u0161iteln\u00FD sou\u010Dasn\u00FD prvn\u00ED z\u00E1sah m\u00E1 hodnotu 2.",
              "Po potopen\u00ED vlastn\u00ED koule ji um\u00EDst\u011Bte kl\u00E1vesou M do D. Odtud mus\u00EDte hr\u00E1t ven z baulku d\u0159\u00EDve, ne\u017E p\u0159\u00EDmo zahrajete na kouli, jej\u00ED\u017E st\u0159ed je v baulku nebo na jeho \u010D\u00E1\u0159e. P\u0159ed n\u00E1vratem do baulku mus\u00EDte zas\u00E1hnout mantinel nebo kouli mimo n\u011Bj. \u0158\u00E1dn\u00FD English Miss p\u0159i v\u0161ech c\u00EDlech v baulku p\u0159id\u00E1 soupe\u0159i 2 body a hraje se z v\u00FDsledn\u00E9 pozice. Faul tak\u00E9 p\u0159id\u00E1 2 body, ale zru\u0161\u00ED bodov\u00E1n\u00ED dan\u00E9ho strku a pod P nab\u00EDdne ponech\u00E1n\u00ED pozice nebo nov\u00E9 postaven\u00ED \u010Derven\u00E9 a soupe\u0159ovy koule a hru z D.",
              "\u010Cerven\u00E1 se po potopen\u00ED vrac\u00ED na bod. P\u0159i opakovan\u00E9m samostatn\u00E9m pot\u00E1p\u011Bn\u00ED \u010Derven\u00E9 z bodu se dvakr\u00E1t hraje z b\u011B\u017En\u00E9ho bodu a pak jednou ze st\u0159edu; obsazen\u00E9 body maj\u00ED n\u00E1hradn\u00ED m\u00EDsta. Potopen\u00E1 soupe\u0159ova koule obvykle z\u016Fst\u00E1v\u00E1 mimo st\u016Fl, dokud nen\u00ED pot\u0159eba. Dot\u00FDk\u00E1-li se hrac\u00ED koule jin\u00E9, \u010Derven\u00E1 se vr\u00E1t\u00ED na sv\u016Fj bod, p\u0159\u00EDtomn\u00E1 soupe\u0159ova koule na st\u0159ed a vlastn\u00ED se hraje z D.",
              "Za n\u00E1b\u011Bh lze zahr\u00E1t nejv\u00FD\u0161e 75 samotn\u00FDch karambol\u016F po sob\u011B nebo 15 hazardov\u00FDch strk\u016F bez karambolu; hazard je potopen\u00ED c\u00EDlov\u00E9 \u010Di vlastn\u00ED koule po kontaktu. Varov\u00E1n\u00ED zazn\u00ED p\u0159i 70 a 10. Kombinace karambolu s hazardem ob\u011B s\u00E9rie p\u0159eru\u0161\u00ED. Po patn\u00E1ct\u00E9m hazardu plat\u00ED zvl\u00E1\u0161tn\u00ED vr\u00E1cen\u00ED soupe\u0159ovy koule, pokud z\u016Fstala mimo st\u016Fl po jeho posledn\u00EDm n\u00E1b\u011Bhu. Pokud je v nastaven\u00ED zapnuto p\u0159ekra\u010Dov\u00E1n\u00ED baulku, mus\u00ED hrac\u00ED koule p\u0159ekro\u010Dit \u010D\u00E1ru dovnit\u0159 v rozmez\u00ED 80\u2013100 bod\u016F ka\u017Ed\u00E9 stovky n\u00E1b\u011Bhu; jinak jde o faul."),
            rule_section(:carom, "Karambol: voln\u00E1 hra, jednoband a trojband",
              "Na stole bez kapes jsou t\u0159i koule. Po celou partii hrajete p\u0159id\u011Blenou b\u00EDlou nebo \u017Elutou. Karambol znamen\u00E1 kontakt vlastn\u00ED koule s ob\u011Bma ostatn\u00EDmi v jednom strku. Spr\u00E1vn\u00FD karambol d\u00E1v\u00E1 1 bod a prodlu\u017Euje n\u00E1b\u011Bh; chyba \u010Di faul p\u0159edaj\u00ED hru bez bodov\u00E9ho trestu. Vyhraje dosa\u017Een\u00ED zvolen\u00E9ho c\u00EDle s ohledem na nastaven\u00ED vyrovn\u00E1vac\u00EDho n\u00E1b\u011Bhu. Je-li vyrovn\u00E1vac\u00ED n\u00E1b\u011Bh zapnut\u00FD a za\u010D\u00EDnaj\u00EDc\u00ED hr\u00E1\u010D dos\u00E1hne c\u00EDle po jednom n\u00E1b\u011Bhu nav\u00EDc, druh\u00FD hr\u00E1\u010D dostane posledn\u00ED n\u00E1b\u011Bh z po\u010D\u00E1te\u010Dn\u00ED pozice. Dosa\u017Een\u00ED c\u00EDle v n\u011Bm znamen\u00E1 rem\u00EDzu partie; skon\u010D\u00ED-li n\u00E1b\u011Bh pod c\u00EDlem, vyhraje za\u010D\u00EDnaj\u00EDc\u00ED hr\u00E1\u010D. Bez vyrovn\u00E1v\u00E1n\u00ED dosa\u017Een\u00ED c\u00EDle vyhr\u00E1v\u00E1 okam\u017Eit\u011B.",
              "Na za\u010D\u00E1tku si pod P vyberte doln\u00ED nebo horn\u00ED po\u010D\u00E1te\u010Dn\u00ED bod. Prvn\u00ED \u00FAtok mus\u00ED v\u00E9st p\u0159\u00EDmo na \u010Dervenou. Discipl\u00EDny se potom li\u0161\u00ED:",
              "- Voln\u00E1 hra nevy\u017Eaduje z\u00E1sah mantinelu. Opakov\u00E1n\u00ED karambol\u016F omezuj\u00ED \u010Dty\u0159i vyzna\u010Den\u00E9 rohov\u00E9 troj\u00FAheln\u00EDky.",
              "- Jednoband vy\u017Eaduje alespo\u0148 jeden kontakt vlastn\u00ED koule s mantinelem p\u0159ed z\u00E1sahem druh\u00E9 r\u016Fzn\u00E9 hran\u00E9 koule.",
              "- Trojband vy\u017Eaduje alespo\u0148 t\u0159i takov\u00E9 kontakty. Jednotliv\u00E9 odrazy od stejn\u00E9ho mantinelu se po\u010D\u00EDtaj\u00ED, stejn\u011B jako odrazy p\u0159ed prvn\u00ED hranou koul\u00ED. Odrazy po druh\u00E9 kouli u\u017E nezda\u0159en\u00FD karambol nezachr\u00E1n\u00ED.",
              "V rohu voln\u00E9 hry sm\u00EDte po vstupu obou hran\u00FDch koul\u00ED jednou bodovat, ani\u017E by n\u011Bkter\u00E1 vyjela. P\u0159i dal\u0161\u00EDm karambolu mus\u00ED alespo\u0148 jedna troj\u00FAheln\u00EDk opustit; b\u011Bhem stejn\u00E9ho strku se sm\u00ED vr\u00E1tit. Koule na hranici se posuzuje v neprosp\u011Bch hr\u00E1\u010De. Sleduje se cel\u00FD pohyb, ne jen kone\u010Dn\u00E1 poloha.",
              "Dot\u00FDk\u00E1-li se hrac\u00ED koule jin\u00E9, voln\u00E1 hra obnov\u00ED cel\u00E9 po\u010D\u00E1te\u010Dn\u00ED rozestaven\u00ED. V bandov\u00FDch discipl\u00EDn\u00E1ch P nab\u00EDdne hru od dotyku bez postr\u010Den\u00ED dot\u00FDkan\u00E9 koule nebo nov\u00E9 postaven\u00ED na body. Jednoband obnovuje v\u0161echny t\u0159i, trojband pouze dot\u00FDkaj\u00EDc\u00ED se koule na p\u0159\u00EDslu\u0161n\u00FDch bodech. P\u0159\u00EDm\u00FD \u00FAder do mantinelu, kter\u00E9ho se hrac\u00ED koule dot\u00FDk\u00E1, je faul. Vylet\u00ED-li koule ze stolu, ve voln\u00E9 h\u0159e a jednobandu se obnov\u00ED v\u0161echny t\u0159i, v trojbandu jen vylet\u011Bl\u00E9."),
            rule_section(:pyramid, "Voln\u00E1 pyramida",
              "Z\u00EDskejte 8 bod\u016F d\u0159\u00EDve ne\u017E soupe\u0159. V\u0161ech \u0161estn\u00E1ct koul\u00ED m\u00E1 stejnou hodnotu: 1 bod za ka\u017Ed\u00E9 spr\u00E1vn\u00E9 potopen\u00ED v\u010Detn\u011B vlastn\u00ED hrac\u00ED koule po kontaktu s jinou. Koule ani kapsa se nehl\u00E1s\u00ED. P\u0159ed ka\u017Ed\u00FDm strkem po rozbit\u00ED pod P otev\u0159ete volbu hrac\u00ED koule a vyberte kteroukoli p\u0159\u00EDtomnou. Spr\u00E1vn\u00E9 potopen\u00ED zachov\u00E1 tah a dovol\u00ED novou volbu.",
              "Rozbit\u00ED hrajete barevnou koul\u00ED zpoza \u010D\u00E1ry domu v lev\u00E9 \u010Dtvrtin\u011B stolu. Po z\u00E1sahu hran\u00E9 koule bu\u010F potopte kouli, po\u0161lete t\u0159i r\u016Fzn\u00E9 hran\u00E9 koule k mantinel\u016Fm, nebo dv\u011B k mantinel\u016Fm a jednu hranou p\u0159es st\u0159edovou \u010D\u00E1ru.",
              "P\u0159i dal\u0161\u00EDch strc\u00EDch mus\u00ED po po\u017Eadovan\u00E9m kontaktu nastat n\u011Bkter\u00E1 z t\u011Bchto situac\u00ED:",
              "- N\u011Bkter\u00E1 koule je potopena.",
              "- Koule se odraz\u00ED od mantinelu a potom dos\u00E1hne jin\u00E9ho mantinelu, p\u0159\u00EDmo nebo p\u0159ed\u00E1n\u00EDm pohybu jin\u00E9 kouli. Podm\u00EDnku m\u016F\u017Ee splnit i z\u00E1sah koule p\u0159ilepen\u00E9 k onomu druh\u00E9mu mantinelu.",
              "- Koule p\u0159ekro\u010D\u00ED st\u0159ed a pot\u00E9 dos\u00E1hne mantinelu p\u0159\u00EDmo \u010Di prost\u0159ednictv\u00EDm jin\u00E9 koule; po\u010D\u00EDt\u00E1 se i koule p\u0159ilepen\u00E1 k dan\u00E9mu mantinelu.",
              "- Po odrazu od mantinelu koule p\u0159ekro\u010D\u00ED st\u0159ed, po\u0161le p\u0159es n\u011Bj jinou kouli nebo zas\u00E1hne kouli na prot\u011Bj\u0161\u00ED polovin\u011B \u010Di na st\u0159edov\u00E9 \u010D\u00E1\u0159e. Po\u010D\u00EDtaj\u00ED se i odpov\u00EDdaj\u00EDc\u00ED kontakty p\u0159edan\u00E9 dal\u0161\u00EDmi koulemi.",
              "Po faulu se nejprve vr\u00E1t\u00ED nespr\u00E1vn\u011B potopen\u00E9 a vylet\u011Bl\u00E9 koule. Soupe\u0159 pod P vybere libovolnou kouli ze stolu jako trestnou, odebere ji a z\u00EDsk\u00E1 1 bod. Potom hraje s\u00E1m nebo vr\u00E1t\u00ED strk. Po chybn\u00E9m rozbit\u00ED m\u016F\u017Ee tak\u00E9 obnovit rozestaven\u00ED a vybrat rozb\u00EDjej\u00EDc\u00EDho; trestn\u00FD bod z\u016Fst\u00E1v\u00E1 a pyramida je ne\u00FApln\u00E1. Potopen\u00ED samotn\u00E9 hrac\u00ED koule tu nen\u00ED automaticky faul: p\u0159i spr\u00E1vn\u00E9m proveden\u00ED po kontaktu boduje. V\u00EDce poru\u0161en\u00ED v jednom strku znamen\u00E1 jedin\u00FD trest.",
              "Vracen\u00E9 koule se stav\u00ED od zadn\u00EDho bodu doprava po pod\u00E9ln\u00E9 ose a p\u0159i nedostatku m\u00EDsta opa\u010Dn\u00FDm sm\u011Brem. Sm\u011Bj\u00ED se st\u00E1t p\u0159\u00ED\u0161t\u00ED hrac\u00ED koul\u00ED. V\u011Bt\u0161\u00ED koule a t\u011Bsn\u00E9 \u010Delisti vy\u017Eaduj\u00ED p\u0159esn\u011Bj\u0161\u00ED m\u00ED\u0159en\u00ED ne\u017E pool; sm\u011Br do kapsy nezaru\u010Duje pr\u016Fchod mezi \u010Delistmi."),
            rule_section(:settings, "Nastaven\u00ED z\u00E1pasu",
              "P\u0159ed hrou vyberte discipl\u00EDnu a podm\u00EDnku v\u00EDt\u011Bzstv\u00ED. Spole\u010Densk\u00FD kule\u010Dn\u00EDk m\u00E1 celkem 1 a\u017E 30 kol a jedno ze t\u0159\u00ED rozestaven\u00ED. Pokud to discipl\u00EDna umo\u017E\u0148uje, ur\u010D\u00EDte bodov\u00FD c\u00EDl partie; c\u00EDl z\u00E1pasu ud\u00E1v\u00E1 po\u010Det vyhran\u00FDch parti\u00ED. Anglick\u00FD kule\u010Dn\u00EDk lze hr\u00E1t i na zvolen\u00FD \u010Das: ji\u017E zah\u00E1jen\u00FD strk se dokon\u010D\u00ED a stejn\u00FD kone\u010Dn\u00FD po\u010Det bod\u016F znamen\u00E1 rem\u00EDzu. Volba vyrovn\u00E1vac\u00EDho n\u00E1b\u011Bhu v karambolu d\u00E1 druh\u00E9mu hr\u00E1\u010Di z\u00E1v\u011Bre\u010Dn\u00FD n\u00E1b\u011Bh z po\u010D\u00E1te\u010Dn\u00ED pozice, pokud je t\u0159eba vyrovnat po\u010Det n\u00E1b\u011Bh\u016F. V anglick\u00E9m kule\u010Dn\u00EDku na \u010Das mus\u00ED b\u00FDt strk p\u0159ijat u stolu p\u0159ed limitem; pouh\u00E9 d\u0159\u00EDv\u011Bj\u0161\u00ED stisknut\u00ED kl\u00E1vesy nesta\u010D\u00ED.",
              "Spole\u010Densk\u00FD kule\u010Dn\u00EDk za\u010D\u00EDn\u00E1 s koso\u010Dtvercem dev\u00EDti hran\u00FDch koul\u00ED. V nastaven\u00ED stolu m\u016F\u017Eete m\u00EDsto n\u011Bj zvolit jednu hranou kouli nebo troj\u00FAheln\u00EDk patn\u00E1cti; z\u00E1v\u011Bre\u010Dnou koul\u00ED pak bude jedni\u010Dka, nebo patn\u00E1ctka. V\u00FDslovn\u011B zvolen\u00E9 rozestaven\u00ED i rozestaven\u00ED star\u0161\u00ED ulo\u017Een\u00E9 hry z\u016Fst\u00E1vaj\u00ED zachov\u00E1na.",
              "C\u00EDl z\u00E1pasu je 1 a\u017E 25 vyhran\u00FDch parti\u00ED. Nastaviteln\u00FD bodov\u00FD c\u00EDl je 1 a\u017E 1000 a \u010Dasov\u00FD limit anglick\u00E9ho kule\u010Dn\u00EDku 1 a\u017E 180 minut.",
              "P\u0159esn\u011Bj\u0161\u00ED fyzika pou\u017E\u00EDv\u00E1 men\u0161\u00ED v\u00FDpo\u010Detn\u00ED kroky a m\u016F\u017Ee zm\u011Bnit v\u00FDsledek t\u011Bsn\u00E9ho kontaktu. S\u00EDla po\u010D\u00EDta\u010De ur\u010Duje po\u010Det porovn\u00E1van\u00FDch n\u00E1vrh\u016F strku. S\u00EDla \u00FAderu i rotace se po\u010D\u00EDtaj\u00ED tak\u00E9 v p\u0159edpov\u011Bd\u00EDch.",
              "Limit 1 a\u017E 500 strk\u016F se t\u00FDk\u00E1 pouze star\u0161\u00EDch ulo\u017Een\u00FDch tr\u00E9nink\u016F, nikoli nov\u00FDch her."),
            rule_section(:referee, "Pravidla a digit\u00E1ln\u00ED \u00FApravy",
              "Pool vych\u00E1z\u00ED z pravidel a p\u0159edpis\u016F WPA z 21. \u0159\u00EDjna 2026, snooker a anglick\u00FD kule\u010Dn\u00EDk z WPBSA 2024\u201325, karambol z UMB a voln\u00E1 pyramida z vyd\u00E1n\u00ED IPC 2025. Cutthroat a spole\u010Densk\u00FD kule\u010Dn\u00EDk pou\u017E\u00EDvaj\u00ED zde popsan\u00E1 klubov\u00E1 pravidla. Po\u0159ad\u00ED u stolu nahrazuje fyzick\u00FD rozst\u0159el o za\u010D\u00E1tek. Samotn\u00E1 dohoda o nov\u00E9m rozestaven\u00ED nep\u0159id\u00E1v\u00E1 v\u00EDt\u011Bznou partii. Automatick\u00FD rozhod\u010D\u00ED snookeru hl\u00E1s\u00ED Miss jen p\u0159i p\u0159\u00EDm\u00E9 cest\u011B; zcela zakryt\u00E9 pokusy z\u016Fst\u00E1vaj\u00ED b\u011B\u017En\u00FDmi fauly bez obnovy pozice.",
              "Simulace je dvourozm\u011Brn\u00E1: nem\u00E1 ovl\u00E1d\u00E1n\u00ED skok\u016F, zvednut\u00ED t\u00E1ga ani mass\u00E9. Postr\u010Den\u00ED dot\u00FDkaj\u00EDc\u00EDch se koul\u00ED a \u010Delisti kapes jsou p\u0159ibli\u017En\u00E9. Prvn\u00ED kontakty nerozli\u0161en\u00E9 v jednom fyzik\u00E1ln\u00EDm kroku se pova\u017Euj\u00ED za sou\u010Dasn\u00E9. Pyramida pou\u017E\u00EDv\u00E1 popsanou tr\u00E9ninkovou geometrii s velk\u00FDmi koulemi a t\u011Bsn\u00FDmi kapsami, nikoli certifikaci sou\u010Dasn\u00E9ho vybaven\u00ED federace. Pom\u016Fcky a p\u0159edpov\u011Bdi pou\u017E\u00EDvaj\u00ED aktivn\u00ED hrac\u00ED kouli a stejnou fyziku jako hra."),
            rule_section(:controls, "Kl\u00E1vesov\u00E9 zkratky",
              "K: P\u0159e\u010D\u00EDst sm\u011Br t\u00E1ga.",
              "F: P\u0159e\u010D\u00EDst s\u00EDlu strku.",
              "G: P\u0159e\u010D\u00EDst prvn\u00ED kontakt na z\u00E1m\u011Brn\u00E9 p\u0159\u00EDmce.",
              "H: Vypsat koule pobl\u00ED\u017E z\u00E1m\u011Brn\u00E9 p\u0159\u00EDmky.",
              "I: Popsat vybranou kouli.",
              "O: Vypsat v\u0161echny koule a jejich pozice.",
              "L: Vybrat dal\u0161\u00ED c\u00EDlovou kouli.",
              "Shift+L: Vybrat p\u0159edchoz\u00ED c\u00EDlovou kouli.",
              "J: Vybrat c\u00EDlovou kapsu.",
              "A: Zam\u00ED\u0159it na st\u0159ed vybran\u00E9 koule.",
              "Shift+A: Zam\u00ED\u0159it vybranou kouli do zvolen\u00E9 kapsy.",
              "E: Zadat p\u0159esn\u00FD \u00FAhel, s\u00EDlu a rotaci.",
              "W: Zv\u00FD\u0161it horn\u00ED rotaci.",
              "Shift+B: Zv\u00FD\u0161it spodn\u00ED rotaci.",
              "N: Zv\u00FD\u0161it levou rotaci.",
              "D: Zv\u00FD\u0161it pravou rotaci.",
              "R: Odstranit rotaci.",
              "C: P\u0159epnout sm\u011Bry mezi stupni a cifern\u00EDkem.",
              "Y: P\u0159edpov\u011Bd\u011Bt strk bez pohybu koul\u00ED.",
              "U: P\u0159e\u010D\u00EDst kontakty posledn\u00EDho strku.",
              "Vlevo: oto\u010Dit proti sm\u011Bru hodinov\u00FDch ru\u010Di\u010Dek o 1 stupe\u0148.",
              "Vpravo: oto\u010Dit po sm\u011Bru hodinov\u00FDch ru\u010Di\u010Dek o 1 stupe\u0148.",
              "Shift+vlevo: oto\u010Dit proti sm\u011Bru hodinov\u00FDch ru\u010Di\u010Dek o 0,1 stupn\u011B.",
              "Shift+vpravo: oto\u010Dit po sm\u011Bru hodinov\u00FDch ru\u010Di\u010Dek o 0,1 stupn\u011B.",
              "Ctrl+vlevo: oto\u010Dit proti sm\u011Bru hodinov\u00FDch ru\u010Di\u010Dek o 0,01 stupn\u011B.",
              "Ctrl+vpravo: oto\u010Dit po sm\u011Bru hodinov\u00FDch ru\u010Di\u010Dek o 0,01 stupn\u011B.",
              "Nahoru: zv\u00FD\u0161it s\u00EDlu o 1 procento.",
              "Dol\u016F: sn\u00ED\u017Eit s\u00EDlu o 1 procento.",
              "Shift+nahoru: zv\u00FD\u0161it s\u00EDlu o 0,1 procenta.",
              "Shift+dol\u016F: sn\u00ED\u017Eit s\u00EDlu o 0,1 procenta.",
              "Enter nebo mezern\u00EDk: prov\u00E9st nyn\u011Bj\u0161\u00ED strk.",
              "T: p\u0159e\u010D\u00EDst, kdo je na tahu.",
              "V: P\u0159edpov\u011Bd\u011Bt odraz od mantinelu a dal\u0161\u00ED z\u00E1sah koule.",
              "B: Popsat objekty za zam\u011B\u0159enou koul\u00ED.",
              "S: P\u0159e\u010D\u00EDst v\u00FDsledky, ve spole\u010Densk\u00E9 h\u0159e vyhran\u00E1 kola a body za potopen\u00ED.",
              "M: Um\u00EDst\u011Bte aktivn\u00ED hrac\u00ED kouli p\u0159i h\u0159e z ruky.",
              "P: Otev\u0159ete hl\u00E1\u0161en\u00ED, volbu hrac\u00ED koule nebo \u010Dekaj\u00EDc\u00ED rozhodnut\u00ED.",
              "Shift+P: P\u0159e\u010Dt\u011Bte aktu\u00E1ln\u00ED stav z\u00E1pasu.",
              "Q: Po potvrzen\u00ED vzdejte aktu\u00E1ln\u00ED kolo, partii \u010Di frame.",
              "\u010C\u00E1rka: Vypo\u010Dt\u011Bte pohyb prvn\u00ED zam\u011B\u0159en\u00E9 koule p\u0159i aktu\u00E1ln\u00ED s\u00EDle a rotaci.")
          ]
        when "en"
          [
            rule_section(:competition, "Social billiards: your first game",
              "New billiards tables select Social billiards for two to eight players, including computer players. The default layout is a diamond of balls 1\u20139 plus the white cue ball. Clear balls 1\u20138, then pot the 9-ball legally to win the round. The match is decided by round wins.",
              "Select an object ball with L or Shift+L and hear its position with I. Press A to aim at it, adjust direction and power with the arrows, then strike with Enter or Space on the Cue control. You do not call a ball or pocket in Social billiards. After the shot, listen to the outcome and whose turn comes next. The next chapter explains rounds, fouls and scoring; aiming controls follow."),
            rule_section(:friendly, "Social rounds and fouls",
              "Social billiards is for two to eight players, including computer players. Choose a total of 1 to 30 rounds. The match ends after that many rounds have been settled; the player with the most round wins wins the match. If several players share the most round wins, the match is a draw.",
              "The default diamond contains nine object balls, numbered 1\u20139, and the white cue ball. The 9-ball is the final ball. While other object balls remain, the cue ball must hit one of those first. A legal ordinary pot keeps your turn; without a pot, play passes to the next player. After contact, a ball must reach a cushion or an object ball must be potted.",
              "A scratch, wrong first ball or missing cushion gives the next player cue ball in hand anywhere: use M to place it. Other balls stay where they finish. If the final ball falls early or on a foul, the round ends and the next player in table order receives the round win. A legal final pot wins the round for the shooter. P starts the next round when offered. Arbitrary placement, undo and resetting an exercise are not part of this game.",
              "Alongside round wins, each legal object-ball pot earns 1 point, including a legal final ball. The cue ball earns no points. A foul shot or an early final-ball pot earns no pot points. These points accumulate across every round of the match; they do not decide round wins or break a tied match. S reads round wins and pot points aloud without opening a window; Shift+P includes both in the current match status."),
            rule_section(:table, "Reading the table",
              "X is measured from the left end and Y from the bottom cushion. Zero degrees points right, 90 up, 180 left and 270 down. C switches spoken directions to clock positions: three, twelve, nine and six. Pocket numbers run from 1 to 6: lower left, lower middle, lower right, upper left, upper middle, upper right. Carom tables have no pockets.",
              "O opens all ball positions, ordered by distance from the active cue ball, with pocketed balls last. L and Shift+L select an object ball; I describes its number or colour, sector, coordinates, distance and any obstruction. You can also reach the ball list with Tab and explore it with the arrows. The active cue is white in pool, your assigned white or yellow in English billiards and carom, or your chosen ball in Free Pyramid.",
              "In pool, the head string crosses the left quarter of the table; the foot spot is on the centre line at the right quarter. In snooker and English billiards, Baulk is the area to the left of the line 73.7 cm from the left end. The D is the semicircle of radius 29.2 cm on that side of the line. Carom\u2019s corner triangles extend 71 cm along the long cushion and 35.5 cm along the short cushion. The head spot is the centre of the head string; the area to its left is called the kitchen.",
              "- Pool: 254 by 127 cm.",
              "- Snooker and English billiards: 356.9 by 177.8 cm.",
              "- Carom: 284 by 142 cm, with no pockets.",
              "- Free Pyramid: 355 by 177.5 cm."),
            rule_section(:aim, "Aiming and striking",
              "Return to the Cue control with Tab. Left and Right turn anticlockwise and clockwise by one degree. Hold Shift for 0.1-degree steps or Ctrl for 0.01 degree. Up and Down change power by one percent, or 0.1 percent with Shift. Releasing an aiming arrow reads a short ball, cushion or pocket description. K reads the exact angle and F the power.",
              "While you turn the cue, short beeps guide your aim: 5000 Hz at the centre of the first ball on the shot line, falling to 500 Hz at either edge. Outside balls there is silence, except when aiming into a pocket. The tone follows side spin and your game sound settings, and stops when you leave the Cue control or open a dialog. These cues are local to your computer.",
              "Select an object ball and press A to aim at its centre. To aim for a pocket, choose that pocket with J, then press Shift+A. This geometric aid sets an angle; cushions, other balls, power and spin can still prevent the pot. G reports the first obstacle on the current line, including the side of a ball that will be contacted. H lists nearby balls within five degrees, including blocked ones.",
              "Press E to enter exact numbers. Both a decimal point and a decimal comma are accepted. Angle ranges from 0 to 359.99 degrees and power from 0.1 to 100 percent. Choose Apply to keep the settings or Cancel to retain the earlier ones. Enter or Space on the Cue control commits the shot."),
            rule_section(:spin, "Spin",
              "W adds follow spin; Shift+B adds draw spin. N adds left spin and D adds right spin. Each press changes the value by five. R returns to a centre-ball strike. Positive top spin helps the cue ball follow an object ball after contact; backspin can draw it back. Side spin changes cushion rebounds and slightly deflects the initial shot. These effects depend on power and distance: cloth friction can remove draw before the cue ball reaches its target.",
              "The two spin values range from -100 to 100. Together they must describe a point within the cue ball: maximum top spin cannot be combined with maximum side spin. The form rejects such a setting."),
            rule_section(:feedback, "Listening to a shot",
              "During play you hear the cue, ball collisions, cushions and pocket drops. The spoken outcome tells you what was hit and pocketed and gives the referee\u2019s decision. U opens the chronological contacts of the last shot, with angle, power and spin. Y calculates the current whole shot and shows its outcome and final positions without moving the real balls. Escape closes a report.",
              "With 3D sound (HRTF), cue strikes, ball collisions, cushions and pocket drops come from their positions on the table. The layout stays fixed: the table\u2019s left and right remain on your left and right, and the far side is in front of you. Aiming beeps always sound in the centre, including when HRTF is enabled. In Power Games Settings \u2192 Sounds, enable HRTF and select Billiards in the list of games using 3D sound. With HRTF off or unavailable, sounds remain in stereo.",
              "When the aiming line enters a pocket opening, a short 3000 Hz tone accompanies its number. The number is not repeated while you stay over that opening. Ball descriptions begin with the number or colour; pool balls 9 to 15 are striped.",
              "Point at a cushion and press V to calculate the active cue ball\u2019s rebound at your current power and spin. You hear the first cushion, the number of cushion contacts and any later ball contact or pocket entry. A shot too weak to reach the cushion is reported as such. This is a preview, not a played shot.",
              "B reads the objects farther along the aiming line, behind the first ball: other balls in order, then a cushion or pocket. Off-axis and rearward balls are omitted. B names a cushion or pocket directly if no ball is before it. This is the straight geometric line; use Y or Comma to calculate physical motion."),
            rule_section(:object_prediction, "Predicting the ball you are aiming at",
              "Point at an object ball and press Comma. This calculates the whole shot with the current angle, power and spin, then reports what happens to the first ball on your aiming line: its contacts and whether it enters a pocket or stops on the table. It does not replace that ball\u2019s motion with a straight aiming ray and does not play the shot. If no ball is on the line, you are told so. Y reports the whole shot with final positions, and V describes the active cue ball\u2019s cushion rebound."),
            rule_section(:match, "Choosing a discipline and making decisions",
              "The table settings select the discipline. Competitive pool, snooker, English billiards and carom require two players; Cutthroat requires three. The first listed player starts, and later racks or frames alternate the start. Competitive matches normally end at the chosen number of game wins. Points within a game are separate from those wins.",
              "P opens declarations and pending decisions. Choose the ball, pocket or other required details, confirm the choice, then use Enter or Space on the Cue control to strike. Enter asks for missing declarations. Shift+P reads the current rules situation, T whose turn it is, and S the scores without a separate window. M places the active cue only when the rules grant ball in hand. Q offers to concede the current game. A stalemate rerack proposed with P needs every other player\u2019s agreement; any refusal returns play to the proposer."),
            rule_section(:pool_eight, "Pool: 8-ball",
              "The table starts open. The break does not assign groups. On a later legal called pot you receive solids 1 to 7 or stripes 9 to 15, and your opponent receives the other group. Continue after pocketing your called ball in the called pocket. Hit your group first; after clearing it, play the 8-ball. On an open table, the 8-ball may be played only if an entire group is already absent and you declare the 8-ball.",
              "Except on the break, declare the ball and pocket before striking. P changes the declaration; Enter asks for any missing declaration. Safety ends your turn even if an object ball drops. Pocketing the 8-ball too early, with a foul or in the wrong pocket loses the rack. A scratch without potting the 8-ball is an ordinary foul. A wrong first ball or no pot and no cushion after contact is also a foul; the opponent receives cue ball in hand anywhere.",
              "If the break pots nothing, at least four different object balls must reach cushions. Otherwise the incoming player may accept the position or choose who reracks and breaks. An 8-ball potted on a legal break is spotted or the breaker may rerack. An 8-ball potted with a break foul gives those choices to the opponent, with cue ball in hand behind the head string if the position is retained. Other break fouls offer the current position or cue ball in hand behind that string. From there you cannot directly hit a ball in the head area without first crossing the string. P can request spotting the nearest legal ball if every legal ball is in that area."),
            rule_section(:pool_nine, "Pool: 9-ball",
              "Always hit the lowest numbered ball remaining first. Any legal object-ball pot continues your turn; a legal 9-ball pot wins, including a combination. Calls are not required. A foul gives the opponent cue ball in hand anywhere. The 9-ball returns to the foot spot if pocketed on a foul or push-out; other object balls stay down. Three consecutive fouls by the same player lose the rack; two are announced as a warning. A legal shot resets that player's foul count.",
              "The rack has the 9-ball on the foot spot and the 1-ball at the front. A break that pots nothing must send four object balls to cushions. The three-ball break rule also requires at least three different balls to be pocketed or cross the head string. If it fails without a foul, the opponent accepts the position or returns the shot; a potted 9-ball is spotted. Only a returned breaker may then push out. After an otherwise legal break, the second shot may be a push-out, declared with P: hitting the lowest ball and reaching a cushion are suspended. After a legal push-out the opponent chooses who plays next."),
            rule_section(:pool_ten, "Pool: 10-ball",
              "Hit the lowest remaining number first, but call a ball and pocket with P before each ordinary shot. There is no safety declaration. Making the call legally keeps your turn. The 10-ball wins only when it was the sole object ball remaining before the shot and enters the called pocket without a foul; earlier 10-balls are spotted.",
              "The break needs a pot or four different object balls at cushions. After a legal break, P can declare a push-out on the second shot; a legal push-out lets the opponent accept or return the shot. In ordinary play, pocketing a ball without making the call also gives the opponent that choice. A foul gives cue ball in hand anywhere; three consecutive fouls lose the rack."),
            rule_section(:straight_pool, "Straight pool 14.1",
              "Call a ball and pocket with P. When you make the call legally, every object ball potted on the shot scores 1 point and your turn continues. Reach the point target to win. A missed call or declared safety ends your turn and returns pocketed balls.",
              "The opening break starts behind the head string. Make your called pot or send the cue and at least two object balls to cushions after contact. Failure costs 2 points; the opponent accepts the position or requires another break. Ordinary fouls cost 1 point and may make your score negative. A scratch gives the opponent cue ball in hand behind the head string. The third consecutive ordinary foul costs 16 on that stroke and forces a fresh full-rack break; breaking fouls do not count in that sequence.",
              "After fourteen balls have scored, they are reracked with the apex empty, leaving the cue and last object ball where they are. Play continues without the opening spread requirement. If the last ball also fell, or both remaining balls obstruct the rack, all fifteen return. An obstructing object ball alone goes to the head spot, or centre if occupied. When only the cue obstructs, a last ball on or beyond the head string gives kitchen ball in hand; one behind the string sends the cue to the head spot, or centre if blocked.",
              "After an agreed stalemate rerack, scores and debts are retained and P offers the choice of new breaker. A new match game starts from zero."),
            rule_section(:one_pocket, "One Pocket",
              "Each player owns one of the two corner pockets at the right end. The breaker chooses theirs with P before the break. Each legal ball into your pocket gives you 1 point, even if the opponent pots it; the first to 8 wins. Your own legal pot keeps your turn. Other pockets\u2019 balls return after the turn, or immediately if the table empties before a win. A break needs contact followed by a rail or a pot, not four balls at cushions.",
              "A foul costs you 1 point and returns one of your scored balls. If none is available, you owe a ball: a future scoring pot repays the debt and is returned. Opponent-pocket balls still score on a foul unless the only foul was pocketing the cue ball. A cue ball off the table or a scratch with another foul does not cancel those opponent points. A scratch gives kitchen ball in hand. Three consecutive fouls lose the game. If both players reach 8 on the same shot, the shooter wins. An agreed stalemate keeps scores and debts and asks for a new breaker and pockets."),
            rule_section(:bank, "Bank Pool: short and full rack",
              "A scoring bank needs a declared ball, pocket and ordered cushion route. Under P choose the ball and pocket, then add each next cushion: left, right, top or bottom. Finish the route when complete; one to twelve contacts may be declared. Cancelling leaves the previous declaration intact. The cue must hit the called ball before any cushion or other ball. The called ball may not then hit another ball or the cue again. Its cushions must follow the call; incidental jaw contacts while entering the destination pocket are omitted.",
              "A valid bank gives 1 point and keeps your turn. Short-rack Bank Pool uses 9 balls and a target of 5; full-rack Bank Pool uses 15 and a target of 8. Extra pocketed balls wait until your turn ends before returning, or return immediately if the table empties before a win. Do not declare a bank on the break: any pot continues but earns no point. With no pot, four different object balls must reach cushions; an inadequate break lets the opponent accept or require another break.",
              "A foul costs 1 point and returns a scored ball. Without one, your debt is repaid by returning a later scoring ball; scores may be negative. A scratch gives kitchen ball in hand. Three consecutive fouls lose the game. Scores and debts survive an agreed stalemate rerack, followed by a P choice of new breaker."),
            rule_section(:cutthroat, "Cutthroat for three players",
              "This club variant assigns fixed groups in seat order: 1\u20135, 6\u201310 and 11\u201315. Protect your own group and remove the others. Any object ball may be hit first, and you may sacrifice one of your own balls. A legal pot continues your turn unless it removed your last ball. Players with no balls are temporarily skipped; the last group remaining wins.",
              "A foul gives the next player cue ball in hand anywhere and returns one pocketed ball for each opponent, choosing the lowest absent number in that group. This can bring a skipped player back into play. Three-foul rack loss is not used. If one legal shot removes every group, the round is a draw. This fixed-group version does not use a negotiation to claim groups. Conceding with Q removes all balls in your group and prevents their revival for the rest of this rack; the remaining players continue."),
            rule_section(:blackball, "Blackball",
              "Play your group of solids or stripes, then black. Calls are not required. The table stays open after the break and free shots; groups are assigned by a later legal ordinary pot. A legal pot keeps your turn. Potting the last of your group and black together is a legal win; potting black with a foul or before clearing your group loses the rack. Black on the break instead reracks for the same breaker.",
              "A legal break pots a ball or sends at least two different object balls across the centre line. A foul grants one free shot followed by one normal shot. For the free shot, play from the current position or use M to move the cue into baulk, the leftmost fifth of the table. The free shot suspends wrong-first-ball only: potting only the opponent\u2019s balls is still a foul. After the normal shot, continuation again needs a legal pot. When fully snookered with no path to any part of a ball on, the usual cushion requirement is suspended. A touching ball on must be played away from without pushing it."),
            rule_section(:snooker, "Snooker",
              "There are fifteen reds, worth one point each, and yellow 2, green 3, brown 4, blue 5, pink 6 and black 7. Red balls have IDs 1 to 15; colours have IDs 16 to 21 in that order. Pot a red, nominate a colour with P or when Enter asks, then alternate red and colour. Multiple reds may score in one stroke. Colours return to their spots during this phase, including after a foul. Reds normally remain pocketed. After the last red you may still play one colour, then clear yellow through black in order without replacing legally potted colours.",
              "A foul gives the opponent 4 to 7 points: use the highest applicable value among the ball on and illegally contacted or pocketed balls. No points are scored by the offender on that stroke. The opponent chooses to play or asks the offender to play again. Cue-ball scratches give placement inside the D only; M moves only the cue ball and leaves all other final positions alone. Occupied colour spots use the highest free spot, then the nearest legal position toward the black end, with the pink/black exception toward the other end when necessary.",
              "After a foul, a snooker on every ball on permits nomination of a free ball with P. Both extreme edges of a ball on must be available to avoid a snooker; a cushion does not count as a blocking ball. If the cue ball is in hand, the whole D is checked at the recorded placement precision. A nominated free ball takes the value of the ball on and returns to its spot if potted. It may not itself leave a non-scoring snooker except in the final two-ball exception.",
              "If a direct path was available but the first required contact was missed, the referee may call Foul and a Miss. The opponent can restore the previous balls and ask the offender to retry; penalty points remain. Two restored full-ball misses cause a warning, and another failure loses the frame. Ordinary Miss is not called when penalty points are already needed or become needed after the stroke. When only black remains, the first pot or foul settles the frame. A tied score respots black, draws a choice of player and gives cue ball in hand in the D; the next pot or foul decides it."),
            rule_section(:english, "English billiards",
              "Each player keeps their own white or yellow cue ball; red is shared. On the opening turn red is on its spot and the starting cue ball is played from the D. The other player\u2019s ball is initially off the table and enters when that player first needs it. Score up to the chosen point target, or lead when the selected time ends. A scoring stroke keeps your turn.",
              "One stroke can combine several scores:",
              "- A cannon means your cue ball contacts both other balls. It scores 2 points, once per stroke.",
              "- Potting red scores 3; potting the other player\u2019s ball scores 2.",
              "- Your cue ball entering a pocket after contacting red scores 3; after the opponent\u2019s ball it scores 2. When both were hit, the first contact decides; an unresolved simultaneous first contact gives 2.",
              "After an in-off, use M to place your cue in the D. You must play out of Baulk before directly playing a ball whose centre is in Baulk, including on the line; when returning into Baulk, a cushion or ball outside it must have been contacted first. A legal English Miss when all targets are in Baulk gives the opponent 2 points and play from the resulting position. A foul instead gives 2 points, cancels that stroke\u2019s scores and offers P decisions: accept the position or reset red and the opponent\u2019s ball, then play from the D.",
              "Red is respotted after a pot. Repeated red-only pots from its spot follow two pots on the normal spot, then one from the centre, with substitute spots when occupied. The opponent\u2019s potted ball usually stays off the table until needed. A cue ball touching another ball triggers red\u2019s spot, the opponent\u2019s centre spot if that ball is present, and cue ball in hand in the D.",
              "A run may contain at most 75 cannon-only strokes or 15 hazard strokes without a cannon; a hazard is a pot or in-off. Warnings come at 70 and 10. Combining a cannon and hazard breaks both sequences. A special fifteenth-hazard respot applies when the opponent\u2019s ball was left off the table by that opponent\u2019s last turn. If Baulk crossing is enabled in settings, you must make the required inward crossing during each break\u2019s 80\u2013100 point interval; failure is a foul."),
            rule_section(:carom, "Carom: straight rail, one cushion and three cushions",
              "There are three balls on a pocketless table. Keep your assigned white or yellow cue throughout the game. A cannon means your cue contacts both other balls in one stroke. A legal cannon gives 1 point and keeps your inning; a miss or foul passes play without a point penalty. Reach the selected point target to win, subject to the equalizing-inning setting. With equalizing enabled, if the opening player reaches the target after one more inning, the other player gets one final inning from the starting position. Reaching the target then draws the game; ending that inning short of it gives the opening player the win. With equalizing disabled, reaching the target wins immediately.",
              "At the start, P lets you choose the lower or upper starting spot. Your first attack must be directly on red. The disciplines then differ as follows:",
              "- Straight rail needs no cushion contact. Its four marked corner triangles restrict repeated cannons.",
              "- One cushion needs at least one contact by your cue with a cushion before it touches the second different object ball.",
              "- Three cushions needs at least three such contacts. Separate impacts on the same cushion count, and impacts before the first object ball also count. Impacts after the second object ball do not repair a missed cannon.",
              "In a straight-rail corner, after both object balls enter, you may make one cannon without either leaving. On the following cannon at least one must leave that triangle; it may return during the same stroke. A ball on the boundary is treated against the player. The programme follows the whole movement, not only where the balls stop.",
              "If your cue touches an object ball, straight rail restores all three to the opening position. In the cushion games P offers playing away without pushing the touching ball or respotting. One cushion resets all three; three cushions replaces only the touching balls on their assigned spots. Driving a frozen cue directly into its cushion is a foul. An off-table ball resets all three in straight rail and one cushion, but only the escaped balls in three cushions."),
            rule_section(:pyramid, "Free Pyramid",
              "Score 8 points before your opponent. All sixteen balls have the same value: 1 point for every legal pot, including your cue ball after it contacts another ball. No ball or pocket call is needed. Before each shot after the break, use P and Choose the cue ball to select any ball still on the table. A legal pot keeps your turn and gives you a fresh choice of cue.",
              "The opening shot uses the coloured ball from behind the home line at the left quarter. After hitting an object ball, either pot a ball, send three different object balls to cushions, or send two to cushions and an object ball across the centre line.",
              "In later shots, after the required ball contact, one of the following must happen:",
              "- A ball is potted.",
              "- A ball rebounds from a cushion and then reaches another cushion, directly or by driving another ball there. Contact with a ball frozen to that other cushion can also satisfy the condition.",
              "- A ball crosses the centre and then reaches a cushion, directly or by transmitting movement to another ball; a frozen ball at that cushion also counts.",
              "- After a cushion rebound, a ball crosses the centre, drives another across, or contacts a ball on the opposite half or centre line; the corresponding transmitted contacts also count.",
              "If you foul, all illegally potted and escaped balls are spotted first. Under P your opponent selects any table ball as the penalty ball, removes it and gains 1 point. They then choose to play or return the shot. After an illegal break they can also rerack and choose who breaks; the penalty point stays and the new pyramid is incomplete. An ordinary cue-ball pot is not automatically a foul here: it scores when made legally after contact. Multiple fouls in one shot incur one penalty.",
              "Spotted balls go from the foot spot toward the right end along the centre line, then backward if space runs out. They may become the next cue ball. The larger balls and narrow jaws need more precise aim than pool; a line toward a pocket is not a promise that the ball will pass its jaws."),
            rule_section(:settings, "Match settings",
              "Before play, choose the discipline and its winning target. Social billiards uses a total of 1 to 30 rounds and one of three layouts. Where the discipline permits it, choose its point target; its match target counts game wins. English billiards can instead run for the selected time: a shot already started when time expires is allowed to finish, and equal final scores are a draw. Carom\u2019s equalizing-inning option gives the second player a final inning from the starting position when needed to equal the number of innings. In timed English billiards, an accepted shot must reach the table before the time limit; pressing a key before it expires is not enough.",
              "Social billiards starts with the nine-ball diamond. In table settings you can instead select one object ball or the fifteen-ball triangle; their final balls are 1 and 15 respectively. An explicit layout choice and an older saved game keep their selected layout.",
              "The match target is 1 to 25 game wins. Adjustable point targets range from 1 to 1000; English time limits range from 1 to 180 minutes.",
              "More accurate physics uses smaller calculation steps and may change the result of a close contact. Computer strength controls how many candidate shots a bot compares. Spin and power remain part of every shot, including previews.",
              "Only older saved practice games use the limit of 1 to 500 shots; it does not apply to new games."),
            rule_section(:referee, "Rules and digital adaptations",
              "Pool follows WPA Rules and Regulations effective 21 October 2026; snooker and English billiards use WPBSA 2024\u201325, carom uses UMB rules, and Free Pyramid uses IPC\u2019s 2025 revision. Cutthroat and Social billiards use the club rules described here. Table order replaces a physical lag. Agreement to rerack does not itself award a game win. The snooker referee calls automatic Miss only with a direct path; entirely obstructed attempts remain ordinary fouls without restoration.",
              "The simulation is two-dimensional: no jumps, cue elevation or mass\u00E9 controls. Frozen-ball pushes and pocket jaws are approximations. First contacts unresolved within the same physics step are treated as simultaneous. Pyramid uses a documented training geometry with large balls and tight pockets; this is not certification of current federation equipment. Directional aids and previews use the active cue and the same physics as play."),
            rule_section(:controls, "Keyboard shortcuts",
              "K: Read cue direction.",
              "F: Read shot power.",
              "G: Read the first contact on the shot line.",
              "H: List balls near the shot line.",
              "I: Describe the selected ball.",
              "O: List all balls and their positions.",
              "L: Select the next object ball.",
              "Shift+L: Select the previous object ball.",
              "J: Choose a target pocket.",
              "A: Aim at the centre of the selected ball.",
              "Shift+A: Aim the selected ball towards the chosen pocket.",
              "E: Enter exact angle, power and spin.",
              "W: Increase follow spin.",
              "Shift+B: Increase draw spin.",
              "N: Increase left spin.",
              "D: Increase right spin.",
              "R: Remove spin.",
              "C: Switch between degrees and clock directions.",
              "Y: Predict this shot without moving the balls.",
              "U: Read contacts from the last shot.",
              "Left: turn anticlockwise by 1 degree.",
              "Right: turn clockwise by 1 degree.",
              "Shift+Left: turn anticlockwise by 0.1 degree.",
              "Shift+Right: turn clockwise by 0.1 degree.",
              "Ctrl+Left: turn anticlockwise by 0.01 degree.",
              "Ctrl+Right: turn clockwise by 0.01 degree.",
              "Up: increase power by 1 percent.",
              "Down: decrease power by 1 percent.",
              "Shift+Up: increase power by 0.1 percent.",
              "Shift+Down: decrease power by 0.1 percent.",
              "Enter or Space: play the current shot.",
              "T: read whose turn it is.",
              "V: Predict the cushion rebound and next ball contact.",
              "B: Describe objects behind the aimed ball.",
              "S: Read scores aloud, including Social round wins and pot points.",
              "M: Place the active cue ball when in hand.",
              "P: Open declarations, cue choice or a pending match decision.",
              "Shift+P: Read the current match situation.",
              "Q: Concede the current round, rack or frame after confirmation.",
              "Comma: Predict the first aimed ball with the current power and spin.")
          ]
        when "es"
          [
            rule_section(:competition, "Billar social: tu primera partida",
              "Las mesas nuevas tienen seleccionado el billar social, en el que pueden participar entre dos y ocho jugadores, incluidos los de ordenador. El montaje predeterminado es un rombo con las bolas 1\u20139 y la blanca. Elimina las bolas 1\u20138 y despu\u00E9s emboca legalmente la 9 para ganar la ronda. El encuentro se decide por las rondas ganadas.",
              "Selecciona una bola objetivo con L o May\u00FAs+L y escucha su posici\u00F3n con I. Pulsa A para apuntarle, ajusta direcci\u00F3n y fuerza con las flechas y tira con Intro o Espacio en el control del taco. En el billar social no declaras bola ni tronera. Tras el tiro escuchar\u00E1s el resultado y a qui\u00E9n le toca. El pr\u00F3ximo cap\u00EDtulo explica rondas, faltas y puntuaci\u00F3n; despu\u00E9s se ense\u00F1an los controles de punter\u00EDa."),
            rule_section(:friendly, "Rondas sociales y faltas",
              "El billar social admite de dos a ocho jugadores, incluidos los de ordenador. Elige un total de 1 a 30 rondas. El encuentro termina al resolverse ese n\u00FAmero de rondas y gana quien haya ganado m\u00E1s. Si varios jugadores comparten el mayor n\u00FAmero de rondas ganadas, el encuentro acaba en empate.",
              "El rombo predeterminado contiene nueve bolas objetivo, numeradas del 1 al 9, y la blanca. La bola final es la 9. Mientras queden otras, la blanca debe golpear primero una de ellas. Embocar legalmente una bola normal mantiene tu turno; si no embocas, juega la siguiente persona. Tras el contacto, alguna bola debe tocar banda o debe entrar una bola objetivo.",
              "Embocar la blanca, golpear primero una bola incorrecta o incumplir el contacto con banda da al siguiente jugador bola en mano en cualquier lugar: col\u00F3cala con M. Las dem\u00E1s conservan su posici\u00F3n. Si entra la bola final antes de tiempo o en un tiro con falta, termina la ronda y la gana el siguiente jugador en el orden de la mesa. Un tiro final legal gana la ronda para quien lo realiza. P permite iniciar la siguiente ronda cuando se ofrece. No se pueden reorganizar bolas libremente, deshacer tiros ni reiniciar ejercicios.",
              "Adem\u00E1s de las rondas ganadas, recibes 1 punto por cada bola objetivo embocada legalmente, incluida la final si es legal. La blanca no da puntos. Un tiro con falta o con la bola final antes de tiempo no da puntos por embocadas. Se acumulan durante todas las rondas del encuentro; no deciden qui\u00E9n gana una ronda ni deshacen un empate del encuentro. S lee las rondas ganadas y los puntos por embocadas sin abrir otra ventana; May\u00FAs+P incluye ambas cifras en el estado del encuentro."),
            rule_section(:table, "Orientarte en la mesa",
              "X mide la distancia desde el extremo izquierdo; Y, desde la banda inferior. Cero grados apunta a la derecha, 90 arriba, 180 a la izquierda y 270 abajo. C cambia la lectura a horas del reloj: tres, doce, nueve y seis. Las troneras 1 a 6 est\u00E1n abajo a la izquierda, abajo en el centro, abajo a la derecha, arriba a la izquierda, arriba en el centro y arriba a la derecha. Las mesas de carambola no tienen troneras.",
              "O abre las posiciones de todas las bolas, ordenadas por distancia a la bola de tiro activa; las embocadas van al final. L y May\u00FAs+L eligen una bola objetivo; I describe su n\u00FAmero o color, zona, coordenadas, distancia y obst\u00E1culos. Tambi\u00E9n puedes llegar a la lista con Tab y recorrerla con las flechas. En pool tiras con la blanca; en billar ingl\u00E9s y carambola, con tu blanca o amarilla asignada; en pir\u00E1mide libre eliges la bola de tiro.",
              "En pool, la l\u00EDnea de cabeza cruza el cuarto izquierdo de la mesa y el punto de pie est\u00E1 en el eje longitudinal, en el cuarto derecho. En snooker y billar ingl\u00E9s, baulk es la zona a la izquierda de la l\u00EDnea situada a 73,7 cm del extremo izquierdo. La D es el semic\u00EDrculo de radio 29,2 cm a ese lado de la l\u00EDnea. Los tri\u00E1ngulos de esquina de carambola se extienden 71 cm por la banda larga y 35,5 cm por la corta. El punto de cabeza es el centro de la l\u00EDnea de cabeza.",
              "- Pool: 254 por 127 cm.",
              "- Snooker y billar ingl\u00E9s: 356,9 por 177,8 cm.",
              "- Carambola: 284 por 142 cm, sin troneras.",
              "- Pir\u00E1mide libre: 355 por 177,5 cm."),
            rule_section(:aim, "Apuntar y tirar",
              "Vuelve con Tab al control del taco. Izquierda y Derecha giran un grado en sentido antihorario y horario. Mant\u00E9n May\u00FAs para pasos de 0,1 grados o Ctrl para 0,01. Arriba y Abajo cambian la fuerza un uno por ciento, o un 0,1 con May\u00FAs. Al soltar una flecha de punter\u00EDa oyes una descripci\u00F3n breve de bola, banda o tronera. K lee el \u00E1ngulo exacto y F la fuerza.",
              "Al girar el taco, unos pitidos cortos ayudan a apuntar: el centro de la primera bola en la l\u00EDnea de tiro suena a 5000 Hz y el tono baja hasta 500 Hz al acercarse a cualquiera de sus bordes. Fuera de las bolas hay silencio, salvo al apuntar a una tronera. El tono tiene en cuenta el efecto lateral y los ajustes de sonido del juego. Se detiene al salir del control Taco o abrir un di\u00E1logo. Solo se oye en tu ordenador.",
              "Selecciona una bola y pulsa A para apuntar a su centro. Para intentar embocarla, elige una tronera con J y pulsa May\u00FAs+A. Esta ayuda geom\u00E9trica ajusta el \u00E1ngulo; las bandas, otras bolas, la fuerza y el efecto a\u00FAn pueden impedir que entre. G describe el primer obst\u00E1culo de la trayectoria, incluido el lado de la bola que recibir\u00E1 el golpe. H enumera las bolas situadas a cinco grados o menos de esa l\u00EDnea, incluso las bloqueadas.",
              "E abre un formulario para introducir valores exactos. Se acepta tanto el punto como la coma decimal. El \u00E1ngulo va de 0 a 359,99 grados y la fuerza de 0,1 a 100 por ciento. Elige Aplicar para conservar los ajustes o Cancelar para mantener los anteriores. Intro o Espacio en el control Taco ejecuta el tiro."),
            rule_section(:spin, "Efecto",
              "W a\u00F1ade efecto de avance y May\u00FAs+B de retroceso. N a\u00F1ade efecto a la izquierda y D a la derecha. Cada pulsaci\u00F3n cambia el valor en cinco unidades. R vuelve al golpe centrado sin efecto. El efecto de avance ayuda a la bola de tiro a seguir a la bola golpeada; el de retroceso puede hacerla volver. El lateral modifica los rebotes y desv\u00EDa ligeramente la direcci\u00F3n inicial. El resultado depende de la fuerza y la distancia: el rozamiento puede agotar el retroceso antes del contacto.",
              "Los dos valores van de -100 a 100. Juntos deben representar un punto dentro de la bola de tiro: no se puede combinar el m\u00E1ximo efecto de avance con el m\u00E1ximo lateral. El formulario rechaza esa combinaci\u00F3n."),
            rule_section(:feedback, "Escuchar el tiro",
              "Durante el juego oyes el taco, las colisiones, las bandas y las bolas que entran. El resultado hablado indica los contactos, las embocadas y la decisi\u00F3n arbitral. U abre la lista cronol\u00F3gica del \u00FAltimo tiro con \u00E1ngulo, fuerza y efecto. Y calcula todo el tiro actual y muestra su resultado y posiciones finales sin mover las bolas reales. Escape cierra el informe.",
              "Con sonido 3D (HRTF), oyes el taco, las colisiones, las bandas y las embocadas desde sus posiciones en la mesa. La distribuci\u00F3n es fija: izquierda y derecha de la mesa siguen a tu izquierda y derecha, y la parte lejana queda delante de ti. Los pitidos de punter\u00EDa siempre suenan en el centro, incluso con HRTF activado. En Power Games, abre Ajustes \u2192 Sonidos, activa HRTF y marca Billar en la lista de juegos con sonido 3D. Con HRTF desactivado o no disponible, los sonidos siguen en est\u00E9reo.",
              "Cuando la l\u00EDnea de punter\u00EDa entra en la abertura de una tronera, un tono breve de 3000 Hz acompa\u00F1a su n\u00FAmero. No se repite el n\u00FAmero mientras sigas sobre esa abertura. Las descripciones empiezan por el n\u00FAmero o color de la bola; en pool, las bolas 9\u201315 son rayadas.",
              "Apunta a una banda y pulsa V para calcular el rebote de la bola de tiro activa con la fuerza y el efecto actuales. Oir\u00E1s la primera banda, el n\u00FAmero de contactos y un posterior contacto con bola o entrada en tronera. Se indica tambi\u00E9n si el tiro es demasiado d\u00E9bil para alcanzar la banda. Es una predicci\u00F3n, no un tiro ejecutado.",
              "B lee los objetos m\u00E1s all\u00E1 de la primera bola en la l\u00EDnea de punter\u00EDa: otras bolas en orden y despu\u00E9s banda o tronera. Omite las bolas fuera de l\u00EDnea y las que quedan detr\u00E1s de la bola de tiro. Si no hay bola antes de una banda o tronera, B la nombra directamente. Es una l\u00EDnea geom\u00E9trica recta; usa Y o Coma para calcular el movimiento f\u00EDsico."),
            rule_section(:object_prediction, "Predecir la bola a la que apuntas",
              "Apunta a una bola objetivo y pulsa Coma. Se calcula el tiro completo con el \u00E1ngulo, la fuerza y el efecto actuales; despu\u00E9s se describe lo que le ocurre a la primera bola de la l\u00EDnea de tiro: sus contactos y si entra en una tronera o se detiene en la mesa. Es el movimiento calculado por la f\u00EDsica del tiro, no una prolongaci\u00F3n recta de la punter\u00EDa. La predicci\u00F3n no ejecuta el tiro. Si no hay ninguna bola en la l\u00EDnea, se te indica. Y ofrece el informe del tiro completo con posiciones finales; V describe el rebote de la bola de tiro activa."),
            rule_section(:match, "Elegir modalidad y tomar decisiones",
              "La modalidad se elige en los ajustes de la mesa. El pool competitivo, el snooker, el billar ingl\u00E9s y la carambola requieren dos jugadores; Cutthroat requiere tres. Empieza la primera persona de la lista y los jugadores alternan el inicio de las siguientes partidas. El encuentro suele terminar al alcanzar el n\u00FAmero elegido de partidas ganadas. Los puntos dentro de cada partida se cuentan por separado.",
              "P abre las declaraciones y decisiones pendientes. Elige la bola, la tronera y los dem\u00E1s datos necesarios y confirma la elecci\u00F3n; despu\u00E9s tira con Intro o Espacio en el control del taco. Intro solicita las declaraciones que falten. May\u00FAs+P lee la situaci\u00F3n reglamentaria, T el turno y S los resultados sin otra ventana. M coloca la bola de tiro activa solo cuando tienes bola en mano. Q permite conceder la partida actual. Una propuesta de recolocar por bloqueo, abierta con P, necesita la aceptaci\u00F3n de todos los dem\u00E1s jugadores; un solo rechazo devuelve el turno a quien la propuso."),
            rule_section(:pool_eight, "Pool: bola 8",
              "La mesa empieza abierta y el saque no asigna grupos. Una bola anunciada y embocada legalmente te asigna lisas 1\u20137 o rayadas 9\u201315; el rival recibe el otro grupo. Contin\u00FAas si embocas la bola anunciada en la tronera anunciada. Golpea primero tu grupo y, una vez eliminado, la 8. En una mesa abierta solo puedes anunciar la 8 si ya falta un grupo entero.",
              "Salvo en el saque, anuncia la bola y la tronera antes del golpe. P cambia la declaraci\u00F3n y Enter solicita los datos que faltan. Una defensa termina el turno aunque caiga una bola. Embocar la 8 antes de tiempo, con falta o en otra tronera pierde la partida. Embocar solo la blanca sin la 8 es una falta normal. Tambi\u00E9n lo son tocar primero una bola incorrecta o no embocar ni alcanzar una banda despu\u00E9s del contacto. El rival recibe blanca en mano en toda la mesa.",
              "Si el saque no emboca nada, al menos cuatro bolas objetivo distintas deben tocar banda. Si no, el rival puede aceptar la posici\u00F3n o elegir qui\u00E9n vuelve a colocar y sacar. Una 8 embocada en un saque legal se repone o el sacador puede repetir. Con falta y 8, decide el rival, con blanca en mano detr\u00E1s de la l\u00EDnea de cabeza si conserva la posici\u00F3n. Otras faltas de saque permiten aceptar la posici\u00F3n o tomar blanca detr\u00E1s de esa l\u00EDnea. Desde all\u00ED no puedes tocar directamente una bola de esa zona sin cruzar primero la l\u00EDnea. Si todas las bolas v\u00E1lidas est\u00E1n all\u00ED, P permite solicitar que la m\u00E1s cercana vuelva al punto de pie."),
            rule_section(:pool_nine, "Pool: bola 9",
              "Golpea primero la bola de menor n\u00FAmero que quede. Cualquier bola objetivo embocada legalmente prolonga el turno y una 9 legal gana, incluso mediante combinaci\u00F3n. No hace falta anunciar tronera. Una falta da al rival blanca en mano en toda la mesa. La 9 vuelve al punto de pie si cae con falta o push-out; las dem\u00E1s quedan fuera. Tres faltas consecutivas del mismo jugador pierden la partida; tras dos se anuncia una advertencia. Un golpe legal reinicia su contador.",
              "En el rombo, la 9 queda en el punto de pie y la 1 delante. Un saque sin embocar debe llevar cuatro bolas a banda. La regla de tres bolas exige adem\u00E1s que al menos tres bolas distintas caigan o crucen la l\u00EDnea de cabeza. Si no se cumple sin otra falta, el rival acepta la posici\u00F3n o devuelve el tiro; una 9 embocada se repone. Solo el sacador que recibe el tiro devuelto puede entonces hacer push-out. Tras un saque legal, el segundo golpe puede ser un push-out declarado con P: se suspenden la obligaci\u00F3n de tocar la menor y la de alcanzar banda. Despu\u00E9s, el rival elige qui\u00E9n sigue."),
            rule_section(:pool_ten, "Pool: bola 10",
              "Golpea primero el n\u00FAmero m\u00E1s bajo que quede, pero declara con P una bola y una tronera antes de cada tiro normal. No hay declaraci\u00F3n de defensa. Cumplir legalmente la declaraci\u00F3n mantiene tu turno. La 10 solo gana si era la \u00FAnica bola objetivo antes del tiro y entra legalmente en la tronera declarada; las dieces anteriores se reponen.",
              "La apertura necesita una embocada o cuatro bolas objetivo distintas en las bandas. Tras una apertura legal puedes declarar con P un push-out para el segundo tiro; despu\u00E9s de un push-out legal el rival acepta o devuelve el tiro. En juego normal, embocar sin cumplir la declaraci\u00F3n tambi\u00E9n ofrece esa elecci\u00F3n al rival. Una falta da bola en mano en cualquier lugar; tres faltas consecutivas pierden la partida."),
            rule_section(:straight_pool, "Pool continuo 14.1",
              "Declara bola y tronera con P. Si cumples legalmente el tiro, cada bola objetivo embocada en \u00E9l vale 1 punto y contin\u00FAas. Gana la partida quien alcanza el objetivo de puntos. Fallar la declaraci\u00F3n o declarar defensa acaba el turno y repone las bolas embocadas.",
              "La apertura se juega desde detr\u00E1s de la l\u00EDnea de cabeza. Cumple la embocada declarada o, despu\u00E9s del contacto, env\u00EDa la blanca y al menos dos bolas objetivo a las bandas. Fallar cuesta 2 puntos; el rival acepta la posici\u00F3n o exige repetir la apertura. Una falta normal cuesta 1 y puede dejar un resultado negativo. Un scratch da al rival bola en mano detr\u00E1s de la l\u00EDnea de cabeza. La tercera falta normal consecutiva cuesta 16 puntos en ese tiro y obliga a abrir de nuevo el tri\u00E1ngulo completo; las faltas de apertura no entran en esa serie.",
              "Tras puntuar catorce bolas, se montan de nuevo con el v\u00E9rtice vac\u00EDo y se dejan la blanca y la \u00FAltima bola en sus posiciones. Contin\u00FAas sin el requisito de dispersi\u00F3n inicial. Si entr\u00F3 tambi\u00E9n la \u00FAltima bola o ambas restantes estorban al tri\u00E1ngulo, vuelven las quince. Una bola objetivo que estorbe sola va al punto de cabeza o al centro si est\u00E1 ocupado. Si solo estorba la blanca, una \u00FAltima bola en la l\u00EDnea de cabeza o m\u00E1s all\u00E1 da bola en mano detr\u00E1s de ella; si est\u00E1 antes, la blanca va al punto de cabeza o al centro.",
              "Una recolocaci\u00F3n acordada por bloqueo conserva puntos y deudas; P ofrece elegir qui\u00E9n abre. Cada nueva partida del encuentro empieza desde cero."),
            rule_section(:one_pocket, "One Pocket",
              "Cada jugador tiene una de las dos troneras de esquina del extremo derecho. Quien abre elige la suya con P antes de tirar. Cada bola legal que entre en tu tronera te da 1 punto, aunque la embocara el rival; el primero en llegar a 8 gana. Embocar legalmente en tu tronera mantiene tu turno. Las bolas de otras troneras se reponen al acabar la entrada, o inmediatamente si se vac\u00EDa la mesa antes de la victoria. La apertura exige contacto y despu\u00E9s banda o embocada, sin dispersar cuatro bolas.",
              "Una falta te quita 1 punto y devuelve una de tus bolas ganadas. Si no tienes ninguna, debes una bola: una futura embocada puntuable paga la deuda y se repone. Las bolas de la tronera rival punt\u00FAan incluso con falta, salvo que la \u00FAnica falta fuera embocar la blanca. Sacar la blanca de la mesa o embocarla junto con otra falta no anula esos puntos del rival. Un scratch da bola en mano detr\u00E1s de la l\u00EDnea de cabeza. Tres faltas consecutivas pierden la partida. Si ambos llegan a 8 en el mismo tiro, gana quien tira. Recolocar de mutuo acuerdo conserva puntos y deudas y exige elegir de nuevo qui\u00E9n hace el saque y las troneras."),
            rule_section(:bank, "Bank Pool: corto y completo",
              "Para que una embocada punt\u00FAe, declara bola, tronera y orden de bandas. Con P elige bola y tronera y a\u00F1ade cada banda siguiente: izquierda, derecha, superior o inferior. Termina la ruta cuando est\u00E9 lista; admite de uno a doce contactos. Cancelar conserva la declaraci\u00F3n anterior. La blanca debe golpear la bola declarada antes de tocar otra bola o banda. La bola declarada no puede tocar otra bola ni volver a tocar la blanca. Sus bandas deben coincidir con la ruta; no cuentan los contactos accidentales con las mand\u00EDbulas de la tronera de destino al entrar.",
              "Una embocada v\u00E1lida de banco da 1 punto y mantiene el turno. La variante corta usa 9 bolas y un objetivo de 5; la completa, 15 bolas y un objetivo de 8. Las bolas extra se reponen al acabar la entrada, o inmediatamente si se vac\u00EDa la mesa antes de ganar. No declares banco en la apertura: embocar mantiene el turno, pero no punt\u00FAa. Sin embocada, cuatro bolas objetivo distintas deben alcanzar las bandas; una apertura insuficiente permite al rival aceptar o exigir repetirla.",
              "Una falta cuesta 1 punto y devuelve una bola ganada. Si no tienes ninguna, pagas la deuda reponiendo una futura bola puntuable; el resultado puede ser negativo. Un scratch da bola en mano detr\u00E1s de la l\u00EDnea de cabeza. Tres faltas consecutivas pierden la partida. Una recolocaci\u00F3n acordada por bloqueo conserva puntos y deudas, y P permite elegir de nuevo qui\u00E9n hace el saque."),
            rule_section(:cutthroat, "Cutthroat para tres jugadores",
              "Esta variante de club asigna grupos fijos por asiento: 1\u20135, 6\u201310 y 11\u201315. Protege tu grupo y elimina los dem\u00E1s. Puedes tocar primero cualquier bola objetivo y sacrificar una propia. Una embocada legal mantiene el turno salvo que retire tu \u00FAltima bola. Se salta temporalmente a quien no tenga bolas; gana el \u00FAltimo grupo que permanezca.",
              "Una falta da al siguiente jugador bola en mano en cualquier lugar y repone una bola embocada de cada rival: el n\u00FAmero m\u00E1s bajo que falte en su grupo. As\u00ED puede volver alguien que estaba siendo saltado. No se pierde por tres faltas. Si un tiro legal elimina todos los grupos, la ronda termina en empate. Los grupos son fijos y no se negocian durante la partida. Conceder con Q retira todas las bolas de tu grupo e impide que vuelvan durante esa partida; los dem\u00E1s jugadores contin\u00FAan."),
            rule_section(:blackball, "Blackball",
              "Juega tu grupo de lisas o rayadas y despu\u00E9s la negra. No se declaran troneras. La mesa sigue abierta tras la apertura y los tiros libres; un tiro normal legal posterior asigna los grupos. Una embocada legal mantiene el turno. Embocar la \u00FAltima bola propia junto con la negra gana legalmente; embocar la negra con falta o antes de eliminar tu grupo pierde la partida. La negra en la apertura, en cambio, provoca otro montaje para la misma persona.",
              "Una apertura legal emboca o hace cruzar la l\u00EDnea central a dos bolas objetivo distintas como m\u00EDnimo. Una falta concede un tiro libre seguido de uno normal. Juega el libre desde la posici\u00F3n actual o usa M para mover la bola de tiro a baulk, la quinta parte izquierda. El tiro libre solo suspende la primera bola obligatoria: embocar \u00FAnicamente bolas rivales sigue siendo falta. Tras el tiro normal, continuar vuelve a exigir una embocada legal. En un snooker completo, sin camino a ninguna parte de una bola v\u00E1lida, se suspende el requisito habitual de banda. Debes alejarte de una bola v\u00E1lida que est\u00E9s tocando sin empujarla."),
            rule_section(:snooker, "Snooker",
              "Hay quince rojas de un punto y amarilla 2, verde 3, marr\u00F3n 4, azul 5, rosa 6 y negra 7. Las rojas tienen identificadores 1\u201315 y los colores 16\u201321 en ese orden. Emboca una roja, nomina un color con P o cuando Enter lo pida y alterna roja y color. Varias rojas pueden puntuar en un golpe. En esta fase los colores vuelven a sus puntos, incluso tras falta; las rojas normalmente quedan fuera. Tras la \u00FAltima roja a\u00FAn puedes jugar un color; despu\u00E9s elimina de amarilla a negra en orden sin reponer los colores embocados legalmente.",
              "Una falta concede al rival de 4 a 7 puntos: se aplica el mayor valor pertinente de la bola v\u00E1lida y las tocadas o embocadas ilegalmente. El infractor no punt\u00FAa ese golpe. El rival juega o pide que repita el infractor. Tras embocar la blanca solo se coloca dentro de la D; M mueve \u00FAnicamente la blanca y conserva las posiciones finales de las dem\u00E1s. Un punto de color ocupado se sustituye por el libre de mayor valor o por la posici\u00F3n legal m\u00E1s cercana hacia la negra; rosa y negra pueden usar la direcci\u00F3n opuesta cuando sea necesario.",
              "Tras una falta, un snooker sobre todas las bolas v\u00E1lidas permite nominar bola libre con P. Deben verse ambos extremos de alguna bola v\u00E1lida para evitar un snooker; la banda no cuenta como obst\u00E1culo. Con blanca en mano se comprueba toda la D a la precisi\u00F3n de posici\u00F3n registrada. La bola libre toma el valor de la v\u00E1lida y vuelve a su punto si cae. No puede dejar por s\u00ED misma un snooker tras un golpe sin puntos, salvo la excepci\u00F3n de las dos \u00FAltimas bolas.",
              "Si hab\u00EDa una trayectoria directa pero no se alcanz\u00F3 el primer contacto debido, el \u00E1rbitro puede declarar Foul and a Miss. El rival puede restaurar la posici\u00F3n y pedir repetici\u00F3n; los puntos de penalizaci\u00F3n se conservan. Dos fallos repetidos con acceso a bola completa generan aviso; otro pierde el frame. No se declara un Miss ordinario si ya se necesitan puntos de faltas o pasan a necesitarse tras el golpe. Cuando solo queda negra, la primera bola o falta resuelve el frame. Un empate repone la negra, sortea el derecho a elegir qui\u00E9n juega y da blanca en mano en la D; la siguiente bola o falta decide."),
            rule_section(:english, "Billar ingl\u00E9s",
              "Cada jugador conserva su bola de tiro blanca o amarilla; la roja es com\u00FAn. Al inicio, la roja est\u00E1 en su punto y quien empieza juega desde la D. La bola del otro jugador est\u00E1 inicialmente fuera de la mesa y entra cuando la necesita. Gana quien alcanza el objetivo de puntos o va por delante al terminar el tiempo elegido. Un tiro puntuado mantiene tu entrada.",
              "Un mismo tiro puede sumar varias jugadas:",
              "- Una carambola, o cannon, ocurre cuando tu bola toca las otras dos. Vale 2 puntos, una sola vez por tiro.",
              "- Embocar la roja vale 3 puntos; embocar la bola del rival, 2.",
              "- Embocar tu propia bola despu\u00E9s de tocar la roja vale 3; despu\u00E9s de la bola rival, 2. Si toca ambas, decide el primer contacto; un primer contacto simult\u00E1neo que no se pueda separar vale 2.",
              "Despu\u00E9s de embocar tu bola, col\u00F3cala en la D con M. Debes jugar fuera de baulk antes de jugar directamente una bola cuyo centro est\u00E9 en baulk, incluida su l\u00EDnea. Antes de regresar a baulk debes haber tocado una banda o bola fuera de \u00E9l. Un English Miss legal con todos los objetivos en baulk da 2 puntos al rival y se juega desde la posici\u00F3n resultante. Una falta tambi\u00E9n da 2, anula los puntos de ese tiro y ofrece con P aceptar la posici\u00F3n o recolocar la roja y la bola rival para jugar desde la D.",
              "La roja vuelve a su punto tras ser embocada. En embocadas consecutivas de solo la roja desde el punto, se juega dos veces desde el punto normal y una desde el centro; hay puntos alternativos si est\u00E1n ocupados. La bola rival embocada suele quedar fuera hasta que se necesita. Si tu bola queda tocando otra, se coloca la roja en su punto, la rival en el centro si estaba en la mesa y t\u00FA juegas desde la D.",
              "Una entrada admite como m\u00E1ximo 75 carambolas puras consecutivas o 15 tiros de hazard sin carambola; un hazard es una embocada de bola objetivo o de la propia tras un contacto. Hay avisos en 70 y 10. Combinar carambola y hazard interrumpe ambas series. Tras el decimoquinto hazard puede recolocarse la bola rival si qued\u00F3 fuera por la \u00FAltima entrada de ese rival. Si activas el cruce de baulk, el cruce hacia su interior debe hacerse entre los puntos 80 y 100 de cada centena de la entrada; omitirlo es falta."),
            rule_section(:carom, "Carambola libre, a una banda y a tres bandas",
              "Hay tres bolas en una mesa sin troneras. Conservas tu bola blanca o amarilla asignada durante toda la partida. Haces carambola cuando tu bola toca las otras dos en un tiro. Una carambola legal da 1 punto y mantiene tu entrada; fallar o cometer falta cede el turno sin descontar puntos. Gana quien alcanza el objetivo elegido, con la entrada de compensaci\u00F3n si est\u00E1 activada. Con la compensaci\u00F3n activada, si quien comenz\u00F3 alcanza el objetivo tras una entrada m\u00E1s, el otro jugador recibe una \u00FAltima entrada desde la posici\u00F3n inicial. Si tambi\u00E9n alcanza el objetivo, la partida es un empate; si termina esa entrada sin alcanzarlo, gana quien comenz\u00F3. Sin compensaci\u00F3n, alcanzar el objetivo gana inmediatamente.",
              "Al comenzar, P permite elegir el punto de salida inferior o superior. El primer ataque debe ser directamente a la roja. Despu\u00E9s se aplican estas diferencias:",
              "- La carambola libre no exige bandas. Sus cuatro tri\u00E1ngulos marcados en las esquinas limitan las carambolas repetidas.",
              "- A una banda, tu bola debe tocar al menos una banda antes de tocar la segunda bola objetivo distinta.",
              "- A tres bandas, necesita al menos tres contactos de ese tipo. Cuentan los rebotes separados en la misma banda y los anteriores a la primera bola objetivo. Los rebotes posteriores a la segunda no corrigen una carambola fallida.",
              "En una esquina de carambola libre, despu\u00E9s de entrar ambas bolas objetivo puedes puntuar una vez sin que salga ninguna. En la siguiente carambola debe salir al menos una del tri\u00E1ngulo; puede regresar durante el mismo tiro. La bola sobre la l\u00EDnea se interpreta en contra del jugador. Se comprueba el movimiento completo, no solo las posiciones finales.",
              "Si tu bola toca otra, la modalidad libre restaura las tres posiciones iniciales. En las modalidades de bandas, P ofrece jugar alej\u00E1ndote sin empujar la bola tocada o recolocar en los puntos. A una banda se recolocan las tres; a tres bandas, solo las que se tocan, en sus puntos correspondientes. Tirar directamente contra una banda a la que est\u00E1 pegada tu bola es falta. Si una bola sale de la mesa, se recolocan las tres en libre y a una banda, pero solo las que salieron a tres bandas."),
            rule_section(:pyramid, "Pir\u00E1mide libre",
              "Consigue 8 puntos antes que tu rival. Las diecis\u00E9is bolas valen lo mismo: 1 punto por cada embocada legal, incluida la bola de tiro tras tocar otra. No se declaran bola ni tronera. Antes de cada tiro posterior a la apertura, abre P y la elecci\u00F3n de bola de tiro para escoger cualquiera que quede en la mesa. Embocar legalmente mantiene el turno y permite elegir de nuevo.",
              "La apertura usa la bola de color desde detr\u00E1s de la l\u00EDnea de casa, en el cuarto izquierdo. Despu\u00E9s de tocar una bola objetivo, emboca una bola, env\u00EDa tres bolas objetivo distintas a las bandas o dos a las bandas y una bola objetivo al otro lado de la l\u00EDnea central.",
              "En los tiros siguientes, tras el contacto obligatorio debe ocurrir una de estas situaciones:",
              "- Se emboca una bola.",
              "- Una bola rebota en banda y despu\u00E9s alcanza otra banda, directamente o enviando otra bola all\u00ED. Tambi\u00E9n puede servir tocar una bola pegada a esa segunda banda.",
              "- Una bola cruza el centro y despu\u00E9s alcanza una banda, por s\u00ED misma o transmitiendo movimiento a otra; tambi\u00E9n cuenta una bola pegada a esa banda.",
              "- Despu\u00E9s de rebotar en banda, una bola cruza el centro, env\u00EDa otra al otro lado o toca una bola de la mitad opuesta o de la l\u00EDnea central. Tambi\u00E9n cuentan los contactos correspondientes transmitidos por otras bolas.",
              "Tras una falta se reponen primero las bolas embocadas ilegalmente y las que salieron. Con P el rival elige cualquier bola de la mesa como penalizaci\u00F3n, la retira y gana 1 punto. Despu\u00E9s juega o devuelve el tiro. Tras una apertura ilegal tambi\u00E9n puede recolocar y elegir qui\u00E9n abre; el punto se conserva y la pir\u00E1mide queda incompleta. Embocar solo tu bola de tiro no es autom\u00E1ticamente falta: punt\u00FAa si se hace legalmente tras un contacto. Varias infracciones en un tiro reciben una sola penalizaci\u00F3n.",
              "Las bolas repuestas se colocan desde el punto de pie hacia la derecha por el eje central, y en sentido contrario si falta espacio. Pueden ser la siguiente bola de tiro. Las bolas grandes y las mand\u00EDbulas estrechas requieren m\u00E1s precisi\u00F3n que el pool; apuntar a una tronera no garantiza pasar entre sus mand\u00EDbulas."),
            rule_section(:settings, "Ajustes del encuentro",
              "Antes de jugar, elige la modalidad y su condici\u00F3n de victoria. El billar social tiene un total de 1 a 30 rondas y uno de tres montajes. Cuando la modalidad lo permite, se fija un objetivo de puntos para cada partida; el objetivo del encuentro indica cu\u00E1ntas partidas hay que ganar. El billar ingl\u00E9s tambi\u00E9n puede jugarse por tiempo: se termina el tiro que ya haya comenzado y, si las puntuaciones finales son iguales, hay empate. La opci\u00F3n de entrada de compensaci\u00F3n en carambola concede al segundo jugador una \u00FAltima entrada desde la posici\u00F3n inicial cuando haga falta igualar las entradas. En el billar ingl\u00E9s por tiempo, el tiro debe aceptarse en la mesa antes del l\u00EDmite; pulsar la tecla antes no basta.",
              "El billar social empieza con el rombo de nueve bolas objetivo. En los ajustes de mesa puedes elegir una sola bola objetivo o el tri\u00E1ngulo de quince; sus bolas finales ser\u00E1n la 1 y la 15, respectivamente. Una elecci\u00F3n expresa y una partida guardada antigua conservan el montaje elegido.",
              "El objetivo del encuentro va de 1 a 25 partidas ganadas. Los objetivos de puntos ajustables van de 1 a 1000; el tiempo del billar ingl\u00E9s, de 1 a 180 minutos.",
              "La f\u00EDsica m\u00E1s precisa usa pasos de c\u00E1lculo menores y puede cambiar un contacto ajustado. La fuerza del ordenador determina cu\u00E1ntas propuestas de tiro compara. La fuerza y el efecto tambi\u00E9n se tienen en cuenta en las predicciones.",
              "El l\u00EDmite de 1 a 500 tiros solo se aplica a entrenamientos guardados antiguos, no a partidas nuevas."),
            rule_section(:referee, "Reglamentos y adaptaci\u00F3n digital",
              "El pool sigue las reglas y regulaciones WPA del 21 de octubre de 2026; el snooker y el billar ingl\u00E9s, WPBSA 2024\u201325; la carambola, UMB; y la pir\u00E1mide libre, la revisi\u00F3n IPC de 2025. Cutthroat y el billar social usan las reglas de club descritas aqu\u00ED. El orden de la mesa sustituye la prueba f\u00EDsica de salida. Acordar una recolocaci\u00F3n no da por s\u00ED mismo una partida ganada. El \u00E1rbitro autom\u00E1tico de snooker declara Miss solo con camino directo; los intentos totalmente obstruidos siguen siendo faltas normales sin restauraci\u00F3n.",
              "La simulaci\u00F3n es bidimensional: no hay controles de salto, elevaci\u00F3n del taco ni mass\u00E9. Los empujones entre bolas en contacto y las mand\u00EDbulas son aproximaciones. Los primeros contactos no separables dentro de un paso f\u00EDsico se consideran simult\u00E1neos. La pir\u00E1mide usa una geometr\u00EDa de entrenamiento documentada con bolas grandes y troneras estrechas, no una certificaci\u00F3n actual del equipo de federaci\u00F3n. Las ayudas y predicciones usan la bola de tiro activa y la misma f\u00EDsica que el juego."),
            rule_section(:controls, "Atajos de teclado",
              "K: Leer la direcci\u00F3n del taco.",
              "F: Leer la fuerza del tiro.",
              "G: Leer el primer contacto en la l\u00EDnea de tiro.",
              "H: Enumerar las bolas pr\u00F3ximas a la l\u00EDnea de tiro.",
              "I: Describir la bola seleccionada.",
              "O: Enumerar todas las bolas y sus posiciones.",
              "L: Seleccionar la siguiente bola objetivo.",
              "Shift+L: Seleccionar la bola objetivo anterior.",
              "J: Elegir la tronera de destino.",
              "A: Apuntar al centro de la bola seleccionada.",
              "Shift+A: Apuntar la bola seleccionada hacia la tronera elegida.",
              "E: Introducir el \u00E1ngulo, la fuerza y el efecto exactos.",
              "W: Aumentar el efecto de avance.",
              "Shift+B: Aumentar el efecto de retroceso.",
              "N: Aumentar el efecto a la izquierda.",
              "D: Aumentar el efecto a la derecha.",
              "R: Quitar el efecto.",
              "C: Alternar entre grados y posiciones del reloj.",
              "Y: Predecir el tiro sin mover las bolas.",
              "U: Leer los contactos del \u00FAltimo tiro.",
              "Izquierda: girar 1 grado en sentido antihorario.",
              "Derecha: girar 1 grado en sentido horario.",
              "May\u00FAs+Izquierda: girar 0,1 grados en sentido antihorario.",
              "May\u00FAs+Derecha: girar 0,1 grados en sentido horario.",
              "Ctrl+Izquierda: girar 0,01 grados en sentido antihorario.",
              "Ctrl+Derecha: girar 0,01 grados en sentido horario.",
              "Arriba: aumentar la fuerza un 1 por ciento.",
              "Abajo: reducir la fuerza un 1 por ciento.",
              "May\u00FAs+Arriba: aumentar la fuerza un 0,1 por ciento.",
              "May\u00FAs+Abajo: reducir la fuerza un 0,1 por ciento.",
              "Intro o Espacio: ejecutar el tiro actual.",
              "T: leer de qui\u00E9n es el turno.",
              "V: Predecir el rebote en la banda y el siguiente contacto con una bola.",
              "B: Describir los objetos detr\u00E1s de la bola apuntada.",
              "S: Leer los resultados, incluidas rondas ganadas y puntos por embocadas en el modo social.",
              "M: Coloca la bola de tiro activa cuando tienes bola en mano.",
              "P: Abre declaraciones, elecci\u00F3n de bola de tiro o decisiones pendientes.",
              "May\u00FAs+P: Lee la situaci\u00F3n actual del encuentro.",
              "Q: Concede la ronda o partida actual tras confirmarlo.",
              "Coma: Predice la primera bola apuntada con la fuerza y el efecto actuales.")
          ]
        when "pl"
          [
            rule_section(:competition, "Bilard towarzyski: pierwsza gra",
              "Nowy st\u00F3\u0142 domy\u015Blnie wybiera bilard towarzyski. Mo\u017Ce w nim gra\u0107 od dw\u00F3ch do o\u015Bmiu graczy, tak\u017Ce komputerowych. Domy\u015Blny uk\u0142ad to romb bil 1\u20139 i bia\u0142a rozgrywaj\u0105ca. Usu\u0144 bile 1\u20138, a potem prawid\u0142owo wbij dziewi\u0105tk\u0119, aby wygra\u0107 rund\u0119. O wyniku meczu decyduj\u0105 wygrane rundy.",
              "Wybierz bil\u0119 obiektow\u0105 klawiszem L lub Shift+L i sprawd\u017A jej po\u0142o\u017Cenie pod I. Naci\u015Bnij A, aby skierowa\u0107 na ni\u0105 kij, popraw kierunek i si\u0142\u0119 strza\u0142kami, a potem uderz Enterem lub Spacj\u0105 na polu kija. W bilardzie towarzyskim nie deklarujesz bili ani \u0142uzy. Po strzale wys\u0142uchaj wyniku i informacji, kto gra dalej. Nast\u0119pny rozdzia\u0142 opisuje rundy, faule i punktacj\u0119, a kolejne ucz\u0105 celowania."),
            rule_section(:friendly, "Rundy towarzyskie i faule",
              "W bilardzie towarzyskim gra od dw\u00F3ch do o\u015Bmiu graczy, tak\u017Ce komputerowych. Wybierz \u0142\u0105cznie od 1 do 30 rund. Mecz ko\u0144czy si\u0119 po rozstrzygni\u0119ciu tej liczby rund i wygrywa osoba z najwi\u0119ksz\u0105 liczb\u0105 zwyci\u0119stw. Je\u015Bli kilka os\u00F3b ma t\u0119 sam\u0105 najwi\u0119ksz\u0105 liczb\u0119 wygranych rund, mecz ko\u0144czy si\u0119 remisem.",
              "W domy\u015Blnym rombie jest dziewi\u0119\u0107 bil obiektowych o numerach 1\u20139 oraz bia\u0142a rozgrywaj\u0105ca. Bil\u0105 ko\u0144cow\u0105 jest dziewi\u0105tka. Dop\u00F3ki zostaj\u0105 inne bile obiektowe, rozgrywaj\u0105ca musi najpierw trafi\u0107 kt\u00F3r\u0105\u015B z nich. Prawid\u0142owe wbicie zwyk\u0142ej bili przed\u0142u\u017Ca twoj\u0105 kolejk\u0119, a brak wbicia oddaje j\u0105 nast\u0119pnej osobie. Po kontakcie kt\u00F3ra\u015B bila musi doj\u015B\u0107 do bandy albo musi nast\u0105pi\u0107 wbicie bili obiektowej.",
              "Wbicie rozgrywaj\u0105cej, trafienie najpierw niew\u0142a\u015Bciwej bili lub brak wymaganej bandy daje nast\u0119pnemu graczowi bil\u0119 w r\u0119ce na ca\u0142ym stole; ustaw j\u0105 pod M. Pozosta\u0142e bile zachowuj\u0105 pozycje. Wczesne wbicie ostatniej bili albo wbicie jej z faulem ko\u0144czy rund\u0119 i przyznaje zwyci\u0119stwo nast\u0119pnej osobie w kolejno\u015Bci przy stole. Prawid\u0142owe wbicie wygrywa rund\u0119 strzelaj\u0105cemu. Pod P rozpoczniesz kolejn\u0105 rund\u0119, gdy pojawi si\u0119 ta decyzja. Dowolne ustawianie bil, cofanie i reset \u0107wiczenia nie nale\u017C\u0105 do tej gry.",
              "Obok wygranych rund zbierasz po 1 punkcie za ka\u017Cd\u0105 prawid\u0142owo wbit\u0105 bil\u0119 obiektow\u0105, tak\u017Ce prawid\u0142owo wbit\u0105 ostatni\u0105 bil\u0119. Bia\u0142a nie daje punkt\u00F3w. Uderzenie z faulem lub przedwczesnym wbiciem ostatniej bili nie daje punkt\u00F3w za wbicia. Punkty sumuj\u0105 si\u0119 przez wszystkie rundy meczu; nie decyduj\u0105 o wygranej w rundzie ani nie rozstrzygaj\u0105 remisu w meczu. S wypowiada wygrane rundy i punkty za wbicia bez otwierania okna, a Shift+P podaje oba liczniki w opisie sytuacji w meczu."),
            rule_section(:table, "Odczytywanie sto\u0142u",
              "X mierzy odleg\u0142o\u015B\u0107 od lewego ko\u0144ca, a Y od dolnej bandy. Kierunki to: 0 stopni w prawo, 90 w g\u00F3r\u0119, 180 w lewo, 270 w d\u00F3\u0142. C prze\u0142\u0105cza odczyt na godziny zegara: odpowiednio trzeci\u0105, dwunast\u0105, dziewi\u0105t\u0105 i sz\u00F3st\u0105. \u0141uzy 1\u20136 le\u017C\u0105 kolejno: na dole po lewej, na dole po\u015Brodku, na dole po prawej, na g\u00F3rze po lewej, na g\u00F3rze po\u015Brodku i na g\u00F3rze po prawej. Sto\u0142y karambolowe nie maj\u0105 \u0142uz.",
              "O otwiera pozycje wszystkich bil, od najbli\u017Cszych aktywnej bili rozgrywaj\u0105cej; wbite s\u0105 na ko\u0144cu. L i Shift+L wybieraj\u0105 bil\u0119 obiektow\u0105, a I opisuje jej numer lub kolor, sektor, wsp\u00F3\u0142rz\u0119dne, odleg\u0142o\u015B\u0107 i przeszkody. Do listy bil mo\u017Cesz te\u017C doj\u015B\u0107 Tabem i przegl\u0105da\u0107 j\u0105 strza\u0142kami. W poolu rozgrywa bia\u0142a; w bilardzie angielskim i karambolu w\u0142asna bia\u0142a lub \u017C\u00F3\u0142ta, a w wolnej piramidzie wybrana przez ciebie bila.",
              "W poolu linia bazy przecina lew\u0105 \u0107wiartk\u0119 sto\u0142u, a punkt tylny le\u017Cy na osi pod\u0142u\u017Cnej w prawej \u0107wiartce. W snookerze i bilardzie angielskim baulk to obszar na lewo od linii oddalonej o 73,7 cm od lewego ko\u0144ca. D jest p\u00F3\u0142kolem o promieniu 29,2 cm po tej stronie linii. Tr\u00F3jk\u0105ty naro\u017Cne karambolu si\u0119gaj\u0105 71 cm wzd\u0142u\u017C d\u0142ugiej bandy i 35,5 cm wzd\u0142u\u017C kr\u00F3tkiej. Punkt bazy to \u015Brodek linii bazy, nazywanej te\u017C lini\u0105 rozbicia.",
              "- Pool: 254 na 127 cm.",
              "- Snooker i bilard angielski: 356,9 na 177,8 cm.",
              "- Karambol: 284 na 142 cm, bez \u0142uz.",
              "- Wolna piramida: 355 na 177,5 cm."),
            rule_section(:aim, "Celowanie i uderzenie",
              "Wr\u00F3\u0107 Tabem na pole kija. Lewo i Prawo obracaj\u0105 go przeciwnie do wskaz\u00F3wek zegara i zgodnie z nimi o jeden stopie\u0144. Shift zmniejsza krok do 0,1 stopnia, a Ctrl do 0,01. G\u00F3ra i D\u00F3\u0142 zmieniaj\u0105 si\u0142\u0119 o jeden procent, z Shiftem o 0,1 procenta. Puszczenie strza\u0142ki celowania odczytuje kr\u00F3tki opis bili, bandy lub \u0142uzy. K podaje dok\u0142adny k\u0105t, a F si\u0142\u0119.",
              "Podczas obracania kija kr\u00F3tkie pikni\u0119cia pomagaj\u0105 namierzy\u0107 bil\u0119: \u015Brodek pierwszej bili na linii uderzenia daje ton 5000 Hz, a zbli\u017Canie si\u0119 do dowolnej kraw\u0119dzi obni\u017Ca go a\u017C do 500 Hz. Poza bilami jest cisza, z wyj\u0105tkiem celowania do \u0142uzy. Sygna\u0142 uwzgl\u0119dnia rotacj\u0119 boczn\u0105 i ustawienia d\u017Awi\u0119k\u00F3w gry. Cichnie po opuszczeniu pola Kij lub otwarciu formularza. S\u0142yszysz go tylko na swoim komputerze.",
              "Wybierz bil\u0119 i naci\u015Bnij A, aby skierowa\u0107 kij na jej \u015Brodek. \u017Beby przygotowa\u0107 wbicie, wybierz \u0142uz\u0119 klawiszem J, a potem naci\u015Bnij Shift+A. Ta pomoc ustawia k\u0105t; banda, inne bile, si\u0142a i rotacja nadal mog\u0105 przeszkodzi\u0107 we wbiciu. Klawisz G opisuje pierwsz\u0105 przeszkod\u0119 na linii celowania, w tym stron\u0119 kontaktu z bil\u0105. H odczytuje bile w s\u0105siedztwie pi\u0119ciu stopni od tej linii, r\u00F3wnie\u017C te zas\u0142oni\u0119te.",
              "Klawisz E otwiera formularz dok\u0142adnych warto\u015Bci. Mo\u017Cesz u\u017Cywa\u0107 kropki lub przecinka dziesi\u0119tnego. K\u0105t mie\u015Bci si\u0119 od 0 do 359,99 stopnia, a si\u0142a od 0,1 do 100 procent. Wybierz Zastosuj, aby zachowa\u0107 ustawienia, albo Anuluj, aby pozosta\u0107 przy poprzednich. Enter lub Spacja w polu Kij wykonuje uderzenie."),
            rule_section(:spin, "Rotacja",
              "W zwi\u0119ksza rotacj\u0119 g\u00F3rn\u0105, a Shift+B doln\u0105. N zwi\u0119ksza rotacj\u0119 w lewo, D w prawo. Ka\u017Cde naci\u015Bni\u0119cie zmienia warto\u015B\u0107 o pi\u0119\u0107. R przywraca uderzenie bez rotacji. Rotacja g\u00F3rna pomaga rozgrywaj\u0105cej pod\u0105\u017Cy\u0107 za trafion\u0105 bil\u0105, a dolna mo\u017Ce j\u0105 cofn\u0105\u0107. Boczna zmienia odbicia od band i nieznacznie odchyla pocz\u0105tkowy kierunek uderzenia. Efekt zale\u017Cy od si\u0142y i odleg\u0142o\u015Bci: tarcie o sukno mo\u017Ce wytraci\u0107 rotacj\u0119 doln\u0105, zanim rozgrywaj\u0105ca dotrze do celu.",
              "Obie warto\u015Bci rotacji mieszcz\u0105 si\u0119 od -100 do 100. \u0141\u0105cznie musz\u0105 odpowiada\u0107 punktowi wewn\u0105trz bili rozgrywaj\u0105cej: maksymalnej rotacji g\u00F3rnej nie mo\u017Cna po\u0142\u0105czy\u0107 z maksymaln\u0105 boczn\u0105. Formularz odrzuci takie ustawienie."),
            rule_section(:feedback, "S\u0142uchanie uderzenia",
              "Podczas gry s\u0142ycha\u0107 kij, zderzenia bil, bandy i wpadanie do \u0142uz. Opis po strzale podaje trafienia, wbicia i decyzj\u0119 s\u0119dziego. U otwiera chronologiczn\u0105 list\u0119 kontakt\u00F3w ostatniego strza\u0142u wraz z k\u0105tem, si\u0142\u0105 i rotacj\u0105. Y oblicza ca\u0142e bie\u017C\u0105ce uderzenie oraz pokazuje wynik i ko\u0144cowe pozycje bez poruszania rzeczywistych bil. Escape zamyka raport.",
              "Przy d\u017Awi\u0119ku 3D (HRTF) kij, zderzenia bil, bandy i wpadanie do \u0142uz s\u0142ycha\u0107 z ich miejsc na stole. Uk\u0142ad jest sta\u0142y: lewa i prawa strona sto\u0142u pozostaj\u0105 po twojej lewej i prawej, a dalsza cz\u0119\u015B\u0107 sto\u0142u znajduje si\u0119 przed tob\u0105. Pikni\u0119cia celowania zawsze brzmi\u0105 na \u015Brodku, tak\u017Ce przy w\u0142\u0105czonym HRTF. W Power Games otw\u00F3rz Ustawienia \u2192 D\u017Awi\u0119ki, w\u0142\u0105cz HRTF i zaznacz Bilard na li\u015Bcie gier z d\u017Awi\u0119kiem 3D. Przy wy\u0142\u0105czonym lub niedost\u0119pnym HRTF d\u017Awi\u0119ki pozostaj\u0105 stereofoniczne.",
              "Gdy linia celowania wejdzie w otw\u00F3r \u0142uzy, kr\u00F3tki ton 3000 Hz towarzyszy jej numerowi. Numer nie powtarza si\u0119 podczas pozostawania nad tym samym otworem. Opisy bil zaczynaj\u0105 si\u0119 od numeru lub koloru; poolowe bile 9\u201315 maj\u0105 pasy.",
              "Skieruj kij na band\u0119 i naci\u015Bnij V, aby obliczy\u0107 odbicie aktywnej rozgrywaj\u0105cej przy bie\u017C\u0105cej sile i rotacji. Us\u0142yszysz pierwsz\u0105 band\u0119, liczb\u0119 kontakt\u00F3w oraz p\u00F3\u017Aniejsze trafienie bili albo wpadni\u0119cie do \u0142uzy. Program powie te\u017C, gdy strza\u0142 jest za s\u0142aby, aby doj\u015B\u0107 do bandy. To prognoza, nie wykonany strza\u0142.",
              "B odczytuje obiekty dalej na linii celowania, za pierwsz\u0105 bil\u0105: nast\u0119pne bile po kolei, potem band\u0119 lub \u0142uz\u0119. Pomija bile poza lini\u0105 i za rozgrywaj\u0105c\u0105. Gdy przed band\u0105 lub \u0142uz\u0105 nie ma bili, B nazywa j\u0105 bezpo\u015Brednio. Jest to prosta linia geometryczna; ruch wynikaj\u0105cy z fizyki obliczysz pod Y albo przecinkiem."),
            rule_section(:object_prediction, "Prognoza namierzonej bili",
              "Wyceluj w bil\u0119 obiektow\u0105 i naci\u015Bnij przecinek. Program obliczy ca\u0142e uderzenie przy bie\u017C\u0105cym k\u0105cie, sile i rotacji, po czym opisze ruch pierwszej bili na linii celowania: jej kontakty oraz to, czy wpada do \u0142uzy, czy zatrzymuje si\u0119 na stole. Jest to wynik fizyki uderzenia, a nie proste przed\u0142u\u017Cenie linii celowania. Prognoza nie wykonuje strza\u0142u. Gdy na linii nie ma bili, us\u0142yszysz t\u0119 informacj\u0119. Y podaje raport ca\u0142ego uderzenia z ko\u0144cowymi pozycjami, a V opisuje odbicie aktywnej bili rozgrywaj\u0105cej od bandy."),
            rule_section(:match, "Wyb\u00F3r odmiany i decyzje przy stole",
              "Odmian\u0119 wybierasz w ustawieniach sto\u0142u. Rozgrywki poolowe, snooker, bilard angielski i karambol wymagaj\u0105 dw\u00F3ch graczy, a Cutthroat trzech. Rozpoczyna pierwsza osoba na li\u015Bcie; p\u00F3\u017Aniej gracze zaczynaj\u0105 partie lub frejmy naprzemiennie. Mecz zwykle ko\u0144czy osi\u0105gni\u0119cie wybranej liczby zwyci\u0119stw w partiach. Punkty zdobyte wewn\u0105trz partii s\u0105 liczone osobno.",
              "P otwiera deklaracje i oczekuj\u0105ce decyzje. Wska\u017C bil\u0119, \u0142uz\u0119 lub inne wymagane szczeg\u00F3\u0142y, zatwierd\u017A wyb\u00F3r, a nast\u0119pnie uderz Enterem lub Spacj\u0105 na polu kija. Enter pyta o brakuj\u0105c\u0105 deklaracj\u0119. Shift+P odczytuje sytuacj\u0119 wynikaj\u0105c\u0105 z zasad, T kolejk\u0119, a S wyniki bez dodatkowego okna. M ustawia aktywn\u0105 bil\u0119 rozgrywaj\u0105c\u0105 tylko wtedy, gdy przys\u0142uguje bila w r\u0119ce. Q proponuje poddanie bie\u017C\u0105cej partii. Ponowne ustawienie przy zastoju, zaproponowane pod P, wymaga zgody wszystkich pozosta\u0142ych graczy; jedna odmowa oddaje gr\u0119 proponuj\u0105cemu."),
            rule_section(:pool_eight, "Pool: 8 bil",
              "Pocz\u0105tkowo st\u00F3\u0142 jest otwarty. Rozbicie nie przypisuje grup. P\u00F3\u017Aniejsze prawid\u0142owe wbicie zadeklarowanej bili przypisuje ci pe\u0142ne 1\u20137 albo pasy 9\u201315; przeciwnik otrzymuje drug\u0105 grup\u0119. Kontynuujesz po wbiciu zadeklarowanej bili do zadeklarowanej \u0142uzy. Najpierw trafiaj w\u0142asn\u0105 grup\u0119, a po jej usuni\u0119ciu graj \u00F3semk\u0119. Przy otwartym stole wolno zadeklarowa\u0107 \u00F3semk\u0119 tylko wtedy, gdy ca\u0142a jedna grupa ju\u017C znikn\u0119\u0142a.",
              "Poza rozbiciem zadeklaruj bil\u0119 i \u0142uz\u0119 przed uderzeniem. P zmienia deklaracj\u0119, a Enter pyta o brakuj\u0105c\u0105. Zagranie bezpieczne ko\u0144czy kolejk\u0119 nawet po wbiciu bili. Wbicie \u00F3semki za wcze\u015Bnie, z faulem lub do niew\u0142a\u015Bciwej \u0142uzy oznacza przegran\u0105. Wbicie samej bia\u0142ej bez \u00F3semki jest zwyk\u0142ym faulem. Faul to r\u00F3wnie\u017C pierwsze trafienie niew\u0142a\u015Bciwej bili albo brak wbicia i brak bandy po kontakcie. Przeciwnik dostaje bia\u0142\u0105 w r\u0119ce na ca\u0142ym stole.",
              "Gdy rozbicie nic nie wbije, co najmniej cztery r\u00F3\u017Cne bile obiektowe musz\u0105 dotkn\u0105\u0107 band. W przeciwnym razie przeciwnik mo\u017Ce przyj\u0105\u0107 pozycj\u0119 albo wskaza\u0107, kto ponownie ustawi i rozbije bile. \u00D3semka wbita przy prawid\u0142owym rozbiciu wraca na punkt lub rozbijaj\u0105cy wybiera ponowne rozbicie. \u00D3semka wbita z faulem daje ten wyb\u00F3r przeciwnikowi, z bia\u0142\u0105 w r\u0119ce za lini\u0105 rozbicia przy zachowaniu pozycji. Przy innych faulach rozbicia wybiera on zastan\u0105 pozycj\u0119 albo bia\u0142\u0105 za lini\u0105. Nie wolno stamt\u0105d trafi\u0107 bezpo\u015Brednio bili pozostaj\u0105cej za t\u0105 lini\u0105 bez jej uprzedniego przekroczenia. Je\u015Bli wszystkie dozwolone bile s\u0105 w tym obszarze, P pozwala poprosi\u0107 o przeniesienie najbli\u017Cszej na punkt."),
            rule_section(:pool_nine, "Pool: 9 bil",
              "Zawsze traf najpierw najni\u017Cszy numer pozostaj\u0105cy na stole. Ka\u017Cde prawid\u0142owe wbicie bili obiektowej przed\u0142u\u017Ca kolejk\u0119, a prawid\u0142owa dziewi\u0105tka wygrywa, tak\u017Ce po kombinacji. Nie trzeba deklarowa\u0107 \u0142uzy. Faul daje przeciwnikowi bia\u0142\u0105 w r\u0119ce na ca\u0142ym stole. Dziewi\u0105tka wraca na punkt po wbiciu z faulem lub push-oucie; pozosta\u0142e bile zostaj\u0105 w \u0142uzach. Trzy kolejne faule tej samej osoby przegrywaj\u0105 parti\u0119, a dwa wywo\u0142uj\u0105 ostrze\u017Cenie. Prawid\u0142owy strza\u0142 zeruje jej licznik fauli.",
              "W rombie dziewi\u0105tka stoi na punkcie, a jedynka z przodu. Rozbicie bez wbicia musi pos\u0142a\u0107 cztery bile do band. Regu\u0142a trzech bil wymaga ponadto, aby co najmniej trzy r\u00F3\u017Cne bile zosta\u0142y wbite lub przekroczy\u0142y lini\u0119 rozbicia. Je\u015Bli nie spe\u0142niono jej bez innego faulu, przeciwnik przyjmuje pozycj\u0119 albo oddaje zagranie; wbita dziewi\u0105tka wraca na punkt. Push-out przys\u0142uguje wtedy tylko rozbijaj\u0105cemu, kt\u00F3remu oddano zagranie. Po prawid\u0142owym rozbiciu drugi strza\u0142 mo\u017Ce by\u0107 zadeklarowanym pod P push-outem: nie trzeba trafia\u0107 najni\u017Cszego numeru ani dochodzi\u0107 do bandy. Po prawid\u0142owym push-oucie przeciwnik wybiera, kto gra dalej."),
            rule_section(:pool_ten, "Pool: 10 bil",
              "Najpierw trafiaj najni\u017Cszy pozosta\u0142y numer, lecz przed zwyk\u0142ym strza\u0142em zadeklaruj pod P bil\u0119 i \u0142uz\u0119. Nie ma deklaracji zagrania bezpiecznego. Prawid\u0142owe wykonanie deklaracji przed\u0142u\u017Ca kolejk\u0119. Dziesi\u0105tka wygrywa tylko wtedy, gdy przed strza\u0142em by\u0142a jedyn\u0105 bil\u0105 obiektow\u0105 i wpad\u0142a do zadeklarowanej \u0142uzy bez faulu; wcze\u015Bniejsze dziesi\u0105tki wracaj\u0105 na punkt.",
              "Rozbicie wymaga wbicia albo kontaktu czterech r\u00F3\u017Cnych bil obiektowych z bandami. Po prawid\u0142owym rozbiciu drugi strza\u0142 mo\u017Ce by\u0107 push-outem zadeklarowanym pod P; po prawid\u0142owym push-oucie przeciwnik przyjmuje strza\u0142 albo oddaje go sprawcy. W zwyk\u0142ej grze wbicie bili bez spe\u0142nienia deklaracji te\u017C daje przeciwnikowi ten wyb\u00F3r. Faul daje bia\u0142\u0105 w r\u0119ce na ca\u0142ym stole, a trzy kolejne faule przegrywaj\u0105 parti\u0119."),
            rule_section(:straight_pool, "Bilard ci\u0105g\u0142y 14.1",
              "Pod P zadeklaruj bil\u0119 i \u0142uz\u0119. Je\u015Bli prawid\u0142owo spe\u0142nisz deklaracj\u0119, ka\u017Cda bila obiektowa wbita tym strza\u0142em daje 1 punkt i grasz dalej. Osi\u0105gnij cel punktowy, aby wygra\u0107 parti\u0119. Niespe\u0142niona deklaracja lub zadeklarowane zagranie bezpieczne ko\u0144czy kolejk\u0119 i przywraca wbite bile.",
              "Pierwsze rozbicie wykonujesz zza linii bazy. Prawid\u0142owo wbij zadeklarowan\u0105 bil\u0119 albo po kontakcie posy\u0142aj do bandy bia\u0142\u0105 i co najmniej dwie bile obiektowe. B\u0142\u0105d kosztuje 2 punkty; przeciwnik przyjmuje pozycj\u0119 albo ka\u017Ce rozbi\u0107 ponownie. Zwyk\u0142y faul kosztuje 1 punkt, wi\u0119c wynik mo\u017Ce by\u0107 ujemny. Po wbiciu bia\u0142ej przeciwnik dostaje j\u0105 w r\u0119k\u0119 za lini\u0105 bazy. Trzeci kolejny zwyk\u0142y faul kosztuje 16 punkt\u00F3w w tym uderzeniu i wymusza nowe rozbicie pe\u0142nego tr\u00F3jk\u0105ta; b\u0142\u0119dy rozbicia nie nale\u017C\u0105 do tej serii.",
              "Po zdobyciu punkt\u00F3w za czterna\u015Bcie bil wracaj\u0105 one do tr\u00F3jk\u0105ta z wolnym wierzcho\u0142kiem; bia\u0142a i ostatnia bila pozostaj\u0105 na miejscach. Grasz dalej bez wymaga\u0144 pierwszego rozbicia. Gdy ostatnia bila te\u017C wpad\u0142a lub obie pozostawione bile przeszkadzaj\u0105 w ustawieniu, wraca pe\u0142ne pi\u0119tna\u015Bcie. Sama przeszkadzaj\u0105ca bila obiektowa trafia na punkt bazy, ewentualnie na \u015Brodek. Gdy przeszkadza tylko bia\u0142a, ostatnia bila na linii bazy lub dalej daje bia\u0142\u0105 w r\u0119ce za lini\u0105; bila po lewej stronie tej linii wysy\u0142a bia\u0142\u0105 na punkt bazy, a przy zaj\u0119ciu na \u015Brodek.",
              "Przy zaakceptowanym ponownym ustawieniu z powodu zastoju punkty i d\u0142ugi zostaj\u0105, a P pozwala wybra\u0107 nowego rozbijaj\u0105cego. Nowa partia meczu zaczyna si\u0119 od zera."),
            rule_section(:one_pocket, "One Pocket",
              "Ka\u017Cdy gracz ma jedn\u0105 z dw\u00F3ch naro\u017Cnych \u0142uz po prawej stronie sto\u0142u. Rozbijaj\u0105cy wybiera swoj\u0105 pod P przed rozbiciem. Ka\u017Cda prawid\u0142owo wbita do twojej \u0142uzy bila daje ci 1 punkt, nawet po strzale przeciwnika; pierwsza osoba z 8 punktami wygrywa. W\u0142asne prawid\u0142owe wbicie przed\u0142u\u017Ca kolejk\u0119. Bile z innych \u0142uz wracaj\u0105 po podej\u015Bciu albo od razu, gdy st\u00F3\u0142 opr\u00F3\u017Cni si\u0119 przed zwyci\u0119stwem. Rozbicie wymaga kontaktu i p\u00F3\u017Aniejszej bandy albo wbicia, bez czterech bil przy bandach.",
              "Faul odbiera ci 1 punkt i przywraca jedn\u0105 zdobyt\u0105 bil\u0119. Gdy jej nie masz, powstaje d\u0142ug: przysz\u0142e punktuj\u0105ce wbicie sp\u0142aca go, a bila wraca. Bile wbite przeciwnikowi punktuj\u0105 tak\u017Ce przy faulu, chyba \u017Ce jedynym faulem by\u0142o wbicie bia\u0142ej. Wypadni\u0119cie bia\u0142ej poza st\u00F3\u0142 albo jej wbicie po\u0142\u0105czone z innym faulem nie kasuje tych punkt\u00F3w przeciwnika. Po wbiciu bia\u0142ej przys\u0142uguje bila w r\u0119ce za lini\u0105 bazy. Trzy kolejne faule przegrywaj\u0105 parti\u0119. Gdy obie osoby osi\u0105gn\u0105 8 w tym samym strzale, wygrywa strzelaj\u0105cy. Uzgodnione ponowne ustawienie zachowuje punkty i d\u0142ugi oraz pyta o nowego rozbijaj\u0105cego i \u0142uzy."),
            rule_section(:bank, "Bank Pool: kr\u00F3tki i pe\u0142ny",
              "Punktuj\u0105ce wbicie od bandy wymaga deklaracji bili, \u0142uzy i kolejno\u015Bci band. Pod P wska\u017C bil\u0119 oraz \u0142uz\u0119, a nast\u0119pnie dodawaj kolejne bandy: lew\u0105, praw\u0105, g\u00F3rn\u0105 lub doln\u0105. Zako\u0144cz gotow\u0105 tras\u0119; mo\u017Cna wskaza\u0107 od jednego do dwunastu kontakt\u00F3w. Anulowanie zachowuje wcze\u015Bniejsz\u0105 deklaracj\u0119. Bia\u0142a musi trafi\u0107 zadeklarowan\u0105 bil\u0119 przed jak\u0105kolwiek band\u0105 lub inn\u0105 bil\u0105. Wskazana bila nie mo\u017Ce potem trafi\u0107 innej bili ani ponownie bia\u0142ej. Jej odbicia musz\u0105 odpowiada\u0107 deklaracji; przypadkowe kontakty ze szcz\u0119kami docelowej \u0142uzy podczas wpadania s\u0105 pomijane.",
              "Prawid\u0142owy bank daje 1 punkt i przed\u0142u\u017Ca kolejk\u0119. Wariant kr\u00F3tki ma 9 bil i cel 5 punkt\u00F3w, pe\u0142ny 15 bil i cel 8. Dodatkowe wbite bile czekaj\u0105 na powr\u00F3t do ko\u0144ca podej\u015Bcia albo wracaj\u0105 od razu, gdy st\u00F3\u0142 opr\u00F3\u017Cni si\u0119 przed zwyci\u0119stwem. Przy rozbiciu nie deklarujesz banku: wbicie przed\u0142u\u017Ca kolejk\u0119, ale nie daje punktu. Bez wbicia cztery r\u00F3\u017Cne bile obiektowe musz\u0105 dotkn\u0105\u0107 band; po b\u0142\u0119dnym rozbiciu przeciwnik przyjmuje uk\u0142ad albo nakazuje powt\u00F3rk\u0119.",
              "Faul kosztuje 1 punkt i powr\u00F3t zdobytej bili. Gdy jej nie masz, d\u0142ug sp\u0142acasz przywr\u00F3ceniem p\u00F3\u017Aniejszej punktuj\u0105cej bili; wynik mo\u017Ce by\u0107 ujemny. Wbicie bia\u0142ej daje j\u0105 w r\u0119k\u0119 za lini\u0105 bazy. Trzy kolejne faule przegrywaj\u0105 parti\u0119. Uzgodnione ponowne ustawienie przy zastoju zachowuje punkty i d\u0142ugi, po czym pod P wybiera si\u0119 nowego rozbijaj\u0105cego."),
            rule_section(:cutthroat, "Cutthroat dla trzech graczy",
              "Ten wariant klubowy przypisuje sta\u0142e grupy wed\u0142ug miejsc przy stole: 1\u20135, 6\u201310 i 11\u201315. Chro\u0144 w\u0142asn\u0105 grup\u0119 i usuwaj pozosta\u0142e. Pierwszy kontakt mo\u017Ce nast\u0105pi\u0107 z dowoln\u0105 bil\u0105 obiektow\u0105; wolno po\u015Bwi\u0119ci\u0107 w\u0142asn\u0105 bil\u0119. Prawid\u0142owe wbicie przed\u0142u\u017Ca kolejk\u0119, chyba \u017Ce usun\u0119\u0142o twoj\u0105 ostatni\u0105 bil\u0119. Osoby bez bil s\u0105 chwilowo pomijane; wygrywa ostatnia grupa pozostaj\u0105ca na stole.",
              "Faul daje nast\u0119pnemu graczowi bia\u0142\u0105 w r\u0119ce na ca\u0142ym stole i przywraca po jednej wbitej bili ka\u017Cdego przeciwnika \u2014 najni\u017Cszy brakuj\u0105cy numer z jego grupy. Mo\u017Ce to przywr\u00F3ci\u0107 do gry wcze\u015Bniej pomijan\u0105 osob\u0119. Nie ma przegranej za trzy faule. Je\u015Bli jedno prawid\u0142owe uderzenie usunie wszystkie grupy, runda ko\u0144czy si\u0119 remisem. W tym wariancie grupy s\u0105 sta\u0142e, bez negocjowania ich wyboru. Poddanie pod Q usuwa wszystkie bile twojej grupy i blokuje ich przywracanie do ko\u0144ca partii; pozostali gracze dogrywaj\u0105."),
            rule_section(:blackball, "Blackball",
              "Graj w\u0142asn\u0105 grup\u0119 pe\u0142nych albo pas\u00F3w, a potem czarn\u0105. Nie trzeba deklarowa\u0107 \u0142uz. St\u00F3\u0142 pozostaje otwarty po rozbiciu i wolnych uderzeniach; grupy przypisuje p\u00F3\u017Aniejsze prawid\u0142owe zwyk\u0142e wbicie. Prawid\u0142owe wbicie przed\u0142u\u017Ca kolejk\u0119. Jednoczesne wbicie ostatniej w\u0142asnej bili i czarnej jest prawid\u0142ow\u0105 wygran\u0105; wbicie czarnej z faulem albo przed usuni\u0119ciem w\u0142asnej grupy oznacza przegran\u0105. Czarna na rozbiciu zamiast tego powoduje nowe ustawienie dla tego samego rozbijaj\u0105cego.",
              "Prawid\u0142owe rozbicie wbija bil\u0119 albo posy\u0142a co najmniej dwie r\u00F3\u017Cne bile obiektowe przez \u015Brodek. Faul daje jedno wolne uderzenie, po nim jedno zwyk\u0142e. Wolne wykonaj z zastanej pozycji lub przenie\u015B rozgrywaj\u0105c\u0105 pod M do baulk \u2014 lewej jednej pi\u0105tej sto\u0142u. Wolne uderzenie zawiesza tylko wymaganie w\u0142a\u015Bciwej pierwszej bili: wbicie wy\u0142\u0105cznie bil przeciwnika nadal jest faulem. Po zwyk\u0142ym uderzeniu dalsza gra znowu wymaga prawid\u0142owego wbicia. Przy pe\u0142nym snookerze bez drogi do jakiejkolwiek cz\u0119\u015Bci dozwolonej bili nie wymaga si\u0119 zwyk\u0142ego kontaktu z band\u0105. Od stykaj\u0105cej si\u0119 dozwolonej bili trzeba odchodzi\u0107 bez jej pchni\u0119cia."),
            rule_section(:snooker, "Snooker",
              "Jest pi\u0119tna\u015Bcie czerwonych po jednym punkcie oraz \u017C\u00F3\u0142ta za 2, zielona za 3, br\u0105zowa za 4, niebieska za 5, r\u00F3\u017Cowa za 6 i czarna za 7. Czerwone maj\u0105 numery 1\u201315, a kolorowe 16\u201321 w podanej kolejno\u015Bci. Wbij czerwon\u0105, wska\u017C kolor pod P lub na pytanie po Enterze, po czym graj naprzemiennie czerwon\u0105 i kolor. W jednym strzale mo\u017Cna punktowa\u0107 kilka czerwonych. Kolory w tej fazie wracaj\u0105 na punkty, r\u00F3wnie\u017C po faulu. Czerwone zwykle pozostaj\u0105 wbite. Po ostatniej czerwonej przys\u0142uguje jeszcze jeden kolor, nast\u0119pnie usuwasz kolory od \u017C\u00F3\u0142tej do czarnej; prawid\u0142owo wbite kolory nie wracaj\u0105 na st\u00F3\u0142.",
              "Faul daje przeciwnikowi od 4 do 7 punkt\u00F3w: bierze si\u0119 najwy\u017Csz\u0105 nale\u017Cn\u0105 warto\u015B\u0107 bili granej oraz nieprawid\u0142owo trafionych lub wbitych. Sprawca nie punktuje tego strza\u0142u. Przeciwnik gra sam albo ka\u017Ce sprawcy zagra\u0107 ponownie. Po wbiciu bia\u0142ej ustawia si\u0119 j\u0105 wy\u0142\u0105cznie w D; M przesuwa tylko bia\u0142\u0105 i zachowuje ko\u0144cowe pozycje innych bil. Zaj\u0119ty punkt koloru zast\u0119puje najwy\u017Cszy wolny punkt, a gdy wszystkie s\u0105 zaj\u0119te \u2014 najbli\u017Csze dozwolone miejsce w stron\u0119 czarnej, z wyj\u0105tkiem r\u00F3\u017Cowej i czarnej, kt\u00F3re w razie potrzeby mog\u0105 trafi\u0107 w przeciwn\u0105 stron\u0119.",
              "Po faulu zas\u0142oni\u0119cie wszystkich bil granych pozwala wskaza\u0107 pod P woln\u0105 bil\u0119, czyli free ball. Aby nie by\u0142o snookera, musz\u0105 by\u0107 dost\u0119pne oba skrajne brzegi co najmniej jednej bili granej; banda nie jest bil\u0105 zas\u0142aniaj\u0105c\u0105. Przy bia\u0142ej w r\u0119ce sprawdzane jest ca\u0142e D z dok\u0142adno\u015Bci\u0105 zapisu pozycji. Wolna bila przyjmuje warto\u015B\u0107 bili granej i wraca na punkt po wbiciu. Po niepunktuj\u0105cym strzale nie mo\u017Ce sama zostawi\u0107 snookera, poza wyj\u0105tkiem ko\u0144cowych dw\u00F3ch bil.",
              "Je\u015Bli by\u0142a dost\u0119pna bezpo\u015Brednia droga, lecz nie nast\u0105pi\u0142o wymagane pierwsze trafienie, s\u0119dzia mo\u017Ce orzec Foul and a Miss. Przeciwnik mo\u017Ce odtworzy\u0107 pozycje sprzed strza\u0142u i nakaza\u0107 powt\u00F3rk\u0119; punkty karne zostaj\u0105. Dwa przywr\u00F3cone nieudane strza\u0142y przy pe\u0142nym dost\u0119pie do bili wywo\u0142uj\u0105 ostrze\u017Cenie, a kolejny przegrywa frejm. Zwyk\u0142ego Miss nie orzeka si\u0119, gdy punkty z fauli by\u0142y ju\u017C potrzebne albo staj\u0105 si\u0119 potrzebne po strzale. Gdy zostaje czarna, pierwsze wbicie lub faul rozstrzyga frejm. Remis przywraca czarn\u0105, losuje prawo wyboru graj\u0105cego i daje bia\u0142\u0105 w r\u0119ce w D; kolejne wbicie lub faul rozstrzyga wynik."),
            rule_section(:english, "Bilard angielski",
              "Ka\u017Cdy gracz ma w\u0142asn\u0105 bia\u0142\u0105 albo \u017C\u00F3\u0142t\u0105 bil\u0119 rozgrywaj\u0105c\u0105; czerwona jest wsp\u00F3lna. Na pocz\u0105tku czerwona stoi na punkcie, a rozpoczynaj\u0105cy gra swoj\u0105 bil\u0105 z D. Bila drugiego gracza pocz\u0105tkowo jest poza sto\u0142em i wchodzi do gry, gdy b\u0119dzie jej potrzebowa\u0142. Wygrywasz po osi\u0105gni\u0119ciu celu punktowego albo prowadz\u0105c po up\u0142ywie wybranego czasu. Punktuj\u0105ce uderzenie przed\u0142u\u017Ca podej\u015Bcie.",
              "W jednym uderzeniu mo\u017Cna po\u0142\u0105czy\u0107 kilka zdobyczy:",
              "- Karambol, nazywany cannon, to kontakt w\u0142asnej rozgrywaj\u0105cej z obiema pozosta\u0142ymi bilami. Daje 2 punkty, najwy\u017Cej raz w jednym uderzeniu.",
              "- Wbicie czerwonej daje 3 punkty, a bili przeciwnika 2.",
              "- Wpadni\u0119cie w\u0142asnej bili po kontakcie z czerwon\u0105 daje 3 punkty, a po bili przeciwnika 2. Gdy dotkni\u0119to obu, decyduje pierwszy kontakt; nierozstrzygalny kontakt jednoczesny daje 2.",
              "Po wbiciu w\u0142asnej bili ustaw j\u0105 pod M w D. Z tego pola trzeba zagra\u0107 poza baulk przed bezpo\u015Brednim graniem bili, kt\u00F3rej \u015Brodek pozostaje w baulk, tak\u017Ce na linii. Przed powrotem do baulk musi nast\u0105pi\u0107 kontakt z band\u0105 lub bil\u0105 poza nim. Prawid\u0142owy English Miss przy wszystkich celach w baulk daje przeciwnikowi 2 punkty i gr\u0119 z pozosta\u0142ej pozycji. Faul tak\u017Ce daje 2 punkty, lecz usuwa zdobycze tego uderzenia i udost\u0119pnia pod P wyb\u00F3r: przyj\u0105\u0107 pozycj\u0119 albo ustawi\u0107 czerwon\u0105 oraz bil\u0119 przeciwnika na punktach i zagra\u0107 z D.",
              "Czerwona po wbiciu wraca na punkt. Przy kolejnych wbiciach wy\u0142\u0105cznie czerwonej ze spotu dwa razy gra si\u0119 j\u0105 z normalnego punktu, a nast\u0119pnie raz ze \u015Brodka; zaj\u0119te punkty maj\u0105 zast\u0119pcze miejsca. Wbita bila przeciwnika zwykle pozostaje poza sto\u0142em do chwili, gdy b\u0119dzie potrzebna. Styk rozgrywaj\u0105cej z inn\u0105 bil\u0105 wymusza czerwon\u0105 na jej punkt, obecn\u0105 bil\u0119 przeciwnika na \u015Brodek i w\u0142asn\u0105 bil\u0119 w r\u0119ce w D.",
              "W podej\u015Bciu wolno wykona\u0107 najwy\u017Cej 75 samych karamboli z rz\u0119du albo 15 uderze\u0144 typu hazard bez karambolu; hazard oznacza wbicie bili obiektowej lub w\u0142asnej po kontakcie. Ostrze\u017Cenia pojawiaj\u0105 si\u0119 przy 70 i 10. Po\u0142\u0105czenie karambolu z hazardem przerywa obie serie. Po pi\u0119tnastym hazardzie istnieje szczeg\u00F3lne przywr\u00F3cenie bili przeciwnika, je\u017Celi pozosta\u0142a poza sto\u0142em po jego ostatnim podej\u015Bciu. Gdy w ustawieniach w\u0142\u0105czono przekraczanie baulk, wymagany ruch do wn\u0119trza baulk musi nast\u0105pi\u0107 w przedziale 80\u2013100 punkt\u00F3w ka\u017Cdej setki punkt\u00F3w w podej\u015Bciu; brak przekroczenia to faul."),
            rule_section(:carom, "Karambol: klasyczny, jednobandowy i trzybandowy",
              "Na stole bez \u0142uz s\u0105 trzy bile. Przez ca\u0142\u0105 parti\u0119 grasz przydzielon\u0105 bia\u0142\u0105 albo \u017C\u00F3\u0142t\u0105. Karambol oznacza kontakt w\u0142asnej bili z obiema pozosta\u0142ymi w jednym uderzeniu. Prawid\u0142owy karambol daje 1 punkt i przed\u0142u\u017Ca podej\u015Bcie; pud\u0142o lub faul oddaje gr\u0119 bez odejmowania punkt\u00F3w. Wygrywa osi\u0105gni\u0119cie wybranego celu punktowego, z uwzgl\u0119dnieniem ustawienia wyr\u00F3wnuj\u0105cego podej\u015Bcia. Przy w\u0142\u0105czonym wyr\u00F3wnuj\u0105cym podej\u015Bciu, je\u017Celi rozpoczynaj\u0105cy osi\u0105gnie cel po jednym podej\u015Bciu wi\u0119cej, drugi gracz dostaje ostatnie podej\u015Bcie z uk\u0142adu pocz\u0105tkowego. Osi\u0105gni\u0119cie w nim celu oznacza remis partii; zako\u0144czenie podej\u015Bcia poni\u017Cej celu daje wygran\u0105 rozpoczynaj\u0105cemu. Przy wy\u0142\u0105czonym wyr\u00F3wnywaniu osi\u0105gni\u0119cie celu od razu wygrywa parti\u0119.",
              "Na pocz\u0105tku pod P wybierz dolny albo g\u00F3rny punkt startowy. Pierwszy atak musi by\u0107 skierowany bezpo\u015Brednio na czerwon\u0105. Potem odmiany r\u00F3\u017Cni\u0105 si\u0119 nast\u0119puj\u0105co:",
              "- Karambol klasyczny nie wymaga band. Cztery wyznaczone tr\u00F3jk\u0105ty w naro\u017Cnikach ograniczaj\u0105 powtarzane karambole.",
              "- W odmianie jednobandowej w\u0142asna bila musi co najmniej raz dotkn\u0105\u0107 bandy, zanim dotknie drugiej r\u00F3\u017Cnej bili obiektowej.",
              "- W odmianie trzybandowej wymagane s\u0105 co najmniej trzy takie kontakty. Osobne odbicia od tej samej bandy licz\u0105 si\u0119, podobnie jak odbicia przed pierwsz\u0105 bil\u0105 obiektow\u0105. Bandy po drugiej bili nie naprawiaj\u0105 nieudanego karambolu.",
              "W naro\u017Cniku klasycznego karambolu, po wej\u015Bciu obu bil obiektowych, wolno raz zapunktowa\u0107 bez wyj\u015Bcia \u017Cadnej z nich. Przy nast\u0119pnym karambolu co najmniej jedna musi opu\u015Bci\u0107 ten tr\u00F3jk\u0105t; mo\u017Ce wr\u00F3ci\u0107 w tym samym uderzeniu. Bila na granicy jest rozpatrywana na niekorzy\u015B\u0107 gracza. Program sprawdza ca\u0142y ruch, a nie tylko miejsca zatrzymania.",
              "Przy styku rozgrywaj\u0105cej z inn\u0105 bil\u0105 karambol klasyczny odtwarza ca\u0142y uk\u0142ad pocz\u0105tkowy. W odmianach bandowych P pozwala zagra\u0107 w stron\u0119 od styku, bez pchni\u0119cia dotykanej bili, albo za\u017C\u0105da\u0107 ustawienia na punktach. Jedna banda ustawia wszystkie trzy, a trzy bandy tylko stykaj\u0105ce si\u0119 bile na w\u0142a\u015Bciwych punktach. Uderzenie przyklejonej rozgrywaj\u0105cej bezpo\u015Brednio w dotykan\u0105 band\u0119 jest faulem. Wypadni\u0119cie poza st\u00F3\u0142 przywraca wszystkie trzy bile w odmianie klasycznej i jednobandowej, lecz tylko wypadni\u0119te w trzybandowej."),
            rule_section(:pyramid, "Wolna piramida",
              "Zdob\u0105d\u017A 8 punkt\u00F3w przed przeciwnikiem. Wszystkie szesna\u015Bcie bil ma t\u0119 sam\u0105 warto\u015B\u0107: 1 punkt za ka\u017Cde prawid\u0142owe wbicie, tak\u017Ce rozgrywaj\u0105cej po kontakcie z inn\u0105 bil\u0105. Nie deklaruje si\u0119 bili ani \u0142uzy. Przed ka\u017Cdym strza\u0142em po rozbiciu pod P wybierz opcj\u0119 wyboru rozgrywaj\u0105cej i wska\u017C dowoln\u0105 bil\u0119 na stole. Prawid\u0142owe wbicie przed\u0142u\u017Ca kolejk\u0119 i pozwala wybra\u0107 j\u0105 na nowo.",
              "Rozbicie wykonujesz kolorow\u0105 bil\u0105 zza linii domu, w lewej \u0107wiartce sto\u0142u. Po trafieniu bili obiektowej wbij bil\u0119, doprowad\u017A trzy r\u00F3\u017Cne obiektowe do band albo doprowad\u017A dwie do band i jedn\u0105 obiektow\u0105 przez lini\u0119 \u015Brodkow\u0105.",
              "W p\u00F3\u017Aniejszych strza\u0142ach po wymaganym kontakcie musi nast\u0105pi\u0107 jedno z poni\u017Cszych zdarze\u0144:",
              "- Kt\u00F3ra\u015B bila wpada do \u0142uzy.",
              "- Bila odbija si\u0119 od bandy, a potem dociera do innej bandy, sama albo posy\u0142aj\u0105c tam inn\u0105 bil\u0119. Kontakt z bil\u0105 przyklejon\u0105 do tej drugiej bandy tak\u017Ce mo\u017Ce spe\u0142ni\u0107 warunek.",
              "- Bila przekracza \u015Brodek i potem dociera do bandy, sama albo przekazuj\u0105c ruch innej bili; liczy si\u0119 r\u00F3wnie\u017C bila przyklejona do tej bandy.",
              "- Po odbiciu od bandy bila przekracza \u015Brodek, posy\u0142a przeze\u0144 inn\u0105 bil\u0119 albo dotyka bili na przeciwnej po\u0142owie lub linii \u015Brodkowej. Licz\u0105 si\u0119 tak\u017Ce odpowiednie kontakty przekazane przez dalsze bile.",
              "Po faulu najpierw wracaj\u0105 nieprawid\u0142owo wbite i wypadni\u0119te bile. Przeciwnik wybiera pod P dowoln\u0105 bil\u0119 ze sto\u0142u jako karn\u0105, zdejmuje j\u0105 i dostaje 1 punkt. Nast\u0119pnie gra sam albo oddaje strza\u0142. Po b\u0142\u0119dnym rozbiciu mo\u017Ce te\u017C ponownie ustawi\u0107 bile i wybra\u0107 rozbijaj\u0105cego; punkt karny zostaje, a piramida jest niepe\u0142na. Wbicie samej rozgrywaj\u0105cej nie jest tu automatycznie faulem: daje punkt przy prawid\u0142owym wykonaniu po kontakcie. Kilka narusze\u0144 w jednym strzale oznacza jedn\u0105 kar\u0119.",
              "Przywracane bile ustawia si\u0119 od tylnego punktu w prawo wzd\u0142u\u017C osi sto\u0142u, a po wyczerpaniu miejsca w przeciwn\u0105 stron\u0119. Mo\u017Cna wybra\u0107 je jako nast\u0119pn\u0105 rozgrywaj\u0105c\u0105. Wi\u0119ksze bile i ciasne szcz\u0119ki wymagaj\u0105 dok\u0142adniejszego celowania ni\u017C pool; skierowanie ku \u0142uzie nie gwarantuje przej\u015Bcia mi\u0119dzy szcz\u0119kami."),
            rule_section(:settings, "Ustawienia meczu",
              "Przed gr\u0105 wybierz odmian\u0119 i warunek zwyci\u0119stwa. Bilard towarzyski obejmuje \u0142\u0105cznie od 1 do 30 rund i jeden z trzech uk\u0142ad\u00F3w bil. W odmianach, kt\u00F3re na to pozwalaj\u0105, ustalasz cel punktowy partii; cel meczu oznacza liczb\u0119 wygranych partii. Bilard angielski mo\u017Ce zamiast tego trwa\u0107 wybrany czas: rozpocz\u0119te przed jego up\u0142ywem uderzenie zostaje doko\u0144czone, a r\u00F3wny wynik ko\u0144cowy daje remis. Opcja wyr\u00F3wnuj\u0105cego podej\u015Bcia w karambolu pozwala drugiemu graczowi zagra\u0107 na koniec z uk\u0142adu pocz\u0105tkowego, gdy trzeba wyr\u00F3wna\u0107 liczb\u0119 podej\u015B\u0107. W bilardzie angielskim na czas strza\u0142 musi zosta\u0107 przyj\u0119ty przy stole przed limitem; samo wcze\u015Bniejsze naci\u015Bni\u0119cie klawisza nie wystarcza.",
              "Bilard towarzyski domy\u015Blnie zaczyna si\u0119 od rombu dziewi\u0119ciu bil obiektowych. W ustawieniach sto\u0142u mo\u017Cesz zamiast niego wybra\u0107 jedn\u0105 bil\u0119 obiektow\u0105 albo tr\u00F3jk\u0105t pi\u0119tnastu; bil\u0105 ko\u0144cow\u0105 b\u0119dzie wtedy odpowiednio 1 albo 15. Wskazany przez ciebie uk\u0142ad oraz uk\u0142ad starszego zapisu pozostaj\u0105 zachowane.",
              "Cel meczu wynosi od 1 do 25 wygranych partii. Ustawiany cel punktowy mie\u015Bci si\u0119 od 1 do 1000, a limit czasu bilardu angielskiego od 1 do 180 minut.",
              "Dok\u0142adniejsza fizyka u\u017Cywa mniejszych krok\u00F3w oblicze\u0144 i mo\u017Ce zmieni\u0107 wynik bliskiego kontaktu. Si\u0142a gry komputera okre\u015Bla liczb\u0119 por\u00F3wnywanych propozycji strza\u0142u. Si\u0142a uderzenia i rotacja s\u0105 uwzgl\u0119dniane tak\u017Ce w prognozach.",
              "Limit od 1 do 500 uderze\u0144 dotyczy wy\u0142\u0105cznie dawnych zapis\u00F3w treningu, nie nowych gier."),
            rule_section(:referee, "Przepisy i dostosowania cyfrowe",
              "Pool opiera si\u0119 na przepisach i regulacjach WPA z 21 pa\u017Adziernika 2026; snooker i bilard angielski na WPBSA 2024\u201325, karambol na UMB, a wolna piramida na redakcji IPC 2025. Cutthroat i bilard towarzyski stosuj\u0105 opisane tu zasady klubowe. Kolejno\u015B\u0107 przy stole zast\u0119puje fizyczn\u0105 pr\u00F3b\u0119 o pierwsze\u0144stwo. Samo uzgodnienie ponownego ustawienia nie daje zwyci\u0119stwa w partii. S\u0119dzia snookera orzeka automatyczny Miss tylko przy drodze bezpo\u015Bredniej; ca\u0142kowicie zas\u0142oni\u0119te pr\u00F3by pozostaj\u0105 zwyk\u0142ymi faulami bez przywracania uk\u0142adu.",
              "Symulacja jest dwuwymiarowa: nie ma sterowania skokiem, uniesieniem kija ani mass\u00E9. Pchni\u0119cia stykaj\u0105cych si\u0119 bil i szcz\u0119ki \u0142uz s\u0105 przybli\u017Ceniami. Pierwsze kontakty nierozr\u00F3\u017Cnione w jednym kroku fizyki uznaje si\u0119 za jednoczesne. Piramida u\u017Cywa opisanego profilu treningowego z du\u017Cymi bilami i ciasnymi \u0142uzami; nie jest to certyfikat aktualnego sprz\u0119tu federacyjnego. Pomoce celowania i prognozy korzystaj\u0105 z aktywnej rozgrywaj\u0105cej i tej samej fizyki co gra."),
            rule_section(:controls, "Skr\u00F3ty klawiszowe",
              "K: Odczytaj kierunek kija.",
              "F: Odczytaj si\u0142\u0119 uderzenia.",
              "G: Odczytaj pierwszy kontakt na linii uderzenia.",
              "H: Odczytaj bile w pobli\u017Cu linii uderzenia.",
              "I: Opisz wybran\u0105 bil\u0119.",
              "O: Odczytaj wszystkie bile i ich pozycje.",
              "L: Wybierz nast\u0119pn\u0105 bil\u0119.",
              "Shift+L: Wybierz poprzedni\u0105 bil\u0119.",
              "J: Wybierz \u0142uz\u0119 docelow\u0105.",
              "A: Wyceluj w \u015Brodek wybranej bili.",
              "Shift+A: Wyceluj wybran\u0105 bil\u0119 do wskazanej \u0142uzy.",
              "E: Wpisz dok\u0142adny k\u0105t, si\u0142\u0119 i rotacj\u0119.",
              "W: Zwi\u0119ksz rotacj\u0119 g\u00F3rn\u0105.",
              "Shift+B: Zwi\u0119ksz rotacj\u0119 doln\u0105.",
              "N: Zwi\u0119ksz rotacj\u0119 w lewo.",
              "D: Zwi\u0119ksz rotacj\u0119 w prawo.",
              "R: Wy\u0142\u0105cz rotacj\u0119.",
              "C: Prze\u0142\u0105cz kierunki mi\u0119dzy stopniami a zegarem.",
              "Y: Przewiduj uderzenie bez ruszania bil.",
              "U: Odczytaj kontakty ostatniego uderzenia.",
              "W lewo: obr\u00F3\u0107 przeciwnie do wskaz\u00F3wek zegara o 1 stopie\u0144.",
              "W prawo: obr\u00F3\u0107 zgodnie ze wskaz\u00F3wkami zegara o 1 stopie\u0144.",
              "Shift+w lewo: obr\u00F3\u0107 przeciwnie do wskaz\u00F3wek zegara o 0,1 stopnia.",
              "Shift+w prawo: obr\u00F3\u0107 zgodnie ze wskaz\u00F3wkami zegara o 0,1 stopnia.",
              "Ctrl+w lewo: obr\u00F3\u0107 przeciwnie do wskaz\u00F3wek zegara o 0,01 stopnia.",
              "Ctrl+w prawo: obr\u00F3\u0107 zgodnie ze wskaz\u00F3wkami zegara o 0,01 stopnia.",
              "W g\u00F3r\u0119: zwi\u0119ksz si\u0142\u0119 o 1 procent.",
              "W d\u00F3\u0142: zmniejsz si\u0142\u0119 o 1 procent.",
              "Shift+w g\u00F3r\u0119: zwi\u0119ksz si\u0142\u0119 o 0,1 procenta.",
              "Shift+w d\u00F3\u0142: zmniejsz si\u0142\u0119 o 0,1 procenta.",
              "Enter lub Spacja: wykonaj bie\u017C\u0105ce uderzenie.",
              "T: odczytaj, czyja jest kolej.",
              "V: Przewiduj odbicie od bandy i kolejne trafienie w bil\u0119.",
              "B: Opisz obiekty za wskazywan\u0105 bil\u0105.",
              "S: Odczytaj wyniki, w towarzyskim wygrane rundy i punkty za wbicia.",
              "M: Ustaw aktywn\u0105 rozgrywaj\u0105c\u0105, gdy przys\u0142uguje bila w r\u0119ce.",
              "P: Otw\u00F3rz deklaracje, wyb\u00F3r rozgrywaj\u0105cej lub oczekuj\u0105c\u0105 decyzj\u0119.",
              "Shift+P: Odczytaj bie\u017C\u0105c\u0105 sytuacj\u0119 w meczu.",
              "Q: Po potwierdzeniu poddaj bie\u017C\u0105c\u0105 rund\u0119, parti\u0119 lub frejm.",
              "Przecinek: Oblicz ruch pierwszej namierzonej bili przy bie\u017C\u0105cej sile i rotacji.")
          ]
        when "ru"
          [
            rule_section(:competition, "\u0422\u043E\u0432\u0430\u0440\u0438\u0449\u0435\u0441\u043A\u0438\u0439 \u0431\u0438\u043B\u044C\u044F\u0440\u0434: \u043F\u0435\u0440\u0432\u0430\u044F \u0438\u0433\u0440\u0430",
              "\u041D\u0430 \u043D\u043E\u0432\u044B\u0445 \u0431\u0438\u043B\u044C\u044F\u0440\u0434\u043D\u044B\u0445 \u0441\u0442\u043E\u043B\u0430\u0445 \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0432\u044B\u0431\u0440\u0430\u043D \u0442\u043E\u0432\u0430\u0440\u0438\u0449\u0435\u0441\u043A\u0438\u0439 \u0440\u0435\u0436\u0438\u043C. \u0412 \u043D\u0451\u043C \u043C\u043E\u0433\u0443\u0442 \u0443\u0447\u0430\u0441\u0442\u0432\u043E\u0432\u0430\u0442\u044C \u043E\u0442 \u0434\u0432\u0443\u0445 \u0434\u043E \u0432\u043E\u0441\u044C\u043C\u0438 \u0438\u0433\u0440\u043E\u043A\u043E\u0432, \u0432 \u0442\u043E\u043C \u0447\u0438\u0441\u043B\u0435 \u043A\u043E\u043C\u043F\u044C\u044E\u0442\u0435\u0440\u043D\u044B\u0445. \u041D\u0430\u0447\u0430\u043B\u044C\u043D\u0430\u044F \u0440\u0430\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u2014 \u0440\u043E\u043C\u0431 \u0438\u0437 \u0448\u0430\u0440\u043E\u0432 1\u20139 \u0438 \u0431\u0435\u043B\u044B\u0439 \u0431\u0438\u0442\u043E\u043A. \u0423\u0431\u0435\u0440\u0438\u0442\u0435 \u0448\u0430\u0440\u044B 1\u20138, \u0437\u0430\u0442\u0435\u043C \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E \u0437\u0430\u0431\u0435\u0439\u0442\u0435 \u0434\u0435\u0432\u044F\u0442\u043A\u0443, \u0447\u0442\u043E\u0431\u044B \u0432\u044B\u0438\u0433\u0440\u0430\u0442\u044C \u0440\u0430\u0443\u043D\u0434. \u041C\u0430\u0442\u0447 \u0440\u0435\u0448\u0430\u0435\u0442\u0441\u044F \u043F\u043E \u0447\u0438\u0441\u043B\u0443 \u0432\u044B\u0438\u0433\u0440\u0430\u043D\u043D\u044B\u0445 \u0440\u0430\u0443\u043D\u0434\u043E\u0432.",
              "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u0439 \u0448\u0430\u0440 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 L \u0438\u043B\u0438 Shift+L \u0438 \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u0435\u0433\u043E \u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 I. \u041D\u0430\u0436\u043C\u0438\u0442\u0435 A \u0434\u043B\u044F \u043F\u0440\u0438\u0446\u0435\u043B\u0438\u0432\u0430\u043D\u0438\u044F, \u0443\u0442\u043E\u0447\u043D\u0438\u0442\u0435 \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u0438 \u0441\u0438\u043B\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438, \u0437\u0430\u0442\u0435\u043C \u0432\u044B\u043F\u043E\u043B\u043D\u0438\u0442\u0435 \u0443\u0434\u0430\u0440 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 Enter \u0438\u043B\u0438 \u041F\u0440\u043E\u0431\u0435\u043B \u043D\u0430 \u043F\u043E\u043B\u0435 \u043A\u0438\u044F. \u0412 \u0442\u043E\u0432\u0430\u0440\u0438\u0449\u0435\u0441\u043A\u043E\u043C \u0440\u0435\u0436\u0438\u043C\u0435 \u0437\u0430\u043A\u0430\u0437\u044B\u0432\u0430\u0442\u044C \u0448\u0430\u0440 \u0438 \u043B\u0443\u0437\u0443 \u043D\u0435 \u043D\u0443\u0436\u043D\u043E. \u041F\u043E\u0441\u043B\u0435 \u0443\u0434\u0430\u0440\u0430 \u0432\u044B \u0443\u0441\u043B\u044B\u0448\u0438\u0442\u0435 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0438 \u0443\u0437\u043D\u0430\u0435\u0442\u0435, \u043A\u0442\u043E \u0438\u0433\u0440\u0430\u0435\u0442 \u0434\u0430\u043B\u044C\u0448\u0435. \u0421\u043B\u0435\u0434\u0443\u044E\u0449\u0430\u044F \u0433\u043B\u0430\u0432\u0430 \u043E\u0431\u044A\u044F\u0441\u043D\u044F\u0435\u0442 \u0440\u0430\u0443\u043D\u0434\u044B, \u043D\u0430\u0440\u0443\u0448\u0435\u043D\u0438\u044F \u0438 \u043E\u0447\u043A\u0438, \u0437\u0430\u0442\u0435\u043C \u043E\u043F\u0438\u0441\u0430\u043D\u043E \u043F\u0440\u0438\u0446\u0435\u043B\u0438\u0432\u0430\u043D\u0438\u0435."),
            rule_section(:friendly, "\u0422\u043E\u0432\u0430\u0440\u0438\u0449\u0435\u0441\u043A\u0438\u0435 \u0440\u0430\u0443\u043D\u0434\u044B \u0438 \u043D\u0430\u0440\u0443\u0448\u0435\u043D\u0438\u044F",
              "\u0412 \u0442\u043E\u0432\u0430\u0440\u0438\u0449\u0435\u0441\u043A\u043E\u043C \u0431\u0438\u043B\u044C\u044F\u0440\u0434\u0435 \u0438\u0433\u0440\u0430\u044E\u0442 \u043E\u0442 \u0434\u0432\u0443\u0445 \u0434\u043E \u0432\u043E\u0441\u044C\u043C\u0438 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u043E\u0432, \u0432 \u0442\u043E\u043C \u0447\u0438\u0441\u043B\u0435 \u043A\u043E\u043C\u043F\u044C\u044E\u0442\u0435\u0440\u043D\u044B\u0445. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043E\u0431\u0449\u0435\u0435 \u0447\u0438\u0441\u043B\u043E \u0440\u0430\u0443\u043D\u0434\u043E\u0432 \u043E\u0442 1 \u0434\u043E 30. \u041C\u0430\u0442\u0447 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043F\u043E\u0441\u043B\u0435 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u0432 \u0432\u0441\u0435\u0445 \u044D\u0442\u0438\u0445 \u0440\u0430\u0443\u043D\u0434\u043E\u0432; \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u0442\u043E\u0442, \u043A\u0442\u043E \u0432\u044B\u0438\u0433\u0440\u0430\u043B \u0431\u043E\u043B\u044C\u0448\u0435 \u0440\u0430\u0443\u043D\u0434\u043E\u0432. \u0415\u0441\u043B\u0438 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0438\u0433\u0440\u043E\u043A\u043E\u0432 \u0432\u044B\u0438\u0433\u0440\u0430\u043B\u0438 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u043E\u0435 \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0435\u0435 \u0447\u0438\u0441\u043B\u043E \u0440\u0430\u0443\u043D\u0434\u043E\u0432, \u043C\u0430\u0442\u0447 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0432\u043D\u0438\u0447\u044C\u044E.",
              "\u0412 \u0438\u0441\u0445\u043E\u0434\u043D\u043E\u043C \u0440\u043E\u043C\u0431\u0435 \u0434\u0435\u0432\u044F\u0442\u044C \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u0445 \u0448\u0430\u0440\u043E\u0432 \u0441 \u043D\u043E\u043C\u0435\u0440\u0430\u043C\u0438 1\u20139 \u0438 \u0431\u0435\u043B\u044B\u0439 \u0431\u0438\u0442\u043E\u043A. \u041F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u043C \u043D\u0443\u0436\u043D\u043E \u0437\u0430\u0431\u0438\u0442\u044C \u0434\u0435\u0432\u044F\u0442\u043A\u0443. \u041F\u043E\u043A\u0430 \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u0434\u0440\u0443\u0433\u0438\u0435 \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u0435 \u0448\u0430\u0440\u044B, \u0431\u0438\u0442\u043E\u043A \u0434\u043E\u043B\u0436\u0435\u043D \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u043A\u043E\u0441\u043D\u0443\u0442\u044C\u0441\u044F \u043E\u0434\u043D\u043E\u0433\u043E \u0438\u0437 \u043D\u0438\u0445. \u041F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u0435 \u0437\u0430\u0431\u0438\u0442\u0438\u0435 \u043E\u0431\u044B\u0447\u043D\u043E\u0433\u043E \u0448\u0430\u0440\u0430 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u043F\u043E\u0434\u0445\u043E\u0434; \u0431\u0435\u0437 \u0437\u0430\u0431\u0438\u0442\u0438\u044F \u0445\u043E\u0434 \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u0438\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u043C\u0443 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u0443. \u041F\u043E\u0441\u043B\u0435 \u0441\u043E\u0443\u0434\u0430\u0440\u0435\u043D\u0438\u044F \u0448\u0430\u0440 \u0434\u043E\u043B\u0436\u0435\u043D \u043A\u043E\u0441\u043D\u0443\u0442\u044C\u0441\u044F \u0431\u043E\u0440\u0442\u0430 \u043B\u0438\u0431\u043E \u0434\u043E\u043B\u0436\u0435\u043D \u0431\u044B\u0442\u044C \u0437\u0430\u0431\u0438\u0442 \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u0439 \u0448\u0430\u0440.",
              "\u041F\u0430\u0434\u0435\u043D\u0438\u0435 \u0431\u0438\u0442\u043A\u0430, \u043F\u0435\u0440\u0432\u044B\u0439 \u043A\u043E\u043D\u0442\u0430\u043A\u0442 \u0441 \u043D\u0435\u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u044B\u043C \u0448\u0430\u0440\u043E\u043C \u0438\u043B\u0438 \u043E\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 \u043D\u0443\u0436\u043D\u043E\u0433\u043E \u043A\u0430\u0441\u0430\u043D\u0438\u044F \u0431\u043E\u0440\u0442\u0430 \u0434\u0430\u044E\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u043C\u0443 \u0438\u0433\u0440\u043E\u043A\u0443 \u0431\u0438\u0442\u043E\u043A \u0441 \u0440\u0443\u043A\u0438 \u0438\u0437 \u043B\u044E\u0431\u043E\u0433\u043E \u043C\u0435\u0441\u0442\u0430; \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0435 \u0435\u0433\u043E \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 M. \u041E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0448\u0430\u0440\u044B \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442 \u043F\u043E\u0437\u0438\u0446\u0438\u0438. \u0415\u0441\u043B\u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u0448\u0430\u0440 \u0437\u0430\u0431\u0438\u0442 \u0440\u0430\u043D\u044C\u0448\u0435 \u0432\u0440\u0435\u043C\u0435\u043D\u0438 \u0438\u043B\u0438 \u0441 \u043D\u0430\u0440\u0443\u0448\u0435\u043D\u0438\u0435\u043C, \u0440\u0430\u0443\u043D\u0434 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043F\u043E\u0431\u0435\u0434\u043E\u0439 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430 \u043F\u043E \u043F\u043E\u0440\u044F\u0434\u043A\u0443 \u0437\u0430 \u0441\u0442\u043E\u043B\u043E\u043C. \u041F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u0435 \u0437\u0430\u0431\u0438\u0442\u0438\u0435 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0433\u043E \u0448\u0430\u0440\u0430 \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442 \u0440\u0430\u0443\u043D\u0434 \u0431\u044C\u044E\u0449\u0435\u043C\u0443. \u041A\u043E\u0433\u0434\u0430 \u043F\u0440\u0435\u0434\u043B\u0430\u0433\u0430\u0435\u0442\u0441\u044F \u043D\u043E\u0432\u044B\u0439 \u0440\u0430\u0443\u043D\u0434, \u043D\u0430\u0447\u043D\u0438\u0442\u0435 \u0435\u0433\u043E \u0447\u0435\u0440\u0435\u0437 P. \u041F\u0440\u043E\u0438\u0437\u0432\u043E\u043B\u044C\u043D\u0430\u044F \u043F\u0435\u0440\u0435\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u0448\u0430\u0440\u043E\u0432, \u043E\u0442\u043C\u0435\u043D\u0430 \u0443\u0434\u0430\u0440\u043E\u0432 \u0438 \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0443\u043F\u0440\u0430\u0436\u043D\u0435\u043D\u0438\u044F \u0437\u0434\u0435\u0441\u044C \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B.",
              "\u041F\u043E\u043C\u0438\u043C\u043E \u043F\u043E\u0431\u0435\u0434 \u0432 \u0440\u0430\u0443\u043D\u0434\u0430\u0445 \u0432\u044B \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442\u0435 1 \u043E\u0447\u043A\u043E \u0437\u0430 \u043A\u0430\u0436\u0434\u044B\u0439 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E \u0437\u0430\u0431\u0438\u0442\u044B\u0439 \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u0439 \u0448\u0430\u0440, \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E \u0437\u0430\u0431\u0438\u0442\u044B\u0439 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439. \u0411\u0438\u0442\u043E\u043A \u043E\u0447\u043A\u043E\u0432 \u043D\u0435 \u0434\u0430\u0451\u0442. \u0423\u0434\u0430\u0440 \u0441 \u043D\u0430\u0440\u0443\u0448\u0435\u043D\u0438\u0435\u043C \u0438\u043B\u0438 \u043F\u0440\u0435\u0436\u0434\u0435\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u044B\u043C \u0437\u0430\u0431\u0438\u0442\u0438\u0435\u043C \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0433\u043E \u0448\u0430\u0440\u0430 \u043D\u0435 \u043F\u0440\u0438\u043D\u043E\u0441\u0438\u0442 \u043E\u0447\u043A\u043E\u0432 \u0437\u0430 \u0437\u0430\u0431\u0438\u0442\u0438\u044F. \u041E\u0447\u043A\u0438 \u0441\u0443\u043C\u043C\u0438\u0440\u0443\u044E\u0442\u0441\u044F \u0437\u0430 \u0432\u0441\u0435 \u0440\u0430\u0443\u043D\u0434\u044B \u043C\u0430\u0442\u0447\u0430; \u043E\u043D\u0438 \u043D\u0435 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u044E\u0442 \u043F\u043E\u0431\u0435\u0434\u0443 \u0432 \u0440\u0430\u0443\u043D\u0434\u0435. \u041F\u0440\u0438 \u0440\u0430\u0432\u043D\u043E\u043C \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0435\u043C \u0447\u0438\u0441\u043B\u0435 \u043F\u043E\u0431\u0435\u0434 \u0432 \u0440\u0430\u0443\u043D\u0434\u0430\u0445 \u043D\u0438\u0447\u044C\u044F \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442\u0441\u044F \u043D\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043C\u043E \u043E\u0442 \u043D\u0430\u0431\u0440\u0430\u043D\u043D\u044B\u0445 \u043E\u0447\u043A\u043E\u0432. S \u043F\u0440\u043E\u0438\u0437\u043D\u043E\u0441\u0438\u0442 \u043F\u043E\u0431\u0435\u0434\u044B \u0432 \u0440\u0430\u0443\u043D\u0434\u0430\u0445 \u0438 \u043E\u0447\u043A\u0438 \u0437\u0430 \u0437\u0430\u0431\u0438\u0442\u0438\u044F \u0431\u0435\u0437 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u043E\u043A\u043D\u0430, Shift+P \u0432\u043A\u043B\u044E\u0447\u0430\u0435\u0442 \u043E\u0431\u0435 \u0432\u0435\u043B\u0438\u0447\u0438\u043D\u044B \u0432 \u0442\u0435\u043A\u0443\u0449\u0443\u044E \u0441\u0438\u0442\u0443\u0430\u0446\u0438\u044E \u0432 \u043C\u0430\u0442\u0447\u0435."),
            rule_section(:table, "\u041E\u0440\u0438\u0435\u043D\u0442\u0430\u0446\u0438\u044F \u043D\u0430 \u0441\u0442\u043E\u043B\u0435",
              "X \u2014 \u0440\u0430\u0441\u0441\u0442\u043E\u044F\u043D\u0438\u0435 \u043E\u0442 \u043B\u0435\u0432\u043E\u0433\u043E \u043A\u0440\u0430\u044F, Y \u2014 \u043E\u0442 \u043D\u0438\u0436\u043D\u0435\u0433\u043E \u0431\u043E\u0440\u0442\u0430. \u041D\u043E\u043B\u044C \u0433\u0440\u0430\u0434\u0443\u0441\u043E\u0432 \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u0435\u043D \u0432\u043F\u0440\u0430\u0432\u043E, 90 \u0432\u0432\u0435\u0440\u0445, 180 \u0432\u043B\u0435\u0432\u043E, 270 \u0432\u043D\u0438\u0437. C \u043F\u0435\u0440\u0435\u043A\u043B\u044E\u0447\u0430\u0435\u0442 \u0447\u0442\u0435\u043D\u0438\u0435 \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0439 \u043D\u0430 \u0447\u0430\u0441\u044B: \u0442\u0440\u0438, \u0434\u0432\u0435\u043D\u0430\u0434\u0446\u0430\u0442\u044C, \u0434\u0435\u0432\u044F\u0442\u044C \u0438 \u0448\u0435\u0441\u0442\u044C. \u041B\u0443\u0437\u044B 1\u20136 \u0440\u0430\u0441\u043F\u043E\u043B\u043E\u0436\u0435\u043D\u044B \u0441\u043D\u0438\u0437\u0443 \u0441\u043B\u0435\u0432\u0430, \u0441\u043D\u0438\u0437\u0443 \u043F\u043E\u0441\u0435\u0440\u0435\u0434\u0438\u043D\u0435, \u0441\u043D\u0438\u0437\u0443 \u0441\u043F\u0440\u0430\u0432\u0430, \u0441\u0432\u0435\u0440\u0445\u0443 \u0441\u043B\u0435\u0432\u0430, \u0441\u0432\u0435\u0440\u0445\u0443 \u043F\u043E\u0441\u0435\u0440\u0435\u0434\u0438\u043D\u0435 \u0438 \u0441\u0432\u0435\u0440\u0445\u0443 \u0441\u043F\u0440\u0430\u0432\u0430. \u0423 \u043A\u0430\u0440\u0430\u043C\u0431\u043E\u043B\u044C\u043D\u043E\u0433\u043E \u0441\u0442\u043E\u043B\u0430 \u043B\u0443\u0437 \u043D\u0435\u0442.",
              "O \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u0432\u0441\u0435\u0445 \u0448\u0430\u0440\u043E\u0432 \u043F\u043E \u0440\u0430\u0441\u0441\u0442\u043E\u044F\u043D\u0438\u044E \u043E\u0442 \u0442\u0435\u043A\u0443\u0449\u0435\u0433\u043E \u0431\u0438\u0442\u043A\u0430; \u0437\u0430\u0431\u0438\u0442\u044B\u0435 \u0438\u0434\u0443\u0442 \u0432 \u043A\u043E\u043D\u0446\u0435. L \u0438 Shift+L \u0432\u044B\u0431\u0438\u0440\u0430\u044E\u0442 \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u0439 \u0448\u0430\u0440, I \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u0435\u0433\u043E \u043D\u043E\u043C\u0435\u0440 \u0438\u043B\u0438 \u0446\u0432\u0435\u0442, \u0441\u0435\u043A\u0442\u043E\u0440, \u043A\u043E\u043E\u0440\u0434\u0438\u043D\u0430\u0442\u044B, \u0440\u0430\u0441\u0441\u0442\u043E\u044F\u043D\u0438\u0435 \u0438 \u043F\u0440\u0435\u043F\u044F\u0442\u0441\u0442\u0432\u0438\u044F. \u041A \u0441\u043F\u0438\u0441\u043A\u0443 \u043C\u043E\u0436\u043D\u043E \u043F\u0435\u0440\u0435\u0439\u0442\u0438 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 Tab \u0438 \u043F\u0440\u043E\u0441\u043C\u0430\u0442\u0440\u0438\u0432\u0430\u0442\u044C \u0435\u0433\u043E \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438. \u0412 \u043F\u0443\u043B\u0435 \u0431\u0438\u0442\u043E\u043A \u0431\u0435\u043B\u044B\u0439; \u0432 \u0430\u043D\u0433\u043B\u0438\u0439\u0441\u043A\u043E\u043C \u0431\u0438\u043B\u044C\u044F\u0440\u0434\u0435 \u0438 \u043A\u0430\u0440\u0430\u043C\u0431\u043E\u043B\u0435 \u0443 \u0432\u0430\u0441 \u0441\u0432\u043E\u0439 \u0431\u0435\u043B\u044B\u0439 \u0438\u043B\u0438 \u0436\u0451\u043B\u0442\u044B\u0439 \u0448\u0430\u0440; \u0432 \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u043E\u0439 \u043F\u0438\u0440\u0430\u043C\u0438\u0434\u0435 \u0431\u0438\u0442\u043E\u043A \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442\u0441\u044F.",
              "\u0412 \u043F\u0443\u043B\u0435 \u043F\u0435\u0440\u0435\u0434\u043D\u044F\u044F \u043B\u0438\u043D\u0438\u044F \u043F\u0440\u043E\u0445\u043E\u0434\u0438\u0442 \u0447\u0435\u0440\u0435\u0437 \u043B\u0435\u0432\u0443\u044E \u0447\u0435\u0442\u0432\u0435\u0440\u0442\u044C \u0441\u0442\u043E\u043B\u0430, \u0437\u0430\u0434\u043D\u044F\u044F \u043E\u0442\u043C\u0435\u0442\u043A\u0430 \u043D\u0430\u0445\u043E\u0434\u0438\u0442\u0441\u044F \u043D\u0430 \u043F\u0440\u043E\u0434\u043E\u043B\u044C\u043D\u043E\u0439 \u043E\u0441\u0438 \u0432 \u043F\u0440\u0430\u0432\u043E\u0439 \u0447\u0435\u0442\u0432\u0435\u0440\u0442\u0438. \u0412 \u0441\u043D\u0443\u043A\u0435\u0440\u0435 \u0438 \u0430\u043D\u0433\u043B\u0438\u0439\u0441\u043A\u043E\u043C \u0431\u0438\u043B\u044C\u044F\u0440\u0434\u0435 \u0431\u0430\u0443\u043B\u043A \u2014 \u043E\u0431\u043B\u0430\u0441\u0442\u044C \u0441\u043B\u0435\u0432\u0430 \u043E\u0442 \u043B\u0438\u043D\u0438\u0438 \u0432 73,7 \u0441\u043C \u043E\u0442 \u043B\u0435\u0432\u043E\u0433\u043E \u043A\u0440\u0430\u044F. D \u2014 \u043F\u043E\u043B\u0443\u043A\u0440\u0443\u0433 \u0440\u0430\u0434\u0438\u0443\u0441\u043E\u043C 29,2 \u0441\u043C \u0441 \u044D\u0442\u043E\u0439 \u0441\u0442\u043E\u0440\u043E\u043D\u044B \u043B\u0438\u043D\u0438\u0438. \u0423\u0433\u043B\u043E\u0432\u044B\u0435 \u0442\u0440\u0435\u0443\u0433\u043E\u043B\u044C\u043D\u0438\u043A\u0438 \u043A\u0430\u0440\u0430\u043C\u0431\u043E\u043B\u044F \u0437\u0430\u043D\u0438\u043C\u0430\u044E\u0442 71 \u0441\u043C \u0432\u0434\u043E\u043B\u044C \u0434\u043B\u0438\u043D\u043D\u043E\u0433\u043E \u0431\u043E\u0440\u0442\u0430 \u0438 35,5 \u0441\u043C \u0432\u0434\u043E\u043B\u044C \u043A\u043E\u0440\u043E\u0442\u043A\u043E\u0433\u043E. \u041F\u0435\u0440\u0435\u0434\u043D\u044F\u044F \u043E\u0442\u043C\u0435\u0442\u043A\u0430, \u0438\u043B\u0438 \u043F\u0435\u0440\u0435\u0434\u043D\u044F\u044F \u0442\u043E\u0447\u043A\u0430, \u043D\u0430\u0445\u043E\u0434\u0438\u0442\u0441\u044F \u0432 \u0441\u0435\u0440\u0435\u0434\u0438\u043D\u0435 \u043F\u0435\u0440\u0435\u0434\u043D\u0435\u0439 \u043B\u0438\u043D\u0438\u0438, \u0442\u0430\u043A\u0436\u0435 \u043D\u0430\u0437\u044B\u0432\u0430\u0435\u043C\u043E\u0439 \u043B\u0438\u043D\u0438\u0435\u0439 \u0434\u043E\u043C\u0430.",
              "- \u041F\u0443\u043B: 254 \u043D\u0430 127 \u0441\u043C.",
              "- \u0421\u043D\u0443\u043A\u0435\u0440 \u0438 \u0430\u043D\u0433\u043B\u0438\u0439\u0441\u043A\u0438\u0439 \u0431\u0438\u043B\u044C\u044F\u0440\u0434: 356,9 \u043D\u0430 177,8 \u0441\u043C.",
              "- \u041A\u0430\u0440\u0430\u043C\u0431\u043E\u043B\u044C: 284 \u043D\u0430 142 \u0441\u043C, \u0431\u0435\u0437 \u043B\u0443\u0437.",
              "- \u0421\u0432\u043E\u0431\u043E\u0434\u043D\u0430\u044F \u043F\u0438\u0440\u0430\u043C\u0438\u0434\u0430: 355 \u043D\u0430 177,5 \u0441\u043C."),
            rule_section(:aim, "\u041F\u0440\u0438\u0446\u0435\u043B\u0438\u0432\u0430\u043D\u0438\u0435 \u0438 \u0443\u0434\u0430\u0440",
              "\u0412\u0435\u0440\u043D\u0438\u0442\u0435\u0441\u044C \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 Tab \u043D\u0430 \u043F\u043E\u043B\u0435 \u043A\u0438\u044F. \u0412\u043B\u0435\u0432\u043E \u0438 \u0412\u043F\u0440\u0430\u0432\u043E \u043F\u043E\u0432\u043E\u0440\u0430\u0447\u0438\u0432\u0430\u044E\u0442 \u0435\u0433\u043E \u043F\u0440\u043E\u0442\u0438\u0432 \u0438 \u043F\u043E \u0447\u0430\u0441\u043E\u0432\u043E\u0439 \u0441\u0442\u0440\u0435\u043B\u043A\u0435 \u043D\u0430 \u043E\u0434\u0438\u043D \u0433\u0440\u0430\u0434\u0443\u0441. Shift \u0443\u043C\u0435\u043D\u044C\u0448\u0430\u0435\u0442 \u0448\u0430\u0433 \u0434\u043E 0,1 \u0433\u0440\u0430\u0434\u0443\u0441\u0430, Ctrl \u2014 \u0434\u043E 0,01. \u0412\u0432\u0435\u0440\u0445 \u0438 \u0412\u043D\u0438\u0437 \u043C\u0435\u043D\u044F\u044E\u0442 \u0441\u0438\u043B\u0443 \u043D\u0430 \u043E\u0434\u0438\u043D \u043F\u0440\u043E\u0446\u0435\u043D\u0442, \u0441 Shift \u2014 \u043D\u0430 0,1 \u043F\u0440\u043E\u0446\u0435\u043D\u0442\u0430. \u041F\u043E\u0441\u043B\u0435 \u043E\u0442\u043F\u0443\u0441\u043A\u0430\u043D\u0438\u044F \u0441\u0442\u0440\u0435\u043B\u043A\u0438 \u043F\u0440\u0438\u0446\u0435\u043B\u0438\u0432\u0430\u043D\u0438\u044F \u0437\u0432\u0443\u0447\u0438\u0442 \u043A\u043E\u0440\u043E\u0442\u043A\u043E\u0435 \u043E\u043F\u0438\u0441\u0430\u043D\u0438\u0435 \u0448\u0430\u0440\u0430, \u0431\u043E\u0440\u0442\u0430 \u0438\u043B\u0438 \u043B\u0443\u0437\u044B. K \u0447\u0438\u0442\u0430\u0435\u0442 \u0442\u043E\u0447\u043D\u044B\u0439 \u0443\u0433\u043E\u043B, F \u2014 \u0441\u0438\u043B\u0443.",
              "\u041F\u0440\u0438 \u043F\u043E\u0432\u043E\u0440\u043E\u0442\u0435 \u043A\u0438\u044F \u043A\u043E\u0440\u043E\u0442\u043A\u0438\u0435 \u0441\u0438\u0433\u043D\u0430\u043B\u044B \u043F\u043E\u043C\u043E\u0433\u0430\u044E\u0442 \u043D\u0430\u0439\u0442\u0438 \u0448\u0430\u0440: \u0446\u0435\u043D\u0442\u0440 \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0448\u0430\u0440\u0430 \u043D\u0430 \u043B\u0438\u043D\u0438\u0438 \u0443\u0434\u0430\u0440\u0430 \u0437\u0432\u0443\u0447\u0438\u0442 \u043D\u0430 \u0447\u0430\u0441\u0442\u043E\u0442\u0435 5000 \u0413\u0446, \u0430 \u043A \u043B\u044E\u0431\u043E\u043C\u0443 \u043A\u0440\u0430\u044E \u0447\u0430\u0441\u0442\u043E\u0442\u0430 \u0441\u043D\u0438\u0436\u0430\u0435\u0442\u0441\u044F \u0434\u043E 500 \u0413\u0446. \u0412\u043D\u0435 \u0448\u0430\u0440\u043E\u0432 \u043D\u0430\u0441\u0442\u0443\u043F\u0430\u0435\u0442 \u0442\u0438\u0448\u0438\u043D\u0430, \u043A\u0440\u043E\u043C\u0435 \u043F\u0440\u0438\u0446\u0435\u043B\u0438\u0432\u0430\u043D\u0438\u044F \u0432 \u043B\u0443\u0437\u0443. \u0421\u0438\u0433\u043D\u0430\u043B \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442 \u0431\u043E\u043A\u043E\u0432\u043E\u0435 \u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435 \u0438 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0437\u0432\u0443\u043A\u043E\u0432 \u0438\u0433\u0440\u044B. \u041E\u043D \u043F\u0440\u0435\u043A\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044F \u043F\u0440\u0438 \u0443\u0445\u043E\u0434\u0435 \u0441 \u044D\u043B\u0435\u043C\u0435\u043D\u0442\u0430 \u00AB\u041A\u0438\u0439\u00BB \u0438\u043B\u0438 \u043E\u0442\u043A\u0440\u044B\u0442\u0438\u0438 \u0434\u0438\u0430\u043B\u043E\u0433\u0430. \u0415\u0433\u043E \u0441\u043B\u044B\u0448\u043D\u043E \u0442\u043E\u043B\u044C\u043A\u043E \u043D\u0430 \u0432\u0430\u0448\u0435\u043C \u043A\u043E\u043C\u043F\u044C\u044E\u0442\u0435\u0440\u0435.",
              "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0448\u0430\u0440 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 A, \u0447\u0442\u043E\u0431\u044B \u043D\u0430\u043F\u0440\u0430\u0432\u0438\u0442\u044C \u043A\u0438\u0439 \u0432 \u0435\u0433\u043E \u0446\u0435\u043D\u0442\u0440. \u0414\u043B\u044F \u043F\u0440\u0438\u0446\u0435\u043B\u0438\u0432\u0430\u043D\u0438\u044F \u0432 \u043B\u0443\u0437\u0443 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0435\u0451 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 J, \u0437\u0430\u0442\u0435\u043C \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Shift+A. \u042D\u0442\u0430 \u0433\u0435\u043E\u043C\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043A\u0430\u044F \u043F\u043E\u0434\u0441\u043A\u0430\u0437\u043A\u0430 \u0437\u0430\u0434\u0430\u0451\u0442 \u0443\u0433\u043E\u043B, \u043D\u043E \u0431\u043E\u0440\u0442, \u0434\u0440\u0443\u0433\u0438\u0435 \u0448\u0430\u0440\u044B, \u0441\u0438\u043B\u0430 \u0438 \u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435 \u0432\u0441\u0451 \u0435\u0449\u0451 \u043C\u043E\u0433\u0443\u0442 \u043F\u043E\u043C\u0435\u0448\u0430\u0442\u044C \u0437\u0430\u0431\u0438\u0442\u044C \u0448\u0430\u0440. G \u043E\u043F\u0438\u0441\u044B\u0432\u0430\u0435\u0442 \u043F\u0435\u0440\u0432\u043E\u0435 \u043F\u0440\u0435\u043F\u044F\u0442\u0441\u0442\u0432\u0438\u0435 \u043D\u0430 \u043B\u0438\u043D\u0438\u0438 \u043F\u0440\u0438\u0446\u0435\u043B\u0430, \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u0441\u0442\u043E\u0440\u043E\u043D\u0443 \u043A\u043E\u043D\u0442\u0430\u043A\u0442\u0430 \u0441 \u0448\u0430\u0440\u043E\u043C. H \u043F\u0435\u0440\u0435\u0447\u0438\u0441\u043B\u044F\u0435\u0442 \u0448\u0430\u0440\u044B \u0432 \u043F\u0440\u0435\u0434\u0435\u043B\u0430\u0445 \u043F\u044F\u0442\u0438 \u0433\u0440\u0430\u0434\u0443\u0441\u043E\u0432 \u043E\u0442 \u044D\u0442\u043E\u0439 \u043B\u0438\u043D\u0438\u0438, \u0432 \u0442\u043E\u043C \u0447\u0438\u0441\u043B\u0435 \u043F\u0435\u0440\u0435\u043A\u0440\u044B\u0442\u044B\u0435.",
              "\u041A\u043B\u0430\u0432\u0438\u0448\u0430 E \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0444\u043E\u0440\u043C\u0443 \u0442\u043E\u0447\u043D\u044B\u0445 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0439. \u0414\u0435\u0441\u044F\u0442\u0438\u0447\u043D\u0443\u044E \u0447\u0430\u0441\u0442\u044C \u043C\u043E\u0436\u043D\u043E \u043E\u0442\u0434\u0435\u043B\u044F\u0442\u044C \u0442\u043E\u0447\u043A\u043E\u0439 \u0438\u043B\u0438 \u0437\u0430\u043F\u044F\u0442\u043E\u0439. \u0423\u0433\u043E\u043B \u2014 \u043E\u0442 0 \u0434\u043E 359,99 \u0433\u0440\u0430\u0434\u0443\u0441\u0430, \u0441\u0438\u043B\u0430 \u2014 \u043E\u0442 0,1 \u0434\u043E 100 \u043F\u0440\u043E\u0446\u0435\u043D\u0442\u043E\u0432. \u041A\u043D\u043E\u043F\u043A\u0430 \u00AB\u041F\u0440\u0438\u043C\u0435\u043D\u0438\u0442\u044C\u00BB \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438, \u00AB\u041E\u0442\u043C\u0435\u043D\u0430\u00BB \u043E\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442 \u043F\u0440\u0435\u0436\u043D\u0438\u0435. Enter \u0438\u043B\u0438 \u043F\u0440\u043E\u0431\u0435\u043B \u043D\u0430 \u044D\u043B\u0435\u043C\u0435\u043D\u0442\u0435 \u00AB\u041A\u0438\u0439\u00BB \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442 \u0443\u0434\u0430\u0440."),
            rule_section(:spin, "\u0412\u0440\u0430\u0449\u0435\u043D\u0438\u0435",
              "W \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 \u0432\u0435\u0440\u0445\u043D\u0435\u0435 \u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435, Shift+B \u2014 \u043D\u0438\u0436\u043D\u0435\u0435. N \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 \u0431\u043E\u043A\u043E\u0432\u043E\u0435 \u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435 \u0432\u043B\u0435\u0432\u043E, D \u2014 \u0432\u043F\u0440\u0430\u0432\u043E. \u041A\u0430\u0436\u0434\u043E\u0435 \u043D\u0430\u0436\u0430\u0442\u0438\u0435 \u043C\u0435\u043D\u044F\u0435\u0442 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u043D\u0430 \u043F\u044F\u0442\u044C. R \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u0443\u0434\u0430\u0440 \u0431\u0435\u0437 \u0432\u0440\u0430\u0449\u0435\u043D\u0438\u044F. \u0412\u0435\u0440\u0445\u043D\u0435\u0435 \u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435 \u043F\u043E\u043C\u043E\u0433\u0430\u0435\u0442 \u0431\u0438\u0442\u043A\u0443 \u043F\u043E\u0439\u0442\u0438 \u0432\u0441\u043B\u0435\u0434 \u0437\u0430 \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u043C \u0448\u0430\u0440\u043E\u043C, \u043D\u0438\u0436\u043D\u0435\u0435 \u043C\u043E\u0436\u0435\u0442 \u0432\u0435\u0440\u043D\u0443\u0442\u044C \u0435\u0433\u043E \u043D\u0430\u0437\u0430\u0434. \u0411\u043E\u043A\u043E\u0432\u043E\u0435 \u043C\u0435\u043D\u044F\u0435\u0442 \u043E\u0442\u0441\u043A\u043E\u043A\u0438 \u043E\u0442 \u0431\u043E\u0440\u0442\u043E\u0432 \u0438 \u043D\u0435\u043C\u043D\u043E\u0433\u043E \u043E\u0442\u043A\u043B\u043E\u043D\u044F\u0435\u0442 \u043D\u0430\u0447\u0430\u043B\u044C\u043D\u043E\u0435 \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435. \u042D\u0444\u0444\u0435\u043A\u0442 \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043E\u0442 \u0441\u0438\u043B\u044B \u0438 \u0440\u0430\u0441\u0441\u0442\u043E\u044F\u043D\u0438\u044F: \u0442\u0440\u0435\u043D\u0438\u0435 \u043E \u0441\u0443\u043A\u043D\u043E \u043C\u043E\u0436\u0435\u0442 \u043F\u043E\u0433\u0430\u0441\u0438\u0442\u044C \u043D\u0438\u0436\u043D\u0435\u0435 \u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435 \u0435\u0449\u0451 \u0434\u043E \u043A\u043E\u043D\u0442\u0430\u043A\u0442\u0430.",
              "\u041E\u0431\u0430 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F \u0432\u0440\u0430\u0449\u0435\u043D\u0438\u044F \u043D\u0430\u0445\u043E\u0434\u044F\u0442\u0441\u044F \u0432 \u0434\u0438\u0430\u043F\u0430\u0437\u043E\u043D\u0435 \u043E\u0442 -100 \u0434\u043E 100. \u0412\u043C\u0435\u0441\u0442\u0435 \u043E\u043D\u0438 \u0434\u043E\u043B\u0436\u043D\u044B \u0437\u0430\u0434\u0430\u0432\u0430\u0442\u044C \u0442\u043E\u0447\u043A\u0443 \u0432\u043D\u0443\u0442\u0440\u0438 \u0431\u0438\u0442\u043A\u0430: \u043C\u0430\u043A\u0441\u0438\u043C\u0430\u043B\u044C\u043D\u043E\u0435 \u0432\u0435\u0440\u0445\u043D\u0435\u0435 \u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435 \u043D\u0435\u043B\u044C\u0437\u044F \u0441\u043E\u0432\u043C\u0435\u0441\u0442\u0438\u0442\u044C \u0441 \u043C\u0430\u043A\u0441\u0438\u043C\u0430\u043B\u044C\u043D\u044B\u043C \u0431\u043E\u043A\u043E\u0432\u044B\u043C. \u0424\u043E\u0440\u043C\u0430 \u043E\u0442\u043A\u043B\u043E\u043D\u0438\u0442 \u0442\u0430\u043A\u043E\u0435 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0435."),
            rule_section(:feedback, "\u0417\u0432\u0443\u043A\u0438 \u0438 \u0441\u0432\u0435\u0434\u0435\u043D\u0438\u044F \u043E\u0431 \u0443\u0434\u0430\u0440\u0435",
              "\u0412\u043E \u0432\u0440\u0435\u043C\u044F \u0438\u0433\u0440\u044B \u0441\u043B\u044B\u0448\u043D\u044B \u043A\u0438\u0439, \u0441\u0442\u043E\u043B\u043A\u043D\u043E\u0432\u0435\u043D\u0438\u044F \u0448\u0430\u0440\u043E\u0432, \u0431\u043E\u0440\u0442\u0430 \u0438 \u043F\u0430\u0434\u0435\u043D\u0438\u044F \u0432 \u043B\u0443\u0437\u044B. \u0413\u043E\u043B\u043E\u0441\u043E\u0432\u043E\u0439 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u043A\u043E\u043D\u0442\u0430\u043A\u0442\u044B, \u0437\u0430\u0431\u0438\u0442\u0438\u044F \u0438 \u0440\u0435\u0448\u0435\u043D\u0438\u0435 \u0441\u0443\u0434\u044C\u0438. U \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0445\u0440\u043E\u043D\u043E\u043B\u043E\u0433\u0438\u044E \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0433\u043E \u0443\u0434\u0430\u0440\u0430 \u0441 \u0443\u0433\u043B\u043E\u043C, \u0441\u0438\u043B\u043E\u0439 \u0438 \u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435\u043C. Y \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442 \u0432\u0435\u0441\u044C \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u0443\u0434\u0430\u0440 \u0438 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0438 \u043A\u043E\u043D\u0435\u0447\u043D\u044B\u0435 \u043F\u043E\u0437\u0438\u0446\u0438\u0438, \u043D\u0435 \u0434\u0432\u0438\u0433\u0430\u044F \u043D\u0430\u0441\u0442\u043E\u044F\u0449\u0438\u0435 \u0448\u0430\u0440\u044B. Escape \u0437\u0430\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u043E\u0442\u0447\u0451\u0442.",
              "\u041F\u0440\u0438 3D-\u0437\u0432\u0443\u043A\u0435 (HRTF) \u0443\u0434\u0430\u0440 \u043A\u0438\u044F, \u0441\u0442\u043E\u043B\u043A\u043D\u043E\u0432\u0435\u043D\u0438\u044F \u0448\u0430\u0440\u043E\u0432, \u0431\u043E\u0440\u0442\u0430 \u0438 \u043F\u0430\u0434\u0435\u043D\u0438\u044F \u0432 \u043B\u0443\u0437\u044B \u0441\u043B\u044B\u0448\u043D\u044B \u0441 \u0438\u0445 \u043C\u0435\u0441\u0442 \u043D\u0430 \u0441\u0442\u043E\u043B\u0435. \u0420\u0430\u0441\u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u043F\u043E\u0441\u0442\u043E\u044F\u043D\u043D\u043E: \u043B\u0435\u0432\u0430\u044F \u0438 \u043F\u0440\u0430\u0432\u0430\u044F \u0441\u0442\u043E\u0440\u043E\u043D\u044B \u0441\u0442\u043E\u043B\u0430 \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u0441\u043B\u0435\u0432\u0430 \u0438 \u0441\u043F\u0440\u0430\u0432\u0430 \u043E\u0442 \u0432\u0430\u0441, \u0434\u0430\u043B\u044C\u043D\u044F\u044F \u0447\u0430\u0441\u0442\u044C \u043D\u0430\u0445\u043E\u0434\u0438\u0442\u0441\u044F \u043F\u0435\u0440\u0435\u0434 \u0432\u0430\u043C\u0438. \u0421\u0438\u0433\u043D\u0430\u043B\u044B \u043F\u0440\u0438\u0446\u0435\u043B\u0438\u0432\u0430\u043D\u0438\u044F \u0432\u0441\u0435\u0433\u0434\u0430 \u0437\u0432\u0443\u0447\u0430\u0442 \u043F\u043E \u0446\u0435\u043D\u0442\u0440\u0443, \u0432 \u0442\u043E\u043C \u0447\u0438\u0441\u043B\u0435 \u043F\u0440\u0438 \u0432\u043A\u043B\u044E\u0447\u0451\u043D\u043D\u043E\u043C HRTF. \u0412 Power Games \u043E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u2192 \u0417\u0432\u0443\u043A\u0438, \u0432\u043A\u043B\u044E\u0447\u0438\u0442\u0435 HRTF \u0438 \u043E\u0442\u043C\u0435\u0442\u044C\u0442\u0435 \u0411\u0438\u043B\u044C\u044F\u0440\u0434 \u0432 \u0441\u043F\u0438\u0441\u043A\u0435 \u0438\u0433\u0440 \u0441 3D-\u0437\u0432\u0443\u043A\u043E\u043C. \u041F\u0440\u0438 \u0432\u044B\u043A\u043B\u044E\u0447\u0435\u043D\u043D\u043E\u043C \u0438\u043B\u0438 \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E\u043C HRTF \u0437\u0432\u0443\u043A\u0438 \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u0441\u0442\u0435\u0440\u0435\u043E\u0444\u043E\u043D\u0438\u0447\u0435\u0441\u043A\u0438\u043C\u0438.",
              "\u041A\u043E\u0433\u0434\u0430 \u043B\u0438\u043D\u0438\u044F \u043F\u0440\u0438\u0446\u0435\u043B\u0438\u0432\u0430\u043D\u0438\u044F \u0432\u0445\u043E\u0434\u0438\u0442 \u0432 \u043E\u0442\u0432\u0435\u0440\u0441\u0442\u0438\u0435 \u043B\u0443\u0437\u044B, \u0435\u0451 \u043D\u043E\u043C\u0435\u0440 \u0441\u043E\u043F\u0440\u043E\u0432\u043E\u0436\u0434\u0430\u0435\u0442\u0441\u044F \u043A\u043E\u0440\u043E\u0442\u043A\u0438\u043C \u0442\u043E\u043D\u043E\u043C 3000 \u0413\u0446. \u041D\u043E\u043C\u0435\u0440 \u043D\u0435 \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u0435\u0442\u0441\u044F, \u043F\u043E\u043A\u0430 \u0432\u044B \u043E\u0441\u0442\u0430\u0451\u0442\u0435\u0441\u044C \u043D\u0430\u0434 \u0442\u0435\u043C \u0436\u0435 \u043E\u0442\u0432\u0435\u0440\u0441\u0442\u0438\u0435\u043C. \u041E\u043F\u0438\u0441\u0430\u043D\u0438\u0435 \u0448\u0430\u0440\u0430 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442\u0441\u044F \u0441 \u043D\u043E\u043C\u0435\u0440\u0430 \u0438\u043B\u0438 \u0446\u0432\u0435\u0442\u0430; \u0432 \u043F\u0443\u043B\u0435 \u0448\u0430\u0440\u044B 9\u201315 \u043F\u043E\u043B\u043E\u0441\u0430\u0442\u044B\u0435.",
              "\u041D\u0430\u043F\u0440\u0430\u0432\u044C\u0442\u0435 \u043A\u0438\u0439 \u043D\u0430 \u0431\u043E\u0440\u0442 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 V \u0434\u043B\u044F \u0440\u0430\u0441\u0447\u0451\u0442\u0430 \u043E\u0442\u0441\u043A\u043E\u043A\u0430 \u0442\u0435\u043A\u0443\u0449\u0435\u0433\u043E \u0431\u0438\u0442\u043A\u0430 \u043F\u0440\u0438 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0445 \u0441\u0438\u043B\u0435 \u0438 \u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0438. \u0412\u044B \u0443\u0441\u043B\u044B\u0448\u0438\u0442\u0435 \u043F\u0435\u0440\u0432\u044B\u0439 \u0431\u043E\u0440\u0442, \u0447\u0438\u0441\u043B\u043E \u043A\u043E\u043D\u0442\u0430\u043A\u0442\u043E\u0432 \u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0435 \u043A\u0430\u0441\u0430\u043D\u0438\u0435 \u0448\u0430\u0440\u0430 \u0438\u043B\u0438 \u043F\u0430\u0434\u0435\u043D\u0438\u0435 \u0432 \u043B\u0443\u0437\u0443. \u0415\u0441\u043B\u0438 \u0441\u0438\u043B\u044B \u043D\u0435 \u0445\u0432\u0430\u0442\u0430\u0435\u0442 \u0434\u043B\u044F \u0434\u043E\u0441\u0442\u0438\u0436\u0435\u043D\u0438\u044F \u0431\u043E\u0440\u0442\u0430, \u043F\u0440\u043E\u0433\u0440\u0430\u043C\u043C\u0430 \u0441\u043E\u043E\u0431\u0449\u0438\u0442 \u043E\u0431 \u044D\u0442\u043E\u043C. \u042D\u0442\u043E \u043F\u0440\u043E\u0433\u043D\u043E\u0437, \u0430 \u043D\u0435 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u043D\u044B\u0439 \u0443\u0434\u0430\u0440.",
              "B \u0447\u0438\u0442\u0430\u0435\u0442 \u043E\u0431\u044A\u0435\u043A\u0442\u044B \u0434\u0430\u043B\u044C\u0448\u0435 \u043F\u043E \u043B\u0438\u043D\u0438\u0438 \u043F\u0440\u0438\u0446\u0435\u043B\u0438\u0432\u0430\u043D\u0438\u044F \u0437\u0430 \u043F\u0435\u0440\u0432\u044B\u043C \u0448\u0430\u0440\u043E\u043C: \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0448\u0430\u0440\u044B \u043F\u043E \u043F\u043E\u0440\u044F\u0434\u043A\u0443, \u0437\u0430\u0442\u0435\u043C \u0431\u043E\u0440\u0442 \u0438\u043B\u0438 \u043B\u0443\u0437\u0443. \u0428\u0430\u0440\u044B \u0432\u043D\u0435 \u043B\u0438\u043D\u0438\u0438 \u0438 \u043F\u043E\u0437\u0430\u0434\u0438 \u0431\u0438\u0442\u043A\u0430 \u043F\u0440\u043E\u043F\u0443\u0441\u043A\u0430\u044E\u0442\u0441\u044F. \u0415\u0441\u043B\u0438 \u043F\u0435\u0440\u0435\u0434 \u0431\u043E\u0440\u0442\u043E\u043C \u0438\u043B\u0438 \u043B\u0443\u0437\u043E\u0439 \u043D\u0435\u0442 \u0448\u0430\u0440\u0430, B \u043D\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u0438\u0445 \u043F\u0440\u044F\u043C\u043E. \u042D\u0442\u043E \u043F\u0440\u044F\u043C\u0430\u044F \u0433\u0435\u043E\u043C\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043A\u0430\u044F \u043B\u0438\u043D\u0438\u044F; \u0444\u0438\u0437\u0438\u0447\u0435\u0441\u043A\u043E\u0435 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435 \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0447\u0435\u0440\u0435\u0437 Y \u0438\u043B\u0438 \u0437\u0430\u043F\u044F\u0442\u0443\u044E."),
            rule_section(:object_prediction, "\u041F\u0440\u043E\u0433\u043D\u043E\u0437 \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u0448\u0430\u0440\u0430",
              "\u041D\u0430\u0432\u0435\u0434\u0438\u0442\u0435 \u043A\u0438\u0439 \u043D\u0430 \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u0439 \u0448\u0430\u0440 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 \u0437\u0430\u043F\u044F\u0442\u0443\u044E. \u0420\u0430\u0441\u0441\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0432\u0435\u0441\u044C \u0443\u0434\u0430\u0440 \u0441 \u0442\u0435\u043A\u0443\u0449\u0438\u043C\u0438 \u0443\u0433\u043B\u043E\u043C, \u0441\u0438\u043B\u043E\u0439 \u0438 \u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435\u043C, \u043F\u043E\u0441\u043B\u0435 \u0447\u0435\u0433\u043E \u043E\u043F\u0438\u0441\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435 \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0448\u0430\u0440\u0430 \u043D\u0430 \u043B\u0438\u043D\u0438\u0438 \u043F\u0440\u0438\u0446\u0435\u043B\u0438\u0432\u0430\u043D\u0438\u044F: \u0435\u0433\u043E \u043A\u043E\u043D\u0442\u0430\u043A\u0442\u044B \u0438 \u0442\u043E, \u0443\u043F\u0430\u0434\u0451\u0442 \u043B\u0438 \u0448\u0430\u0440 \u0432 \u043B\u0443\u0437\u0443 \u0438\u043B\u0438 \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0441\u044F \u043D\u0430 \u0441\u0442\u043E\u043B\u0435. \u042D\u0442\u043E \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0440\u0430\u0441\u0447\u0451\u0442\u0430 \u0444\u0438\u0437\u0438\u043A\u0438, \u0430 \u043D\u0435 \u043F\u0440\u043E\u0441\u0442\u043E\u0435 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0435\u043D\u0438\u0435 \u043F\u0440\u044F\u043C\u043E\u0439. \u041F\u0440\u043E\u0433\u043D\u043E\u0437 \u043D\u0435 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442 \u0443\u0434\u0430\u0440. \u0415\u0441\u043B\u0438 \u043D\u0430 \u043B\u0438\u043D\u0438\u0438 \u043D\u0435\u0442 \u0448\u0430\u0440\u0430, \u0432\u044B \u0443\u0441\u043B\u044B\u0448\u0438\u0442\u0435 \u043E\u0431 \u044D\u0442\u043E\u043C. Y \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u0432\u0435\u0441\u044C \u0443\u0434\u0430\u0440 \u0441 \u043A\u043E\u043D\u0435\u0447\u043D\u044B\u043C\u0438 \u043F\u043E\u0437\u0438\u0446\u0438\u044F\u043C\u0438, V \u043E\u043F\u0438\u0441\u044B\u0432\u0430\u0435\u0442 \u043E\u0442\u0441\u043A\u043E\u043A \u0442\u0435\u043A\u0443\u0449\u0435\u0433\u043E \u0431\u0438\u0442\u043A\u0430 \u043E\u0442 \u0431\u043E\u0440\u0442\u0430."),
            rule_section(:match, "\u0412\u044B\u0431\u043E\u0440 \u0434\u0438\u0441\u0446\u0438\u043F\u043B\u0438\u043D\u044B \u0438 \u0440\u0435\u0448\u0435\u043D\u0438\u044F",
              "\u0414\u0438\u0441\u0446\u0438\u043F\u043B\u0438\u043D\u0443 \u0432\u044B\u0431\u0438\u0440\u0430\u044E\u0442 \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u0442\u043E\u043B\u0430. \u0414\u043B\u044F \u0441\u043E\u0440\u0435\u0432\u043D\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u043F\u0443\u043B\u0430, \u0441\u043D\u0443\u043A\u0435\u0440\u0430, \u0430\u043D\u0433\u043B\u0438\u0439\u0441\u043A\u043E\u0433\u043E \u0431\u0438\u043B\u044C\u044F\u0440\u0434\u0430 \u0438 \u043A\u0430\u0440\u0430\u043C\u0431\u043E\u043B\u044F \u043D\u0443\u0436\u043D\u044B \u0434\u0432\u0430 \u0438\u0433\u0440\u043E\u043A\u0430, \u0434\u043B\u044F Cutthroat \u2014 \u0442\u0440\u0438. \u041F\u0435\u0440\u0432\u044B\u043C \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A \u0432 \u043D\u0430\u0447\u0430\u043B\u0435 \u0441\u043F\u0438\u0441\u043A\u0430; \u0437\u0430\u0442\u0435\u043C \u043F\u0440\u0430\u0432\u043E \u043D\u0430\u0447\u0430\u043B\u0430 \u043F\u0430\u0440\u0442\u0438\u0439 \u0438\u043B\u0438 \u0444\u0440\u0435\u0439\u043C\u043E\u0432 \u0447\u0435\u0440\u0435\u0434\u0443\u0435\u0442\u0441\u044F. \u041E\u0431\u044B\u0447\u043D\u043E \u043C\u0430\u0442\u0447 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0435\u0442\u0441\u044F \u0434\u043E \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0433\u043E \u0447\u0438\u0441\u043B\u0430 \u043F\u043E\u0431\u0435\u0434 \u0432 \u043F\u0430\u0440\u0442\u0438\u044F\u0445. \u041E\u0447\u043A\u0438 \u0432\u043D\u0443\u0442\u0440\u0438 \u043F\u0430\u0440\u0442\u0438\u0438 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E \u043E\u0442 \u044D\u0442\u0438\u0445 \u043F\u043E\u0431\u0435\u0434.",
              "P \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0437\u0430\u043A\u0430\u0437 \u0443\u0434\u0430\u0440\u043E\u0432 \u0438 \u043E\u0436\u0438\u0434\u0430\u044E\u0449\u0438\u0435 \u0440\u0435\u0448\u0435\u043D\u0438\u044F. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0448\u0430\u0440, \u043B\u0443\u0437\u0443 \u0438 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u044B\u0435 \u043F\u0430\u0440\u0430\u043C\u0435\u0442\u0440\u044B, \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 \u0432\u044B\u0431\u043E\u0440, \u0437\u0430\u0442\u0435\u043C \u0432\u044B\u043F\u043E\u043B\u043D\u0438\u0442\u0435 \u0443\u0434\u0430\u0440 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 Enter \u0438\u043B\u0438 \u041F\u0440\u043E\u0431\u0435\u043B \u043D\u0430 \u043F\u043E\u043B\u0435 \u043A\u0438\u044F. Enter \u0437\u0430\u043F\u0440\u043E\u0441\u0438\u0442 \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u044E\u0449\u0438\u0439 \u0437\u0430\u043A\u0430\u0437. Shift+P \u0447\u0438\u0442\u0430\u0435\u0442 \u0442\u0435\u043A\u0443\u0449\u0443\u044E \u0438\u0433\u0440\u043E\u0432\u0443\u044E \u0441\u0438\u0442\u0443\u0430\u0446\u0438\u044E, T \u2014 \u0447\u0435\u0439 \u0445\u043E\u0434, S \u2014 \u0441\u0447\u0451\u0442 \u0431\u0435\u0437 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u043E\u043A\u043D\u0430. M \u0443\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u0435\u0442 \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u0431\u0438\u0442\u043E\u043A \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u0440\u0438 \u0438\u0433\u0440\u0435 \u0441 \u0440\u0443\u043A\u0438. Q \u043F\u0440\u0435\u0434\u043B\u0430\u0433\u0430\u0435\u0442 \u0441\u0434\u0430\u0442\u044C \u0442\u0435\u043A\u0443\u0449\u0443\u044E \u043F\u0430\u0440\u0442\u0438\u044E. \u041F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u043D\u0443\u044E \u0447\u0435\u0440\u0435\u0437 P \u043F\u0435\u0440\u0435\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0443 \u043F\u0440\u0438 \u0442\u0443\u043F\u0438\u043A\u043E\u0432\u043E\u0439 \u043F\u043E\u0437\u0438\u0446\u0438\u0438 \u0434\u043E\u043B\u0436\u043D\u044B \u043F\u0440\u0438\u043D\u044F\u0442\u044C \u0432\u0441\u0435 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0438\u0433\u0440\u043E\u043A\u0438; \u043B\u044E\u0431\u043E\u0439 \u043E\u0442\u043A\u0430\u0437 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u0445\u043E\u0434 \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0438\u0432\u0448\u0435\u043C\u0443."),
            rule_section(:pool_eight, "\u041F\u0443\u043B-8",
              "\u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u0441\u0442\u043E\u043B \u043E\u0442\u043A\u0440\u044B\u0442. \u0420\u0430\u0437\u0431\u0438\u0442\u0438\u0435 \u043D\u0435 \u043D\u0430\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u0433\u0440\u0443\u043F\u043F\u044B. \u041F\u043E\u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0435 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u0435 \u0437\u0430\u0431\u0438\u0442\u0438\u0435 \u0437\u0430\u043A\u0430\u0437\u0430\u043D\u043D\u043E\u0433\u043E \u0448\u0430\u0440\u0430 \u043D\u0430\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u0432\u0430\u043C \u0441\u043F\u043B\u043E\u0448\u043D\u044B\u0435 1\u20137 \u0438\u043B\u0438 \u043F\u043E\u043B\u043E\u0441\u0430\u0442\u044B\u0435 9\u201315, \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0443 \u2014 \u0434\u0440\u0443\u0433\u0443\u044E \u0433\u0440\u0443\u043F\u043F\u0443. \u041F\u043E\u0441\u043B\u0435 \u0437\u0430\u0431\u0438\u0442\u0438\u044F \u0437\u0430\u043A\u0430\u0437\u0430\u043D\u043D\u043E\u0433\u043E \u0448\u0430\u0440\u0430 \u0432 \u0437\u0430\u043A\u0430\u0437\u0430\u043D\u043D\u0443\u044E \u043B\u0443\u0437\u0443 \u0445\u043E\u0434 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0435\u0442\u0441\u044F. \u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u043A\u0430\u0441\u0430\u0439\u0442\u0435\u0441\u044C \u0441\u0432\u043E\u0435\u0439 \u0433\u0440\u0443\u043F\u043F\u044B, \u043F\u043E\u0441\u043B\u0435 \u0435\u0451 \u0443\u0434\u0430\u043B\u0435\u043D\u0438\u044F \u2014 \u0432\u043E\u0441\u044C\u043C\u0451\u0440\u043A\u0438. \u041D\u0430 \u043E\u0442\u043A\u0440\u044B\u0442\u043E\u043C \u0441\u0442\u043E\u043B\u0435 \u0432\u043E\u0441\u044C\u043C\u0451\u0440\u043A\u0443 \u043C\u043E\u0436\u043D\u043E \u0437\u0430\u043A\u0430\u0437\u0430\u0442\u044C, \u0442\u043E\u043B\u044C\u043A\u043E \u0435\u0441\u043B\u0438 \u0446\u0435\u043B\u0430\u044F \u0433\u0440\u0443\u043F\u043F\u0430 \u0443\u0436\u0435 \u043E\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442.",
              "\u041A\u0440\u043E\u043C\u0435 \u0440\u0430\u0437\u0431\u0438\u0442\u0438\u044F, \u0437\u0430\u0440\u0430\u043D\u0435\u0435 \u0437\u0430\u043A\u0430\u0436\u0438\u0442\u0435 \u0448\u0430\u0440 \u0438 \u043B\u0443\u0437\u0443. P \u043C\u0435\u043D\u044F\u0435\u0442 \u0437\u0430\u043A\u0430\u0437, Enter \u0437\u0430\u043F\u0440\u0430\u0448\u0438\u0432\u0430\u0435\u0442 \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u044E\u0449\u0438\u0435 \u0434\u0430\u043D\u043D\u044B\u0435. \u041E\u0442\u044B\u0433\u0440\u044B\u0448 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0435\u0442 \u0445\u043E\u0434 \u0434\u0430\u0436\u0435 \u043F\u0440\u0438 \u0437\u0430\u0431\u0438\u0442\u043E\u043C \u0448\u0430\u0440\u0435. \u0412\u043E\u0441\u044C\u043C\u0451\u0440\u043A\u0430, \u0437\u0430\u0431\u0438\u0442\u0430\u044F \u0440\u0430\u043D\u044C\u0448\u0435 \u0432\u0440\u0435\u043C\u0435\u043D\u0438, \u0441 \u0444\u043E\u043B\u043E\u043C \u0438\u043B\u0438 \u043D\u0435 \u0432 \u0437\u0430\u043A\u0430\u0437\u0430\u043D\u043D\u0443\u044E \u043B\u0443\u0437\u0443, \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u043F\u0440\u043E\u0438\u0433\u0440\u044B\u0448. \u041E\u0434\u043D\u0430 \u043B\u0438\u0448\u044C \u0431\u0435\u043B\u0430\u044F \u0431\u0435\u0437 \u0432\u043E\u0441\u044C\u043C\u0451\u0440\u043A\u0438 \u2014 \u043E\u0431\u044B\u0447\u043D\u044B\u0439 \u0444\u043E\u043B. \u041D\u0435\u0432\u0435\u0440\u043D\u044B\u0439 \u043F\u0435\u0440\u0432\u044B\u0439 \u0448\u0430\u0440 \u043B\u0438\u0431\u043E \u043E\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 \u0437\u0430\u0431\u0438\u0442\u0438\u044F \u0438 \u0431\u043E\u0440\u0442\u0430 \u043F\u043E\u0441\u043B\u0435 \u043A\u0430\u0441\u0430\u043D\u0438\u044F \u0442\u0430\u043A\u0436\u0435 \u0434\u0430\u044E\u0442 \u0444\u043E\u043B; \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u0431\u0438\u0442\u043E\u043A \u0441 \u0440\u0443\u043A\u0438 \u043F\u043E \u0432\u0441\u0435\u043C\u0443 \u0441\u0442\u043E\u043B\u0443.",
              "\u0415\u0441\u043B\u0438 \u043F\u0440\u0438 \u0440\u0430\u0437\u0431\u0438\u0442\u0438\u0438 \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u0437\u0430\u0431\u0438\u0442\u043E, \u043C\u0438\u043D\u0438\u043C\u0443\u043C \u0447\u0435\u0442\u044B\u0440\u0435 \u0440\u0430\u0437\u043D\u044B\u0445 \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u0445 \u0448\u0430\u0440\u0430 \u0434\u043E\u043B\u0436\u043D\u044B \u043A\u043E\u0441\u043D\u0443\u0442\u044C\u0441\u044F \u0431\u043E\u0440\u0442\u043E\u0432. \u0418\u043D\u0430\u0447\u0435 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A \u043C\u043E\u0436\u0435\u0442 \u043F\u0440\u0438\u043D\u044F\u0442\u044C \u043F\u043E\u0437\u0438\u0446\u0438\u044E \u0438\u043B\u0438 \u0432\u044B\u0431\u0440\u0430\u0442\u044C, \u043A\u0442\u043E \u0437\u0430\u043D\u043E\u0432\u043E \u0432\u044B\u0441\u0442\u0430\u0432\u0438\u0442 \u0438 \u0440\u0430\u0437\u043E\u0431\u044C\u0451\u0442 \u0448\u0430\u0440\u044B. \u0412\u043E\u0441\u044C\u043C\u0451\u0440\u043A\u0430 \u043F\u0440\u0438 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u043C \u0440\u0430\u0437\u0431\u0438\u0442\u0438\u0438 \u0432\u044B\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u043D\u0430 \u0442\u043E\u0447\u043A\u0443 \u043B\u0438\u0431\u043E \u0440\u0430\u0437\u0431\u0438\u0432\u0430\u044E\u0449\u0438\u0439 \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442 \u043F\u043E\u0432\u0442\u043E\u0440. \u041F\u0440\u0438 \u0444\u043E\u043B\u0435 \u0441 \u0432\u043E\u0441\u044C\u043C\u0451\u0440\u043A\u043E\u0439 \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A; \u0435\u0441\u043B\u0438 \u043F\u043E\u0437\u0438\u0446\u0438\u044F \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442\u0441\u044F, \u0431\u0438\u0442\u043E\u043A \u0438\u0433\u0440\u0430\u0435\u0442 \u0441 \u0440\u0443\u043A\u0438 \u0438\u0437-\u0437\u0430 \u043B\u0438\u043D\u0438\u0438 \u0434\u043E\u043C\u0430. \u0414\u0440\u0443\u0433\u0438\u0435 \u0444\u043E\u043B\u044B \u0440\u0430\u0437\u0431\u0438\u0442\u0438\u044F \u0434\u0430\u044E\u0442 \u0432\u044B\u0431\u043E\u0440 \u0442\u0435\u043A\u0443\u0449\u0435\u0439 \u043F\u043E\u0437\u0438\u0446\u0438\u0438 \u0438\u043B\u0438 \u0431\u0438\u0442\u043A\u0430 \u0438\u0437-\u0437\u0430 \u043B\u0438\u043D\u0438\u0438. \u041E\u0442\u0442\u0443\u0434\u0430 \u043D\u0435\u043B\u044C\u0437\u044F \u043F\u0440\u044F\u043C\u043E \u0443\u0434\u0430\u0440\u0438\u0442\u044C \u0448\u0430\u0440 \u0432 \u0434\u043E\u043C\u0435 \u0431\u0435\u0437 \u043F\u0440\u0435\u0434\u0432\u0430\u0440\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u043F\u0435\u0440\u0435\u0441\u0435\u0447\u0435\u043D\u0438\u044F \u043B\u0438\u043D\u0438\u0438. \u0415\u0441\u043B\u0438 \u0432\u0441\u0435 \u0440\u0430\u0437\u0440\u0435\u0448\u0451\u043D\u043D\u044B\u0435 \u0448\u0430\u0440\u044B \u0432 \u0434\u043E\u043C\u0435, P \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u0435\u0442 \u0437\u0430\u043F\u0440\u043E\u0441\u0438\u0442\u044C \u0432\u044B\u0441\u0442\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u0431\u043B\u0438\u0436\u0430\u0439\u0448\u0435\u0433\u043E \u043D\u0430 \u0442\u043E\u0447\u043A\u0443."),
            rule_section(:pool_nine, "\u041F\u0443\u043B-9",
              "\u041F\u0435\u0440\u0432\u044B\u043C \u0432\u0441\u0435\u0433\u0434\u0430 \u043A\u0430\u0441\u0430\u0439\u0442\u0435\u0441\u044C \u043D\u0430\u0438\u043C\u0435\u043D\u044C\u0448\u0435\u0433\u043E \u043D\u043E\u043C\u0435\u0440\u0430 \u043D\u0430 \u0441\u0442\u043E\u043B\u0435. \u041B\u044E\u0431\u043E\u0439 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E \u0437\u0430\u0431\u0438\u0442\u044B\u0439 \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u0439 \u0448\u0430\u0440 \u043F\u0440\u043E\u0434\u043B\u0435\u0432\u0430\u0435\u0442 \u0445\u043E\u0434, \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u0430\u044F \u0434\u0435\u0432\u044F\u0442\u043A\u0430 \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442, \u0432 \u0442\u043E\u043C \u0447\u0438\u0441\u043B\u0435 \u043A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u0435\u0439. \u0417\u0430\u043A\u0430\u0437 \u043D\u0435 \u043D\u0443\u0436\u0435\u043D. \u0424\u043E\u043B \u0434\u0430\u0451\u0442 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0443 \u0431\u0438\u0442\u043E\u043A \u0441 \u0440\u0443\u043A\u0438 \u043F\u043E \u0432\u0441\u0435\u043C\u0443 \u0441\u0442\u043E\u043B\u0443. \u0414\u0435\u0432\u044F\u0442\u043A\u0430 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044F \u043D\u0430 \u0442\u043E\u0447\u043A\u0443 \u043F\u043E\u0441\u043B\u0435 \u0444\u043E\u043B\u0430 \u0438\u043B\u0438 push-out, \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0437\u0430\u0431\u0438\u0442\u044B\u0435 \u0448\u0430\u0440\u044B \u043D\u0435 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u044E\u0442\u0441\u044F. \u0422\u0440\u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u0444\u043E\u043B\u0430 \u043E\u0434\u043D\u043E\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430 \u043F\u0440\u043E\u0438\u0433\u0440\u044B\u0432\u0430\u044E\u0442 \u043F\u0430\u0440\u0442\u0438\u044E; \u043F\u043E\u0441\u043B\u0435 \u0434\u0432\u0443\u0445 \u0437\u0432\u0443\u0447\u0438\u0442 \u043F\u0440\u0435\u0434\u0443\u043F\u0440\u0435\u0436\u0434\u0435\u043D\u0438\u0435. \u041F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u044B\u0439 \u0443\u0434\u0430\u0440 \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0435\u0442 \u0435\u0433\u043E \u0441\u0447\u0451\u0442\u0447\u0438\u043A \u0444\u043E\u043B\u043E\u0432.",
              "\u0412 \u0440\u043E\u043C\u0431\u0435 \u0434\u0435\u0432\u044F\u0442\u043A\u0430 \u0441\u0442\u043E\u0438\u0442 \u043D\u0430 \u0442\u043E\u0447\u043A\u0435, \u0435\u0434\u0438\u043D\u0438\u0446\u0430 \u0441\u043F\u0435\u0440\u0435\u0434\u0438. \u0420\u0430\u0437\u0431\u0438\u0442\u0438\u0435 \u0431\u0435\u0437 \u0437\u0430\u0431\u0438\u0442\u0438\u044F \u0434\u043E\u043B\u0436\u043D\u043E \u0434\u043E\u0432\u0435\u0441\u0442\u0438 \u0447\u0435\u0442\u044B\u0440\u0435 \u0448\u0430\u0440\u0430 \u0434\u043E \u0431\u043E\u0440\u0442\u043E\u0432. \u041F\u0440\u0430\u0432\u0438\u043B\u043E \u0442\u0440\u0451\u0445 \u0448\u0430\u0440\u043E\u0432 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u043E \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043C\u0438\u043D\u0438\u043C\u0443\u043C \u0442\u0440\u0438 \u0440\u0430\u0437\u043D\u044B\u0445 \u0437\u0430\u0431\u0438\u0442\u044B\u0445 \u0448\u0430\u0440\u0430 \u0438\u043B\u0438 \u043F\u0435\u0440\u0435\u0441\u0435\u0447\u0435\u043D\u0438\u044F \u043B\u0438\u043D\u0438\u0438 \u0434\u043E\u043C\u0430. \u0415\u0441\u043B\u0438 \u043E\u043D\u043E \u043D\u0430\u0440\u0443\u0448\u0435\u043D\u043E \u0431\u0435\u0437 \u0434\u0440\u0443\u0433\u043E\u0433\u043E \u0444\u043E\u043B\u0430, \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A \u043F\u0440\u0438\u043D\u0438\u043C\u0430\u0435\u0442 \u043F\u043E\u0437\u0438\u0446\u0438\u044E \u0438\u043B\u0438 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u0443\u0434\u0430\u0440; \u0437\u0430\u0431\u0438\u0442\u0430\u044F \u0434\u0435\u0432\u044F\u0442\u043A\u0430 \u0432\u044B\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442\u0441\u044F. Push-out \u0442\u043E\u0433\u0434\u0430 \u0440\u0430\u0437\u0440\u0435\u0448\u0451\u043D \u043B\u0438\u0448\u044C \u0440\u0430\u0437\u0431\u0438\u0432\u0430\u044E\u0449\u0435\u043C\u0443, \u043A\u043E\u0442\u043E\u0440\u043E\u043C\u0443 \u0432\u0435\u0440\u043D\u0443\u043B\u0438 \u0443\u0434\u0430\u0440. \u041F\u043E\u0441\u043B\u0435 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u0433\u043E \u0440\u0430\u0437\u0431\u0438\u0442\u0438\u044F \u0432\u0442\u043E\u0440\u043E\u0439 \u0443\u0434\u0430\u0440 \u043C\u043E\u0436\u0435\u0442 \u0431\u044B\u0442\u044C push-out, \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u043D\u044B\u043C \u0447\u0435\u0440\u0435\u0437 P: \u0442\u0440\u0435\u0431\u043E\u0432\u0430\u043D\u0438\u044F \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u043A\u0430\u0441\u0430\u043D\u0438\u044F \u043C\u043B\u0430\u0434\u0448\u0435\u0433\u043E \u0448\u0430\u0440\u0430 \u0438 \u0431\u043E\u0440\u0442\u0430 \u043E\u0442\u043C\u0435\u043D\u044F\u044E\u0442\u0441\u044F. \u041F\u043E\u0441\u043B\u0435 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u0433\u043E push-out \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430."),
            rule_section(:pool_ten, "\u041F\u0443\u043B: \u0434\u0435\u0441\u044F\u0442\u043A\u0430",
              "\u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u043A\u0430\u0441\u0430\u0439\u0442\u0435\u0441\u044C \u043D\u0430\u0438\u043C\u0435\u043D\u044C\u0448\u0435\u0433\u043E \u043E\u0441\u0442\u0430\u0432\u0448\u0435\u0433\u043E\u0441\u044F \u043D\u043E\u043C\u0435\u0440\u0430, \u043D\u043E \u043F\u0435\u0440\u0435\u0434 \u043E\u0431\u044B\u0447\u043D\u044B\u043C \u0443\u0434\u0430\u0440\u043E\u043C \u0447\u0435\u0440\u0435\u0437 P \u0437\u0430\u043A\u0430\u0436\u0438\u0442\u0435 \u0448\u0430\u0440 \u0438 \u043B\u0443\u0437\u0443. \u0417\u0430\u043A\u0430\u0437\u0430 \u043E\u0442\u044B\u0433\u0440\u044B\u0448\u0430 \u0437\u0434\u0435\u0441\u044C \u043D\u0435\u0442. \u041F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u0435 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u0435 \u0437\u0430\u043A\u0430\u0437\u0430 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u043F\u043E\u0434\u0445\u043E\u0434. \u0414\u0435\u0441\u044F\u0442\u043A\u0430 \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442, \u0442\u043E\u043B\u044C\u043A\u043E \u0435\u0441\u043B\u0438 \u0434\u043E \u0443\u0434\u0430\u0440\u0430 \u0431\u044B\u043B\u0430 \u0435\u0434\u0438\u043D\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u043C \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u043C \u0448\u0430\u0440\u043E\u043C \u0438 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E \u0443\u043F\u0430\u043B\u0430 \u0432 \u0437\u0430\u043A\u0430\u0437\u0430\u043D\u043D\u0443\u044E \u043B\u0443\u0437\u0443; \u0431\u043E\u043B\u0435\u0435 \u0440\u0430\u043D\u043D\u0438\u0435 \u0434\u0435\u0441\u044F\u0442\u043A\u0438 \u0432\u044B\u0441\u0442\u0430\u0432\u043B\u044F\u044E\u0442\u0441\u044F.",
              "\u0420\u0430\u0437\u0431\u0438\u0442\u0438\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0437\u0430\u0431\u0438\u0442\u0438\u044F \u0438\u043B\u0438 \u043A\u0430\u0441\u0430\u043D\u0438\u044F \u0431\u043E\u0440\u0442\u043E\u0432 \u0447\u0435\u0442\u044B\u0440\u044C\u043C\u044F \u0440\u0430\u0437\u043B\u0438\u0447\u043D\u044B\u043C\u0438 \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u043C\u0438 \u0448\u0430\u0440\u0430\u043C\u0438. \u041F\u043E\u0441\u043B\u0435 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u0433\u043E \u0440\u0430\u0437\u0431\u0438\u0442\u0438\u044F \u0432\u0442\u043E\u0440\u043E\u0439 \u0443\u0434\u0430\u0440 \u043C\u043E\u0436\u0435\u0442 \u0431\u044B\u0442\u044C push-out, \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u043D\u044B\u043C \u0447\u0435\u0440\u0435\u0437 P; \u043F\u043E\u0441\u043B\u0435 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u0433\u043E push-out \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A \u043F\u0440\u0438\u043D\u0438\u043C\u0430\u0435\u0442 \u043F\u043E\u0437\u0438\u0446\u0438\u044E \u0438\u043B\u0438 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u0443\u0434\u0430\u0440. \u041F\u0440\u0438 \u043E\u0431\u044B\u0447\u043D\u043E\u0439 \u0438\u0433\u0440\u0435 \u0437\u0430\u0431\u0438\u0442\u0438\u0435 \u0431\u0435\u0437 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u044F \u0437\u0430\u043A\u0430\u0437\u0430 \u0442\u043E\u0436\u0435 \u0434\u0430\u0451\u0442 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0443 \u044D\u0442\u043E\u0442 \u0432\u044B\u0431\u043E\u0440. \u0424\u043E\u043B \u0434\u0430\u0451\u0442 \u0431\u0438\u0442\u043E\u043A \u0441 \u0440\u0443\u043A\u0438 \u0438\u0437 \u043B\u044E\u0431\u043E\u0433\u043E \u043C\u0435\u0441\u0442\u0430, \u0442\u0440\u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u0444\u043E\u043B\u0430 \u043E\u0437\u043D\u0430\u0447\u0430\u044E\u0442 \u043F\u0440\u043E\u0438\u0433\u0440\u044B\u0448 \u043F\u0430\u0440\u0442\u0438\u0438."),
            rule_section(:straight_pool, "\u041F\u0443\u043B 14.1 \u0441 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0435\u043D\u0438\u0435\u043C",
              "\u0427\u0435\u0440\u0435\u0437 P \u0437\u0430\u043A\u0430\u0436\u0438\u0442\u0435 \u0448\u0430\u0440 \u0438 \u043B\u0443\u0437\u0443. \u041F\u0440\u0438 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u043C \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u0438 \u0437\u0430\u043A\u0430\u0437\u0430 \u043A\u0430\u0436\u0434\u044B\u0439 \u0437\u0430\u0431\u0438\u0442\u044B\u0439 \u044D\u0442\u0438\u043C \u0443\u0434\u0430\u0440\u043E\u043C \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u0439 \u0448\u0430\u0440 \u0434\u0430\u0451\u0442 1 \u043E\u0447\u043A\u043E, \u0438 \u043F\u043E\u0434\u0445\u043E\u0434 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0435\u0442\u0441\u044F. \u0414\u043E\u0441\u0442\u0438\u0433\u043D\u0438\u0442\u0435 \u0437\u0430\u0434\u0430\u043D\u043D\u043E\u0439 \u0446\u0435\u043B\u0438, \u0447\u0442\u043E\u0431\u044B \u0432\u044B\u0438\u0433\u0440\u0430\u0442\u044C \u043F\u0430\u0440\u0442\u0438\u044E. \u041D\u0435\u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u043D\u044B\u0439 \u0437\u0430\u043A\u0430\u0437 \u0438\u043B\u0438 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u043D\u044B\u0439 \u043E\u0442\u044B\u0433\u0440\u044B\u0448 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442 \u043F\u043E\u0434\u0445\u043E\u0434 \u0438 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u0437\u0430\u0431\u0438\u0442\u044B\u0435 \u0448\u0430\u0440\u044B.",
              "\u041F\u0435\u0440\u0432\u043E\u0435 \u0440\u0430\u0437\u0431\u0438\u0442\u0438\u0435 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442\u0441\u044F \u0438\u0437-\u0437\u0430 \u043F\u0435\u0440\u0435\u0434\u043D\u0435\u0439 \u043B\u0438\u043D\u0438\u0438. \u0412\u044B\u043F\u043E\u043B\u043D\u0438\u0442\u0435 \u0437\u0430\u043A\u0430\u0437\u0430\u043D\u043D\u043E\u0435 \u0437\u0430\u0431\u0438\u0442\u0438\u0435 \u043B\u0438\u0431\u043E \u043F\u043E\u0441\u043B\u0435 \u043A\u043E\u043D\u0442\u0430\u043A\u0442\u0430 \u0434\u043E\u0432\u0435\u0434\u0438\u0442\u0435 \u0434\u043E \u0431\u043E\u0440\u0442\u043E\u0432 \u0431\u0438\u0442\u043E\u043A \u0438 \u0445\u043E\u0442\u044F \u0431\u044B \u0434\u0432\u0430 \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u0445 \u0448\u0430\u0440\u0430. \u041E\u0448\u0438\u0431\u043A\u0430 \u0441\u0442\u043E\u0438\u0442 2 \u043E\u0447\u043A\u0430; \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A \u043F\u0440\u0438\u043D\u0438\u043C\u0430\u0435\u0442 \u043F\u043E\u0437\u0438\u0446\u0438\u044E \u0438\u043B\u0438 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0433\u043E \u0440\u0430\u0437\u0431\u0438\u0442\u0438\u044F. \u041E\u0431\u044B\u0447\u043D\u044B\u0439 \u0444\u043E\u043B \u0441\u0442\u043E\u0438\u0442 1 \u043E\u0447\u043A\u043E, \u0441\u0447\u0451\u0442 \u043C\u043E\u0436\u0435\u0442 \u0441\u0442\u0430\u0442\u044C \u043E\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u043C. \u041F\u0430\u0434\u0435\u043D\u0438\u0435 \u0431\u0438\u0442\u043A\u0430 \u0434\u0430\u0451\u0442 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0443 \u0438\u0433\u0440\u0443 \u0441 \u0440\u0443\u043A\u0438 \u0438\u0437-\u0437\u0430 \u043F\u0435\u0440\u0435\u0434\u043D\u0435\u0439 \u043B\u0438\u043D\u0438\u0438. \u0422\u0440\u0435\u0442\u0438\u0439 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u043E\u0431\u044B\u0447\u043D\u044B\u0439 \u0444\u043E\u043B \u0441\u0442\u043E\u0438\u0442 16 \u043E\u0447\u043A\u043E\u0432 \u0437\u0430 \u044D\u0442\u043E\u0442 \u0443\u0434\u0430\u0440 \u0438 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043D\u043E\u0432\u043E\u0433\u043E \u0440\u0430\u0437\u0431\u0438\u0442\u0438\u044F \u043F\u043E\u043B\u043D\u043E\u0439 \u043F\u0438\u0440\u0430\u043C\u0438\u0434\u044B; \u043E\u0448\u0438\u0431\u043A\u0438 \u0440\u0430\u0437\u0431\u0438\u0442\u0438\u044F \u0432 \u044D\u0442\u0443 \u0441\u0435\u0440\u0438\u044E \u043D\u0435 \u0432\u0445\u043E\u0434\u044F\u0442.",
              "\u041F\u043E\u0441\u043B\u0435 \u043D\u0430\u0431\u043E\u0440\u0430 \u043E\u0447\u043A\u043E\u0432 \u0437\u0430 \u0447\u0435\u0442\u044B\u0440\u043D\u0430\u0434\u0446\u0430\u0442\u044C \u0448\u0430\u0440\u043E\u0432 \u0438\u0445 \u0441\u0442\u0430\u0432\u044F\u0442 \u0432 \u0442\u0440\u0435\u0443\u0433\u043E\u043B\u044C\u043D\u0438\u043A \u0441 \u043F\u0443\u0441\u0442\u043E\u0439 \u0432\u0435\u0440\u0448\u0438\u043D\u043E\u0439; \u0431\u0438\u0442\u043E\u043A \u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u0439 \u0448\u0430\u0440 \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u043D\u0430 \u043C\u0435\u0441\u0442\u0435. \u0418\u0433\u0440\u0430 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0435\u0442\u0441\u044F \u0431\u0435\u0437 \u0442\u0440\u0435\u0431\u043E\u0432\u0430\u043D\u0438\u0439 \u043D\u0430\u0447\u0430\u043B\u044C\u043D\u043E\u0433\u043E \u0440\u0430\u0437\u0431\u0438\u0442\u0438\u044F. \u0415\u0441\u043B\u0438 \u0443\u043F\u0430\u043B \u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u0448\u0430\u0440 \u043B\u0438\u0431\u043E \u043E\u0431\u0430 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0445\u0441\u044F \u043C\u0435\u0448\u0430\u044E\u0442 \u0440\u0430\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0435, \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u044E\u0442\u0441\u044F \u0432\u0441\u0435 \u043F\u044F\u0442\u043D\u0430\u0434\u0446\u0430\u0442\u044C. \u041E\u0434\u0438\u043D \u043C\u0435\u0448\u0430\u044E\u0449\u0438\u0439 \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u0439 \u0448\u0430\u0440 \u0441\u0442\u0430\u0432\u0438\u0442\u0441\u044F \u043D\u0430 \u043F\u0435\u0440\u0435\u0434\u043D\u044E\u044E \u0442\u043E\u0447\u043A\u0443, \u043F\u0440\u0438 \u0437\u0430\u043D\u044F\u0442\u043E\u0441\u0442\u0438 \u2014 \u0432 \u0446\u0435\u043D\u0442\u0440. \u0415\u0441\u043B\u0438 \u043C\u0435\u0448\u0430\u0435\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u0431\u0438\u0442\u043E\u043A, \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u0448\u0430\u0440 \u043D\u0430 \u043F\u0435\u0440\u0435\u0434\u043D\u0435\u0439 \u043B\u0438\u043D\u0438\u0438 \u0438\u043B\u0438 \u0434\u0430\u043B\u044C\u0448\u0435 \u043A \u043F\u0438\u0440\u0430\u043C\u0438\u0434\u0435 \u0434\u0430\u0451\u0442 \u0431\u0438\u0442\u043E\u043A \u0441 \u0440\u0443\u043A\u0438 \u0438\u0437-\u0437\u0430 \u043B\u0438\u043D\u0438\u0438; \u043F\u0440\u0438 \u0448\u0430\u0440\u0435 \u0441\u043E \u0441\u0442\u043E\u0440\u043E\u043D\u044B \u043F\u0435\u0440\u0435\u0434\u043D\u0435\u0433\u043E \u0431\u043E\u0440\u0442\u0430 \u0431\u0438\u0442\u043E\u043A \u0441\u0442\u0430\u0432\u0438\u0442\u0441\u044F \u043D\u0430 \u043F\u0435\u0440\u0435\u0434\u043D\u044E\u044E \u0442\u043E\u0447\u043A\u0443 \u0438\u043B\u0438 \u0432 \u0446\u0435\u043D\u0442\u0440.",
              "\u0421\u043E\u0433\u043B\u0430\u0441\u043E\u0432\u0430\u043D\u043D\u0430\u044F \u043F\u0435\u0440\u0435\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u043F\u0440\u0438 \u0442\u0443\u043F\u0438\u043A\u043E\u0432\u043E\u0439 \u043F\u043E\u0437\u0438\u0446\u0438\u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u043E\u0447\u043A\u0438 \u0438 \u0434\u043E\u043B\u0433\u0438; \u0447\u0435\u0440\u0435\u0437 P \u0432\u044B\u0431\u0438\u0440\u0430\u044E\u0442 \u043D\u043E\u0432\u043E\u0433\u043E \u0440\u0430\u0437\u0431\u0438\u0432\u0430\u044E\u0449\u0435\u0433\u043E. \u041D\u043E\u0432\u0430\u044F \u043F\u0430\u0440\u0442\u0438\u044F \u043C\u0430\u0442\u0447\u0430 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442\u0441\u044F \u0441 \u043D\u0443\u043B\u044F."),
            rule_section(:one_pocket, "\u0412 \u043E\u0434\u043D\u0443 \u043B\u0443\u0437\u0443 \u2014 One Pocket",
              "\u0423 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430 \u043E\u0434\u043D\u0430 \u0438\u0437 \u0434\u0432\u0443\u0445 \u0443\u0433\u043B\u043E\u0432\u044B\u0445 \u043B\u0443\u0437 \u0443 \u043F\u0440\u0430\u0432\u043E\u0433\u043E \u043A\u0440\u0430\u044F. \u0420\u0430\u0437\u0431\u0438\u0432\u0430\u044E\u0449\u0438\u0439 \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442 \u0441\u0432\u043E\u044E \u0447\u0435\u0440\u0435\u0437 P \u0434\u043E \u0443\u0434\u0430\u0440\u0430. \u041A\u0430\u0436\u0434\u044B\u0439 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E \u0437\u0430\u0431\u0438\u0442\u044B\u0439 \u0432 \u0432\u0430\u0448\u0443 \u043B\u0443\u0437\u0443 \u0448\u0430\u0440 \u0434\u0430\u0451\u0442 \u0432\u0430\u043C 1 \u043E\u0447\u043A\u043E, \u0434\u0430\u0436\u0435 \u043F\u043E\u0441\u043B\u0435 \u0443\u0434\u0430\u0440\u0430 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430; \u043F\u0435\u0440\u0432\u044B\u0439, \u043A\u0442\u043E \u043D\u0430\u0431\u0435\u0440\u0451\u0442 8, \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442. \u041F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u0435 \u0437\u0430\u0431\u0438\u0442\u0438\u0435 \u0432 \u0441\u0432\u043E\u044E \u043B\u0443\u0437\u0443 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u043F\u043E\u0434\u0445\u043E\u0434. \u0428\u0430\u0440\u044B \u0438\u0437 \u0434\u0440\u0443\u0433\u0438\u0445 \u043B\u0443\u0437 \u0432\u044B\u0441\u0442\u0430\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u043F\u043E\u0441\u043B\u0435 \u043F\u043E\u0434\u0445\u043E\u0434\u0430 \u043B\u0438\u0431\u043E \u0441\u0440\u0430\u0437\u0443 \u043F\u0440\u0438 \u043E\u043F\u0443\u0441\u0442\u043E\u0448\u0435\u043D\u0438\u0438 \u0441\u0442\u043E\u043B\u0430 \u0434\u043E \u043F\u043E\u0431\u0435\u0434\u044B. \u0420\u0430\u0437\u0431\u0438\u0442\u0438\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043A\u043E\u043D\u0442\u0430\u043A\u0442\u0430 \u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E \u0431\u043E\u0440\u0442\u0430 \u0438\u043B\u0438 \u0437\u0430\u0431\u0438\u0442\u0438\u044F, \u0431\u0435\u0437 \u0442\u0440\u0435\u0431\u043E\u0432\u0430\u043D\u0438\u044F \u0447\u0435\u0442\u044B\u0440\u0451\u0445 \u0448\u0430\u0440\u043E\u0432 \u0443 \u0431\u043E\u0440\u0442\u043E\u0432.",
              "\u0424\u043E\u043B \u043E\u0442\u043D\u0438\u043C\u0430\u0435\u0442 \u0443 \u0432\u0430\u0441 1 \u043E\u0447\u043A\u043E \u0438 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u043E\u0434\u0438\u043D \u0432\u044B\u0438\u0433\u0440\u0430\u043D\u043D\u044B\u0439 \u0448\u0430\u0440. \u0415\u0441\u043B\u0438 \u0442\u0430\u043A\u043E\u0433\u043E \u0448\u0430\u0440\u0430 \u043D\u0435\u0442, \u0432\u043E\u0437\u043D\u0438\u043A\u0430\u0435\u0442 \u0434\u043E\u043B\u0433: \u0431\u0443\u0434\u0443\u0449\u0438\u0439 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0438\u0432\u043D\u044B\u0439 \u0448\u0430\u0440 \u043F\u043E\u0433\u0430\u0448\u0430\u0435\u0442 \u0435\u0433\u043E \u0438 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044F \u043D\u0430 \u0441\u0442\u043E\u043B. \u0428\u0430\u0440\u044B \u0432 \u043B\u0443\u0437\u0435 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u043F\u0440\u0438\u043D\u043E\u0441\u044F\u0442 \u0435\u043C\u0443 \u043E\u0447\u043A\u0438 \u0434\u0430\u0436\u0435 \u043F\u0440\u0438 \u0444\u043E\u043B\u0435, \u043A\u0440\u043E\u043C\u0435 \u0441\u043B\u0443\u0447\u0430\u044F, \u043A\u043E\u0433\u0434\u0430 \u0435\u0434\u0438\u043D\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u043C \u0444\u043E\u043B\u043E\u043C \u0431\u044B\u043B\u043E \u043F\u0430\u0434\u0435\u043D\u0438\u0435 \u0431\u0438\u0442\u043A\u0430 \u0432 \u043B\u0443\u0437\u0443. \u0412\u044B\u043B\u0435\u0442 \u0431\u0438\u0442\u043A\u0430 \u0438\u043B\u0438 \u0435\u0433\u043E \u043F\u0430\u0434\u0435\u043D\u0438\u0435 \u0432\u043C\u0435\u0441\u0442\u0435 \u0441 \u0434\u0440\u0443\u0433\u0438\u043C \u0444\u043E\u043B\u043E\u043C \u043D\u0435 \u043E\u0442\u043C\u0435\u043D\u044F\u0435\u0442 \u044D\u0442\u0438 \u043E\u0447\u043A\u0438 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430. \u041F\u043E\u0441\u043B\u0435 \u043F\u0430\u0434\u0435\u043D\u0438\u044F \u0431\u0438\u0442\u043A\u0430 \u0435\u0433\u043E \u0438\u0433\u0440\u0430\u044E\u0442 \u0441 \u0440\u0443\u043A\u0438 \u0438\u0437-\u0437\u0430 \u043F\u0435\u0440\u0435\u0434\u043D\u0435\u0439 \u043B\u0438\u043D\u0438\u0438. \u0422\u0440\u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u0444\u043E\u043B\u0430 \u043F\u0440\u043E\u0438\u0433\u0440\u044B\u0432\u0430\u044E\u0442 \u043F\u0430\u0440\u0442\u0438\u044E. \u041F\u0440\u0438 \u0434\u043E\u0441\u0442\u0438\u0436\u0435\u043D\u0438\u0438 8 \u043E\u0431\u043E\u0438\u043C\u0438 \u0438\u0433\u0440\u043E\u043A\u0430\u043C\u0438 \u043E\u0434\u043D\u0438\u043C \u0443\u0434\u0430\u0440\u043E\u043C \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442 \u0431\u044C\u044E\u0449\u0438\u0439. \u0421\u043E\u0433\u043B\u0430\u0441\u043E\u0432\u0430\u043D\u043D\u0430\u044F \u043F\u0435\u0440\u0435\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u043E\u0447\u043A\u0438 \u0438 \u0434\u043E\u043B\u0433\u0438 \u0438 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043D\u043E\u0432\u043E\u0433\u043E \u0432\u044B\u0431\u043E\u0440\u0430 \u0440\u0430\u0437\u0431\u0438\u0432\u0430\u044E\u0449\u0435\u0433\u043E \u0438 \u043B\u0443\u0437."),
            rule_section(:bank, "\u0411\u044D\u043D\u043A-\u043F\u0443\u043B: \u043A\u043E\u0440\u043E\u0442\u043A\u0438\u0439 \u0438 \u043F\u043E\u043B\u043D\u044B\u0439",
              "\u0420\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0438\u0432\u043D\u043E\u0435 \u0437\u0430\u0431\u0438\u0442\u0438\u0435 \u043E\u0442 \u0431\u043E\u0440\u0442\u0430 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0437\u0430\u043A\u0430\u0437\u0430 \u0448\u0430\u0440\u0430, \u043B\u0443\u0437\u044B \u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u0438 \u0431\u043E\u0440\u0442\u043E\u0432. \u0427\u0435\u0440\u0435\u0437 P \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0448\u0430\u0440 \u0438 \u043B\u0443\u0437\u0443, \u0437\u0430\u0442\u0435\u043C \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0439\u0442\u0435 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0431\u043E\u0440\u0442: \u043B\u0435\u0432\u044B\u0439, \u043F\u0440\u0430\u0432\u044B\u0439, \u0432\u0435\u0440\u0445\u043D\u0438\u0439 \u0438\u043B\u0438 \u043D\u0438\u0436\u043D\u0438\u0439. \u0417\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u0435 \u0433\u043E\u0442\u043E\u0432\u044B\u0439 \u043C\u0430\u0440\u0448\u0440\u0443\u0442; \u043C\u043E\u0436\u043D\u043E \u0437\u0430\u043A\u0430\u0437\u0430\u0442\u044C \u043E\u0442 \u043E\u0434\u043D\u043E\u0433\u043E \u0434\u043E \u0434\u0432\u0435\u043D\u0430\u0434\u0446\u0430\u0442\u0438 \u043A\u043E\u043D\u0442\u0430\u043A\u0442\u043E\u0432. \u041E\u0442\u043C\u0435\u043D\u0430 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u043F\u0440\u0435\u0436\u043D\u0438\u0439 \u0437\u0430\u043A\u0430\u0437. \u0411\u0438\u0442\u043E\u043A \u0434\u043E\u043B\u0436\u0435\u043D \u043F\u043E\u043F\u0430\u0441\u0442\u044C \u0432 \u0437\u0430\u043A\u0430\u0437\u0430\u043D\u043D\u044B\u0439 \u0448\u0430\u0440 \u0434\u043E \u0434\u0440\u0443\u0433\u043E\u0433\u043E \u0448\u0430\u0440\u0430 \u0438\u043B\u0438 \u0431\u043E\u0440\u0442\u0430. \u0417\u0430\u043A\u0430\u0437\u0430\u043D\u043D\u044B\u0439 \u0448\u0430\u0440 \u0437\u0430\u0442\u0435\u043C \u043D\u0435 \u0434\u043E\u043B\u0436\u0435\u043D \u043A\u0430\u0441\u0430\u0442\u044C\u0441\u044F \u0434\u0440\u0443\u0433\u043E\u0433\u043E \u0448\u0430\u0440\u0430 \u0438\u043B\u0438 \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E \u0431\u0438\u0442\u043A\u0430. \u0411\u043E\u0440\u0442\u044B \u0434\u043E\u043B\u0436\u043D\u044B \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u043E\u0432\u0430\u0442\u044C \u0437\u0430\u043A\u0430\u0437\u0443; \u0441\u043B\u0443\u0447\u0430\u0439\u043D\u044B\u0435 \u043A\u0430\u0441\u0430\u043D\u0438\u044F \u0433\u0443\u0431\u043E\u043A \u0446\u0435\u043B\u0435\u0432\u043E\u0439 \u043B\u0443\u0437\u044B \u043F\u0440\u0438 \u043F\u0430\u0434\u0435\u043D\u0438\u0438 \u043D\u0435 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u044E\u0442\u0441\u044F.",
              "\u041F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u044B\u0439 \u0431\u044D\u043D\u043A \u0434\u0430\u0451\u0442 1 \u043E\u0447\u043A\u043E \u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u043F\u043E\u0434\u0445\u043E\u0434. \u041A\u043E\u0440\u043E\u0442\u043A\u0438\u0439 \u0432\u0430\u0440\u0438\u0430\u043D\u0442 \u0438\u0433\u0440\u0430\u0435\u0442\u0441\u044F \u0434\u0435\u0432\u044F\u0442\u044C\u044E \u0448\u0430\u0440\u0430\u043C\u0438 \u0434\u043E 5 \u043E\u0447\u043A\u043E\u0432, \u043F\u043E\u043B\u043D\u044B\u0439 \u2014 \u043F\u044F\u0442\u043D\u0430\u0434\u0446\u0430\u0442\u044C\u044E \u0434\u043E 8. \u0414\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u0437\u0430\u0431\u0438\u0442\u044B\u0435 \u0448\u0430\u0440\u044B \u0432\u044B\u0441\u0442\u0430\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u043F\u043E\u0441\u043B\u0435 \u043F\u043E\u0434\u0445\u043E\u0434\u0430 \u043B\u0438\u0431\u043E \u0441\u0440\u0430\u0437\u0443 \u043F\u0440\u0438 \u043E\u043F\u0443\u0441\u0442\u043E\u0448\u0435\u043D\u0438\u0438 \u0441\u0442\u043E\u043B\u0430 \u0434\u043E \u043F\u043E\u0431\u0435\u0434\u044B. \u041D\u0430 \u0440\u0430\u0437\u0431\u0438\u0442\u0438\u0438 \u0437\u0430\u043A\u0430\u0437 \u0431\u044D\u043D\u043A\u0430 \u043D\u0435 \u043D\u0443\u0436\u0435\u043D: \u0437\u0430\u0431\u0438\u0442\u0438\u0435 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0435\u0442 \u043F\u043E\u0434\u0445\u043E\u0434, \u043D\u043E \u043D\u0435 \u0434\u0430\u0451\u0442 \u043E\u0447\u043A\u0430. \u0411\u0435\u0437 \u0437\u0430\u0431\u0438\u0442\u0438\u044F \u0447\u0435\u0442\u044B\u0440\u0435 \u0440\u0430\u0437\u043D\u044B\u0445 \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u0445 \u0448\u0430\u0440\u0430 \u0434\u043E\u043B\u0436\u043D\u044B \u043A\u043E\u0441\u043D\u0443\u0442\u044C\u0441\u044F \u0431\u043E\u0440\u0442\u043E\u0432; \u043F\u043E\u0441\u043B\u0435 \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u043E\u0433\u043E \u0440\u0430\u0437\u0431\u0438\u0442\u0438\u044F \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A \u043F\u0440\u0438\u043D\u0438\u043C\u0430\u0435\u0442 \u043F\u043E\u0437\u0438\u0446\u0438\u044E \u0438\u043B\u0438 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u044C \u0440\u0430\u0437\u0431\u0438\u0442\u0438\u0435.",
              "\u0424\u043E\u043B \u0441\u0442\u043E\u0438\u0442 1 \u043E\u0447\u043A\u043E \u0438 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u0432\u044B\u0438\u0433\u0440\u0430\u043D\u043D\u044B\u0439 \u0448\u0430\u0440. \u0415\u0441\u043B\u0438 \u0435\u0433\u043E \u043D\u0435\u0442, \u0434\u043E\u043B\u0433 \u043F\u043E\u0433\u0430\u0448\u0430\u0435\u0442\u0441\u044F \u0432\u044B\u0441\u0442\u0430\u0432\u043B\u0435\u043D\u0438\u0435\u043C \u0431\u0443\u0434\u0443\u0449\u0435\u0433\u043E \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0438\u0432\u043D\u043E\u0433\u043E \u0448\u0430\u0440\u0430; \u0441\u0447\u0451\u0442 \u043C\u043E\u0436\u0435\u0442 \u0431\u044B\u0442\u044C \u043E\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u043C. \u041F\u0430\u0434\u0435\u043D\u0438\u0435 \u0431\u0438\u0442\u043A\u0430 \u0434\u0430\u0451\u0442 \u0438\u0433\u0440\u0443 \u0441 \u0440\u0443\u043A\u0438 \u0438\u0437-\u0437\u0430 \u043F\u0435\u0440\u0435\u0434\u043D\u0435\u0439 \u043B\u0438\u043D\u0438\u0438. \u0422\u0440\u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u0444\u043E\u043B\u0430 \u043F\u0440\u043E\u0438\u0433\u0440\u044B\u0432\u0430\u044E\u0442 \u043F\u0430\u0440\u0442\u0438\u044E. \u0421\u043E\u0433\u043B\u0430\u0441\u043E\u0432\u0430\u043D\u043D\u0430\u044F \u043F\u0435\u0440\u0435\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u043F\u0440\u0438 \u0442\u0443\u043F\u0438\u043A\u0435 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u043E\u0447\u043A\u0438 \u0438 \u0434\u043E\u043B\u0433\u0438; \u0437\u0430\u0442\u0435\u043C \u0447\u0435\u0440\u0435\u0437 P \u0432\u044B\u0431\u0438\u0440\u0430\u044E\u0442 \u043D\u043E\u0432\u043E\u0433\u043E \u0440\u0430\u0437\u0431\u0438\u0432\u0430\u044E\u0449\u0435\u0433\u043E."),
            rule_section(:cutthroat, "Cutthroat \u0434\u043B\u044F \u0442\u0440\u043E\u0438\u0445",
              "\u0412 \u044D\u0442\u043E\u043C \u043A\u043B\u0443\u0431\u043D\u043E\u043C \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0435 \u0433\u0440\u0443\u043F\u043F\u044B \u0437\u0430\u043A\u0440\u0435\u043F\u043B\u0435\u043D\u044B \u043F\u043E \u043C\u0435\u0441\u0442\u0430\u043C \u0437\u0430 \u0441\u0442\u043E\u043B\u043E\u043C: 1\u20135, 6\u201310 \u0438 11\u201315. \u0421\u043E\u0445\u0440\u0430\u043D\u044F\u0439\u0442\u0435 \u0441\u0432\u043E\u044E \u0433\u0440\u0443\u043F\u043F\u0443 \u0438 \u0443\u0431\u0438\u0440\u0430\u0439\u0442\u0435 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435. \u041F\u0435\u0440\u0432\u044B\u043C \u043C\u043E\u0436\u043D\u043E \u043A\u043E\u0441\u043D\u0443\u0442\u044C\u0441\u044F \u043B\u044E\u0431\u043E\u0433\u043E \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u0448\u0430\u0440\u0430, \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u043E \u043F\u043E\u0436\u0435\u0440\u0442\u0432\u043E\u0432\u0430\u0442\u044C \u0438 \u0441\u0432\u043E\u0438\u043C. \u041F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u0435 \u0437\u0430\u0431\u0438\u0442\u0438\u0435 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u043F\u043E\u0434\u0445\u043E\u0434, \u0435\u0441\u043B\u0438 \u043D\u0435 \u0443\u0431\u0440\u0430\u043D \u0432\u0430\u0448 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u0448\u0430\u0440. \u0418\u0433\u0440\u043E\u043A\u0438 \u0431\u0435\u0437 \u0448\u0430\u0440\u043E\u0432 \u0432\u0440\u0435\u043C\u0435\u043D\u043D\u043E \u043F\u0440\u043E\u043F\u0443\u0441\u043A\u0430\u044E\u0442\u0441\u044F; \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u044F\u044F \u043E\u0441\u0442\u0430\u0432\u0448\u0430\u044F\u0441\u044F \u0433\u0440\u0443\u043F\u043F\u0430.",
              "\u0424\u043E\u043B \u0434\u0430\u0451\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u043C\u0443 \u0438\u0433\u0440\u043E\u043A\u0443 \u0431\u0438\u0442\u043E\u043A \u0441 \u0440\u0443\u043A\u0438 \u0438\u0437 \u043B\u044E\u0431\u043E\u0433\u043E \u043C\u0435\u0441\u0442\u0430 \u0438 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u043F\u043E \u043E\u0434\u043D\u043E\u043C\u0443 \u0437\u0430\u0431\u0438\u0442\u043E\u043C\u0443 \u0448\u0430\u0440\u0443 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u2014 \u043D\u0430\u0438\u043C\u0435\u043D\u044C\u0448\u0438\u0439 \u043E\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0439 \u043D\u043E\u043C\u0435\u0440 \u0432 \u0435\u0433\u043E \u0433\u0440\u0443\u043F\u043F\u0435. \u042D\u0442\u043E \u043C\u043E\u0436\u0435\u0442 \u0432\u0435\u0440\u043D\u0443\u0442\u044C \u043F\u0440\u043E\u043F\u0443\u0441\u043A\u0430\u0435\u043C\u043E\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430 \u0432 \u0438\u0433\u0440\u0443. \u041F\u0440\u043E\u0438\u0433\u0440\u044B\u0448\u0430 \u0437\u0430 \u0442\u0440\u0438 \u0444\u043E\u043B\u0430 \u0437\u0434\u0435\u0441\u044C \u043D\u0435\u0442. \u0415\u0441\u043B\u0438 \u043E\u0434\u0438\u043D \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u044B\u0439 \u0443\u0434\u0430\u0440 \u0443\u0431\u0438\u0440\u0430\u0435\u0442 \u0432\u0441\u0435 \u0433\u0440\u0443\u043F\u043F\u044B, \u0440\u0430\u0443\u043D\u0434 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043D\u0438\u0447\u044C\u0435\u0439. \u0413\u0440\u0443\u043F\u043F\u044B \u0432 \u044D\u0442\u043E\u043C \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0435 \u0444\u0438\u043A\u0441\u0438\u0440\u043E\u0432\u0430\u043D\u044B \u0438 \u043D\u0435 \u0440\u0430\u0441\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u044E\u0442\u0441\u044F \u043F\u043E \u0434\u043E\u0433\u043E\u0432\u043E\u0440\u0451\u043D\u043D\u043E\u0441\u0442\u0438. \u0421\u0434\u0430\u0447\u0430 \u0447\u0435\u0440\u0435\u0437 Q \u0443\u0431\u0438\u0440\u0430\u0435\u0442 \u0432\u0441\u0435 \u0448\u0430\u0440\u044B \u0432\u0430\u0448\u0435\u0439 \u0433\u0440\u0443\u043F\u043F\u044B \u0438 \u0437\u0430\u043F\u0440\u0435\u0449\u0430\u0435\u0442 \u0438\u0445 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435 \u0434\u043E \u043A\u043E\u043D\u0446\u0430 \u043F\u0430\u0440\u0442\u0438\u0438; \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0438\u0433\u0440\u043E\u043A\u0438 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u044E\u0442."),
            rule_section(:blackball, "\u0411\u043B\u044D\u043A\u0431\u043E\u043B",
              "\u0418\u0433\u0440\u0430\u0439\u0442\u0435 \u0441\u0432\u043E\u044E \u0433\u0440\u0443\u043F\u043F\u0443 \u0441\u043F\u043B\u043E\u0448\u043D\u044B\u0445 \u0438\u043B\u0438 \u043F\u043E\u043B\u043E\u0441\u0430\u0442\u044B\u0445 \u0448\u0430\u0440\u043E\u0432, \u0437\u0430\u0442\u0435\u043C \u0447\u0451\u0440\u043D\u044B\u0439. \u0417\u0430\u043A\u0430\u0437\u044B\u0432\u0430\u0442\u044C \u043B\u0443\u0437\u044B \u043D\u0435 \u043D\u0443\u0436\u043D\u043E. \u041F\u043E\u0441\u043B\u0435 \u0440\u0430\u0437\u0431\u0438\u0442\u0438\u044F \u0438 \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u044B\u0445 \u0443\u0434\u0430\u0440\u043E\u0432 \u0441\u0442\u043E\u043B \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u043C; \u0433\u0440\u0443\u043F\u043F\u044B \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u044E\u0442\u0441\u044F \u0431\u043E\u043B\u0435\u0435 \u043F\u043E\u0437\u0434\u043D\u0438\u043C \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u044B\u043C \u043E\u0431\u044B\u0447\u043D\u044B\u043C \u0437\u0430\u0431\u0438\u0442\u0438\u0435\u043C. \u041F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u0435 \u0437\u0430\u0431\u0438\u0442\u0438\u0435 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u043F\u043E\u0434\u0445\u043E\u0434. \u041E\u0434\u043D\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u043E\u0435 \u0437\u0430\u0431\u0438\u0442\u0438\u0435 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0433\u043E \u0441\u0432\u043E\u0435\u0433\u043E \u0448\u0430\u0440\u0430 \u0438 \u0447\u0451\u0440\u043D\u043E\u0433\u043E \u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u043F\u043E\u0431\u0435\u0434\u043E\u0439; \u0437\u0430\u0431\u0438\u0442\u0438\u0435 \u0447\u0451\u0440\u043D\u043E\u0433\u043E \u0441 \u0444\u043E\u043B\u043E\u043C \u0438\u043B\u0438 \u0434\u043E \u0443\u0434\u0430\u043B\u0435\u043D\u0438\u044F \u0441\u0432\u043E\u0435\u0439 \u0433\u0440\u0443\u043F\u043F\u044B \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u043F\u043E\u0440\u0430\u0436\u0435\u043D\u0438\u0435. \u0427\u0451\u0440\u043D\u044B\u0439 \u043D\u0430 \u0440\u0430\u0437\u0431\u0438\u0442\u0438\u0438 \u0432\u043C\u0435\u0441\u0442\u043E \u044D\u0442\u043E\u0433\u043E \u0432\u044B\u0437\u044B\u0432\u0430\u0435\u0442 \u043D\u043E\u0432\u0443\u044E \u0440\u0430\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0443 \u0434\u043B\u044F \u0442\u043E\u0433\u043E \u0436\u0435 \u0440\u0430\u0437\u0431\u0438\u0432\u0430\u044E\u0449\u0435\u0433\u043E.",
              "\u041F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u0435 \u0440\u0430\u0437\u0431\u0438\u0442\u0438\u0435 \u0437\u0430\u0431\u0438\u0432\u0430\u0435\u0442 \u0448\u0430\u0440 \u043B\u0438\u0431\u043E \u043F\u0440\u043E\u0432\u043E\u0434\u0438\u0442 \u043C\u0438\u043D\u0438\u043C\u0443\u043C \u0434\u0432\u0430 \u0440\u0430\u0437\u043D\u044B\u0445 \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u0445 \u0448\u0430\u0440\u0430 \u0447\u0435\u0440\u0435\u0437 \u0446\u0435\u043D\u0442\u0440\u0430\u043B\u044C\u043D\u0443\u044E \u043B\u0438\u043D\u0438\u044E. \u0424\u043E\u043B \u0434\u0430\u0451\u0442 \u043E\u0434\u0438\u043D \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u044B\u0439 \u0443\u0434\u0430\u0440, \u043F\u043E\u0441\u043B\u0435 \u043D\u0435\u0433\u043E \u043E\u0434\u0438\u043D \u043E\u0431\u044B\u0447\u043D\u044B\u0439. \u0421\u0432\u043E\u0431\u043E\u0434\u043D\u044B\u0439 \u043C\u043E\u0436\u043D\u043E \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u0441 \u043C\u0435\u0441\u0442\u0430 \u043B\u0438\u0431\u043E \u0447\u0435\u0440\u0435\u0437 M \u043F\u0435\u0440\u0435\u043D\u0435\u0441\u0442\u0438 \u0431\u0438\u0442\u043E\u043A \u0432 \u0431\u0430\u0443\u043B\u043A \u2014 \u043B\u0435\u0432\u0443\u044E \u043F\u044F\u0442\u0443\u044E \u0447\u0430\u0441\u0442\u044C \u0441\u0442\u043E\u043B\u0430. \u0421\u0432\u043E\u0431\u043E\u0434\u043D\u044B\u0439 \u0443\u0434\u0430\u0440 \u043E\u0442\u043C\u0435\u043D\u044F\u0435\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u0442\u0440\u0435\u0431\u043E\u0432\u0430\u043D\u0438\u0435 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u0433\u043E \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0448\u0430\u0440\u0430: \u0437\u0430\u0431\u0438\u0442\u0438\u0435 \u0438\u0441\u043A\u043B\u044E\u0447\u0438\u0442\u0435\u043B\u044C\u043D\u043E \u0448\u0430\u0440\u043E\u0432 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0444\u043E\u043B\u043E\u043C. \u041F\u043E\u0441\u043B\u0435 \u043E\u0431\u044B\u0447\u043D\u043E\u0433\u043E \u0443\u0434\u0430\u0440\u0430 \u0434\u043B\u044F \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0435\u043D\u0438\u044F \u0441\u043D\u043E\u0432\u0430 \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044F \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u0435 \u0437\u0430\u0431\u0438\u0442\u0438\u0435. \u041F\u0440\u0438 \u043F\u043E\u043B\u043D\u043E\u043C \u0441\u043D\u0443\u043A\u0435\u0440\u0435 \u0431\u0435\u0437 \u043F\u0443\u0442\u0438 \u043A \u043B\u044E\u0431\u043E\u0439 \u0447\u0430\u0441\u0442\u0438 \u0440\u0430\u0437\u0440\u0435\u0448\u0451\u043D\u043D\u043E\u0433\u043E \u0448\u0430\u0440\u0430 \u0442\u0440\u0435\u0431\u043E\u0432\u0430\u043D\u0438\u0435 \u0431\u043E\u0440\u0442\u0430 \u0441\u043D\u0438\u043C\u0430\u0435\u0442\u0441\u044F. \u041E\u0442 \u0441\u043E\u043F\u0440\u0438\u043A\u0430\u0441\u0430\u044E\u0449\u0435\u0433\u043E\u0441\u044F \u0440\u0430\u0437\u0440\u0435\u0448\u0451\u043D\u043D\u043E\u0433\u043E \u0448\u0430\u0440\u0430 \u043D\u0443\u0436\u043D\u043E \u0438\u0433\u0440\u0430\u0442\u044C \u0432 \u0441\u0442\u043E\u0440\u043E\u043D\u0443, \u043D\u0435 \u043F\u0440\u043E\u043F\u0438\u0445\u0438\u0432\u0430\u044F \u0435\u0433\u043E."),
            rule_section(:snooker, "\u0421\u043D\u0443\u043A\u0435\u0440",
              "\u0415\u0441\u0442\u044C \u043F\u044F\u0442\u043D\u0430\u0434\u0446\u0430\u0442\u044C \u043A\u0440\u0430\u0441\u043D\u044B\u0445 \u043F\u043E \u043E\u0434\u043D\u043E\u043C\u0443 \u043E\u0447\u043A\u0443, \u0436\u0451\u043B\u0442\u044B\u0439 \u0437\u0430 2, \u0437\u0435\u043B\u0451\u043D\u044B\u0439 \u0437\u0430 3, \u043A\u043E\u0440\u0438\u0447\u043D\u0435\u0432\u044B\u0439 \u0437\u0430 4, \u0441\u0438\u043D\u0438\u0439 \u0437\u0430 5, \u0440\u043E\u0437\u043E\u0432\u044B\u0439 \u0437\u0430 6 \u0438 \u0447\u0451\u0440\u043D\u044B\u0439 \u0437\u0430 7. \u041A\u0440\u0430\u0441\u043D\u044B\u0435 \u0438\u043C\u0435\u044E\u0442 \u043D\u043E\u043C\u0435\u0440\u0430 1\u201315, \u0446\u0432\u0435\u0442\u043D\u044B\u0435 \u2014 16\u201321 \u0432 \u044D\u0442\u043E\u043C \u043F\u043E\u0440\u044F\u0434\u043A\u0435. \u0417\u0430\u0431\u0435\u0439\u0442\u0435 \u043A\u0440\u0430\u0441\u043D\u044B\u0439, \u043D\u0430\u0437\u043E\u0432\u0438\u0442\u0435 \u0446\u0432\u0435\u0442 \u0447\u0435\u0440\u0435\u0437 P \u0438\u043B\u0438 \u043F\u043E \u0437\u0430\u043F\u0440\u043E\u0441\u0443 Enter, \u0437\u0430\u0442\u0435\u043C \u0447\u0435\u0440\u0435\u0434\u0443\u0439\u0442\u0435 \u043A\u0440\u0430\u0441\u043D\u044B\u0439 \u0438 \u0446\u0432\u0435\u0442\u043D\u043E\u0439. \u041D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u043A\u0440\u0430\u0441\u043D\u044B\u0445 \u043C\u043E\u0433\u0443\u0442 \u043F\u0440\u0438\u043D\u0435\u0441\u0442\u0438 \u043E\u0447\u043A\u0438 \u0432 \u043E\u0434\u043D\u043E\u043C \u0443\u0434\u0430\u0440\u0435. \u0426\u0432\u0435\u0442\u043D\u044B\u0435 \u043D\u0430 \u044D\u0442\u043E\u043C \u044D\u0442\u0430\u043F\u0435 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u044E\u0442\u0441\u044F \u043D\u0430 \u0442\u043E\u0447\u043A\u0438, \u0432 \u0442\u043E\u043C \u0447\u0438\u0441\u043B\u0435 \u043F\u043E\u0441\u043B\u0435 \u0444\u043E\u043B\u0430; \u043A\u0440\u0430\u0441\u043D\u044B\u0435 \u043E\u0431\u044B\u0447\u043D\u043E \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u0437\u0430\u0431\u0438\u0442\u044B\u043C\u0438. \u041F\u043E\u0441\u043B\u0435 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0433\u043E \u043A\u0440\u0430\u0441\u043D\u043E\u0433\u043E \u0440\u0430\u0437\u0440\u0435\u0448\u0451\u043D \u0435\u0449\u0451 \u043E\u0434\u0438\u043D \u0446\u0432\u0435\u0442\u043D\u043E\u0439, \u0437\u0430\u0442\u0435\u043C \u0448\u0430\u0440\u044B \u0443\u0431\u0438\u0440\u0430\u044E\u0442 \u043E\u0442 \u0436\u0451\u043B\u0442\u043E\u0433\u043E \u0434\u043E \u0447\u0451\u0440\u043D\u043E\u0433\u043E \u043F\u043E \u043F\u043E\u0440\u044F\u0434\u043A\u0443 \u0431\u0435\u0437 \u0432\u043E\u0437\u0432\u0440\u0430\u0442\u0430 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E \u0437\u0430\u0431\u0438\u0442\u044B\u0445.",
              "\u0424\u043E\u043B \u0434\u0430\u0451\u0442 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0443 \u043E\u0442 4 \u0434\u043E 7 \u043E\u0447\u043A\u043E\u0432 \u043F\u043E \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0435\u0439 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0435\u0439 \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u0438 \u0448\u0430\u0440\u0430 \u043D\u0430 \u0438\u0433\u0440\u0435 \u0438 \u043D\u0435\u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E \u0437\u0430\u0434\u0435\u0442\u044B\u0445 \u0438\u043B\u0438 \u0437\u0430\u0431\u0438\u0442\u044B\u0445 \u0448\u0430\u0440\u043E\u0432. \u041D\u0430\u0440\u0443\u0448\u0438\u0442\u0435\u043B\u044C \u0437\u0430 \u044D\u0442\u043E\u0442 \u0443\u0434\u0430\u0440 \u043D\u0435 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043E\u0447\u043A\u043E\u0432. \u0421\u043E\u043F\u0435\u0440\u043D\u0438\u043A \u0438\u0433\u0440\u0430\u0435\u0442 \u0441\u0430\u043C \u043B\u0438\u0431\u043E \u043F\u0440\u043E\u0441\u0438\u0442 \u043D\u0430\u0440\u0443\u0448\u0438\u0442\u0435\u043B\u044F \u043F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u044C. \u041F\u043E\u0441\u043B\u0435 \u0437\u0430\u0431\u0438\u0442\u0438\u044F \u0431\u0438\u0442\u043E\u043A \u0432\u044B\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u0432 D; M \u043F\u0435\u0440\u0435\u043C\u0435\u0449\u0430\u0435\u0442 \u043B\u0438\u0448\u044C \u0431\u0435\u043B\u044B\u0439, \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044F \u043A\u043E\u043D\u0435\u0447\u043D\u044B\u0435 \u043F\u043E\u0437\u0438\u0446\u0438\u0438 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445. \u0417\u0430\u043D\u044F\u0442\u0443\u044E \u0442\u043E\u0447\u043A\u0443 \u0446\u0432\u0435\u0442\u043D\u043E\u0433\u043E \u0437\u0430\u043C\u0435\u043D\u044F\u0435\u0442 \u0441\u0442\u0430\u0440\u0448\u0430\u044F \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u0430\u044F, \u0437\u0430\u0442\u0435\u043C \u0431\u043B\u0438\u0436\u0430\u0439\u0448\u0435\u0435 \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u043E\u0435 \u043C\u0435\u0441\u0442\u043E \u043A \u0447\u0451\u0440\u043D\u043E\u043C\u0443 \u043A\u043E\u043D\u0446\u0443; \u0434\u043B\u044F \u0440\u043E\u0437\u043E\u0432\u043E\u0433\u043E \u0438 \u0447\u0451\u0440\u043D\u043E\u0433\u043E \u043F\u0440\u0438 \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u043E\u0441\u0442\u0438 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u043E \u043F\u0440\u043E\u0442\u0438\u0432\u043E\u043F\u043E\u043B\u043E\u0436\u043D\u043E\u0435 \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435.",
              "\u041F\u043E\u0441\u043B\u0435 \u0444\u043E\u043B\u0430 \u0441\u043D\u0443\u043A\u0435\u0440 \u043D\u0430 \u0432\u0441\u0435\u0445 \u0448\u0430\u0440\u0430\u0445 \u043D\u0430 \u0438\u0433\u0440\u0435 \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u0435\u0442 \u043D\u0430\u0437\u043D\u0430\u0447\u0438\u0442\u044C \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u044B\u0439 \u0448\u0430\u0440 \u0447\u0435\u0440\u0435\u0437 P. \u0414\u043B\u044F \u043E\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u044F \u0441\u043D\u0443\u043A\u0435\u0440\u0430 \u0434\u043E\u043B\u0436\u043D\u044B \u0431\u044B\u0442\u044C \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B \u043E\u0431\u0430 \u043A\u0440\u0430\u0439\u043D\u0438\u0445 \u043A\u0440\u0430\u044F \u0445\u043E\u0442\u044F \u0431\u044B \u043E\u0434\u043D\u043E\u0433\u043E \u0448\u0430\u0440\u0430 \u043D\u0430 \u0438\u0433\u0440\u0435; \u0431\u043E\u0440\u0442 \u043D\u0435 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044F \u043F\u0440\u0435\u0433\u0440\u0430\u0434\u043E\u0439-\u0448\u0430\u0440\u043E\u043C. \u041F\u0440\u0438 \u0431\u0438\u0442\u043A\u0435 \u0441 \u0440\u0443\u043A\u0438 \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u0435\u0442\u0441\u044F \u0432\u0441\u044F D \u0441 \u0442\u043E\u0447\u043D\u043E\u0441\u0442\u044C\u044E \u0437\u0430\u043F\u0438\u0441\u0438 \u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u044F. \u0421\u0432\u043E\u0431\u043E\u0434\u043D\u044B\u0439 \u0448\u0430\u0440 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u0448\u0430\u0440\u0430 \u043D\u0430 \u0438\u0433\u0440\u0435 \u0438 \u043F\u043E\u0441\u043B\u0435 \u0437\u0430\u0431\u0438\u0442\u0438\u044F \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044F \u043D\u0430 \u0442\u043E\u0447\u043A\u0443. \u041F\u0440\u0438 \u0443\u0434\u0430\u0440\u0435 \u0431\u0435\u0437 \u043E\u0447\u043A\u043E\u0432 \u043E\u043D \u043D\u0435 \u043C\u043E\u0436\u0435\u0442 \u0441\u0430\u043C \u043E\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u0441\u043D\u0443\u043A\u0435\u0440, \u043A\u0440\u043E\u043C\u0435 \u0438\u0441\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u044F \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0445 \u0434\u0432\u0443\u0445 \u0448\u0430\u0440\u043E\u0432.",
              "\u0415\u0441\u043B\u0438 \u043F\u0440\u044F\u043C\u0430\u044F \u0442\u0440\u0430\u0435\u043A\u0442\u043E\u0440\u0438\u044F \u0431\u044B\u043B\u0430 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u0430, \u043D\u043E \u043D\u0443\u0436\u043D\u043E\u0433\u043E \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u043A\u0430\u0441\u0430\u043D\u0438\u044F \u043D\u0435 \u043F\u0440\u043E\u0438\u0437\u043E\u0448\u043B\u043E, \u0441\u0443\u0434\u044C\u044F \u043C\u043E\u0436\u0435\u0442 \u043E\u0431\u044A\u044F\u0432\u0438\u0442\u044C Foul and a Miss. \u0421\u043E\u043F\u0435\u0440\u043D\u0438\u043A \u043C\u043E\u0436\u0435\u0442 \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u043F\u0440\u0435\u0436\u043D\u044E\u044E \u043F\u043E\u0437\u0438\u0446\u0438\u044E \u0438 \u043F\u043E\u0442\u0440\u0435\u0431\u043E\u0432\u0430\u0442\u044C \u043F\u043E\u0432\u0442\u043E\u0440; \u0448\u0442\u0440\u0430\u0444\u043D\u044B\u0435 \u043E\u0447\u043A\u0438 \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F. \u041F\u043E\u0441\u043B\u0435 \u0434\u0432\u0443\u0445 \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u044B\u0445 \u043F\u0440\u043E\u043C\u0430\u0445\u043E\u0432 \u0441 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u043C \u043F\u043E\u043B\u043D\u044B\u043C \u0448\u0430\u0440\u043E\u043C \u0437\u0432\u0443\u0447\u0438\u0442 \u043F\u0440\u0435\u0434\u0443\u043F\u0440\u0435\u0436\u0434\u0435\u043D\u0438\u0435, \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u043F\u0440\u043E\u043C\u0430\u0445 \u043F\u0440\u043E\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442 \u0444\u0440\u0435\u0439\u043C. \u041E\u0431\u044B\u0447\u043D\u044B\u0439 Miss \u043D\u0435 \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F, \u0435\u0441\u043B\u0438 \u043E\u0447\u043A\u0438 \u043E\u0442 \u0444\u043E\u043B\u043E\u0432 \u0443\u0436\u0435 \u043D\u0443\u0436\u043D\u044B \u0438\u043B\u0438 \u0441\u0442\u0430\u043D\u043E\u0432\u044F\u0442\u0441\u044F \u043D\u0443\u0436\u043D\u044B \u043F\u043E\u0441\u043B\u0435 \u0443\u0434\u0430\u0440\u0430. \u041A\u043E\u0433\u0434\u0430 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0447\u0451\u0440\u043D\u044B\u0439, \u043F\u0435\u0440\u0432\u043E\u0435 \u0437\u0430\u0431\u0438\u0442\u0438\u0435 \u0438\u043B\u0438 \u0444\u043E\u043B \u0440\u0435\u0448\u0430\u0435\u0442 \u0444\u0440\u0435\u0439\u043C. \u041F\u0440\u0438 \u0440\u0430\u0432\u0435\u043D\u0441\u0442\u0432\u0435 \u0447\u0451\u0440\u043D\u044B\u0439 \u0432\u044B\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442\u0441\u044F, \u0436\u0440\u0435\u0431\u0438\u0439 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442 \u043F\u0440\u0430\u0432\u043E \u0432\u044B\u0431\u043E\u0440\u0430 \u0438\u0433\u0440\u043E\u043A\u0430, \u0431\u0438\u0442\u043E\u043A \u0434\u0430\u0451\u0442\u0441\u044F \u0441 \u0440\u0443\u043A\u0438 \u0432 D; \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0435 \u0437\u0430\u0431\u0438\u0442\u0438\u0435 \u0438\u043B\u0438 \u0444\u043E\u043B \u0440\u0435\u0448\u0430\u0435\u0442 \u0438\u0441\u0445\u043E\u0434."),
            rule_section(:english, "\u0410\u043D\u0433\u043B\u0438\u0439\u0441\u043A\u0438\u0439 \u0431\u0438\u043B\u044C\u044F\u0440\u0434",
              "\u0423 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430 \u0441\u0432\u043E\u0439 \u0431\u0435\u043B\u044B\u0439 \u0438\u043B\u0438 \u0436\u0451\u043B\u0442\u044B\u0439 \u0431\u0438\u0442\u043E\u043A; \u043A\u0440\u0430\u0441\u043D\u044B\u0439 \u0448\u0430\u0440 \u043E\u0431\u0449\u0438\u0439. \u0412 \u043D\u0430\u0447\u0430\u043B\u0435 \u043A\u0440\u0430\u0441\u043D\u044B\u0439 \u0441\u0442\u043E\u0438\u0442 \u043D\u0430 \u0442\u043E\u0447\u043A\u0435, \u0430 \u043F\u0435\u0440\u0432\u044B\u0439 \u0438\u0433\u0440\u043E\u043A \u0438\u0433\u0440\u0430\u0435\u0442 \u0441\u0432\u043E\u0438\u043C \u0431\u0438\u0442\u043A\u043E\u043C \u0438\u0437 D. \u0428\u0430\u0440 \u0432\u0442\u043E\u0440\u043E\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430 \u043F\u0435\u0440\u0432\u043E\u043D\u0430\u0447\u0430\u043B\u044C\u043D\u043E \u0432\u043D\u0435 \u0441\u0442\u043E\u043B\u0430 \u0438 \u0432\u0432\u043E\u0434\u0438\u0442\u0441\u044F, \u043A\u043E\u0433\u0434\u0430 \u043F\u043E\u043D\u0430\u0434\u043E\u0431\u0438\u0442\u0441\u044F \u044D\u0442\u043E\u043C\u0443 \u0438\u0433\u0440\u043E\u043A\u0443. \u041F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u0442\u043E\u0442, \u043A\u0442\u043E \u043D\u0430\u0431\u0440\u0430\u043B \u0437\u0430\u0434\u0430\u043D\u043D\u043E\u0435 \u0447\u0438\u0441\u043B\u043E \u043E\u0447\u043A\u043E\u0432 \u0438\u043B\u0438 \u043B\u0438\u0434\u0438\u0440\u0443\u0435\u0442 \u043F\u043E \u0438\u0441\u0442\u0435\u0447\u0435\u043D\u0438\u0438 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0433\u043E \u0432\u0440\u0435\u043C\u0435\u043D\u0438. \u0420\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0438\u0432\u043D\u044B\u0439 \u0443\u0434\u0430\u0440 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u043F\u043E\u0434\u0445\u043E\u0434.",
              "\u041E\u0434\u0438\u043D \u0443\u0434\u0430\u0440 \u043C\u043E\u0436\u0435\u0442 \u043F\u0440\u0438\u043D\u0435\u0441\u0442\u0438 \u043E\u0447\u043A\u0438 \u0441\u0440\u0430\u0437\u0443 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u0438\u043C\u0438 \u0441\u043F\u043E\u0441\u043E\u0431\u0430\u043C\u0438:",
              "- \u041A\u0430\u0440\u0430\u043C\u0431\u043E\u043B\u044C, \u0438\u043B\u0438 cannon, \u2014 \u043A\u0430\u0441\u0430\u043D\u0438\u0435 \u0441\u0432\u043E\u0438\u043C \u0431\u0438\u0442\u043A\u043E\u043C \u043E\u0431\u043E\u0438\u0445 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445 \u0448\u0430\u0440\u043E\u0432. \u0414\u0430\u0451\u0442 2 \u043E\u0447\u043A\u0430, \u043D\u0435 \u0431\u043E\u043B\u0435\u0435 \u043E\u0434\u043D\u043E\u0433\u043E \u0440\u0430\u0437\u0430 \u0437\u0430 \u0443\u0434\u0430\u0440.",
              "- \u0417\u0430\u0431\u0438\u0442\u0438\u0435 \u043A\u0440\u0430\u0441\u043D\u043E\u0433\u043E \u0434\u0430\u0451\u0442 3 \u043E\u0447\u043A\u0430, \u0448\u0430\u0440\u0430 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u2014 2.",
              "- \u041F\u0430\u0434\u0435\u043D\u0438\u0435 \u0441\u0432\u043E\u0435\u0433\u043E \u0431\u0438\u0442\u043A\u0430 \u043F\u043E\u0441\u043B\u0435 \u043A\u0440\u0430\u0441\u043D\u043E\u0433\u043E \u0434\u0430\u0451\u0442 3 \u043E\u0447\u043A\u0430, \u043F\u043E\u0441\u043B\u0435 \u0448\u0430\u0440\u0430 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u2014 2. \u0415\u0441\u043B\u0438 \u0437\u0430\u0434\u0435\u0442\u044B \u043E\u0431\u0430, \u0440\u0435\u0448\u0430\u0435\u0442 \u043F\u0435\u0440\u0432\u044B\u0439 \u043A\u043E\u043D\u0442\u0430\u043A\u0442; \u043D\u0435\u0440\u0430\u0437\u043B\u0438\u0447\u0438\u043C\u044B\u0439 \u043E\u0434\u043D\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u044B\u0439 \u043F\u0435\u0440\u0432\u044B\u0439 \u043A\u043E\u043D\u0442\u0430\u043A\u0442 \u0434\u0430\u0451\u0442 2.",
              "\u041F\u043E\u0441\u043B\u0435 \u043F\u0430\u0434\u0435\u043D\u0438\u044F \u0441\u0432\u043E\u0435\u0433\u043E \u0431\u0438\u0442\u043A\u0430 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0435 \u0435\u0433\u043E \u0432 D \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 M. \u0418\u0437 D \u043D\u0443\u0436\u043D\u043E \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u0437\u0430 \u043F\u0440\u0435\u0434\u0435\u043B\u044B \u0431\u0430\u0443\u043B\u043A\u0430 \u0434\u043E \u043F\u0440\u044F\u043C\u043E\u0433\u043E \u043A\u043E\u043D\u0442\u0430\u043A\u0442\u0430 \u0441 \u0448\u0430\u0440\u043E\u043C, \u0446\u0435\u043D\u0442\u0440 \u043A\u043E\u0442\u043E\u0440\u043E\u0433\u043E \u0432 \u0431\u0430\u0443\u043B\u043A\u0435, \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u043B\u0438\u043D\u0438\u044E. \u041F\u0435\u0440\u0435\u0434 \u0432\u043E\u0437\u0432\u0440\u0430\u0442\u043E\u043C \u0432 \u0431\u0430\u0443\u043B\u043A \u043D\u0443\u0436\u043D\u043E \u043A\u043E\u0441\u043D\u0443\u0442\u044C\u0441\u044F \u0431\u043E\u0440\u0442\u0430 \u0438\u043B\u0438 \u0448\u0430\u0440\u0430 \u0432\u043D\u0435 \u043D\u0435\u0433\u043E. \u041F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u044B\u0439 English Miss, \u043A\u043E\u0433\u0434\u0430 \u0432\u0441\u0435 \u0446\u0435\u043B\u0438 \u0432 \u0431\u0430\u0443\u043B\u043A\u0435, \u0434\u0430\u0451\u0442 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0443 2 \u043E\u0447\u043A\u0430 \u0438 \u0438\u0433\u0440\u0443 \u0438\u0437 \u043E\u0441\u0442\u0430\u0432\u0448\u0435\u0439\u0441\u044F \u043F\u043E\u0437\u0438\u0446\u0438\u0438. \u0424\u043E\u043B \u0442\u0430\u043A\u0436\u0435 \u0434\u0430\u0451\u0442 2 \u043E\u0447\u043A\u0430, \u043E\u0442\u043C\u0435\u043D\u044F\u0435\u0442 \u043D\u0430\u0431\u0440\u0430\u043D\u043D\u043E\u0435 \u044D\u0442\u0438\u043C \u0443\u0434\u0430\u0440\u043E\u043C \u0438 \u0447\u0435\u0440\u0435\u0437 P \u043F\u0440\u0435\u0434\u043B\u0430\u0433\u0430\u0435\u0442 \u043E\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u043F\u043E\u0437\u0438\u0446\u0438\u044E \u043B\u0438\u0431\u043E \u0432\u044B\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u043A\u0440\u0430\u0441\u043D\u044B\u0439 \u0438 \u0448\u0430\u0440 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u0438 \u0438\u0433\u0440\u0430\u0442\u044C \u0438\u0437 D.",
              "\u041A\u0440\u0430\u0441\u043D\u044B\u0439 \u043F\u043E\u0441\u043B\u0435 \u0437\u0430\u0431\u0438\u0442\u0438\u044F \u0432\u044B\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u043D\u0430 \u0442\u043E\u0447\u043A\u0443. \u041F\u0440\u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u043C \u0437\u0430\u0431\u0438\u0442\u0438\u0438 \u0442\u043E\u043B\u044C\u043A\u043E \u043A\u0440\u0430\u0441\u043D\u043E\u0433\u043E \u0441 \u0442\u043E\u0447\u043A\u0438 \u0434\u0432\u0430 \u0440\u0430\u0437\u0430 \u0438\u0433\u0440\u0430\u044E\u0442 \u0441 \u043E\u0431\u044B\u0447\u043D\u043E\u0439 \u0442\u043E\u0447\u043A\u0438, \u0437\u0430\u0442\u0435\u043C \u043E\u0434\u0438\u043D \u0440\u0430\u0437 \u0438\u0437 \u0446\u0435\u043D\u0442\u0440\u0430; \u0434\u043B\u044F \u0437\u0430\u043D\u044F\u0442\u044B\u0445 \u0442\u043E\u0447\u0435\u043A \u043F\u0440\u0435\u0434\u0443\u0441\u043C\u043E\u0442\u0440\u0435\u043D\u044B \u0437\u0430\u043F\u0430\u0441\u043D\u044B\u0435. \u0417\u0430\u0431\u0438\u0442\u044B\u0439 \u0448\u0430\u0440 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u043E\u0431\u044B\u0447\u043D\u043E \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0432\u043D\u0435 \u0441\u0442\u043E\u043B\u0430, \u043F\u043E\u043A\u0430 \u043D\u0435 \u043F\u043E\u043D\u0430\u0434\u043E\u0431\u0438\u0442\u0441\u044F. \u041F\u0440\u0438 \u043A\u0430\u0441\u0430\u043D\u0438\u0438 \u0431\u0438\u0442\u043A\u0430 \u0441 \u0434\u0440\u0443\u0433\u0438\u043C \u0448\u0430\u0440\u043E\u043C \u043A\u0440\u0430\u0441\u043D\u044B\u0439 \u0432\u044B\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u043D\u0430 \u0441\u0432\u043E\u044E \u0442\u043E\u0447\u043A\u0443, \u043F\u0440\u0438\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0439 \u0448\u0430\u0440 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u2014 \u0432 \u0446\u0435\u043D\u0442\u0440, \u0441\u0432\u043E\u0439 \u0431\u0438\u0442\u043E\u043A \u0438\u0433\u0440\u0430\u0435\u0442\u0441\u044F \u0441 \u0440\u0443\u043A\u0438 \u0438\u0437 D.",
              "\u0417\u0430 \u043F\u043E\u0434\u0445\u043E\u0434 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u043E \u043D\u0435 \u0431\u043E\u043B\u0435\u0435 75 \u0447\u0438\u0441\u0442\u044B\u0445 \u043A\u0430\u0440\u0430\u043C\u0431\u043E\u043B\u0435\u0439 \u043F\u043E\u0434\u0440\u044F\u0434 \u0438\u043B\u0438 15 \u0443\u0434\u0430\u0440\u043E\u0432 hazard \u0431\u0435\u0437 \u043A\u0430\u0440\u0430\u043C\u0431\u043E\u043B\u044F; hazard \u2014 \u0437\u0430\u0431\u0438\u0442\u0438\u0435 \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u0448\u0430\u0440\u0430 \u043B\u0438\u0431\u043E \u0441\u0432\u043E\u0435\u0433\u043E \u0431\u0438\u0442\u043A\u0430 \u043F\u043E\u0441\u043B\u0435 \u043A\u043E\u043D\u0442\u0430\u043A\u0442\u0430. \u041F\u0440\u0435\u0434\u0443\u043F\u0440\u0435\u0436\u0434\u0435\u043D\u0438\u044F \u0434\u0430\u044E\u0442\u0441\u044F \u043F\u043E\u0441\u043B\u0435 70 \u0438 10. \u0421\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0435 \u043A\u0430\u0440\u0430\u043C\u0431\u043E\u043B\u044F \u0441 hazard \u043F\u0440\u0435\u0440\u044B\u0432\u0430\u0435\u0442 \u043E\u0431\u0435 \u0441\u0435\u0440\u0438\u0438. \u041F\u043E\u0441\u043B\u0435 \u043F\u044F\u0442\u043D\u0430\u0434\u0446\u0430\u0442\u043E\u0433\u043E hazard \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u043E\u0441\u043E\u0431\u043E\u0435 \u0432\u044B\u0441\u0442\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u0448\u0430\u0440\u0430 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430, \u0435\u0441\u043B\u0438 \u043E\u043D \u043E\u0441\u0442\u0430\u043B\u0441\u044F \u0432\u043D\u0435 \u0441\u0442\u043E\u043B\u0430 \u043F\u043E\u0441\u043B\u0435 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0433\u043E \u043F\u043E\u0434\u0445\u043E\u0434\u0430 \u044D\u0442\u043E\u0433\u043E \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430. \u041F\u0440\u0438 \u0432\u043A\u043B\u044E\u0447\u0451\u043D\u043D\u043E\u043C \u043F\u0435\u0440\u0435\u0441\u0435\u0447\u0435\u043D\u0438\u0438 \u0431\u0430\u0443\u043B\u043A\u0430 \u043D\u0443\u0436\u043D\u043E \u043F\u0435\u0440\u0435\u0441\u0435\u0447\u044C \u043B\u0438\u043D\u0438\u044E \u0432\u043D\u0443\u0442\u0440\u044C \u043C\u0435\u0436\u0434\u0443 80 \u0438 100 \u043E\u0447\u043A\u0430\u043C\u0438 \u043A\u0430\u0436\u0434\u043E\u0439 \u0441\u043E\u0442\u043D\u0438 \u043F\u043E\u0434\u0445\u043E\u0434\u0430; \u043D\u0435\u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u0435 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044F \u0444\u043E\u043B\u043E\u043C."),
            rule_section(:carom, "\u041A\u0430\u0440\u0430\u043C\u0431\u043E\u043B\u044C: \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u044B\u0439, \u043E\u0434\u043D\u043E\u0431\u043E\u0440\u0442\u043D\u044B\u0439 \u0438 \u0442\u0440\u0451\u0445\u0431\u043E\u0440\u0442\u043D\u044B\u0439",
              "\u041D\u0430 \u0441\u0442\u043E\u043B\u0435 \u0431\u0435\u0437 \u043B\u0443\u0437 \u0442\u0440\u0438 \u0448\u0430\u0440\u0430. \u0412\u0441\u044E \u043F\u0430\u0440\u0442\u0438\u044E \u0432\u044B \u0438\u0433\u0440\u0430\u0435\u0442\u0435 \u0441\u0432\u043E\u0438\u043C \u0431\u0435\u043B\u044B\u043C \u0438\u043B\u0438 \u0436\u0451\u043B\u0442\u044B\u043C \u0431\u0438\u0442\u043A\u043E\u043C. \u041A\u0430\u0440\u0430\u043C\u0431\u043E\u043B\u044C \u2014 \u043A\u0430\u0441\u0430\u043D\u0438\u0435 \u0431\u0438\u0442\u043A\u043E\u043C \u043E\u0431\u043E\u0438\u0445 \u0434\u0440\u0443\u0433\u0438\u0445 \u0448\u0430\u0440\u043E\u0432 \u0437\u0430 \u043E\u0434\u0438\u043D \u0443\u0434\u0430\u0440. \u041F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u044B\u0439 \u043A\u0430\u0440\u0430\u043C\u0431\u043E\u043B\u044C \u0434\u0430\u0451\u0442 1 \u043E\u0447\u043A\u043E \u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u043F\u043E\u0434\u0445\u043E\u0434; \u043F\u0440\u043E\u043C\u0430\u0445 \u0438\u043B\u0438 \u0444\u043E\u043B \u043F\u0435\u0440\u0435\u0434\u0430\u0451\u0442 \u0445\u043E\u0434 \u0431\u0435\u0437 \u0432\u044B\u0447\u0438\u0442\u0430\u043D\u0438\u044F \u043E\u0447\u043A\u043E\u0432. \u041F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u0434\u043E\u0441\u0442\u0438\u0436\u0435\u043D\u0438\u0435 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0439 \u0446\u0435\u043B\u0438 \u0441 \u0443\u0447\u0451\u0442\u043E\u043C \u0443\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u044E\u0449\u0435\u0433\u043E \u043F\u043E\u0434\u0445\u043E\u0434\u0430, \u0435\u0441\u043B\u0438 \u043E\u043D \u0432\u043A\u043B\u044E\u0447\u0451\u043D. \u0415\u0441\u043B\u0438 \u0443\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u043D\u0438\u0435 \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u043E \u0438 \u043D\u0430\u0447\u0438\u043D\u0430\u0432\u0448\u0438\u0439 \u0438\u0433\u0440\u043E\u043A \u0434\u043E\u0441\u0442\u0438\u0433\u0430\u0435\u0442 \u0446\u0435\u043B\u0438, \u0438\u043C\u0435\u044F \u043D\u0430 \u043E\u0434\u0438\u043D \u043F\u043E\u0434\u0445\u043E\u0434 \u0431\u043E\u043B\u044C\u0448\u0435, \u0432\u0442\u043E\u0440\u043E\u0439 \u0438\u0433\u0440\u043E\u043A \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u043F\u043E\u0434\u0445\u043E\u0434 \u0438\u0437 \u043D\u0430\u0447\u0430\u043B\u044C\u043D\u043E\u0439 \u043F\u043E\u0437\u0438\u0446\u0438\u0438. \u0414\u043E\u0441\u0442\u0438\u0436\u0435\u043D\u0438\u0435 \u0446\u0435\u043B\u0438 \u0432 \u043D\u0451\u043C \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u043D\u0438\u0447\u044C\u044E \u0432 \u043F\u0430\u0440\u0442\u0438\u0438; \u0435\u0441\u043B\u0438 \u043F\u043E\u0434\u0445\u043E\u0434 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0434\u043E \u0434\u043E\u0441\u0442\u0438\u0436\u0435\u043D\u0438\u044F \u0446\u0435\u043B\u0438, \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442 \u043D\u0430\u0447\u0438\u043D\u0430\u0432\u0448\u0438\u0439. \u041F\u0440\u0438 \u0432\u044B\u043A\u043B\u044E\u0447\u0435\u043D\u043D\u043E\u043C \u0443\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u043D\u0438\u0438 \u0434\u043E\u0441\u0442\u0438\u0436\u0435\u043D\u0438\u0435 \u0446\u0435\u043B\u0438 \u0441\u0440\u0430\u0437\u0443 \u0434\u0430\u0451\u0442 \u043F\u043E\u0431\u0435\u0434\u0443.",
              "\u0412 \u043D\u0430\u0447\u0430\u043B\u0435 \u0447\u0435\u0440\u0435\u0437 P \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043D\u0438\u0436\u043D\u044E\u044E \u0438\u043B\u0438 \u0432\u0435\u0440\u0445\u043D\u044E\u044E \u0441\u0442\u0430\u0440\u0442\u043E\u0432\u0443\u044E \u0442\u043E\u0447\u043A\u0443. \u041F\u0435\u0440\u0432\u044B\u0439 \u0443\u0434\u0430\u0440 \u0434\u043E\u043B\u0436\u0435\u043D \u0438\u0434\u0442\u0438 \u043F\u0440\u044F\u043C\u043E \u043D\u0430 \u043A\u0440\u0430\u0441\u043D\u044B\u0439. \u0414\u0430\u043B\u0435\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0442 \u0440\u0430\u0437\u043B\u0438\u0447\u0438\u044F:",
              "- \u0421\u0432\u043E\u0431\u043E\u0434\u043D\u044B\u0439 \u043A\u0430\u0440\u0430\u043C\u0431\u043E\u043B\u044C \u043D\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043A\u0430\u0441\u0430\u043D\u0438\u0439 \u0431\u043E\u0440\u0442\u043E\u0432. \u041F\u043E\u0432\u0442\u043E\u0440\u043D\u044B\u0435 \u043A\u0430\u0440\u0430\u043C\u0431\u043E\u043B\u0438 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u044B \u0447\u0435\u0442\u044B\u0440\u044C\u043C\u044F \u0440\u0430\u0437\u043C\u0435\u0447\u0435\u043D\u043D\u044B\u043C\u0438 \u0443\u0433\u043B\u043E\u0432\u044B\u043C\u0438 \u0442\u0440\u0435\u0443\u0433\u043E\u043B\u044C\u043D\u0438\u043A\u0430\u043C\u0438.",
              "- \u0412 \u043E\u0434\u043D\u043E\u0431\u043E\u0440\u0442\u043D\u043E\u043C \u043A\u0430\u0440\u0430\u043C\u0431\u043E\u043B\u0435 \u0431\u0438\u0442\u043E\u043A \u0434\u043E\u043B\u0436\u0435\u043D \u0445\u043E\u0442\u044F \u0431\u044B \u0440\u0430\u0437 \u043A\u043E\u0441\u043D\u0443\u0442\u044C\u0441\u044F \u0431\u043E\u0440\u0442\u0430 \u0434\u043E \u0432\u0442\u043E\u0440\u043E\u0433\u043E \u0440\u0430\u0437\u043B\u0438\u0447\u043D\u043E\u0433\u043E \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u0448\u0430\u0440\u0430.",
              "- \u0412 \u0442\u0440\u0451\u0445\u0431\u043E\u0440\u0442\u043D\u043E\u043C \u043D\u0443\u0436\u043D\u044B \u043D\u0435 \u043C\u0435\u043D\u0435\u0435 \u0442\u0440\u0451\u0445 \u0442\u0430\u043A\u0438\u0445 \u043A\u043E\u043D\u0442\u0430\u043A\u0442\u043E\u0432. \u041E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u0435 \u043E\u0442\u0441\u043A\u043E\u043A\u0438 \u043E\u0442 \u043E\u0434\u043D\u043E\u0433\u043E \u0431\u043E\u0440\u0442\u0430 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u044E\u0442\u0441\u044F, \u043A\u0430\u043A \u0438 \u043E\u0442\u0441\u043A\u043E\u043A\u0438 \u0434\u043E \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u0448\u0430\u0440\u0430. \u0411\u043E\u0440\u0442\u044B \u043F\u043E\u0441\u043B\u0435 \u0432\u0442\u043E\u0440\u043E\u0433\u043E \u0448\u0430\u0440\u0430 \u0443\u0436\u0435 \u043D\u0435 \u0438\u0441\u043F\u0440\u0430\u0432\u043B\u044F\u044E\u0442 \u043D\u0435\u0443\u0434\u0430\u0447\u043D\u044B\u0439 \u043A\u0430\u0440\u0430\u043C\u0431\u043E\u043B\u044C.",
              "\u0412 \u0443\u0433\u043B\u0443 \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u043E\u0433\u043E \u043A\u0430\u0440\u0430\u043C\u0431\u043E\u043B\u044F \u043F\u043E\u0441\u043B\u0435 \u0432\u0445\u043E\u0434\u0430 \u043E\u0431\u043E\u0438\u0445 \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u0445 \u0448\u0430\u0440\u043E\u0432 \u043C\u043E\u0436\u043D\u043E \u043E\u0434\u0438\u043D \u0440\u0430\u0437 \u043D\u0430\u0431\u0440\u0430\u0442\u044C \u043E\u0447\u043A\u043E \u0431\u0435\u0437 \u0432\u044B\u0445\u043E\u0434\u0430 \u0448\u0430\u0440\u043E\u0432. \u041F\u0440\u0438 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u043C \u043A\u0430\u0440\u0430\u043C\u0431\u043E\u043B\u0435 \u0445\u043E\u0442\u044F \u0431\u044B \u043E\u0434\u0438\u043D \u0434\u043E\u043B\u0436\u0435\u043D \u043F\u043E\u043A\u0438\u043D\u0443\u0442\u044C \u0442\u0440\u0435\u0443\u0433\u043E\u043B\u044C\u043D\u0438\u043A; \u0432\u0435\u0440\u043D\u0443\u0442\u044C\u0441\u044F \u0432 \u0442\u043E\u043C \u0436\u0435 \u0443\u0434\u0430\u0440\u0435 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u043E. \u0428\u0430\u0440 \u043D\u0430 \u0433\u0440\u0430\u043D\u0438\u0446\u0435 \u043E\u0446\u0435\u043D\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043D\u0435 \u0432 \u043F\u043E\u043B\u044C\u0437\u0443 \u0438\u0433\u0440\u043E\u043A\u0430. \u041F\u0440\u043E\u0432\u0435\u0440\u044F\u0435\u0442\u0441\u044F \u0432\u0435\u0441\u044C \u043F\u0443\u0442\u044C, \u0430 \u043D\u0435 \u0442\u043E\u043B\u044C\u043A\u043E \u043A\u043E\u043D\u0435\u0447\u043D\u044B\u0435 \u043F\u043E\u0437\u0438\u0446\u0438\u0438.",
              "\u041F\u0440\u0438 \u043A\u0430\u0441\u0430\u043D\u0438\u0438 \u0431\u0438\u0442\u043A\u0430 \u0441 \u0434\u0440\u0443\u0433\u0438\u043C \u0448\u0430\u0440\u043E\u043C \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u044B\u0439 \u043A\u0430\u0440\u0430\u043C\u0431\u043E\u043B\u044C \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u0435\u0442 \u043D\u0430\u0447\u0430\u043B\u044C\u043D\u0443\u044E \u043F\u043E\u0437\u0438\u0446\u0438\u044E \u0432\u0441\u0435\u0445 \u0442\u0440\u0451\u0445. \u0412 \u0431\u043E\u0440\u0442\u043E\u0432\u044B\u0445 \u0434\u0438\u0441\u0446\u0438\u043F\u043B\u0438\u043D\u0430\u0445 P \u043F\u0440\u0435\u0434\u043B\u0430\u0433\u0430\u0435\u0442 \u0438\u0433\u0440\u0430\u0442\u044C \u043E\u0442 \u043A\u0430\u0441\u0430\u043D\u0438\u044F \u0431\u0435\u0437 \u043F\u0440\u043E\u043F\u0438\u0445\u0430 \u0441\u043E\u043F\u0440\u0438\u043A\u0430\u0441\u0430\u044E\u0449\u0435\u0433\u043E\u0441\u044F \u0448\u0430\u0440\u0430 \u0438\u043B\u0438 \u0432\u044B\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u0448\u0430\u0440\u044B \u043D\u0430 \u0442\u043E\u0447\u043A\u0438. \u0412 \u043E\u0434\u043D\u043E\u0431\u043E\u0440\u0442\u043D\u043E\u043C \u0432\u044B\u0441\u0442\u0430\u0432\u043B\u044F\u044E\u0442 \u0432\u0441\u0435 \u0442\u0440\u0438, \u0432 \u0442\u0440\u0451\u0445\u0431\u043E\u0440\u0442\u043D\u043E\u043C \u2014 \u0442\u043E\u043B\u044C\u043A\u043E \u0441\u043E\u043F\u0440\u0438\u043A\u0430\u0441\u0430\u044E\u0449\u0438\u0435\u0441\u044F \u043D\u0430 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0435 \u0442\u043E\u0447\u043A\u0438. \u041F\u0440\u044F\u043C\u043E\u0439 \u0443\u0434\u0430\u0440 \u0432 \u0431\u043E\u0440\u0442, \u043A \u043A\u043E\u0442\u043E\u0440\u043E\u043C\u0443 \u043F\u0440\u0438\u0436\u0430\u0442 \u0431\u0438\u0442\u043E\u043A, \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044F \u0444\u043E\u043B\u043E\u043C. \u041F\u0440\u0438 \u0432\u044B\u043B\u0435\u0442\u0435 \u0448\u0430\u0440\u0430 \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u044B\u0439 \u0438 \u043E\u0434\u043D\u043E\u0431\u043E\u0440\u0442\u043D\u044B\u0439 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u044B \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u044E\u0442 \u0432\u0441\u0435 \u0442\u0440\u0438, \u0442\u0440\u0451\u0445\u0431\u043E\u0440\u0442\u043D\u044B\u0439 \u2014 \u0442\u043E\u043B\u044C\u043A\u043E \u0432\u044B\u043B\u0435\u0442\u0435\u0432\u0448\u0438\u0435."),
            rule_section(:pyramid, "\u0421\u0432\u043E\u0431\u043E\u0434\u043D\u0430\u044F \u043F\u0438\u0440\u0430\u043C\u0438\u0434\u0430",
              "\u041D\u0430\u0431\u0435\u0440\u0438\u0442\u0435 8 \u043E\u0447\u043A\u043E\u0432 \u0440\u0430\u043D\u044C\u0448\u0435 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430. \u0412\u0441\u0435 \u0448\u0435\u0441\u0442\u043D\u0430\u0434\u0446\u0430\u0442\u044C \u0448\u0430\u0440\u043E\u0432 \u0440\u0430\u0432\u043D\u043E\u0446\u0435\u043D\u043D\u044B: 1 \u043E\u0447\u043A\u043E \u0437\u0430 \u043A\u0430\u0436\u0434\u044B\u0439 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E \u0437\u0430\u0431\u0438\u0442\u044B\u0439 \u0448\u0430\u0440, \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u0431\u0438\u0442\u043E\u043A \u043F\u043E\u0441\u043B\u0435 \u043A\u043E\u043D\u0442\u0430\u043A\u0442\u0430 \u0441 \u0434\u0440\u0443\u0433\u0438\u043C \u0448\u0430\u0440\u043E\u043C. \u0417\u0430\u043A\u0430\u0437\u044B\u0432\u0430\u0442\u044C \u0448\u0430\u0440 \u0438 \u043B\u0443\u0437\u0443 \u043D\u0435 \u043D\u0443\u0436\u043D\u043E. \u041F\u0435\u0440\u0435\u0434 \u043A\u0430\u0436\u0434\u044B\u043C \u0443\u0434\u0430\u0440\u043E\u043C \u043F\u043E\u0441\u043B\u0435 \u0440\u0430\u0437\u0431\u0438\u0442\u0438\u044F \u043E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u0447\u0435\u0440\u0435\u0437 P \u0432\u044B\u0431\u043E\u0440 \u0431\u0438\u0442\u043A\u0430 \u0438 \u0443\u043A\u0430\u0436\u0438\u0442\u0435 \u043B\u044E\u0431\u043E\u0439 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0439\u0441\u044F \u043D\u0430 \u0441\u0442\u043E\u043B\u0435 \u0448\u0430\u0440. \u041F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u0435 \u0437\u0430\u0431\u0438\u0442\u0438\u0435 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u043F\u043E\u0434\u0445\u043E\u0434 \u0438 \u043F\u0440\u0430\u0432\u043E \u043D\u043E\u0432\u043E\u0433\u043E \u0432\u044B\u0431\u043E\u0440\u0430 \u0431\u0438\u0442\u043A\u0430.",
              "\u0420\u0430\u0437\u0431\u0438\u0442\u0438\u0435 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442\u0441\u044F \u0446\u0432\u0435\u0442\u043D\u044B\u043C \u0448\u0430\u0440\u043E\u043C \u0441 \u0440\u0443\u043A\u0438 \u0438\u0437 \u0434\u043E\u043C\u0430, \u043B\u0435\u0432\u043E\u0439 \u0447\u0435\u0442\u0432\u0435\u0440\u0442\u0438 \u0441\u0442\u043E\u043B\u0430, \u043D\u0435 \u0441 \u043B\u0438\u043D\u0438\u0438 \u0434\u043E\u043C\u0430. \u041F\u043E\u0441\u043B\u0435 \u043A\u043E\u043D\u0442\u0430\u043A\u0442\u0430 \u0441 \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u043C \u0448\u0430\u0440\u043E\u043C \u043D\u0443\u0436\u043D\u043E \u0437\u0430\u0431\u0438\u0442\u044C \u0448\u0430\u0440, \u0434\u043E\u0432\u0435\u0441\u0442\u0438 \u0442\u0440\u0438 \u0440\u0430\u0437\u043D\u044B\u0445 \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u0445 \u0448\u0430\u0440\u0430 \u0434\u043E \u0431\u043E\u0440\u0442\u043E\u0432 \u043B\u0438\u0431\u043E \u0434\u0432\u0430 \u0434\u043E \u0431\u043E\u0440\u0442\u043E\u0432 \u0438 \u043E\u0434\u0438\u043D \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u0439 \u0447\u0435\u0440\u0435\u0437 \u0446\u0435\u043D\u0442\u0440\u0430\u043B\u044C\u043D\u0443\u044E \u043B\u0438\u043D\u0438\u044E.",
              "\u0412 \u043F\u043E\u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0445 \u0443\u0434\u0430\u0440\u0430\u0445 \u043F\u043E\u0441\u043B\u0435 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u043A\u043E\u043D\u0442\u0430\u043A\u0442\u0430 \u0434\u043E\u043B\u0436\u043D\u043E \u043F\u0440\u043E\u0438\u0437\u043E\u0439\u0442\u0438 \u043E\u0434\u043D\u043E \u0438\u0437 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E:",
              "- \u0428\u0430\u0440 \u0437\u0430\u0431\u0438\u0442 \u0432 \u043B\u0443\u0437\u0443.",
              "- \u0428\u0430\u0440 \u043E\u0442\u0440\u0430\u0437\u0438\u043B\u0441\u044F \u043E\u0442 \u0431\u043E\u0440\u0442\u0430 \u0438 \u0434\u043E\u0441\u0442\u0438\u0433 \u0434\u0440\u0443\u0433\u043E\u0433\u043E \u0431\u043E\u0440\u0442\u0430 \u0441\u0430\u043C \u0438\u043B\u0438 \u0434\u043E\u0432\u0451\u043B \u0434\u043E \u043D\u0435\u0433\u043E \u0434\u0440\u0443\u0433\u043E\u0439 \u0448\u0430\u0440. \u0423\u0441\u043B\u043E\u0432\u0438\u0435 \u0442\u0430\u043A\u0436\u0435 \u043C\u043E\u0436\u0435\u0442 \u0432\u044B\u043F\u043E\u043B\u043D\u0438\u0442\u044C \u043A\u0430\u0441\u0430\u043D\u0438\u0435 \u0448\u0430\u0440\u0430, \u0441\u0442\u043E\u044F\u0449\u0435\u0433\u043E \u0432\u043F\u043B\u043E\u0442\u043D\u0443\u044E \u043A \u0442\u043E\u043C\u0443 \u0434\u0440\u0443\u0433\u043E\u043C\u0443 \u0431\u043E\u0440\u0442\u0443.",
              "- \u0428\u0430\u0440 \u043F\u0435\u0440\u0435\u0441\u0451\u043A \u0446\u0435\u043D\u0442\u0440\u0430\u043B\u044C\u043D\u0443\u044E \u043B\u0438\u043D\u0438\u044E \u0438 \u0437\u0430\u0442\u0435\u043C \u0434\u043E\u0441\u0442\u0438\u0433 \u0431\u043E\u0440\u0442\u0430 \u0441\u0430\u043C \u0438\u043B\u0438 \u043F\u0435\u0440\u0435\u0434\u0430\u0432 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435 \u0434\u0440\u0443\u0433\u043E\u043C\u0443 \u0448\u0430\u0440\u0443; \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0438 \u0448\u0430\u0440 \u0432\u043F\u043B\u043E\u0442\u043D\u0443\u044E \u043A \u044D\u0442\u043E\u043C\u0443 \u0431\u043E\u0440\u0442\u0443.",
              "- \u041F\u043E\u0441\u043B\u0435 \u043E\u0442\u0440\u0430\u0436\u0435\u043D\u0438\u044F \u043E\u0442 \u0431\u043E\u0440\u0442\u0430 \u0448\u0430\u0440 \u043F\u0435\u0440\u0435\u0441\u0451\u043A \u0446\u0435\u043D\u0442\u0440, \u043F\u0435\u0440\u0435\u043A\u0430\u0442\u0438\u043B \u0447\u0435\u0440\u0435\u0437 \u043D\u0435\u0433\u043E \u0434\u0440\u0443\u0433\u043E\u0439 \u0448\u0430\u0440 \u043B\u0438\u0431\u043E \u043A\u043E\u0441\u043D\u0443\u043B\u0441\u044F \u0448\u0430\u0440\u0430 \u043D\u0430 \u043F\u0440\u043E\u0442\u0438\u0432\u043E\u043F\u043E\u043B\u043E\u0436\u043D\u043E\u0439 \u043F\u043E\u043B\u043E\u0432\u0438\u043D\u0435 \u0438\u043B\u0438 \u0446\u0435\u043D\u0442\u0440\u0430\u043B\u044C\u043D\u043E\u0439 \u043B\u0438\u043D\u0438\u0438. \u0423\u0447\u0438\u0442\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u0438 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0435 \u043A\u043E\u043D\u0442\u0430\u043A\u0442\u044B, \u043F\u0435\u0440\u0435\u0434\u0430\u043D\u043D\u044B\u0435 \u0447\u0435\u0440\u0435\u0437 \u0434\u0440\u0443\u0433\u0438\u0435 \u0448\u0430\u0440\u044B.",
              "\u041F\u043E\u0441\u043B\u0435 \u043D\u0430\u0440\u0443\u0448\u0435\u043D\u0438\u044F \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u0432\u044B\u0441\u0442\u0430\u0432\u043B\u044F\u044E\u0442 \u043D\u0435\u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E \u0437\u0430\u0431\u0438\u0442\u044B\u0435 \u0438 \u0432\u044B\u0441\u043A\u043E\u0447\u0438\u0432\u0448\u0438\u0435 \u0448\u0430\u0440\u044B. \u0421\u043E\u043F\u0435\u0440\u043D\u0438\u043A \u0447\u0435\u0440\u0435\u0437 P \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442 \u043B\u044E\u0431\u043E\u0439 \u0448\u0430\u0440 \u043D\u0430 \u0441\u0442\u043E\u043B\u0435 \u043A\u0430\u043A \u0448\u0442\u0440\u0430\u0444\u043D\u043E\u0439, \u0441\u043D\u0438\u043C\u0430\u0435\u0442 \u0435\u0433\u043E \u0438 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 1 \u043E\u0447\u043A\u043E. \u0417\u0430\u0442\u0435\u043C \u0438\u0433\u0440\u0430\u0435\u0442 \u0441\u0430\u043C \u0438\u043B\u0438 \u043F\u0435\u0440\u0435\u0434\u0430\u0451\u0442 \u0443\u0434\u0430\u0440. \u041F\u043E\u0441\u043B\u0435 \u043D\u0435\u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u0433\u043E \u0440\u0430\u0437\u0431\u0438\u0442\u0438\u044F \u043C\u043E\u0436\u043D\u043E \u0442\u0430\u043A\u0436\u0435 \u0441\u043E\u0431\u0440\u0430\u0442\u044C \u0448\u0430\u0440\u044B \u0437\u0430\u043D\u043E\u0432\u043E \u0438 \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0440\u0430\u0437\u0431\u0438\u0432\u0430\u044E\u0449\u0435\u0433\u043E; \u0448\u0442\u0440\u0430\u0444\u043D\u043E\u0435 \u043E\u0447\u043A\u043E \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442\u0441\u044F, \u043F\u0438\u0440\u0430\u043C\u0438\u0434\u0430 \u0431\u0443\u0434\u0435\u0442 \u043D\u0435\u043F\u043E\u043B\u043D\u043E\u0439. \u0421\u0430\u043C\u043E \u043F\u043E \u0441\u0435\u0431\u0435 \u043F\u0430\u0434\u0435\u043D\u0438\u0435 \u0431\u0438\u0442\u043A\u0430 \u0437\u0434\u0435\u0441\u044C \u043D\u0435 \u0444\u043E\u043B: \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u0435 \u0437\u0430\u0431\u0438\u0442\u0438\u0435 \u043F\u043E\u0441\u043B\u0435 \u043A\u043E\u043D\u0442\u0430\u043A\u0442\u0430 \u043F\u0440\u0438\u043D\u043E\u0441\u0438\u0442 \u043E\u0447\u043A\u043E. \u041D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u043D\u0430\u0440\u0443\u0448\u0435\u043D\u0438\u0439 \u0432 \u043E\u0434\u043D\u043E\u043C \u0443\u0434\u0430\u0440\u0435 \u043D\u0430\u043A\u0430\u0437\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u043E\u0434\u0438\u043D \u0440\u0430\u0437.",
              "\u0412\u044B\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u043C\u044B\u0435 \u0448\u0430\u0440\u044B \u0441\u0442\u0430\u0432\u044F\u0442 \u043E\u0442 \u0437\u0430\u0434\u043D\u0435\u0439 \u043E\u0442\u043C\u0435\u0442\u043A\u0438 \u0432\u043F\u0440\u0430\u0432\u043E \u043F\u043E \u043F\u0440\u043E\u0434\u043E\u043B\u044C\u043D\u043E\u0439 \u043E\u0441\u0438, \u043F\u0440\u0438 \u043D\u0435\u0445\u0432\u0430\u0442\u043A\u0435 \u043C\u0435\u0441\u0442\u0430 \u2014 \u0432 \u043E\u0431\u0440\u0430\u0442\u043D\u0443\u044E \u0441\u0442\u043E\u0440\u043E\u043D\u0443. \u041B\u044E\u0431\u043E\u0439 \u0438\u0437 \u043D\u0438\u0445 \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u043C \u0431\u0438\u0442\u043A\u043E\u043C. \u041A\u0440\u0443\u043F\u043D\u044B\u0435 \u0448\u0430\u0440\u044B \u0438 \u0442\u0435\u0441\u043D\u044B\u0435 \u0433\u0443\u0431\u043A\u0438 \u0442\u0440\u0435\u0431\u0443\u044E\u0442 \u0431\u043E\u043B\u044C\u0448\u0435\u0439 \u0442\u043E\u0447\u043D\u043E\u0441\u0442\u0438, \u0447\u0435\u043C \u043F\u0443\u043B; \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u043D\u0430 \u043B\u0443\u0437\u0443 \u043D\u0435 \u0433\u0430\u0440\u0430\u043D\u0442\u0438\u0440\u0443\u0435\u0442 \u043F\u0440\u043E\u0445\u043E\u0434 \u043C\u0435\u0436\u0434\u0443 \u0433\u0443\u0431\u043A\u0430\u043C\u0438."),
            rule_section(:settings, "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u043C\u0430\u0442\u0447\u0430",
              "\u041F\u0435\u0440\u0435\u0434 \u0438\u0433\u0440\u043E\u0439 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0434\u0438\u0441\u0446\u0438\u043F\u043B\u0438\u043D\u0443 \u0438 \u0443\u0441\u043B\u043E\u0432\u0438\u0435 \u043F\u043E\u0431\u0435\u0434\u044B. \u0412 \u0442\u043E\u0432\u0430\u0440\u0438\u0449\u0435\u0441\u043A\u043E\u043C \u0431\u0438\u043B\u044C\u044F\u0440\u0434\u0435 \u0437\u0430\u0434\u0430\u044E\u0442\u0441\u044F \u043E\u0431\u0449\u0435\u0435 \u0447\u0438\u0441\u043B\u043E \u0440\u0430\u0443\u043D\u0434\u043E\u0432 \u043E\u0442 1 \u0434\u043E 30 \u0438 \u043E\u0434\u043D\u0430 \u0438\u0437 \u0442\u0440\u0451\u0445 \u0440\u0430\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043E\u043A. \u0412 \u0434\u0438\u0441\u0446\u0438\u043F\u043B\u0438\u043D\u0430\u0445, \u0433\u0434\u0435 \u044D\u0442\u043E \u043F\u0440\u0435\u0434\u0443\u0441\u043C\u043E\u0442\u0440\u0435\u043D\u043E, \u0443\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u044E\u0442 \u043E\u0447\u043A\u043E\u0432\u0443\u044E \u0446\u0435\u043B\u044C \u043F\u0430\u0440\u0442\u0438\u0438; \u0446\u0435\u043B\u044C \u043C\u0430\u0442\u0447\u0430 \u2014 \u0447\u0438\u0441\u043B\u043E \u0432\u044B\u0438\u0433\u0440\u0430\u043D\u043D\u044B\u0445 \u043F\u0430\u0440\u0442\u0438\u0439. \u0412 \u0430\u043D\u0433\u043B\u0438\u0439\u0441\u043A\u043E\u043C \u0431\u0438\u043B\u044C\u044F\u0440\u0434\u0435 \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0438\u0433\u0440\u0443 \u043D\u0430 \u0432\u0440\u0435\u043C\u044F: \u043D\u0430\u0447\u0430\u0442\u044B\u0439 \u0434\u043E \u0435\u0433\u043E \u0438\u0441\u0442\u0435\u0447\u0435\u043D\u0438\u044F \u0443\u0434\u0430\u0440 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0435\u0442\u0441\u044F, \u0430 \u0440\u0430\u0432\u043D\u044B\u0439 \u0438\u0442\u043E\u0433\u043E\u0432\u044B\u0439 \u0441\u0447\u0451\u0442 \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u043D\u0438\u0447\u044C\u044E. \u041E\u043F\u0446\u0438\u044F \u0443\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u044E\u0449\u0435\u0433\u043E \u043F\u043E\u0434\u0445\u043E\u0434\u0430 \u0432 \u043A\u0430\u0440\u0430\u043C\u0431\u043E\u043B\u0435 \u0434\u0430\u0451\u0442 \u0432\u0442\u043E\u0440\u043E\u043C\u0443 \u0438\u0433\u0440\u043E\u043A\u0443 \u0437\u0430\u043A\u043B\u044E\u0447\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u043F\u043E\u0434\u0445\u043E\u0434 \u0438\u0437 \u043D\u0430\u0447\u0430\u043B\u044C\u043D\u043E\u0439 \u043F\u043E\u0437\u0438\u0446\u0438\u0438, \u043A\u043E\u0433\u0434\u0430 \u043D\u0443\u0436\u043D\u043E \u0441\u0440\u0430\u0432\u043D\u044F\u0442\u044C \u0447\u0438\u0441\u043B\u043E \u043F\u043E\u0434\u0445\u043E\u0434\u043E\u0432. \u0412 \u0430\u043D\u0433\u043B\u0438\u0439\u0441\u043A\u043E\u043C \u0431\u0438\u043B\u044C\u044F\u0440\u0434\u0435 \u043D\u0430 \u0432\u0440\u0435\u043C\u044F \u0443\u0434\u0430\u0440 \u0434\u043E\u043B\u0436\u0435\u043D \u0431\u044B\u0442\u044C \u043F\u0440\u0438\u043D\u044F\u0442 \u0437\u0430 \u0441\u0442\u043E\u043B\u043E\u043C \u0434\u043E \u043B\u0438\u043C\u0438\u0442\u0430; \u0431\u043E\u043B\u0435\u0435 \u0440\u0430\u043D\u043D\u0435\u0433\u043E \u043D\u0430\u0436\u0430\u0442\u0438\u044F \u043A\u043B\u0430\u0432\u0438\u0448\u0438 \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u043E.",
              "\u0422\u043E\u0432\u0430\u0440\u0438\u0449\u0435\u0441\u043A\u0438\u0439 \u0431\u0438\u043B\u044C\u044F\u0440\u0434 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442\u0441\u044F \u0441 \u0440\u043E\u043C\u0431\u0430 \u0438\u0437 \u0434\u0435\u0432\u044F\u0442\u0438 \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u0445 \u0448\u0430\u0440\u043E\u0432. \u0412 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u0442\u043E\u043B\u0430 \u0432\u043C\u0435\u0441\u0442\u043E \u043D\u0435\u0433\u043E \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u043E\u0434\u0438\u043D \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u0439 \u0448\u0430\u0440 \u0438\u043B\u0438 \u0442\u0440\u0435\u0443\u0433\u043E\u043B\u044C\u043D\u0438\u043A \u0438\u0437 \u043F\u044F\u0442\u043D\u0430\u0434\u0446\u0430\u0442\u0438; \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u043C \u0442\u043E\u0433\u0434\u0430 \u0431\u0443\u0434\u0435\u0442 \u0448\u0430\u0440 1 \u0438\u043B\u0438 15 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0435\u043D\u043D\u043E. \u042F\u0432\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u0430\u044F \u0440\u0430\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u0438 \u0440\u0430\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u0441\u0442\u0430\u0440\u043E\u0439 \u0441\u043E\u0445\u0440\u0430\u043D\u0451\u043D\u043D\u043E\u0439 \u0438\u0433\u0440\u044B \u043D\u0435 \u043C\u0435\u043D\u044F\u044E\u0442\u0441\u044F.",
              "\u0426\u0435\u043B\u044C \u043C\u0430\u0442\u0447\u0430 \u2014 \u043E\u0442 1 \u0434\u043E 25 \u0432\u044B\u0438\u0433\u0440\u0430\u043D\u043D\u044B\u0445 \u043F\u0430\u0440\u0442\u0438\u0439. \u041D\u0430\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u0435\u043C\u0430\u044F \u043E\u0447\u043A\u043E\u0432\u0430\u044F \u0446\u0435\u043B\u044C \u2014 \u043E\u0442 1 \u0434\u043E 1000, \u043B\u0438\u043C\u0438\u0442 \u0432\u0440\u0435\u043C\u0435\u043D\u0438 \u0430\u043D\u0433\u043B\u0438\u0439\u0441\u043A\u043E\u0433\u043E \u0431\u0438\u043B\u044C\u044F\u0440\u0434\u0430 \u2014 \u043E\u0442 1 \u0434\u043E 180 \u043C\u0438\u043D\u0443\u0442.",
              "\u0411\u043E\u043B\u0435\u0435 \u0442\u043E\u0447\u043D\u0430\u044F \u0444\u0438\u0437\u0438\u043A\u0430 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442 \u043C\u0435\u043D\u044C\u0448\u0438\u0435 \u0448\u0430\u0433\u0438 \u0440\u0430\u0441\u0447\u0451\u0442\u0430 \u0438 \u043C\u043E\u0436\u0435\u0442 \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0431\u043B\u0438\u0437\u043A\u043E\u0433\u043E \u043A\u043E\u043D\u0442\u0430\u043A\u0442\u0430. \u0421\u0438\u043B\u0430 \u043A\u043E\u043C\u043F\u044C\u044E\u0442\u0435\u0440\u0430 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442 \u0447\u0438\u0441\u043B\u043E \u0441\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u0435\u043C\u044B\u0445 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u043E\u0432 \u0443\u0434\u0430\u0440\u0430. \u0421\u0438\u043B\u0430 \u0438 \u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u0442\u0430\u043A\u0436\u0435 \u0432 \u043F\u0440\u043E\u0433\u043D\u043E\u0437\u0430\u0445.",
              "\u041B\u0438\u043C\u0438\u0442 \u043E\u0442 1 \u0434\u043E 500 \u0443\u0434\u0430\u0440\u043E\u0432 \u043E\u0442\u043D\u043E\u0441\u0438\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u043A \u0441\u0442\u0430\u0440\u044B\u043C \u0441\u043E\u0445\u0440\u0430\u043D\u0451\u043D\u043D\u044B\u043C \u0442\u0440\u0435\u043D\u0438\u0440\u043E\u0432\u043A\u0430\u043C, \u0430 \u043D\u0435 \u043A \u043D\u043E\u0432\u044B\u043C \u0438\u0433\u0440\u0430\u043C."),
            rule_section(:referee, "\u041F\u0440\u0430\u0432\u0438\u043B\u0430 \u0438 \u0446\u0438\u0444\u0440\u043E\u0432\u0430\u044F \u0430\u0434\u0430\u043F\u0442\u0430\u0446\u0438\u044F",
              "\u041F\u0443\u043B \u043E\u0441\u043D\u043E\u0432\u0430\u043D \u043D\u0430 \u043F\u0440\u0430\u0432\u0438\u043B\u0430\u0445 \u0438 \u0440\u0435\u0433\u043B\u0430\u043C\u0435\u043D\u0442\u0435 WPA \u043E\u0442 21 \u043E\u043A\u0442\u044F\u0431\u0440\u044F 2026 \u0433\u043E\u0434\u0430, \u0441\u043D\u0443\u043A\u0435\u0440 \u0438 \u0430\u043D\u0433\u043B\u0438\u0439\u0441\u043A\u0438\u0439 \u0431\u0438\u043B\u044C\u044F\u0440\u0434 \u2014 \u043D\u0430 WPBSA 2024\u201325, \u043A\u0430\u0440\u0430\u043C\u0431\u043E\u043B\u044C \u2014 \u043D\u0430 UMB, \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u0430\u044F \u043F\u0438\u0440\u0430\u043C\u0438\u0434\u0430 \u2014 \u043D\u0430 \u0440\u0435\u0434\u0430\u043A\u0446\u0438\u0438 IPC 2025. Cutthroat \u0438 \u0442\u043E\u0432\u0430\u0440\u0438\u0449\u0435\u0441\u043A\u0438\u0439 \u0431\u0438\u043B\u044C\u044F\u0440\u0434 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u044E\u0442 \u043E\u043F\u0438\u0441\u0430\u043D\u043D\u044B\u0435 \u0437\u0434\u0435\u0441\u044C \u043A\u043B\u0443\u0431\u043D\u044B\u0435 \u043F\u0440\u0430\u0432\u0438\u043B\u0430. \u041F\u043E\u0440\u044F\u0434\u043E\u043A \u0437\u0430 \u0441\u0442\u043E\u043B\u043E\u043C \u0437\u0430\u043C\u0435\u043D\u044F\u0435\u0442 \u0444\u0438\u0437\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448 \u043D\u0430\u0447\u0430\u043B\u0430. \u0421\u0430\u043C\u043E \u0441\u043E\u0433\u043B\u0430\u0448\u0435\u043D\u0438\u0435 \u043E \u043F\u0435\u0440\u0435\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0435 \u043D\u0435 \u0434\u0430\u0451\u0442 \u043F\u043E\u0431\u0435\u0434\u044B \u0432 \u043F\u0430\u0440\u0442\u0438\u0438. \u0410\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0441\u0443\u0434\u044C\u044F \u0441\u043D\u0443\u043A\u0435\u0440\u0430 \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0435\u0442 Miss \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u0440\u0438 \u043F\u0440\u044F\u043C\u043E\u043C \u043F\u0443\u0442\u0438; \u043F\u043E\u043B\u043D\u043E\u0441\u0442\u044C\u044E \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u0435 \u043F\u043E\u043F\u044B\u0442\u043A\u0438 \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u043E\u0431\u044B\u0447\u043D\u044B\u043C\u0438 \u0444\u043E\u043B\u0430\u043C\u0438 \u0431\u0435\u0437 \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F \u043F\u043E\u0437\u0438\u0446\u0438\u0438.",
              "\u0421\u0438\u043C\u0443\u043B\u044F\u0446\u0438\u044F \u0434\u0432\u0443\u043C\u0435\u0440\u043D\u0430\u044F: \u0443\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F \u043F\u0440\u044B\u0436\u043A\u043E\u043C, \u043F\u043E\u0434\u044A\u0451\u043C\u043E\u043C \u043A\u0438\u044F \u0438 mass\u00E9 \u043D\u0435\u0442. \u041E\u0446\u0435\u043D\u043A\u0430 \u043F\u0440\u043E\u043F\u0438\u0445\u0430 \u0441\u043E\u043F\u0440\u0438\u043A\u0430\u0441\u0430\u044E\u0449\u0438\u0445\u0441\u044F \u0448\u0430\u0440\u043E\u0432 \u0438 \u0433\u0443\u0431\u043E\u043A \u043B\u0443\u0437 \u043F\u0440\u0438\u0431\u043B\u0438\u0437\u0438\u0442\u0435\u043B\u044C\u043D\u0430\u044F. \u041F\u0435\u0440\u0432\u044B\u0435 \u043A\u043E\u043D\u0442\u0430\u043A\u0442\u044B, \u043D\u0435\u0440\u0430\u0437\u043B\u0438\u0447\u0438\u043C\u044B\u0435 \u0432 \u043E\u0434\u043D\u043E\u043C \u0448\u0430\u0433\u0435 \u0444\u0438\u0437\u0438\u043A\u0438, \u0441\u0447\u0438\u0442\u0430\u044E\u0442\u0441\u044F \u043E\u0434\u043D\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u044B\u043C\u0438. \u0414\u043B\u044F \u043F\u0438\u0440\u0430\u043C\u0438\u0434\u044B \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442\u0441\u044F \u043E\u043F\u0438\u0441\u0430\u043D\u043D\u0430\u044F \u0442\u0440\u0435\u043D\u0438\u0440\u043E\u0432\u043E\u0447\u043D\u0430\u044F \u0433\u0435\u043E\u043C\u0435\u0442\u0440\u0438\u044F \u0441 \u043A\u0440\u0443\u043F\u043D\u044B\u043C\u0438 \u0448\u0430\u0440\u0430\u043C\u0438 \u0438 \u0443\u0437\u043A\u0438\u043C\u0438 \u043B\u0443\u0437\u0430\u043C\u0438, \u0430 \u043D\u0435 \u0441\u0435\u0440\u0442\u0438\u0444\u0438\u043A\u0430\u0446\u0438\u044F \u0441\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u043E\u0433\u043E \u043E\u0431\u043E\u0440\u0443\u0434\u043E\u0432\u0430\u043D\u0438\u044F \u0444\u0435\u0434\u0435\u0440\u0430\u0446\u0438\u0438. \u041F\u043E\u0434\u0441\u043A\u0430\u0437\u043A\u0438 \u0438 \u043F\u0440\u043E\u0433\u043D\u043E\u0437\u044B \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u044E\u0442 \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u0431\u0438\u0442\u043E\u043A \u0438 \u0442\u0443 \u0436\u0435 \u0444\u0438\u0437\u0438\u043A\u0443, \u0447\u0442\u043E \u0438 \u0438\u0433\u0440\u0430."),
            rule_section(:controls, "\u041A\u043B\u0430\u0432\u0438\u0448\u0438 \u0443\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F",
              "K: \u041F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u043A\u0438\u044F.",
              "F: \u041F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0441\u0438\u043B\u0443 \u0443\u0434\u0430\u0440\u0430.",
              "G: \u041F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043F\u0435\u0440\u0432\u044B\u0439 \u043A\u043E\u043D\u0442\u0430\u043A\u0442 \u043D\u0430 \u043B\u0438\u043D\u0438\u0438 \u0443\u0434\u0430\u0440\u0430.",
              "H: \u041F\u0435\u0440\u0435\u0447\u0438\u0441\u043B\u0438\u0442\u044C \u0448\u0430\u0440\u044B \u0440\u044F\u0434\u043E\u043C \u0441 \u043B\u0438\u043D\u0438\u0435\u0439 \u0443\u0434\u0430\u0440\u0430.",
              "I: \u041E\u043F\u0438\u0441\u0430\u0442\u044C \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0439 \u0448\u0430\u0440.",
              "O: \u041F\u0435\u0440\u0435\u0447\u0438\u0441\u043B\u0438\u0442\u044C \u0432\u0441\u0435 \u0448\u0430\u0440\u044B \u0438 \u0438\u0445 \u043F\u043E\u0437\u0438\u0446\u0438\u0438.",
              "L: \u0412\u044B\u0431\u0440\u0430\u0442\u044C \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u0439 \u0448\u0430\u0440.",
              "Shift+L: \u0412\u044B\u0431\u0440\u0430\u0442\u044C \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0438\u0439 \u043F\u0440\u0438\u0446\u0435\u043B\u044C\u043D\u044B\u0439 \u0448\u0430\u0440.",
              "J: \u0412\u044B\u0431\u0440\u0430\u0442\u044C \u0446\u0435\u043B\u0435\u0432\u0443\u044E \u043B\u0443\u0437\u0443.",
              "A: \u041F\u0440\u0438\u0446\u0435\u043B\u0438\u0442\u044C\u0441\u044F \u0432 \u0446\u0435\u043D\u0442\u0440 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0433\u043E \u0448\u0430\u0440\u0430.",
              "Shift+A: \u041D\u0430\u043F\u0440\u0430\u0432\u0438\u0442\u044C \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0439 \u0448\u0430\u0440 \u0432 \u0443\u043A\u0430\u0437\u0430\u043D\u043D\u0443\u044E \u043B\u0443\u0437\u0443.",
              "E: \u0412\u0432\u0435\u0441\u0442\u0438 \u0442\u043E\u0447\u043D\u044B\u0435 \u0443\u0433\u043E\u043B, \u0441\u0438\u043B\u0443 \u0438 \u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435.",
              "W: \u0423\u0432\u0435\u043B\u0438\u0447\u0438\u0442\u044C \u0432\u0435\u0440\u0445\u043D\u0435\u0435 \u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435.",
              "Shift+B: \u0423\u0432\u0435\u043B\u0438\u0447\u0438\u0442\u044C \u043D\u0438\u0436\u043D\u0435\u0435 \u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435.",
              "N: \u0423\u0432\u0435\u043B\u0438\u0447\u0438\u0442\u044C \u043B\u0435\u0432\u043E\u0435 \u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435.",
              "D: \u0423\u0432\u0435\u043B\u0438\u0447\u0438\u0442\u044C \u043F\u0440\u0430\u0432\u043E\u0435 \u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435.",
              "R: \u0423\u0431\u0440\u0430\u0442\u044C \u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435.",
              "C: \u041F\u0435\u0440\u0435\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F \u043C\u0435\u0436\u0434\u0443 \u0433\u0440\u0430\u0434\u0443\u0441\u0430\u043C\u0438 \u0438 \u0447\u0430\u0441\u0430\u043C\u0438.",
              "Y: \u0420\u0430\u0441\u0441\u0447\u0438\u0442\u0430\u0442\u044C \u0443\u0434\u0430\u0440 \u0431\u0435\u0437 \u043F\u0435\u0440\u0435\u043C\u0435\u0449\u0435\u043D\u0438\u044F \u0448\u0430\u0440\u043E\u0432.",
              "U: \u041F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043A\u043E\u043D\u0442\u0430\u043A\u0442\u044B \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0433\u043E \u0443\u0434\u0430\u0440\u0430.",
              "\u0412\u043B\u0435\u0432\u043E: \u043F\u043E\u0432\u0435\u0440\u043D\u0443\u0442\u044C \u043F\u0440\u043E\u0442\u0438\u0432 \u0447\u0430\u0441\u043E\u0432\u043E\u0439 \u0441\u0442\u0440\u0435\u043B\u043A\u0438 \u043D\u0430 1 \u0433\u0440\u0430\u0434\u0443\u0441.",
              "\u0412\u043F\u0440\u0430\u0432\u043E: \u043F\u043E\u0432\u0435\u0440\u043D\u0443\u0442\u044C \u043F\u043E \u0447\u0430\u0441\u043E\u0432\u043E\u0439 \u0441\u0442\u0440\u0435\u043B\u043A\u0435 \u043D\u0430 1 \u0433\u0440\u0430\u0434\u0443\u0441.",
              "Shift+\u0432\u043B\u0435\u0432\u043E: \u043F\u043E\u0432\u0435\u0440\u043D\u0443\u0442\u044C \u043F\u0440\u043E\u0442\u0438\u0432 \u0447\u0430\u0441\u043E\u0432\u043E\u0439 \u0441\u0442\u0440\u0435\u043B\u043A\u0438 \u043D\u0430 0,1 \u0433\u0440\u0430\u0434\u0443\u0441\u0430.",
              "Shift+\u0432\u043F\u0440\u0430\u0432\u043E: \u043F\u043E\u0432\u0435\u0440\u043D\u0443\u0442\u044C \u043F\u043E \u0447\u0430\u0441\u043E\u0432\u043E\u0439 \u0441\u0442\u0440\u0435\u043B\u043A\u0435 \u043D\u0430 0,1 \u0433\u0440\u0430\u0434\u0443\u0441\u0430.",
              "Ctrl+\u0432\u043B\u0435\u0432\u043E: \u043F\u043E\u0432\u0435\u0440\u043D\u0443\u0442\u044C \u043F\u0440\u043E\u0442\u0438\u0432 \u0447\u0430\u0441\u043E\u0432\u043E\u0439 \u0441\u0442\u0440\u0435\u043B\u043A\u0438 \u043D\u0430 0,01 \u0433\u0440\u0430\u0434\u0443\u0441\u0430.",
              "Ctrl+\u0432\u043F\u0440\u0430\u0432\u043E: \u043F\u043E\u0432\u0435\u0440\u043D\u0443\u0442\u044C \u043F\u043E \u0447\u0430\u0441\u043E\u0432\u043E\u0439 \u0441\u0442\u0440\u0435\u043B\u043A\u0435 \u043D\u0430 0,01 \u0433\u0440\u0430\u0434\u0443\u0441\u0430.",
              "\u0412\u0432\u0435\u0440\u0445: \u0443\u0432\u0435\u043B\u0438\u0447\u0438\u0442\u044C \u0441\u0438\u043B\u0443 \u043D\u0430 1 \u043F\u0440\u043E\u0446\u0435\u043D\u0442.",
              "\u0412\u043D\u0438\u0437: \u0443\u043C\u0435\u043D\u044C\u0448\u0438\u0442\u044C \u0441\u0438\u043B\u0443 \u043D\u0430 1 \u043F\u0440\u043E\u0446\u0435\u043D\u0442.",
              "Shift+\u0432\u0432\u0435\u0440\u0445: \u0443\u0432\u0435\u043B\u0438\u0447\u0438\u0442\u044C \u0441\u0438\u043B\u0443 \u043D\u0430 0,1 \u043F\u0440\u043E\u0446\u0435\u043D\u0442\u0430.",
              "Shift+\u0432\u043D\u0438\u0437: \u0443\u043C\u0435\u043D\u044C\u0448\u0438\u0442\u044C \u0441\u0438\u043B\u0443 \u043D\u0430 0,1 \u043F\u0440\u043E\u0446\u0435\u043D\u0442\u0430.",
              "Enter \u0438\u043B\u0438 \u043F\u0440\u043E\u0431\u0435\u043B: \u0432\u044B\u043F\u043E\u043B\u043D\u0438\u0442\u044C \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u0443\u0434\u0430\u0440.",
              "T: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C, \u0447\u0435\u0439 \u0445\u043E\u0434.",
              "V: \u0420\u0430\u0441\u0441\u0447\u0438\u0442\u0430\u0442\u044C \u043E\u0442\u0441\u043A\u043E\u043A \u043E\u0442 \u0431\u043E\u0440\u0442\u0430 \u0438 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0435 \u043A\u0430\u0441\u0430\u043D\u0438\u0435 \u0448\u0430\u0440\u0430.",
              "B: \u041E\u043F\u0438\u0441\u0430\u0442\u044C \u043E\u0431\u044A\u0435\u043A\u0442\u044B \u0437\u0430 \u0448\u0430\u0440\u043E\u043C, \u043D\u0430 \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u0435\u043D \u043A\u0438\u0439.",
              "S: \u041F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0441\u0447\u0451\u0442, \u0432 \u0442\u043E\u0432\u0430\u0440\u0438\u0449\u0435\u0441\u043A\u043E\u043C \u0440\u0435\u0436\u0438\u043C\u0435 \u2014 \u043F\u043E\u0431\u0435\u0434\u044B \u0432 \u0440\u0430\u0443\u043D\u0434\u0430\u0445 \u0438 \u043E\u0447\u043A\u0438 \u0437\u0430 \u0437\u0430\u0431\u0438\u0442\u0438\u044F.",
